@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_choreography_monotonic_sampler_preserves_exact_async_identity(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
) -> None:
    failure: BaseException = SystemExit(127) if failure_type is SystemExit else KeyboardInterrupt()

    class InterruptingClock(_MonotonicClock):
        def __init__(self) -> None:
            super().__init__([])

        def __call__(self) -> Never:
            raise failure

    clock = InterruptingClock()
    issuer, _ = _open_issuer(
        monkeypatch,
        tmp_path,
        monotonic_clock=clock,
    )
    with pytest.raises(failure_type) as retained_interruption:
        issuer._run_exclusive_choreography(lambda _lease: None)

    assert retained_interruption.value is failure
    _assert_choreography_authority_is_burned(issuer)
    _assert_launch_lock_is_held(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_pre_registration_lifecycle_lock_call_to_store_re_resolves_and_burns(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    target = _nested_code(
        type(issuer)._run_authenticated_choreography_scope,
        "execute_authenticated_body",
    )
    offset = _call_return_offset(target, callable_name="_bound_lifecycle_lock")
    failure: BaseException = SystemExit(151) if failure_type is SystemExit else KeyboardInterrupt()
    action_called = False

    def unreachable(_lease: object) -> None:
        nonlocal action_called
        action_called = True

    tool_id = _enable_instruction_interrupt(
        target,
        offset,
        tool_name=f"trusted-time-pre-register-lock-{failure_type.__name__}-test",
        interruption=failure,
    )
    try:
        with pytest.raises(failure_type) as retained_interruption:
            issuer._run_exclusive_choreography(unreachable)
    finally:
        _disable_instruction_interrupt(tool_id, target)

    assert retained_interruption.value is failure
    assert action_called is False
    _assert_choreography_authority_is_burned(issuer)
    _assert_launch_lock_is_held(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize(
    "failure_stage",
    ["usable", "session", "root_descriptor", "root_projection"],
)
@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_pre_registration_setup_failure_burns_closure_authority(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_stage: str,
    failure_type: type[BaseException],
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    failure: BaseException = SystemExit(153) if failure_type is SystemExit else KeyboardInterrupt()
    action_called = False

    def interrupt(*_args: object, **_kwargs: object) -> Never:
        raise failure

    def unreachable(_lease: object) -> None:
        nonlocal action_called
        action_called = True

    with monkeypatch.context() as scoped:
        if failure_stage == "usable":
            scoped.setattr(type(issuer), "_require_usable", interrupt)
        elif failure_stage == "session":
            scoped.setattr(type(issuer), "_validate_session", interrupt)
        elif failure_stage == "root_descriptor":
            scoped.setattr(type(issuer), "_ignored_root", property(interrupt))
        else:
            defaults = type(issuer)._run_authenticated_choreography_scope.__kwdefaults__
            assert defaults is not None
            scoped.setitem(defaults, "_fspath", interrupt)

        with pytest.raises(failure_type) as retained_interruption:
            issuer._run_exclusive_choreography(unreachable)

    assert retained_interruption.value is failure
    assert action_called is False
    _assert_choreography_authority_is_burned(issuer)
    _assert_launch_lock_is_held(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def _seed_cursor_state(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
) -> None:
    issuer._issued_created_observation_sha256 = "3" * 64
    issuer._last_observation_sha256 = "4" * 64
    issuer._first_staged_snapshot_sha256 = "5" * 64
    issuer._staged_observation_count = 1


def _assert_launch_lock_is_held(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
) -> None:
    lease = issuer._launch_lock_lease
    assert type(lease) is _TrustedTimeLaunchLockLease
    assert lease.closed is False
    _validate_trusted_time_launch_lock(lease)
    with pytest.raises(BlockingIOError):
        _acquire_trusted_time_launch_lock(os.fspath(issuer._ignored_root))


def _close_and_assert_launch_lock_is_reacquirable(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
) -> None:
    ignored_root = os.fspath(issuer._ignored_root)
    lease = issuer._launch_lock_lease
    assert type(lease) is _TrustedTimeLaunchLockLease
    issuer.close()
    assert lease.closed is True
    assert issuer._launch_lock_lease is None
    replacement = _acquire_trusted_time_launch_lock(ignored_root)
    _validate_trusted_time_launch_lock(replacement)
    replacement.close()
    assert replacement.closed is True


