@pytest.mark.parametrize("initial_depth", [0, 1])
@pytest.mark.parametrize(
    "interruption_point",
    ["acquire_return", "body_return", "release_return"],
)
@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_exact_rlock_runner_restores_depth_and_preserves_async_identity(
    initial_depth: int,
    interruption_point: str,
    failure_type: type[BaseException],
) -> None:
    lock = threading.RLock()
    for _ in range(initial_depth):
        assert lock.acquire() is True
    failure: BaseException = (
        SystemExit(67 + initial_depth) if failure_type is SystemExit else KeyboardInterrupt()
    )
    if interruption_point == "release_return":
        target_code = reader._restore_rlock_depth.__code__
        instructions = list(dis.get_instructions(reader._restore_rlock_depth))
        release_load_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.argval == "release"
        )
        release_call_index = next(
            index
            for index in range(release_load_index + 1, len(instructions))
            if instructions[index].opname == "CALL"
        )
        target_offset = instructions[release_call_index + 1].offset
    else:
        target_code = reader._run_under_exact_rlock.__code__
        target_name = "acquired" if interruption_point == "acquire_return" else "result"
        target_offset = next(
            instruction.offset
            for instruction in dis.get_instructions(reader._run_under_exact_rlock)
            if instruction.opname == "STORE_FAST" and instruction.argval == target_name
        )
    interrupted = False

    def interrupt(_: object, instruction_offset: int) -> None:
        nonlocal interrupted
        if not interrupted and instruction_offset == target_offset:
            interrupted = True
            raise failure

    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(tool_id, "trusted-time-exact-rlock-transition-test")
    try:
        sys.monitoring.register_callback(
            tool_id,
            sys.monitoring.events.INSTRUCTION,
            interrupt,
        )
        sys.monitoring.set_local_events(
            tool_id,
            target_code,
            sys.monitoring.events.INSTRUCTION,
        )
        with pytest.raises(failure_type) as retained_interruption:
            reader._run_under_exact_rlock(lock, lambda: object())
    finally:
        sys.monitoring.set_local_events(tool_id, target_code, 0)
        sys.monitoring.register_callback(tool_id, sys.monitoring.events.INSTRUCTION, None)
        sys.monitoring.free_tool_id(tool_id)

    assert interrupted is True
    assert retained_interruption.value is failure
    assert cast(Any, lock)._recursion_count() == initial_depth
    acquired_elsewhere = threading.Event()

    def acquire_elsewhere() -> None:
        if lock.acquire(timeout=2.0):
            acquired_elsewhere.set()
            lock.release()

    worker = threading.Thread(target=acquire_elsewhere)
    worker.start()
    if initial_depth == 1:
        assert not acquired_elsewhere.wait(timeout=0.05)
        lock.release()
    assert acquired_elsewhere.wait(timeout=2.0)
    worker.join(timeout=2.0)
    assert not worker.is_alive()


@pytest.mark.parametrize("interruption_point", ["scope_enter_return", "scope_leave_return"])
@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_issuance_scope_token_is_removed_after_entry_or_exit_interruption(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    interruption_point: str,
    failure_type: type[BaseException],
) -> None:
    issuer, queued = _open_issuer(
        monkeypatch,
        tmp_path,
        outputs=[fixtures._json_line("LOCAL:DAEMON:1")],
    )
    _seed_cursor_state(issuer)
    launch_lock_lease = issuer._launch_lock_lease
    assert type(launch_lock_lease) is _TrustedTimeLaunchLockLease
    guarded_cursor = (
        reader.TrustedTimePostEnrollmentTopologyObservationIssuer.issue_observation_cursor
    )
    call_scope = inspect.getclosurevars(guarded_cursor).nonlocals[
        "call_in_authenticated_owner_scope"
    ]
    assert callable(call_scope)
    if interruption_point == "scope_enter_return":
        target_code = cast(Callable[..., object], call_scope).__code__
        instructions = list(dis.get_instructions(cast(Callable[..., object], call_scope)))
    else:
        target_code = next(
            constant
            for constant in cast(Callable[..., object], call_scope).__code__.co_consts
            if isinstance(constant, CodeType) and constant.co_name == "leave_under_lock_once"
        )
        instructions = list(dis.get_instructions(target_code))
    run_load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.argval == "_run_under_lock"
    )
    run_call_index = next(
        index
        for index in range(run_load_index + 1, len(instructions))
        if instructions[index].opname == "CALL"
    )
    target_offset = instructions[run_call_index + 1].offset
    failure: BaseException = SystemExit(73) if failure_type is SystemExit else KeyboardInterrupt()
    interrupted = False

    def interrupt(_: object, instruction_offset: int) -> None:
        nonlocal interrupted
        if not interrupted and instruction_offset == target_offset:
            interrupted = True
            raise failure

    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(tool_id, "trusted-time-owner-scope-transition-test")
    try:
        sys.monitoring.register_callback(
            tool_id,
            sys.monitoring.events.INSTRUCTION,
            interrupt,
        )
        sys.monitoring.set_local_events(
            tool_id,
            target_code,
            sys.monitoring.events.INSTRUCTION,
        )
        with pytest.raises(failure_type) as retained_interruption:
            issuer.issue_observation_cursor()
    finally:
        sys.monitoring.set_local_events(tool_id, target_code, 0)
        sys.monitoring.register_callback(tool_id, sys.monitoring.events.INSTRUCTION, None)
        sys.monitoring.free_tool_id(tool_id)

    assert interrupted is True
    assert retained_interruption.value is failure
    assert launch_lock_lease.closed is False
    if interruption_point == "scope_enter_return":
        assert len(queued.outputs) == 1
        assert issuer._cursor_count == 0
    else:
        assert queued.outputs == []
        assert issuer._cursor_count == 1
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_inert_abort_retries_depth_probe_and_preserves_async_identity(
    failure_type: type[BaseException],
) -> None:
    failure: BaseException = SystemExit(79) if failure_type is SystemExit else KeyboardInterrupt()
    abort_activation = reader._abort_authenticated_issuer_activation
    revoke_owner = inspect.getclosurevars(abort_activation).nonlocals["revoke_owner"]
    assert callable(revoke_owner)
    revoke_owner_locked_code = next(
        constant
        for constant in cast(Callable[..., object], revoke_owner).__code__.co_consts
        if isinstance(constant, CodeType) and constant.co_name == "revoke_owner_locked"
    )
    instructions = list(dis.get_instructions(revoke_owner_locked_code))
    depth_load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.argval == "_rlock_depth"
    )
    depth_call_index = next(
        index
        for index in range(depth_load_index + 1, len(instructions))
        if instructions[index].opname == "CALL"
    )
    target_offset = instructions[depth_call_index + 1].offset
    interrupted = False

    def interrupt(_: object, instruction_offset: int) -> None:
        nonlocal interrupted
        if not interrupted and instruction_offset == target_offset:
            interrupted = True
            raise failure

    issuer = reader.TrustedTimePostEnrollmentTopologyObservationIssuer.allocate_inert()
    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(tool_id, "trusted-time-inert-abort-depth-test")
    try:
        sys.monitoring.register_callback(
            tool_id,
            sys.monitoring.events.INSTRUCTION,
            interrupt,
        )
        sys.monitoring.set_local_events(
            tool_id,
            revoke_owner_locked_code,
            sys.monitoring.events.INSTRUCTION,
        )
        with pytest.raises(failure_type) as retained_interruption:
            abort_activation(issuer)
    finally:
        sys.monitoring.set_local_events(tool_id, revoke_owner_locked_code, 0)
        sys.monitoring.register_callback(tool_id, sys.monitoring.events.INSTRUCTION, None)
        sys.monitoring.free_tool_id(tool_id)

    assert interrupted is True
    assert retained_interruption.value is failure
    assert issuer._closed is True
    assert issuer._poisoned is True
    assert issuer._authentication_capability is None
    assert issuer._launch_lock_lease is None


