@pytest.mark.parametrize("interruption_point", ["before_close", "after_close"])
@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_activation_abort_retries_lock_close_instruction_interruptions(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    interruption_point: str,
    failure_type: type[BaseException],
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    saved_capability = issuer._authentication_capability
    launch_lock_lease = issuer._launch_lock_lease
    ignored_root = issuer._ignored_root
    assert type(launch_lock_lease) is _TrustedTimeLaunchLockLease
    abort_activation = reader._abort_authenticated_issuer_activation
    abort_once_code = next(
        constant
        for constant in abort_activation.__code__.co_consts
        if isinstance(constant, CodeType) and constant.co_name == "abort_once"
    )
    instructions = list(dis.get_instructions(abort_once_code))
    close_load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname == "LOAD_DEREF" and instruction.argval == "_close_launch_lock"
    )
    close_call_index = next(
        index
        for index in range(close_load_index + 1, len(instructions))
        if instructions[index].opname == "CALL"
    )
    target_offset = (
        instructions[close_call_index].offset
        if interruption_point == "before_close"
        else instructions[close_call_index + 1].offset
    )
    interrupted = False

    def interrupt(_: object, instruction_offset: int) -> None:
        nonlocal interrupted
        if not interrupted and instruction_offset == target_offset:
            interrupted = True
            if failure_type is SystemExit:
                raise SystemExit(41)
            raise KeyboardInterrupt

    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(tool_id, "trusted-time-activation-abort-close-test")
    try:
        sys.monitoring.register_callback(
            tool_id,
            sys.monitoring.events.INSTRUCTION,
            interrupt,
        )
        sys.monitoring.set_local_events(
            tool_id,
            abort_once_code,
            sys.monitoring.events.INSTRUCTION,
        )
        with pytest.raises(failure_type) as retained_interruption:
            abort_activation(issuer)
    finally:
        sys.monitoring.set_local_events(tool_id, abort_once_code, 0)
        sys.monitoring.register_callback(tool_id, sys.monitoring.events.INSTRUCTION, None)
        sys.monitoring.free_tool_id(tool_id)

    assert interrupted is True
    assert retained_interruption.value.__traceback__ is not None
    assert launch_lock_lease.closed is True
    with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
        reader._authenticated_issuer_runtime_provenance(issuer, saved_capability)
    replacement = _acquire_trusted_time_launch_lock(os.fspath(ignored_root))
    _validate_trusted_time_launch_lock(replacement)
    replacement.close()


def test_caller_owned_activation_return_interruption_burns_native_lease(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    """The exact owner exists before activation and caller cleanup burns its lease."""

    socket_path = fixtures._short_socket_path(tmp_path)
    queued = fixtures._QueuedRunner([fixtures._json_line("LOCAL:DAEMON:1")])
    ignored_root = tmp_path / "artifacts"
    docker_executable, docker_executable_identity = reader._resolve_trusted_docker_executable()
    original_activate = fixtures._test_only_authenticated_activation_closure()[0]
    activation_defaults = cast(dict[str, object], original_activate.__kwdefaults__)
    monkeypatch.setitem(
        activation_defaults,
        "_resolve_docker",
        lambda: (docker_executable, docker_executable_identity),
    )
    monkeypatch.setitem(activation_defaults, "_runner", queued)
    monkeypatch.setitem(activation_defaults, "_session_token_factory", lambda: b"n" * 32)
    monkeypatch.setitem(activation_defaults, "_ignored_root_value", os.fspath(ignored_root))
    monkeypatch.setitem(
        activation_defaults,
        "_artifact_directory_value",
        os.fspath(ignored_root / "trusted-time"),
    )
    issuer = reader.TrustedTimePostEnrollmentTopologyObservationIssuer.allocate_inert()
    capability_registry = cast(
        dict[object, object],
        inspect.getclosurevars(reader._authenticated_issuer_capability_is_active).nonlocals[
            "active_capabilities"
        ],
    )
    registrations_before = len(capability_registry)
    closed_leases: list[_TrustedTimeLaunchLockLease] = []

    def interrupted_caller() -> None:
        try:
            issuer.activate(
                expected_daemon_identity=LocalDockerDaemonIdentity(
                    context_name="<DOCKER_HOST>",
                    endpoint=f"unix://{socket_path}",
                    daemon_id="LOCAL:DAEMON:1",
                ),
                docker_environment={},
            )
        except BaseException:
            lease = issuer._launch_lock_lease
            assert type(lease) is _TrustedTimeLaunchLockLease
            closed_leases.append(lease)
            issuer.close()
            raise

    failure = KeyboardInterrupt()

    def interrupt_return(*_: object) -> None:
        raise failure

    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(tool_id, "trusted-time-reader-activate-return-test")
    try:
        sys.monitoring.register_callback(
            tool_id,
            sys.monitoring.events.PY_RETURN,
            interrupt_return,
        )
        sys.monitoring.set_local_events(
            tool_id,
            reader.TrustedTimePostEnrollmentTopologyObservationIssuer.activate.__code__,
            sys.monitoring.events.PY_RETURN,
        )
        with pytest.raises(KeyboardInterrupt) as retained_interruption:
            interrupted_caller()
    finally:
        sys.monitoring.set_local_events(
            tool_id,
            reader.TrustedTimePostEnrollmentTopologyObservationIssuer.activate.__code__,
            0,
        )
        sys.monitoring.register_callback(tool_id, sys.monitoring.events.PY_RETURN, None)
        sys.monitoring.free_tool_id(tool_id)
    gc.collect()

    assert retained_interruption.value is failure
    assert len(capability_registry) == registrations_before
    assert len(closed_leases) == 1
    assert closed_leases[0].closed is True
    assert issuer._closed is True
    assert issuer._poisoned is True
    assert issuer._authentication_capability is None
    assert issuer._launch_lock_lease is None
    replacement = _acquire_trusted_time_launch_lock(os.fspath(ignored_root))
    _validate_trusted_time_launch_lock(replacement)
    replacement.close()


