def _install_claimed_authorization_special_method_attack(
    authorization_type: type[object],
    attack: str,
) -> tuple[list[tuple[str, object, object | None]], Callable[[], None]]:
    namespace = type.__getattribute__(authorization_type, "__dict__")
    missing = object()
    original_hash = namespace.get("__hash__", missing)
    original_eq = namespace.get("__eq__", missing)
    invocations: list[tuple[str, object, object | None]] = []

    def hostile_hash(candidate: object) -> int:
        invocations.append(("hash", candidate, None))
        if attack == "hash_raises":
            raise RuntimeError("hostile authorization hash executed")
        return 0

    def hostile_eq(candidate: object, other: object) -> bool:
        invocations.append(("eq", candidate, other))
        if attack == "eq_raises":
            raise RuntimeError("hostile authorization equality executed")
        return True

    assert attack in _CLAIMED_AUTHORIZATION_SPECIAL_METHOD_ATTACKS
    type.__setattr__(authorization_type, "__hash__", hostile_hash)
    if attack.startswith("eq_"):
        type.__setattr__(authorization_type, "__eq__", hostile_eq)

    def restore() -> None:
        if original_eq is missing:
            if "__eq__" in type.__getattribute__(authorization_type, "__dict__"):
                type.__delattr__(authorization_type, "__eq__")
        else:
            type.__setattr__(authorization_type, "__eq__", original_eq)
        if original_hash is missing:
            type.__delattr__(authorization_type, "__hash__")
        else:
            type.__setattr__(authorization_type, "__hash__", original_hash)

    return invocations, restore


