def _claimed_producer_authority_codes() -> dict[str, CodeType]:
    issue = _claimed_fence_recovery_binder_issue_test_seam()
    closure = inspect.getclosurevars(issue).nonlocals
    retirement_callback = _claimed_fence_recovery_binder_retirement_callback_test_seam()
    roots = {
        "issue_recovery_binder": issue.__code__,
        "register_authorization_locked": _nested_code(
            issue,
            "register_authorization_locked",
        ),
        "retire_lost_recovery_binder_issuer": retirement_callback.__code__,
        "recovery_binder_authorizations_are_exact_locked": cast(
            FunctionType,
            closure["recovery_binder_authorizations_are_exact_locked"],
        ).__code__,
        "recovery_binder_path_values": cast(
            FunctionType,
            closure["recovery_binder_path_values"],
        ).__code__,
        "recovery_binder_thread_token": cast(
            FunctionType,
            closure["recovery_binder_thread_token"],
        ).__code__,
        "preferred_control_error": cast(
            FunctionType,
            closure["preferred_control_error"],
        ).__code__,
    }
    assert tuple(roots) == _CLAIMED_PRODUCER_AUTHORITY_ROOT_NAMES
    assert all(type(code) is CodeType for code in roots.values())
    return roots


def _claimed_issue_cleanup_ast() -> tuple[
    ast.FunctionDef,
    str,
    tuple[ast.Call, ast.Call, ast.Call, ast.Call],
]:
    source_path = Path(cast(str, claimed_fence.__file__))
    tree = ast.parse(
        source_path.read_text(encoding="utf-8"),
        filename=os.fspath(source_path),
    )
    issue = next(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.FunctionDef) and node.name == "issue_recovery_binder"
    )
    nested_names = {
        node.name
        for node in issue.body
        if isinstance(node, ast.FunctionDef)
        and ("cleanup" in node.name or "retire_authorization" in node.name)
    }
    direct_calls_by_name: dict[str, list[ast.Call]] = {}
    for node in ast.walk(issue):
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id in nested_names
        ):
            direct_calls_by_name.setdefault(node.func.id, []).append(node)
    cleanup_name, cleanup_calls = next(
        (name, calls) for name, calls in direct_calls_by_name.items() if len(calls) == 4
    )
    ordered_calls = tuple(sorted(cleanup_calls, key=lambda call: call.lineno))
    assert len(ordered_calls) == 4
    return (
        issue,
        cleanup_name,
        cast(
            tuple[ast.Call, ast.Call, ast.Call, ast.Call],
            ordered_calls,
        ),
    )


def _claimed_issue_cleanup_boundary_offset(
    issue: Callable[..., None],
    boundary: str,
) -> int:
    instructions = list(dis.get_instructions(issue))
    if boundary == "handler_primary_store":
        return _instruction_offset(
            issue,
            opname="STORE_FAST",
            argval="primary_error",
            occurrence="last",
        )
    primary_store_index = max(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname in {"STORE_DEREF", "STORE_FAST"}
        and instruction.argval == "primary_error"
    )
    handler_pop_index = next(
        index
        for index in range(primary_store_index + 1, len(instructions))
        if instructions[index].opname == "POP_EXCEPT"
    )
    if boundary == "handler_pop_except":
        return instructions[handler_pop_index].offset
    if boundary == "handler_handoff":
        handoff_index = next(
            index
            for index in range(handler_pop_index + 1, len(instructions))
            if instructions[index].opname.startswith("JUMP")
        )
        return instructions[handoff_index].offset

    _issue_ast, cleanup_name, cleanup_calls = _claimed_issue_cleanup_ast()
    call_offsets: list[tuple[int, int]] = []
    for cleanup_call in cleanup_calls:
        matching_call_indices = [
            index
            for index, instruction in enumerate(instructions)
            if instruction.opname == "CALL" and instruction.positions.lineno == cleanup_call.lineno
        ]
        assert matching_call_indices
        call_index = matching_call_indices[0]
        load_names = {
            instruction.argval
            for instruction in instructions[max(0, call_index - 8) : call_index]
            if type(instruction.argval) is str
        }
        assert cleanup_name in load_names
        call_offsets.append(
            (
                instructions[call_index].offset,
                instructions[call_index + 1].offset,
            )
        )
    if boundary.startswith("cleanup_call_before_"):
        occurrence = int(boundary.rpartition("_")[2])
        return call_offsets[occurrence][0]
    if boundary.startswith("cleanup_call_return_"):
        occurrence = int(boundary.rpartition("_")[2])
        return call_offsets[occurrence][1]

    assert boundary == "reducer_return"
    preferred_load_indices = [
        index
        for index, instruction in enumerate(instructions)
        if type(instruction.argval) is str
        and "preferred" in instruction.argval
        and instruction.opname in {"LOAD_DEREF", "LOAD_FAST", "LOAD_GLOBAL", "LOAD_NAME"}
    ]
    assert preferred_load_indices
    reducer_call_index = next(
        index
        for index in range(preferred_load_indices[-1] + 1, len(instructions))
        if instructions[index].opname == "CALL"
    )
    return instructions[reducer_call_index + 1].offset


def _claimed_fence_registration_test_seams() -> tuple[
    dict[object, object],
    dict[object, object],
    dict[object, object],
    Callable[[Callable[[], object]], object],
    CodeType,
]:
    prepare_closure = inspect.getclosurevars(
        claimed_fence.prepare_post_enrollment_start_claimed_pre_release_fence
    )
    unregister = cast(Callable[..., None], prepare_closure.nonlocals["unregister"])
    unregister_closure = inspect.getclosurevars(unregister)
    return (
        cast(dict[object, object], unregister_closure.nonlocals["registrations"]),
        cast(
            dict[object, object],
            unregister_closure.nonlocals["claimed_action_choreographies"],
        ),
        cast(
            dict[object, object],
            unregister_closure.nonlocals["consumed_claimed_action_origins"],
        ),
        cast(
            Callable[[Callable[[], object]], object],
            unregister_closure.nonlocals["run_under_registry_lock"],
        ),
        _nested_code(unregister, "unregister_locked"),
    )


def _issue_registered_recovery_claim_binder(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
    lease: object,
    capability: object,
    *,
    artifact_directory: Path,
    ignored_root: Path,
) -> reader._TrustedTimePostEnrollmentRecoveryClaimBinder:
    binder = object.__new__(reader._TrustedTimePostEnrollmentRecoveryClaimBinder)
    _register_recovery_claim_binder(
        issuer,
        lease,
        capability,
        binder,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )
    return binder


def _bind_registered_recovery_claim(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
    lease: object,
    capability: object,
    retained: RetainedTrustedTimePostEnrollmentStartClaim,
    *,
    artifact_directory: Path,
    ignored_root: Path,
) -> reader._TrustedTimePostEnrollmentRecoveryClaimBinder:
    binder = _issue_registered_recovery_claim_binder(
        issuer,
        lease,
        capability,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )
    binder._checkpoint(
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )
    binder(retained)
    return binder


def _persist_recovery_outcome(
    retained: RetainedTrustedTimePostEnrollmentStartClaim,
    *,
    artifact_directory: Path,
    ignored_root: Path,
) -> recovery_outcome.RetainedTrustedTimePostEnrollmentStartOutcome:
    return recovery_outcome._persist_outcome(
        retained_claim=retained,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )


def _persist_foreign_recovery_outcome(
    *,
    artifact_directory: Path,
) -> recovery_outcome.RetainedTrustedTimePostEnrollmentStartOutcome:
    operation_id = claim_fixtures.OTHER_OPERATION_ID
    approval_sha256 = "d" * 64
    claim_sha256 = "e" * 64
    retained_claim_artifact_sha256 = "f" * 64
    encoded = recovery_outcome.retained_post_enrollment_start_recovery_required_outcome_bytes(
        operation_id=operation_id,
        approval_sha256=approval_sha256,
        claim_sha256=claim_sha256,
        retained_claim_artifact_sha256=retained_claim_artifact_sha256,
    )
    outcome_sha256 = hashlib.sha256(encoded).hexdigest()
    artifact_path = artifact_directory / recovery_outcome._outcome_file_name(outcome_sha256)
    slot_path = artifact_directory / recovery_outcome.POST_ENROLLMENT_START_OUTCOME_SLOT_FILE_NAME
    artifact_path.write_bytes(encoded)
    artifact_path.chmod(0o600)
    slot_path.write_bytes(
        recovery_outcome._outcome_slot_bytes(
            outcome_sha256,
            outcome_contract_version=(
                recovery_outcome.POST_ENROLLMENT_START_RETAINED_OUTCOME_CONTRACT_VERSION
            ),
            status="retained",
        )
    )
    slot_path.chmod(0o600)
    for path in (artifact_path, slot_path):
        descriptor = os.open(path, os.O_RDONLY)
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
    directory_descriptor = os.open(artifact_directory, os.O_RDONLY)
    try:
        os.fsync(directory_descriptor)
    finally:
        os.close(directory_descriptor)
    receipt = recovery_outcome.RetainedTrustedTimePostEnrollmentStartOutcome(
        operation_id=operation_id,
        approval_sha256=approval_sha256,
        claim_sha256=claim_sha256,
        retained_claim_artifact_sha256=retained_claim_artifact_sha256,
        outcome_sha256=outcome_sha256,
        artifact_path=artifact_path,
        encoded=encoded,
        file_identity=recovery_outcome._stable_file_identity(artifact_path.stat()),
        slot_file_identity=recovery_outcome._stable_file_identity(slot_path.stat()),
        status=(
            recovery_outcome.TrustedTimePostEnrollmentStartRetainedOutcomeStatus.RECOVERY_REQUIRED
        ),
        reason=(
            recovery_outcome.TrustedTimePostEnrollmentStartRetainedOutcomeReason.POST_ENROLLMENT_START_RECOVERY_REQUIRED
        ),
    )
    return receipt


def _foreign_retained_claim_projection_view(
    retained: RetainedTrustedTimePostEnrollmentStartClaim,
) -> RetainedTrustedTimePostEnrollmentStartClaim:
    foreign_claim = claim_fixtures._claim(claim_fixtures.OTHER_OPERATION_ID)
    candidate = object.__new__(RetainedTrustedTimePostEnrollmentStartClaim)
    object.__setattr__(candidate, "claim", foreign_claim)
    object.__setattr__(candidate, "operation_id", claim_fixtures.OTHER_OPERATION_ID)
    object.__setattr__(candidate, "claim_projection_sha256", "d" * 64)
    object.__setattr__(candidate, "artifact_sha256", "e" * 64)
    object.__setattr__(candidate, "artifact_path", retained.artifact_path)
    object.__setattr__(candidate, "encoded", retained.encoded)
    object.__setattr__(candidate, "file_identity", retained.file_identity)
    return candidate


def _exact_dataclass_identity_clone(candidate: object) -> object:
    candidate_type = type(candidate)
    fields = vars(candidate_type).get("__dataclass_fields__")
    assert type(fields) is dict
    clone = object.__new__(candidate_type)
    for field_name in fields:
        object.__setattr__(
            clone,
            field_name,
            object.__getattribute__(candidate, field_name),
        )
    return clone


