def _nested_live_claim_target(claim: object, target_name: str) -> object:
    approval = object.__getattribute__(claim, "approval")
    review = object.__getattribute__(approval, "review")
    confirmed = object.__getattribute__(review, "confirmed_enrollment")
    return {
        "review": review,
        "confirmed": confirmed,
        "launch": object.__getattribute__(review, "proposed_launch"),
        "identities": object.__getattribute__(confirmed, "identities"),
        "sequence_one": object.__getattribute__(confirmed, "sequence_one"),
    }[target_name]


def _different_nested_claim_field_value(candidate: object) -> object:
    if type(candidate) is str:
        if not candidate:
            return "0"
        replacement_prefix = "0" if candidate[0] != "0" else "1"
        return replacement_prefix + candidate[1:]
    if type(candidate) is bool:
        return not candidate
    if type(candidate) is int:
        return candidate + 1
    clone = _exact_dataclass_identity_clone(candidate)
    fields = vars(type(clone)).get("__dataclass_fields__")
    assert type(fields) is dict
    scalar_field = next(
        field_name
        for field_name in fields
        if type(object.__getattribute__(clone, field_name)) in {bool, int, str}
    )
    scalar = object.__getattribute__(clone, scalar_field)
    object.__setattr__(
        clone,
        scalar_field,
        _different_nested_claim_field_value(scalar),
    )
    return clone


def _mutate_nested_live_claim_field(
    claim: object,
    target_name: str,
    field_name: str,
) -> None:
    target = _nested_live_claim_target(claim, target_name)
    before = object.__getattribute__(target, field_name)
    replacement = _different_nested_claim_field_value(before)
    assert replacement is not before
    object.__setattr__(target, field_name, replacement)
    assert object.__getattribute__(target, field_name) is replacement


def _mutate_transition_live_claim_surface(
    retained_claim: RetainedTrustedTimePostEnrollmentStartClaim,
    mutation: str,
) -> None:
    if mutation == "artifact_path":
        _mutate_exact_path_to_same_parent_name(
            retained_claim.artifact_path,
            "foreign-retained-claim.json",
        )
        return
    if mutation == "artifact_file":
        artifact_path = retained_claim.artifact_path
        encoded = artifact_path.read_bytes()
        assert encoded
        replacement = bytes((encoded[0] ^ 1,)) + encoded[1:]
        assert len(replacement) == len(encoded)
        artifact_path.write_bytes(replacement)
        descriptor = os.open(artifact_path, os.O_RDONLY)
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        return
    target_name, field_name = mutation.split(":", 1)
    _mutate_nested_live_claim_field(
        retained_claim.claim,
        target_name,
        field_name,
    )


def _mutate_live_checkpoint_field(
    checkpoint: object,
    field_name: str,
    retained_claim: RetainedTrustedTimePostEnrollmentStartClaim,
) -> None:
    before = object.__getattribute__(checkpoint, field_name)
    if field_name == "retained_claim":
        replacement: object = _foreign_retained_claim_projection_view(retained_claim)
    elif type(before) is Path:
        replacement = before.parent / f"foreign-{before.name}"
    elif type(before) is str:
        replacement = "failure" if before == "success" else "foreign"
    else:
        assert type(before) is int
        replacement = before + 1
    assert replacement != before
    object.__setattr__(checkpoint, field_name, replacement)


def _overwrite_exact_dataclass_identity(target: object, source: object) -> None:
    assert type(target) is type(source)
    fields = vars(type(target)).get("__dataclass_fields__")
    assert type(fields) is dict
    for field_name in fields:
        object.__setattr__(
            target,
            field_name,
            object.__getattribute__(source, field_name),
        )


def _replace_recovery_receipt_with_foreign_durable_projection(
    receipt: recovery_outcome.RetainedTrustedTimePostEnrollmentStartOutcome,
    *,
    artifact_directory: Path,
) -> None:
    receipt.artifact_path.unlink()
    (artifact_directory / recovery_outcome.POST_ENROLLMENT_START_OUTCOME_SLOT_FILE_NAME).unlink()
    replacement = _persist_foreign_recovery_outcome(
        artifact_directory=artifact_directory,
    )
    _overwrite_exact_dataclass_identity(receipt, replacement)


def _replace_controller_receipt_with_foreign_durable_projection(
    receipt: controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome,
    retained: RetainedTrustedTimePostEnrollmentStartClaim,
    *,
    artifact_directory: Path,
    ignored_root: Path,
) -> None:
    for path in (
        receipt.artifact_path,
        artifact_directory
        / controller_outcome._POST_ENROLLMENT_START_CONTROLLER_OUTCOME_SLOT_FILE_NAME,
        artifact_directory
        / controller_outcome._POST_ENROLLMENT_START_CONTROLLER_OUTCOME_COMMIT_FILE_NAME,
    ):
        path.unlink(missing_ok=True)
    replacement = _real_prepared_controller_failure_receipt(
        _foreign_retained_claim_projection_view(retained),
        artifact_directory=artifact_directory,
    )
    controller_outcome._commit_prepared_controller_outcome(
        replacement,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )
    _overwrite_exact_dataclass_identity(receipt, replacement)


