def _active_choreography_registry() -> dict[int, tuple[object, ...]]:
    closure = inspect.getclosurevars(reader._transition_authenticated_post_effect_outcome_retention)
    return cast(dict[int, tuple[object, ...]], closure.nonlocals["active_choreographies"])


def _active_choreography_state(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
) -> tuple[object, ...]:
    return _active_choreography_registry()[id(issuer)]


def _choreography_state_raw_value(
    state: tuple[object, ...],
    name: str,
) -> object:
    return tuple.__getitem__(state, _CHOREOGRAPHY_STATE_INDEX[name])


def _choreography_state_value(state: tuple[object, ...], name: str) -> object:
    raw_value = _choreography_state_raw_value(state, name)
    expected_tag = _CHOREOGRAPHY_STATE_IDENTITY_TAG.get(name)
    expected_length = 3
    if expected_tag is None:
        expected_tag = _CHOREOGRAPHY_STATE_RECEIPT_BINDING_TAG.get(name)
        expected_length = 8
    if (
        expected_tag is None
        or raw_value is None
        or type(raw_value) is not tuple
        or len(raw_value) != expected_length
        or tuple.__getitem__(raw_value, 0) != expected_tag
    ):
        return raw_value
    reference = tuple.__getitem__(raw_value, 1)
    identity = tuple.__getitem__(raw_value, 2)
    if type(reference) is not weakref.ReferenceType or type(identity) is not int:
        return raw_value
    resolved = reference()
    return resolved if resolved is not None and id(resolved) == identity else None


def _assert_choreography_identity_slot(
    state: tuple[object, ...],
    name: str,
    expected: object,
) -> tuple[object, ...]:
    identity = _choreography_state_raw_value(state, name)
    assert type(identity) is tuple
    assert len(identity) == 3
    assert tuple.__getitem__(identity, 0) == _CHOREOGRAPHY_STATE_IDENTITY_TAG[name]
    reference = tuple.__getitem__(identity, 1)
    assert type(reference) is weakref.ReferenceType
    assert reference() is expected
    assert tuple.__getitem__(identity, 2) == id(expected)
    return identity


def _choreography_identity_witness(
    name: str,
    expected: object,
) -> tuple[object, ...]:
    return (
        _CHOREOGRAPHY_STATE_IDENTITY_TAG[name],
        weakref.ref(expected),
        id(expected),
    )


def _assert_choreography_receipt_binding_slot(
    state: tuple[object, ...],
    name: str,
    expected_receipt: object,
    *,
    receipt_projection_length: int,
    checkpoint_identity: tuple[object, ...],
    checkpoint_projection_length: int,
    claim_identity: tuple[object, ...],
) -> tuple[object, ...]:
    binding = _choreography_state_raw_value(state, name)
    assert type(binding) is tuple
    assert len(binding) == 8
    assert tuple.__getitem__(binding, 0) == (_CHOREOGRAPHY_STATE_RECEIPT_BINDING_TAG[name])
    reference = tuple.__getitem__(binding, 1)
    assert type(reference) is weakref.ReferenceType
    assert reference() is expected_receipt
    assert tuple.__getitem__(binding, 2) == id(expected_receipt)
    receipt_projection = tuple.__getitem__(binding, 3)
    assert type(receipt_projection) is tuple
    assert len(receipt_projection) == receipt_projection_length
    assert tuple.__getitem__(binding, 4) is checkpoint_identity
    checkpoint_projection = tuple.__getitem__(binding, 5)
    assert type(checkpoint_projection) is tuple
    assert len(checkpoint_projection) == checkpoint_projection_length
    assert tuple.__getitem__(binding, 6) is claim_identity
    claim_projection = tuple.__getitem__(binding, 7)
    assert type(claim_projection) is tuple
    assert len(claim_projection) == 11
    return binding


def _active_choreography_state_value(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
    name: str,
) -> object:
    return _choreography_state_value(_active_choreography_state(issuer), name)


def _choreography_binding_value(state: tuple[object, ...], name: str) -> object:
    binding = _choreography_state_value(state, "binding")
    assert type(binding) is tuple
    return tuple.__getitem__(binding, _CHOREOGRAPHY_BINDING_INDEX[name])


def _choreography_canonical_root_strings(
    state: tuple[object, ...],
) -> tuple[str, str]:
    launch_lock_binding = _choreography_binding_value(state, "launch_lock_binding")
    assert type(launch_lock_binding) is tuple
    ignored_root = tuple.__getitem__(launch_lock_binding, 2)
    artifact_directory = tuple.__getitem__(launch_lock_binding, 3)
    assert type(ignored_root) is str
    assert type(artifact_directory) is str
    return artifact_directory, ignored_root


def _tuple_with_item(
    value: tuple[object, ...],
    index: int,
    replacement: object,
) -> tuple[object, ...]:
    items = list(value)
    items[index] = replacement
    return tuple(items)


def _tuple_tree_contains_identity(value: object, expected: object) -> bool:
    if value is expected:
        return True
    if type(value) is not tuple:
        return False
    return any(
        _tuple_tree_contains_identity(item, expected) for item in cast(tuple[object, ...], value)
    )


def _choreography_state_with_item(
    state: tuple[object, ...],
    name: str,
    replacement: object,
) -> tuple[object, ...]:
    return _tuple_with_item(state, _CHOREOGRAPHY_STATE_INDEX[name], replacement)


def _choreography_state_with_binding_item(
    state: tuple[object, ...],
    name: str,
    replacement: object,
) -> tuple[object, ...]:
    binding = _choreography_state_value(state, "binding")
    assert type(binding) is tuple
    forged_binding = _tuple_with_item(
        binding,
        _CHOREOGRAPHY_BINDING_INDEX[name],
        replacement,
    )
    return _choreography_state_with_item(state, "binding", forged_binding)


def _choreography_cas_test_seams() -> tuple[
    Callable[..., None],
    Callable[..., tuple[object, ...]],
    Callable[[Callable[[], object]], object],
    Callable[[object, object], bool],
]:
    closure = inspect.getclosurevars(reader._transition_authenticated_post_effect_outcome_retention)
    compare_and_swap = cast(
        Callable[..., None],
        closure.nonlocals["compare_and_swap_choreography_state_locked"],
    )
    build_candidate = cast(
        Callable[..., tuple[object, ...]],
        closure.nonlocals["build_choreography_state_candidate"],
    )
    run_under_registry_lock = cast(
        Callable[[Callable[[], object]], object],
        closure.nonlocals["run_under_registry_lock"],
    )
    state_validator = cast(
        Callable[[object, object], bool],
        inspect.getclosurevars(compare_and_swap).nonlocals["choreography_state_is_exact"],
    )
    return compare_and_swap, build_candidate, run_under_registry_lock, state_validator


def _choreography_lifecycle_test_seams() -> tuple[
    dict[int, tuple[object, ...]],
    Callable[[Callable[[], object]], object],
]:
    closure = inspect.getclosurevars(reader._authenticated_issuer_scope_is_live)
    lifecycle_for_owner_locked = cast(
        Callable[..., object],
        closure.nonlocals["lifecycle_for_owner_locked"],
    )
    lifecycle_closure = inspect.getclosurevars(lifecycle_for_owner_locked)
    lifecycles = cast(
        dict[int, tuple[object, ...]],
        lifecycle_closure.nonlocals["issuer_lifecycles"],
    )
    run_under_registry_lock = cast(
        Callable[[Callable[[], object]], object],
        closure.nonlocals["run_under_registry_lock"],
    )
    return lifecycles, run_under_registry_lock


def _assert_choreography_authority_is_burned(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
) -> None:
    assert id(issuer) not in _active_choreography_registry()
    lifecycle_registry, run_under_registry_lock = _choreography_lifecycle_test_seams()
    lifecycle = run_under_registry_lock(lambda: lifecycle_registry[id(issuer)])
    assert type(lifecycle) is tuple
    assert tuple.__getitem__(lifecycle, 4) == "burned"
    assert tuple.__getitem__(lifecycle, 7) == ()
    assert tuple.__getitem__(lifecycle, 8) is None
    assert issuer._authentication_capability is None
    assert issuer._choreography_inflight is False
    assert issuer._choreography_scope_nonce is None
    assert issuer._poisoned is True


def _authenticated_choreography_scope_kwdefaults() -> dict[str, object]:
    issuer_type = reader.TrustedTimePostEnrollmentTopologyObservationIssuer
    defaults = issuer_type._run_authenticated_choreography_scope.__kwdefaults__
    assert defaults is not None
    return defaults


def _authenticated_choreography_scope_method() -> FunctionType:
    issuer_type = reader.TrustedTimePostEnrollmentTopologyObservationIssuer
    method = issuer_type._run_authenticated_choreography_scope
    assert type(method) is FunctionType
    return method


def _instruction_offset(
    callable_object: Callable[..., object] | CodeType,
    *,
    opname: str,
    argval: object,
    occurrence: Literal["first", "last"] = "first",
) -> int:
    """Locate one exact bytecode boundary used by async-interruption tests."""

    matching = [
        instruction.offset
        for instruction in dis.get_instructions(callable_object)
        if instruction.opname == opname and instruction.argval == argval
    ]
    assert matching
    return matching[0] if occurrence == "first" else matching[-1]


def _offset_after_instruction(
    callable_object: Callable[..., object] | CodeType,
    *,
    opname: str,
    argval: object,
    occurrence: Literal["first", "last"] = "first",
) -> int:
    instructions = list(dis.get_instructions(callable_object))
    matching = [
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname == opname and instruction.argval == argval
    ]
    assert matching
    index = matching[0] if occurrence == "first" else matching[-1]
    return instructions[index + 1].offset


def _call_return_offset(
    callable_object: Callable[..., object] | CodeType,
    *,
    callable_name: str,
    occurrence: Literal["first", "last"] = "first",
) -> int:
    instructions = list(dis.get_instructions(callable_object))
    call_returns: list[int] = []
    for load_index, instruction in enumerate(instructions):
        if instruction.opname not in {
            "LOAD_ATTR",
            "LOAD_DEREF",
            "LOAD_FAST",
            "LOAD_GLOBAL",
            "LOAD_METHOD",
        }:
            continue
        if instruction.argval != callable_name:
            continue
        call_index = next(
            index
            for index in range(load_index + 1, len(instructions))
            if instructions[index].opname == "CALL"
        )
        call_returns.append(instructions[call_index + 1].offset)
    assert call_returns
    return call_returns[0] if occurrence == "first" else call_returns[-1]


def _nested_code(
    callable_object: Callable[..., object] | CodeType,
    name: str,
) -> CodeType:
    root = callable_object if type(callable_object) is CodeType else callable_object.__code__
    pending = [root]
    while pending:
        candidate = pending.pop()
        if candidate.co_name == name:
            return candidate
        pending.extend(constant for constant in candidate.co_consts if type(constant) is CodeType)
    raise AssertionError(f"nested code {name!r} is unavailable")


def _nested_code_containing_instruction_names(
    callable_object: Callable[..., object] | CodeType,
    *required_names: str,
) -> CodeType:
    root = callable_object if type(callable_object) is CodeType else callable_object.__code__
    pending = [root]
    matches: list[CodeType] = []
    while pending:
        candidate = pending.pop()
        instruction_names = {
            instruction.argval
            for instruction in dis.get_instructions(candidate)
            if type(instruction.argval) is str
        }
        if all(name in instruction_names for name in required_names):
            matches.append(candidate)
        pending.extend(constant for constant in candidate.co_consts if type(constant) is CodeType)
    assert len(matches) == 1
    return matches[0]


def _code_containing_handler_gap(
    callable_object: Callable[..., object] | CodeType,
    *,
    validation_callable_name: str,
    error_name: str,
) -> CodeType:
    """Find the exact nested dispatcher that owns one validation handler."""

    root = callable_object if type(callable_object) is CodeType else callable_object.__code__
    pending = [root]
    matches: list[CodeType] = []
    while pending:
        candidate = pending.pop()
        instructions = list(dis.get_instructions(candidate))
        names = {
            instruction.argval for instruction in instructions if type(instruction.argval) is str
        }
        if validation_callable_name in names and any(
            instruction.opname in {"STORE_DEREF", "STORE_FAST"} and instruction.argval == error_name
            for instruction in instructions
        ):
            matches.append(candidate)
        pending.extend(constant for constant in candidate.co_consts if type(constant) is CodeType)
    assert len(matches) == 1
    return matches[0]


def _reader_handler_gap_offset(
    target: CodeType,
    *,
    error_name: str,
    boundary: str,
) -> int:
    """Locate the logical except-target, POP_EXCEPT, or cleanup handoff."""

    instructions = list(dis.get_instructions(target))
    error_store_indices = [
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname in {"STORE_DEREF", "STORE_FAST"} and instruction.argval == error_name
    ]
    assert len(error_store_indices) >= 2
    handler_store_index = error_store_indices[-1]
    if boundary == "handler_error_store":
        return instructions[handler_store_index].offset
    pop_except_index = next(
        index
        for index in range(handler_store_index + 1, len(instructions))
        if instructions[index].opname == "POP_EXCEPT"
    )
    if boundary == "handler_pop_except":
        return instructions[pop_except_index].offset
    assert boundary == "handler_cleanup_handoff"
    handoff_index = next(
        index
        for index in range(pop_except_index + 1, len(instructions))
        if instructions[index].opname.startswith("JUMP")
    )
    return instructions[handoff_index].offset


def _choreography_registration_commit_code(
    registrar: Callable[..., object],
) -> CodeType:
    for name in (
        "commit_choreography_registration_locked",
        "register_choreography_locked",
    ):
        try:
            return _nested_code(registrar, name)
        except AssertionError:
            pass
    raise AssertionError("choreography registration commit code is unavailable")


def _choreography_material_builder_code(
    registrar: Callable[..., object],
) -> CodeType:
    nonlocals = inspect.getclosurevars(registrar).nonlocals
    candidate = nonlocals.get("build_choreography_lease_sha256")
    if callable(candidate) and hasattr(candidate, "__code__"):
        return cast(Callable[..., object], candidate).__code__
    return _nested_code_containing_instruction_names(
        registrar,
        "token_bytes",
        "canonical_first_enrollment_json_bytes",
    )


def _choreography_material_callable_name(
    target: CodeType,
    captured_name: str,
    legacy_name: str,
) -> str:
    instruction_names = {
        instruction.argval
        for instruction in dis.get_instructions(target)
        if type(instruction.argval) is str
    }
    if captured_name in instruction_names:
        return captured_name
    assert legacy_name in instruction_names
    return legacy_name


def _outer_cleanup_attempt_call_indices(target: CodeType) -> list[int]:
    instructions = list(dis.get_instructions(target))
    first_load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname == "LOAD_FAST" and instruction.argval == "cleanup_after_body_attempt"
    )
    terminal_reduction_index = next(
        index
        for index in range(first_load_index + 1, len(instructions))
        if instructions[index].argval == "_preferred"
    )
    load_indices = [
        index
        for index in range(first_load_index, terminal_reduction_index)
        if instructions[index].opname == "LOAD_FAST"
        and instructions[index].argval == "cleanup_after_body_attempt"
    ]
    assert len(load_indices) == 4
    return [
        next(
            index
            for index in range(load_index + 1, terminal_reduction_index)
            if instructions[index].opname == "CALL"
        )
        for load_index in load_indices
    ]


def _open_descriptor_count() -> int:
    descriptor_root = Path("/dev/fd") if Path("/dev/fd").is_dir() else Path("/proc/self/fd")
    return len(os.listdir(descriptor_root))


def _enable_instruction_interrupt(
    callable_object: Callable[..., object] | CodeType,
    offset: int,
    *,
    tool_name: str,
    interruption: BaseException | None = None,
) -> int:
    """Raise once immediately before the selected instruction executes."""

    target_code = callable_object if type(callable_object) is CodeType else callable_object.__code__
    injected = False

    def interrupt(_: object, instruction_offset: int) -> None:
        nonlocal injected
        if not injected and instruction_offset == offset:
            injected = True
            raise interruption if interruption is not None else KeyboardInterrupt

    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(tool_id, tool_name)
    sys.monitoring.register_callback(
        tool_id,
        sys.monitoring.events.INSTRUCTION,
        interrupt,
    )
    sys.monitoring.set_local_events(
        tool_id,
        target_code,
        sys.monitoring.events.INSTRUCTION,
    )
    return tool_id


def _disable_instruction_interrupt(
    tool_id: int,
    callable_object: Callable[..., object] | CodeType,
) -> None:
    target_code = callable_object if type(callable_object) is CodeType else callable_object.__code__
    sys.monitoring.set_local_events(tool_id, target_code, 0)
    sys.monitoring.register_callback(tool_id, sys.monitoring.events.INSTRUCTION, None)
    sys.monitoring.free_tool_id(tool_id)


def _enable_instruction_callback(
    callable_object: Callable[..., object] | CodeType,
    offset: int,
    *,
    tool_name: str,
    callback: Callable[[], None],
) -> int:
    target_code = callable_object if type(callable_object) is CodeType else callable_object.__code__
    injected = False

    def invoke_once(_: object, instruction_offset: int) -> None:
        nonlocal injected
        if not injected and instruction_offset == offset:
            injected = True
            callback()

    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(tool_id, tool_name)
    sys.monitoring.register_callback(
        tool_id,
        sys.monitoring.events.INSTRUCTION,
        invoke_once,
    )
    sys.monitoring.set_local_events(
        tool_id,
        target_code,
        sys.monitoring.events.INSTRUCTION,
    )
    return tool_id


def _enable_validation_then_handler_interrupt(
    target: CodeType,
    *,
    validation_return_offset: int,
    handler_offset: int,
    interruption: BaseException,
    tool_name: str,
) -> tuple[int, list[str]]:
    """Raise an ordinary validation error, then one exact handler control."""

    observed: list[str] = []

    def interrupt_in_order(_: object, instruction_offset: int) -> None:
        if not observed and instruction_offset == validation_return_offset:
            observed.append("validation")
            raise RuntimeError("injected sealed validation failure")
        if observed == ["validation"] and instruction_offset == handler_offset:
            observed.append("handler")
            raise interruption

    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(tool_id, tool_name)
    sys.monitoring.register_callback(
        tool_id,
        sys.monitoring.events.INSTRUCTION,
        interrupt_in_order,
    )
    sys.monitoring.set_local_events(
        tool_id,
        target,
        sys.monitoring.events.INSTRUCTION,
    )
    return tool_id, observed


def _transition_registered_post_effect_retention(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
    lease: object,
    recovery_capability: object,
    retained: RetainedTrustedTimePostEnrollmentStartClaim,
    *,
    artifact_directory: Path,
    ignored_root: Path,
) -> reader._TrustedTimePostEnrollmentPostEffectOutcomeCapability:
    _bind_registered_recovery_claim(
        issuer,
        lease,
        recovery_capability,
        retained,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )
    candidate = issuer._issue_post_effect_outcome_retention_candidate()
    issuer._transition_to_post_effect_outcome_retention(
        lease,
        recovery_capability,
        retained,
        post_effect_outcome_candidate=candidate,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )
    return candidate


def _confirmed_controller_receipt(
    artifact_directory: Path,
) -> controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome:
    retained = object.__new__(
        controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome
    )
    object.__setattr__(
        retained,
        "status",
        controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeStatus.CONFIRMED,
    )
    object.__setattr__(
        retained,
        "reason",
        controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.POST_ENROLLMENT_START_CONFIRMED,
    )
    object.__setattr__(retained, "artifact_path", artifact_directory / "exact-receipt.json")
    object.__setattr__(retained, "commit_file_identity", None)
    object.__setattr__(
        retained,
        "_prepared_marker",
        controller_outcome._PREPARED_OUTCOME_RECEIPT_MARKER,
    )
    _populate_synthetic_controller_receipt_projection(retained)
    return retained


def _recovery_controller_receipt(
    artifact_directory: Path,
    *,
    reason: controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason = (
        controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.SEQUENCE_TWO_UNCONFIRMED
    ),
) -> controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome:
    retained = object.__new__(
        controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome
    )
    object.__setattr__(
        retained,
        "status",
        controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeStatus.RECOVERY_REQUIRED,
    )
    object.__setattr__(retained, "reason", reason)
    object.__setattr__(retained, "artifact_path", artifact_directory / "exact-failure.json")
    object.__setattr__(retained, "commit_file_identity", None)
    object.__setattr__(
        retained,
        "_prepared_marker",
        controller_outcome._PREPARED_OUTCOME_RECEIPT_MARKER,
    )
    _populate_synthetic_controller_receipt_projection(retained)
    return retained


def _populate_synthetic_controller_receipt_projection(
    receipt: controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome,
) -> None:
    object.__setattr__(receipt, "active_controller_admission_sha256", "a" * 64)
    object.__setattr__(
        receipt,
        "contract_version",
        (controller_outcome.POST_ENROLLMENT_START_RETAINED_CONTROLLER_OUTCOME_V1_CONTRACT_VERSION),
    )
    object.__setattr__(receipt, "durable_shutdown_locator", None)
    object.__setattr__(receipt, "durable_shutdown_locator_sha256", None)
    outcome_sha256 = "b" * 64
    object.__setattr__(receipt, "outcome_sha256", outcome_sha256)
    artifact_path = cast(Path, receipt.artifact_path)
    object.__setattr__(
        receipt,
        "artifact_path",
        artifact_path.parent / controller_outcome._outcome_file_name(outcome_sha256),
    )
    object.__setattr__(receipt, "encoded", b"synthetic-controller-outcome")
    object.__setattr__(
        receipt,
        "file_identity",
        (1, 2, 3, 4, 5, 6, 7, 8, 9),
    )
    object.__setattr__(
        receipt,
        "slot_file_identity",
        (9, 8, 7, 6, 5, 4, 3, 2, 1),
    )
    object.__setattr__(receipt, "_evidence", None)


def _bind_synthetic_controller_receipt_to_claim(
    receipt: controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome,
    retained_claim: RetainedTrustedTimePostEnrollmentStartClaim,
) -> controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome:
    """Populate the exact immutable claim projection used by terminal adoption."""

    object.__setattr__(receipt, "operation_id", retained_claim.operation_id)
    object.__setattr__(
        receipt,
        "approval_sha256",
        retained_claim.claim.approval.approval_sha256,
    )
    object.__setattr__(receipt, "claim_sha256", retained_claim.claim.claim_sha256)
    object.__setattr__(
        receipt,
        "retained_claim_artifact_sha256",
        retained_claim.artifact_sha256,
    )
    return receipt


def _real_prepared_controller_receipt(
    retained_claim: RetainedTrustedTimePostEnrollmentStartClaim,
    *,
    artifact_directory: Path,
    status: controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeStatus,
    reason: controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason,
) -> controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome:
    confirmed = (
        status is controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeStatus.CONFIRMED
    )
    release_confirmed = reason is not (
        controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.RELEASE_OUTCOME_UNCONFIRMED
    )
    sequence_confirmed = reason in {
        controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.POST_ENROLLMENT_START_CONFIRMED,
        controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.SUCCESS_OUTCOME_UNCONFIRMED,
    }
    topology_qualified = sequence_confirmed
    verification_confirmed = sequence_confirmed
    assert confirmed is (
        reason
        is (
            controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.POST_ENROLLMENT_START_CONFIRMED
        )
    )
    assert confirmed or status is (
        controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeStatus.RECOVERY_REQUIRED
    )
    contract_version = (
        controller_outcome.POST_ENROLLMENT_START_RETAINED_CONTROLLER_OUTCOME_V1_CONTRACT_VERSION
    )
    payload: dict[str, object] = {
        field_name: False for field_name in controller_outcome.FIRST_ENROLLMENT_AUTHORITY_FIELDS
    }
    payload.update({field_name: False for field_name in controller_outcome._CLOSED_FIELDS})
    payload.update(
        {
            "active_controller_admission_sha256": "a" * 64,
            "approval_sha256": retained_claim.claim.approval.approval_sha256,
            "claim_retention_revalidated": True,
            "claim_sha256": retained_claim.claim.claim_sha256,
            "contract_version": contract_version,
            "controller_execution_confirmed": confirmed,
            "operation_id": retained_claim.operation_id,
            "pre_effect_observation_sha256": "b" * 64,
            "persistent_start_confirmed": topology_qualified,
            "persistent_topology_transcript_sha256": ("2" * 64 if topology_qualified else None),
            "persistent_topology_sha256": "1" * 64 if topology_qualified else None,
            "qualified": confirmed,
            "read_only_configuration_sha256": "c" * 64,
            "reason": reason.value,
            "release_attempted": True,
            "release_confirmed": release_confirmed,
            "release_execution_sha256": "e" * 64 if release_confirmed else None,
            "retained_claim_artifact_sha256": retained_claim.artifact_sha256,
            "runtime_start_confirmed": sequence_confirmed,
            "runtime_state_sha256": "f" * 64 if sequence_confirmed else None,
            "sequence_2_confirmed": sequence_confirmed,
            "service": (
                controller_outcome.POST_ENROLLMENT_START_RETAINED_CONTROLLER_OUTCOME_SERVICE
            ),
            "source_start_confirmed": True,
            "status": status.value,
            "success_outcome_retained": confirmed,
            "successor_candidate_sha256": "0" * 64 if sequence_confirmed else None,
            "supervisor_start_confirmed": True,
            "topology_qualified": topology_qualified,
            "verification_transcript_sha256": ("3" * 64 if verification_confirmed else None),
            "verifier_binding_sha256": "d" * 64,
        }
    )
    encoded = controller_outcome.canonical_first_enrollment_json_bytes(payload)
    outcome_sha256 = hashlib.sha256(encoded).hexdigest()
    artifact_path = artifact_directory / controller_outcome._outcome_file_name(outcome_sha256)
    slot_path = (
        artifact_directory
        / controller_outcome._POST_ENROLLMENT_START_CONTROLLER_OUTCOME_SLOT_FILE_NAME
    )
    artifact_path.write_bytes(encoded)
    artifact_path.chmod(0o600)
    slot_path.write_bytes(
        controller_outcome._slot_bytes(
            outcome_sha256,
            contract_version=contract_version,
        )
    )
    slot_path.chmod(0o600)
    receipt = controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome(
        operation_id=retained_claim.operation_id,
        approval_sha256=retained_claim.claim.approval.approval_sha256,
        claim_sha256=retained_claim.claim.claim_sha256,
        retained_claim_artifact_sha256=retained_claim.artifact_sha256,
        active_controller_admission_sha256="a" * 64,
        contract_version=contract_version,
        status=status,
        reason=reason,
        durable_shutdown_locator=None,
        durable_shutdown_locator_sha256=None,
        outcome_sha256=outcome_sha256,
        artifact_path=artifact_path,
        encoded=encoded,
        file_identity=controller_outcome._stable_file_identity(artifact_path.stat()),
        slot_file_identity=controller_outcome._stable_file_identity(slot_path.stat()),
        commit_file_identity=None,
        _prepared_marker=controller_outcome._PREPARED_OUTCOME_RECEIPT_MARKER,
        _evidence=None,
    )
    assert controller_outcome._revalidate_prepared_controller_outcome(
        receipt,
        artifact_directory=artifact_directory,
        ignored_root=artifact_directory.parent,
    )
    return receipt


def _real_prepared_controller_success_receipt(
    retained_claim: RetainedTrustedTimePostEnrollmentStartClaim,
    *,
    artifact_directory: Path,
) -> controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome:
    return _real_prepared_controller_receipt(
        retained_claim,
        artifact_directory=artifact_directory,
        status=(controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeStatus.CONFIRMED),
        reason=(
            controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.POST_ENROLLMENT_START_CONFIRMED
        ),
    )


def _real_prepared_controller_failure_receipt(
    retained_claim: RetainedTrustedTimePostEnrollmentStartClaim,
    *,
    artifact_directory: Path,
    reason: controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason = (
        controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.RELEASE_OUTCOME_UNCONFIRMED
    ),
) -> controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome:
    return _real_prepared_controller_receipt(
        retained_claim,
        artifact_directory=artifact_directory,
        status=(
            controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeStatus.RECOVERY_REQUIRED
        ),
        reason=reason,
    )


def _complete_and_commit_controller_receipt(
    issuer: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
    lease: object,
    recovery_capability: object,
    retained_claim: RetainedTrustedTimePostEnrollmentStartClaim,
    receipt: controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome,
    *,
    outcome_kind: Literal["success", "failure"],
    artifact_directory: Path,
    ignored_root: Path,
) -> None:
    post_effect_capability = _transition_registered_post_effect_retention(
        issuer,
        lease,
        recovery_capability,
        retained_claim,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )
    checkpoint = issuer._begin_post_effect_controller_outcome_retention(
        post_effect_capability,
        lease,
        retained_claim,
        outcome_kind=outcome_kind,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )
    issuer._complete_post_effect_controller_outcome_retention(
        post_effect_capability,
        checkpoint,
        receipt,
    )
    controller_outcome._commit_prepared_controller_outcome(
        receipt,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )


def _mutate_terminal_receipt_projection(
    receipt: object,
    projection: str,
    *,
    foreign_root: Path,
) -> None:
    if projection == "artifact_path_parent":
        artifact_path = cast(Path, receipt.artifact_path)
        replacement_directory = foreign_root / "trusted-time"
        replacement_directory.mkdir(parents=True, exist_ok=True)
        object.__setattr__(
            receipt,
            "artifact_path",
            replacement_directory / artifact_path.name,
        )
        return
    current = cast(str, getattr(receipt, projection))
    replacement = (
        "foreign-operation-id"
        if projection == "operation_id"
        else ("e" * 64 if current != "e" * 64 else "f" * 64)
    )
    object.__setattr__(receipt, projection, replacement)


def _mutate_exact_path_to_same_parent_name(candidate: Path, replacement_name: str) -> None:
    original_parent = candidate.parent
    original_value = os.fspath(candidate)
    replacement = original_parent / replacement_name
    replacement_value = os.fspath(replacement)
    assert replacement_value != original_value
    raw_paths = cast(list[str], object.__getattribute__(candidate, "_raw_paths"))
    raw_paths[:] = [replacement_value]
    object.__setattr__(candidate, "_str", replacement_value)
    assert candidate.parent == original_parent
    assert os.fspath(candidate) == replacement_value


def _interrupt_next_choreography_action_result_store(
    interruption_type: type[BaseException] = KeyboardInterrupt,
) -> Callable[[], None]:
    """Interrupt exactly after the recovery-retention callback CALL returns."""

    issuer_type = reader.TrustedTimePostEnrollmentTopologyObservationIssuer
    target_code = _nested_code(
        issuer_type._run_authenticated_choreography_scope,
        "execute_authenticated_body",
    )
    instructions = list(dis.get_instructions(target_code))
    target_offset = next(
        instruction.offset
        for index, instruction in enumerate(instructions)
        if instruction.opname == "STORE_DEREF"
        and instruction.argval == "result"
        and index > 0
        and instructions[index - 1].opname == "CALL"
    )
    return _interrupt_exact_instruction(
        target_code,
        target_offset,
        tool_name="trusted-time-terminal-action-return-test",
        interruption_type=interruption_type,
    )


def _interrupt_exact_instruction(
    target_code: Any,
    target_offset: int,
    *,
    tool_name: str,
    interruption_type: type[BaseException] = KeyboardInterrupt,
    interruption: BaseException | None = None,
) -> Callable[[], None]:
    """Install one self-verifying instruction-boundary interruption."""

    injected = False
    retained_interruption = interruption_type() if interruption is None else interruption
    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(tool_id, tool_name)

    def interrupt(code: object, instruction_offset: int) -> None:
        nonlocal injected
        if not injected and code is target_code and instruction_offset == target_offset:
            injected = True
            raise retained_interruption

    sys.monitoring.register_callback(
        tool_id,
        sys.monitoring.events.INSTRUCTION,
        interrupt,
    )
    sys.monitoring.set_local_events(
        tool_id,
        target_code,
        sys.monitoring.events.INSTRUCTION,
    )

    def close() -> None:
        sys.monitoring.set_local_events(tool_id, target_code, 0)
        sys.monitoring.register_callback(tool_id, sys.monitoring.events.INSTRUCTION, None)
        sys.monitoring.free_tool_id(tool_id)
        assert injected is True

    return close


