def _native_authority_state_vector(
    lifecycle_phase: str,
    state_phase: str | None,
    action_active: bool,
    *,
    claim: bool = False,
    binder: bool = False,
    recovery_checkpoint: bool = False,
    recovery_receipt: Literal["none", "prepared", "durable"] = "none",
    post_effect_capability: bool = False,
    controller_checkpoint: bool = False,
    controller_receipt: Literal["none", "prepared", "durable"] = "none",
) -> tuple[object, ...]:
    return (
        _NATIVE_AUTHORITY_STATE_TAG,
        lifecycle_phase,
        state_phase,
        action_active,
        claim,
        binder,
        recovery_checkpoint,
        recovery_receipt,
        post_effect_capability,
        controller_checkpoint,
        controller_receipt,
    )


def _native_authority_transition_vector(
    name: str,
    before: tuple[object, ...],
    after: tuple[object, ...],
    *,
    boundary: str,
    primary_error: Literal["none", "ordinary", "keyboard_interrupt", "system_exit"],
    cleanup_error: Literal["none", "ordinary", "keyboard_interrupt", "system_exit"],
    cleanup_disposition: str,
    return_disposition: str,
    selected_error: Literal["none", "ordinary", "keyboard_interrupt", "system_exit"],
    exact_primary: bool,
) -> tuple[object, ...]:
    return (
        _NATIVE_AUTHORITY_VECTOR_TAG,
        name,
        before,
        boundary,
        primary_error,
        cleanup_error,
        after,
        cleanup_disposition,
        return_disposition,
        selected_error,
        exact_primary,
    )


