def _native_callback_vector(
    name: str,
    callback_kind: Literal["runner", "caller_action", "retained_claim_sink"],
    *,
    candidate_identity_exact: bool,
    output_valid: bool,
    current_revision: int,
    expected_revision: int,
    callback_error: Literal["none", "ordinary", "keyboard_interrupt", "system_exit"],
    cleanup_error: Literal["none", "ordinary", "keyboard_interrupt", "system_exit"],
    disposition: str,
    selected_error: Literal["none", "ordinary", "keyboard_interrupt", "system_exit"],
    selected_source: Literal["none", "callback", "cleanup"],
    exact_selected_identity: bool,
) -> tuple[object, ...]:
    return (
        _NATIVE_CALLBACK_VECTOR_TAG,
        name,
        callback_kind,
        0,
        candidate_identity_exact,
        output_valid,
        current_revision,
        expected_revision,
        callback_error,
        cleanup_error,
        disposition,
        selected_error,
        selected_source,
        exact_selected_identity,
        False,
    )


