def _native_issuer_stat9(path: str) -> tuple[int, ...]:
    metadata = os.stat(path, follow_symlinks=False)
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_uid,
        metadata.st_gid,
        metadata.st_nlink,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


def _native_issuer_stat5(path: str) -> tuple[int, ...]:
    metadata = os.stat(path, follow_symlinks=False)
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_uid,
        metadata.st_gid,
    )


def _native_issuer_checkpoint_l_u64(value: int) -> bytes:
    assert type(value) is int and 0 <= value <= (1 << 64) - 1
    return value.to_bytes(8, "big", signed=False)


def _native_issuer_checkpoint_l_i64(value: int) -> bytes:
    assert type(value) is int and -(1 << 63) <= value <= (1 << 63) - 1
    return value.to_bytes(8, "big", signed=True)


def _native_issuer_checkpoint_l_checked_nanoseconds(
    seconds: int,
    nanoseconds: int,
) -> int:
    assert type(seconds) is int and type(nanoseconds) is int
    if not 0 <= nanoseconds < 1_000_000_000:
        raise OverflowError("nanosecond component is outside the canonical range")
    value = seconds * 1_000_000_000 + nanoseconds
    if not -(2**63) <= value < 2**63:
        raise OverflowError("nanosecond timestamp is outside signed int64")
    return value


def _native_issuer_checkpoint_l_bytes(value: bytes) -> bytes:
    assert type(value) is bytes
    return _native_issuer_checkpoint_l_u64(len(value)) + value


def _native_issuer_checkpoint_l_text(value: str) -> bytes:
    assert type(value) is str
    encoded = value.encode("utf-8", "strict")
    assert b"\0" not in encoded
    return _native_issuer_checkpoint_l_bytes(encoded)


def _native_issuer_checkpoint_l_hex(value: str) -> bytes:
    assert (
        type(value) is str
        and len(value) == 64
        and value == value.lower()
        and set(value) <= set("0123456789abcdef")
    )
    return _native_issuer_checkpoint_l_bytes(value.encode("ascii", "strict"))


def _native_issuer_checkpoint_l_key(value: tuple[int, int, int]) -> bytes:
    assert type(value) is tuple and len(value) == 3
    return b"".join(_native_issuer_checkpoint_l_u64(item) for item in value)


def _native_issuer_checkpoint_l_stat5(value: tuple[int, ...]) -> bytes:
    assert type(value) is tuple and len(value) == 5
    return b"".join(_native_issuer_checkpoint_l_u64(item) for item in value)


def _native_issuer_checkpoint_l_stat9(value: tuple[int, ...]) -> bytes:
    assert type(value) is tuple and len(value) == 9
    return b"".join(
        (
            _native_issuer_checkpoint_l_stat5(value[:5]),
            _native_issuer_checkpoint_l_u64(value[5]),
            _native_issuer_checkpoint_l_i64(value[6]),
            _native_issuer_checkpoint_l_i64(value[7]),
            _native_issuer_checkpoint_l_i64(value[8]),
        )
    )


def _native_issuer_checkpoint_l_artifact_link_count_transition_is_exact(
    prepared: int,
    durable: int,
) -> bool:
    unsigned_maximum = 2**64 - 1
    assert type(prepared) is int and type(durable) is int
    if not (1 <= prepared <= unsigned_maximum and 1 <= durable <= unsigned_maximum):
        return False
    return durable == prepared or (prepared != unsigned_maximum and durable == prepared + 1)


def _native_issuer_checkpoint_l_digest(domain: str, *fields: bytes) -> str:
    assert type(domain) is str and domain in _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_DOMAINS
    encoded_domain = domain.encode("ascii", "strict")
    assert b"\0" not in encoded_domain
    assert all(type(field) is bytes for field in fields)
    return hashlib.sha256(encoded_domain + b"\0" + b"".join(fields)).hexdigest()


def _native_issuer_checkpoint_l_path_digest(
    root_identity: tuple[int, ...],
    components: tuple[tuple[bytes, tuple[int, ...]], ...],
) -> str:
    assert type(components) is tuple and 1 <= len(components) <= 257
    assert len(components) + 1 <= 258
    total_bytes = 1
    encoded = [
        _native_issuer_checkpoint_l_u64(len(components) + 1),
        _native_issuer_checkpoint_l_bytes(b"/"),
        _native_issuer_checkpoint_l_stat5(root_identity),
    ]
    for raw_name, identity in components:
        assert type(raw_name) is bytes and 1 <= len(raw_name) <= 255
        assert b"/" not in raw_name and b"\0" not in raw_name
        total_bytes += len(raw_name) + 1
        encoded.extend(
            (
                _native_issuer_checkpoint_l_bytes(raw_name),
                _native_issuer_checkpoint_l_stat5(identity),
            )
        )
    assert total_bytes <= 4095
    return _native_issuer_checkpoint_l_digest(
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_DOMAINS[0],
        *encoded,
    )


def _native_issuer_checkpoint_l_inventory_digest(
    entries: tuple[tuple[bytes, tuple[int, ...]], ...],
    *,
    reserve_commit: bool,
) -> tuple[int, int, str]:
    assert type(entries) is tuple and type(reserve_commit) is bool
    ordered = tuple(sorted(entries, key=lambda entry: entry[0]))
    names = tuple(name for name, _identity in ordered)
    assert all(
        type(name) is bytes
        and 1 <= len(name) <= 255
        and name not in {b".", b".."}
        and b"/" not in name
        and b"\0" not in name
        for name in names
    )
    assert len(names) == len(set(names))
    total_name_bytes = sum(map(len, names))
    commit_name_bytes = len(
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_COMMIT_BASENAME.encode("ascii", "strict")
    )
    if reserve_commit:
        assert len(ordered) <= 4095
        assert total_name_bytes <= 1024 * 1024 - commit_name_bytes
    else:
        assert len(ordered) <= 4096
        assert total_name_bytes <= 1024 * 1024
    fields = [
        _native_issuer_checkpoint_l_u64(len(ordered)),
        _native_issuer_checkpoint_l_u64(total_name_bytes),
    ]
    for name, identity in ordered:
        fields.extend(
            (
                _native_issuer_checkpoint_l_bytes(name),
                _native_issuer_checkpoint_l_stat9(identity),
            )
        )
    return (
        len(ordered),
        total_name_bytes,
        _native_issuer_checkpoint_l_digest(
            _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_DOMAINS[1],
            *fields,
        ),
    )


def _native_issuer_checkpoint_l_projection5(value: tuple[object, ...]) -> bytes:
    assert type(value) is tuple and len(value) == 5
    return b"".join(
        (
            _native_issuer_checkpoint_l_text(cast(str, value[0])),
            _native_issuer_checkpoint_l_hex(cast(str, value[1])),
            _native_issuer_checkpoint_l_hex(cast(str, value[2])),
            _native_issuer_checkpoint_l_hex(cast(str, value[3])),
            _native_issuer_checkpoint_l_text(cast(str, value[4])),
        )
    )


def _native_issuer_checkpoint_l_claim_summary(value: tuple[object, ...]) -> bytes:
    assert type(value) is tuple and len(value) == 3
    return b"".join(
        (
            _native_issuer_checkpoint_l_key(cast(tuple[int, int, int], value[0])),
            _native_issuer_checkpoint_l_projection5(cast(tuple[object, ...], value[1])),
            _native_issuer_checkpoint_l_hex(cast(str, value[2])),
        )
    )


def _native_issuer_checkpoint_l_checkpoint_summary(value: tuple[object, ...]) -> bytes:
    assert type(value) is tuple and len(value) == 2
    projection = cast(tuple[object, ...], value[1])
    assert type(projection) is tuple and len(projection) == 8
    outcome_kind = cast(str, projection[1])
    assert outcome_kind in {"success", "failure"}
    return b"".join(
        (
            _native_issuer_checkpoint_l_key(cast(tuple[int, int, int], value[0])),
            _native_issuer_checkpoint_l_key(cast(tuple[int, int, int], projection[0])),
            _native_issuer_checkpoint_l_u64(0 if outcome_kind == "success" else 1),
            _native_issuer_checkpoint_l_text(cast(str, projection[2])),
            _native_issuer_checkpoint_l_text(cast(str, projection[3])),
            *(_native_issuer_checkpoint_l_u64(cast(int, item)) for item in projection[4:8]),
        )
    )


def _native_issuer_checkpoint_l_prepared_receipt_summary(
    value: tuple[object, ...],
) -> bytes:
    assert type(value) is tuple and len(value) in {5, 6}
    assert value[1] == "prepared"
    if len(value) == 6:
        assert value[5] is None
    projection = cast(tuple[object, ...], value[2])
    assert type(projection) is tuple and len(projection) == 7
    locator = projection[6]
    encoded_locator = (
        _native_issuer_checkpoint_l_hex(cast(str, locator))
        if locator is not None
        else _native_issuer_checkpoint_l_bytes(b"")
    )
    return b"".join(
        (
            _native_issuer_checkpoint_l_key(cast(tuple[int, int, int], value[0])),
            _native_issuer_checkpoint_l_projection5(cast(tuple[object, ...], projection[0])),
            _native_issuer_checkpoint_l_hex(cast(str, projection[1])),
            _native_issuer_checkpoint_l_text(cast(str, projection[2])),
            _native_issuer_checkpoint_l_text(cast(str, projection[3])),
            _native_issuer_checkpoint_l_text(cast(str, projection[4])),
            _native_issuer_checkpoint_l_hex(cast(str, projection[5])),
            _native_issuer_checkpoint_l_u64(int(locator is not None)),
            encoded_locator,
            _native_issuer_checkpoint_l_claim_summary(cast(tuple[object, ...], value[3])),
            _native_issuer_checkpoint_l_checkpoint_summary(cast(tuple[object, ...], value[4])),
        )
    )


def _native_issuer_checkpoint_l_binding_digest(
    *,
    cell: tuple[int, int, int],
    prepared_state: tuple[int, int, int, int, int, int, int, int],
    source_lifecycle: tuple[int, int, int],
    authority: tuple[object, ...],
    receipt_revisions: tuple[int, int],
    prepared_receipt: tuple[object, ...],
    state_paths: tuple[str, str, str],
    identities: tuple[object, ...],
    regular_proofs: tuple[object, ...],
    inventories: tuple[object, ...],
) -> str:
    assert type(cell) is tuple and len(cell) == 3
    assert type(prepared_state) is tuple and len(prepared_state) == 8
    assert prepared_state[1] == 9 and prepared_state[6:] == (0, 1)
    assert type(source_lifecycle) is tuple and len(source_lifecycle) == 3
    assert source_lifecycle[1] in {2, 3}
    assert source_lifecycle[2] == (source_lifecycle[1] == 2)
    assert type(authority) is tuple and len(authority) == 6
    assert type(receipt_revisions) is tuple and len(receipt_revisions) == 2
    assert receipt_revisions == (prepared_state[0] - 1, prepared_state[0])
    assert type(state_paths) is tuple and len(state_paths) == 3
    assert type(identities) is tuple and len(identities) == 7
    assert type(regular_proofs) is tuple and len(regular_proofs) == 6
    assert type(inventories) is tuple and len(inventories) == 9
    fields = [*(_native_issuer_checkpoint_l_u64(item) for item in cell)]
    fields.extend(_native_issuer_checkpoint_l_u64(item) for item in prepared_state)
    fields.extend(_native_issuer_checkpoint_l_u64(item) for item in source_lifecycle)
    fields.extend(
        _native_issuer_checkpoint_l_key(cast(tuple[int, int, int], key)) for key in authority[:3]
    )
    fields.extend(_native_issuer_checkpoint_l_u64(cast(int, item)) for item in authority[3:])
    fields.extend(_native_issuer_checkpoint_l_u64(item) for item in receipt_revisions)
    fields.append(_native_issuer_checkpoint_l_prepared_receipt_summary(prepared_receipt))
    fields.extend(_native_issuer_checkpoint_l_text(item) for item in state_paths)
    fields.extend(
        (
            _native_issuer_checkpoint_l_hex(cast(str, identities[0])),
            _native_issuer_checkpoint_l_stat5(cast(tuple[int, ...], identities[1])),
            _native_issuer_checkpoint_l_stat5(cast(tuple[int, ...], identities[2])),
        )
    )
    fields.extend(
        _native_issuer_checkpoint_l_stat9(cast(tuple[int, ...], identity))
        for identity in identities[3:]
    )
    for index in range(0, len(regular_proofs), 2):
        fields.extend(
            (
                _native_issuer_checkpoint_l_stat9(cast(tuple[int, ...], regular_proofs[index])),
                _native_issuer_checkpoint_l_hex(cast(str, regular_proofs[index + 1])),
            )
        )
    for index in range(0, len(inventories), 3):
        fields.extend(
            (
                _native_issuer_checkpoint_l_u64(cast(int, inventories[index])),
                _native_issuer_checkpoint_l_u64(cast(int, inventories[index + 1])),
                _native_issuer_checkpoint_l_hex(cast(str, inventories[index + 2])),
            )
        )
    return _native_issuer_checkpoint_l_digest(
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_DOMAINS[2],
        *fields,
    )


def _native_issuer_checkpoint_l_marker_bytes(
    contract_version: str,
    outcome_sha256: str,
    *,
    status: str,
) -> bytes:
    assert type(contract_version) is str and "\0" not in contract_version
    _native_issuer_checkpoint_l_hex(outcome_sha256)
    assert status in {"reserved", "committed"}
    encoded = (
        json.dumps(
            {
                "contract_version": contract_version,
                "outcome_sha256": outcome_sha256,
                "status": status,
            },
            ensure_ascii=True,
            allow_nan=False,
            separators=(",", ":"),
        ).encode("ascii", "strict")
        + b"\n"
    )
    assert b"\0" not in encoded
    return encoded


def _native_issuer_environment_sha256(
    environment_identity: tuple[tuple[str, str], ...],
) -> str:
    material = json.dumps(
        dict(environment_identity),
        ensure_ascii=True,
        separators=(",", ":"),
    ).encode("ascii", "strict")
    return hashlib.sha256(material).hexdigest()


def _native_issuer_socket_path_capacity() -> int:
    assert sys.platform in {"darwin", "linux"}
    return 104 if sys.platform == "darwin" else 108


def _native_issuer_short_temporary_root() -> Path:
    assert sys.platform in {"darwin", "linux"}
    return Path("/private/tmp") if sys.platform == "darwin" else Path("/tmp")


@pytest.mark.parametrize(
    ("platform_name", "expected_root"),
    (("darwin", Path("/private/tmp")), ("linux", Path("/tmp"))),
)
def test_native_issuer_short_temporary_root_is_platform_exact(
    monkeypatch: pytest.MonkeyPatch,
    platform_name: str,
    expected_root: Path,
) -> None:
    monkeypatch.setattr(sys, "platform", platform_name)

    assert _native_issuer_short_temporary_root() == expected_root


def _new_native_issuer_activation_projection(
    directory: Path,
) -> tuple[tuple[object, ...], socket.socket]:
    socket_path_capacity = _native_issuer_socket_path_capacity()
    if len(os.fsencode(directory / "docker.sock")) >= socket_path_capacity:
        directory = Path(
            tempfile.mkdtemp(
                prefix="aqt-i2-",
                dir=os.fspath(_native_issuer_short_temporary_root()),
            )
        )
    else:
        directory.mkdir(mode=0o700, parents=True)
    ignored_root_path = directory / "ignored"
    ignored_root_path.mkdir(mode=0o700)
    ignored_root = os.fspath(ignored_root_path.resolve(strict=True))
    docker_executable_path = directory / "docker-for-native-issuer-test"
    docker_executable_path.write_bytes(b"#!/bin/sh\nexit 0\n")
    docker_executable_path.chmod(0o500)
    docker_executable = os.fspath(docker_executable_path.resolve(strict=True))
    socket_path_object = directory / "docker.sock"
    assert len(os.fsencode(socket_path_object)) < socket_path_capacity
    socket_owner = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    socket_owner.bind(os.fspath(socket_path_object))
    socket_path_object.chmod(0o600)
    socket_path = os.fspath(socket_path_object.resolve(strict=True))
    endpoint = f"unix://{socket_path}"
    environment_identity = (
        ("DOCKER_HOST", endpoint),
        ("PATH", "/usr/bin:/bin"),
    )
    projection = (
        _NATIVE_ISSUER_ACTIVATION_PROJECTION_TAG,
        ignored_root,
        hashlib.sha256(os.fsencode(directory)).hexdigest(),
        environment_identity,
        _native_issuer_environment_sha256(environment_identity),
        (
            "trusted-time-daemon-identity-registration-v1",
            "<DOCKER_HOST>",
            endpoint,
            "native-daemon-1",
        ),
        docker_executable,
        _native_issuer_stat9(docker_executable),
        _native_issuer_stat5(socket_path),
    )
    return projection, socket_owner


def _close_native_issuer_projection_socket(
    projection: tuple[object, ...],
    socket_owner: socket.socket,
) -> None:
    socket_owner.close()
    daemon_registration = cast(tuple[object, ...], tuple.__getitem__(projection, 5))
    endpoint = cast(str, tuple.__getitem__(daemon_registration, 2))
    with suppress(FileNotFoundError):
        os.unlink(endpoint[7:])
    executable = Path(cast(str, tuple.__getitem__(projection, 6)))
    shutil.rmtree(executable.parent, ignore_errors=True)


def _mutate_native_issuer_external_identity(
    projection: tuple[object, ...],
    mutation: str,
) -> tuple[socket.socket | None, tuple[Path, ...]]:
    executable = Path(cast(str, tuple.__getitem__(projection, 6)))
    daemon = cast(tuple[object, ...], tuple.__getitem__(projection, 5))
    endpoint = cast(str, tuple.__getitem__(daemon, 2))
    socket_path = Path(endpoint[7:])
    if mutation == "executable_mode":
        executable.chmod(0o700)
        return None, ()
    if mutation == "executable_identity":
        backup = executable.with_name(f"{executable.name}.original")
        os.replace(executable, backup)
        executable.write_bytes(b"#!/bin/sh\nexit 0\n")
        executable.chmod(0o500)
        return None, (backup,)
    if mutation == "socket_mode":
        socket_path.chmod(0o620)
        return None, ()
    assert mutation == "socket_identity"
    backup = socket_path.with_name(f"{socket_path.name}.original")
    os.replace(socket_path, backup)
    replacement = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    replacement.bind(os.fspath(socket_path))
    socket_path.chmod(0o600)
    return replacement, (backup,)


def _repair_native_issuer_external_projection(
    projection: tuple[object, ...],
    mutation: str,
) -> tuple[object, ...]:
    executable = cast(str, tuple.__getitem__(projection, 6))
    daemon = cast(tuple[object, ...], tuple.__getitem__(projection, 5))
    endpoint = cast(str, tuple.__getitem__(daemon, 2))
    socket_path = endpoint[7:]
    if mutation == "executable_mode":
        os.chmod(executable, 0o500)
    elif mutation == "socket_mode":
        os.chmod(socket_path, 0o600)
    repaired = _tuple_with_item(projection, 7, _native_issuer_stat9(executable))
    return _tuple_with_item(repaired, 8, _native_issuer_stat5(socket_path))


def _native_issuer_external_identity_backup_paths(
    projection: tuple[object, ...],
    mutation: str,
) -> tuple[Path, ...]:
    if mutation == "executable_identity":
        executable = Path(cast(str, tuple.__getitem__(projection, 6)))
        return (executable.with_name(f"{executable.name}.original"),)
    if mutation == "socket_identity":
        daemon = cast(tuple[object, ...], tuple.__getitem__(projection, 5))
        endpoint = cast(str, tuple.__getitem__(daemon, 2))
        socket_path = Path(endpoint[7:])
        return (socket_path.with_name(f"{socket_path.name}.original"),)
    return ()


def _fork_native_issuer_external_projection_mutator(
    projection: tuple[object, ...],
    mutation: str,
) -> tuple[int, int, int, tuple[Path, ...]]:
    ready_read, ready_write = os.pipe()
    resume_read, resume_write = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through child status
        os.close(ready_write)
        os.close(resume_read)
        replacement_socket: socket.socket | None = None
        status = 0
        try:
            if os.read(ready_read, 1) != b"1":
                status = 2
            else:
                replacement_socket, _backups = _mutate_native_issuer_external_identity(
                    projection,
                    mutation,
                )
        except BaseException:
            status = 3
        finally:
            with suppress(OSError):
                os.write(resume_write, b"1")
            if replacement_socket is not None:
                replacement_socket.close()
            os.close(ready_read)
            os.close(resume_write)
        os._exit(status)

    os.close(ready_read)
    os.close(resume_write)
    return (
        child_pid,
        ready_write,
        resume_read,
        _native_issuer_external_identity_backup_paths(projection, mutation),
    )


def _reap_native_issuer_external_projection_mutator(
    child_pid: int,
    ready_write: int,
    resume_read: int,
) -> int:
    for descriptor in (ready_write, resume_read):
        if descriptor >= 0:
            with suppress(OSError):
                os.close(descriptor)
    waited_pid, status = os.waitpid(child_pid, 0)
    assert waited_pid == child_pid
    return os.waitstatus_to_exitcode(status)


def _fork_native_issuer_external_projection_responder() -> tuple[int, int, int]:
    ready_read, ready_write = os.pipe()
    resume_read, resume_write = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through child status
        os.close(ready_write)
        os.close(resume_read)
        status = 0
        try:
            if os.read(ready_read, 1) != b"1":
                status = 2
        except BaseException:
            status = 3
        finally:
            with suppress(OSError):
                os.write(resume_write, b"1")
            os.close(ready_read)
            os.close(resume_write)
        os._exit(status)

    os.close(ready_read)
    os.close(resume_write)
    return child_pid, ready_write, resume_read


def _configure_native_issuer_preloaded_external_projection_barrier(
    configure: Callable[[int, int], None],
) -> tuple[int, int, int, int]:
    ready_read, ready_write = os.pipe()
    resume_read, resume_write = os.pipe()
    try:
        os.write(resume_write, b"1")
        assert configure(ready_write, resume_read) is None
    except BaseException:
        for descriptor in (ready_read, ready_write, resume_read, resume_write):
            with suppress(OSError):
                os.close(descriptor)
        raise
    return ready_read, ready_write, resume_read, resume_write


def _assert_native_issuer_preloaded_barrier_was_not_consumed(
    descriptors: tuple[int, int, int, int],
) -> None:
    ready_read, _ready_write, _resume_read, _resume_write = descriptors
    try:
        ready, _, _ = select.select([ready_read], [], [], 0.0)
        assert ready == []
    finally:
        _close_native_issuer_external_projection_barrier_descriptors(descriptors)


def _assert_native_issuer_preloaded_barrier_is_pending(
    descriptors: tuple[int, int, int, int],
) -> None:
    ready_read, _ready_write, _resume_read, _resume_write = descriptors
    ready, _, _ = select.select([ready_read], [], [], 0.0)
    assert ready == []


def _assert_native_issuer_preloaded_barrier_was_consumed(
    descriptors: tuple[int, int, int, int],
) -> None:
    ready_read, _ready_write, _resume_read, _resume_write = descriptors
    try:
        ready, _, _ = select.select([ready_read], [], [], 1.0)
        assert ready == [ready_read]
        assert os.read(ready_read, 1) == b"1"
    finally:
        _close_native_issuer_external_projection_barrier_descriptors(descriptors)


def _close_native_issuer_external_projection_barrier_descriptors(
    descriptors: tuple[int, int, int, int],
) -> None:
    for descriptor in descriptors:
        with suppress(OSError):
            os.close(descriptor)


def _native_issuer_checkpoint_l_stat9_from_result(
    metadata: os.stat_result,
) -> tuple[int, ...]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_uid,
        metadata.st_gid,
        metadata.st_nlink,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


def _native_issuer_checkpoint_l_proof_open_flags() -> int:
    return os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_NOCTTY


def _native_issuer_checkpoint_l_write_all(descriptor: int, payload: bytes) -> None:
    assert type(descriptor) is int and descriptor >= 0 and type(payload) is bytes
    offset = 0
    while offset != len(payload):
        try:
            written = os.write(descriptor, payload[offset:])
        except InterruptedError:
            continue
        assert written > 0
        offset += written


def _native_issuer_checkpoint_l_read_all(descriptor: int, maximum_bytes: int) -> bytes:
    assert descriptor >= 0 and maximum_bytes >= 1
    chunks: list[bytes] = []
    total = 0
    while True:
        try:
            chunk = os.read(descriptor, min(65536, maximum_bytes + 1 - total))
        except InterruptedError:
            continue
        if not chunk:
            break
        chunks.append(chunk)
        total += len(chunk)
        assert total <= maximum_bytes
    return b"".join(chunks)


def _native_issuer_checkpoint_l_create_regular(
    directory_descriptor: int,
    raw_name: bytes,
    payload: bytes,
) -> tuple[int, ...]:
    descriptor = os.open(
        raw_name,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC | os.O_NOFOLLOW,
        0o600,
        dir_fd=directory_descriptor,
    )
    try:
        _native_issuer_checkpoint_l_write_all(descriptor, payload)
        os.fsync(descriptor)
        metadata = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    assert stat.S_ISREG(metadata.st_mode)
    assert metadata.st_uid == os.geteuid()
    assert stat.S_IMODE(metadata.st_mode) == 0o600
    assert metadata.st_nlink == 1
    return _native_issuer_checkpoint_l_stat9_from_result(metadata)


def _native_issuer_checkpoint_l_inventory(
    artifact_directory: str,
    *,
    reserve_commit: bool,
    exclude_names: frozenset[bytes] = frozenset(),
) -> tuple[int, int, str]:
    encoded_directory = os.fsencode(artifact_directory)
    directory_descriptor = os.open(
        encoded_directory,
        os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
    )
    try:
        names = tuple(os.listdir(encoded_directory))
        assert all(type(name) is bytes for name in names)
        entries = tuple(
            (
                cast(bytes, name),
                _native_issuer_checkpoint_l_stat9_from_result(
                    os.stat(cast(bytes, name), dir_fd=directory_descriptor, follow_symlinks=False)
                ),
            )
            for name in names
            if name not in {b".", b".."} and name not in exclude_names
        )
    finally:
        os.close(directory_descriptor)
    return _native_issuer_checkpoint_l_inventory_digest(
        entries,
        reserve_commit=reserve_commit,
    )


def _native_issuer_checkpoint_l_path_capture(
    artifact_directory: str,
) -> tuple[str, tuple[tuple[bytes, tuple[int, ...]], ...]]:
    encoded = os.fsencode(artifact_directory)
    assert encoded.startswith(b"/") and b"\0" not in encoded and len(encoded) <= 4095
    raw_components = tuple(component for component in encoded.split(b"/") if component)
    assert 2 <= len(raw_components) <= 257
    directory_flags = (
        os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_NOCTTY
    )
    current = os.open(b"/", directory_flags)
    opened: list[tuple[bytes, tuple[int, ...]]] = []
    try:
        root_identity = _native_issuer_stat5("/")
        assert _native_issuer_checkpoint_l_stat5(root_identity)
        for raw_component in raw_components:
            assert 1 <= len(raw_component) <= 255
            following = os.open(raw_component, directory_flags, dir_fd=current)
            os.close(current)
            current = following
            metadata = os.fstat(current)
            assert stat.S_ISDIR(metadata.st_mode)
            opened.append(
                (
                    raw_component,
                    (
                        metadata.st_dev,
                        metadata.st_ino,
                        metadata.st_mode,
                        metadata.st_uid,
                        metadata.st_gid,
                    ),
                )
            )
        for _raw_component, identity in opened[-2:]:
            assert identity[3] == os.geteuid()
            assert stat.S_IMODE(identity[2]) == 0o700
    finally:
        os.close(current)
    exact = tuple(opened)
    return _native_issuer_checkpoint_l_path_digest(root_identity, exact), exact


def _native_issuer_checkpoint_l_regular_proof(
    artifact_directory: str,
    raw_name: bytes,
    *,
    maximum_bytes: int,
) -> tuple[tuple[int, ...], str, bytes]:
    directory_descriptor = os.open(
        os.fsencode(artifact_directory),
        os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
    )
    descriptor = -1
    try:
        descriptor = os.open(
            raw_name,
            _native_issuer_checkpoint_l_proof_open_flags(),
            dir_fd=directory_descriptor,
        )
        before = os.fstat(descriptor)
        named = os.stat(raw_name, dir_fd=directory_descriptor, follow_symlinks=False)
        assert stat.S_ISREG(before.st_mode)
        assert before.st_uid == os.geteuid()
        assert stat.S_IMODE(before.st_mode) == 0o600
        assert before.st_nlink == 1
        assert before.st_dev == os.fstat(directory_descriptor).st_dev
        assert (before.st_dev, before.st_ino) == (named.st_dev, named.st_ino)
        chunks: list[bytes] = []
        total = 0
        while True:
            try:
                chunk = os.read(descriptor, min(65536, maximum_bytes + 1 - total))
            except InterruptedError:
                continue
            if not chunk:
                break
            chunks.append(chunk)
            total += len(chunk)
            assert total <= maximum_bytes
        os.fsync(descriptor)
        after = os.fstat(descriptor)
        named_after = os.stat(raw_name, dir_fd=directory_descriptor, follow_symlinks=False)
        assert _native_issuer_checkpoint_l_stat9_from_result(before) == (
            _native_issuer_checkpoint_l_stat9_from_result(after)
        )
        assert (after.st_dev, after.st_ino) == (named_after.st_dev, named_after.st_ino)
        payload = b"".join(chunks)
        return (
            _native_issuer_checkpoint_l_stat9_from_result(after),
            hashlib.sha256(payload).hexdigest(),
            payload,
        )
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        os.close(directory_descriptor)


def _native_issuer_checkpoint_l_prepare_files(
    artifact_directory: str,
    *,
    contract_version: str,
    outcome_bytes: bytes,
    unrelated_names: tuple[bytes, ...] = (),
) -> dict[str, object]:
    assert type(artifact_directory) is str
    assert type(outcome_bytes) is bytes and 1 <= len(outcome_bytes) <= 131072
    encoded_directory = os.fsencode(artifact_directory)
    os.makedirs(encoded_directory, mode=0o700, exist_ok=True)
    directory_descriptor = os.open(
        encoded_directory,
        os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
    )
    outcome_sha256 = hashlib.sha256(outcome_bytes).hexdigest()
    outcome_basename = (
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_OUTCOME_PREFIX
        + outcome_sha256
        + _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_OUTCOME_SUFFIX
    )
    slot_bytes = _native_issuer_checkpoint_l_marker_bytes(
        contract_version,
        outcome_sha256,
        status="reserved",
    )
    try:
        outcome_identity = _native_issuer_checkpoint_l_create_regular(
            directory_descriptor,
            outcome_basename.encode("ascii", "strict"),
            outcome_bytes,
        )
        slot_identity = _native_issuer_checkpoint_l_create_regular(
            directory_descriptor,
            _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_SLOT_BASENAME.encode("ascii", "strict"),
            slot_bytes,
        )
        for raw_name in unrelated_names:
            assert type(raw_name) is bytes and 1 <= len(raw_name) <= 255
            _native_issuer_checkpoint_l_create_regular(
                directory_descriptor,
                raw_name,
                b"unrelated\n",
            )
        os.fsync(directory_descriptor)
        artifact_identity = _native_issuer_checkpoint_l_stat9_from_result(
            os.fstat(directory_descriptor)
        )
    finally:
        os.close(directory_descriptor)
    assert (outcome_identity[0], outcome_identity[1]) != (
        slot_identity[0],
        slot_identity[1],
    )
    return {
        "artifact_directory": artifact_directory,
        "outcome_sha256": outcome_sha256,
        "outcome_basename": outcome_basename,
        "outcome_bytes": outcome_bytes,
        "outcome_identity": outcome_identity,
        "slot_bytes": slot_bytes,
        "slot_identity": slot_identity,
        "prepared_artifact_identity": artifact_identity,
        "prepared_inventory": _native_issuer_checkpoint_l_inventory(
            artifact_directory,
            reserve_commit=True,
        ),
    }


def _native_issuer_checkpoint_l_mutate_prepared_evidence(
    values: dict[str, object],
    mutation: str,
) -> None:
    assert mutation in {
        "missing_outcome",
        "renamed_outcome",
        "symlink_outcome",
        "nonregular_outcome",
        "outcome_mode",
        "outcome_nlink",
        "outcome_empty",
        "outcome_oversize",
        "outcome_hash",
        "slot_bytes",
        "preexisting_commit",
        "controller_staging",
        "recovery_staging",
        "commit_staging",
        "legacy_outcome",
        "second_outcome",
    }
    artifact_directory = cast(str, values["artifact_directory"])
    directory_descriptor = os.open(
        os.fsencode(artifact_directory),
        os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
    )
    try:
        outcome_name = cast(str, values["outcome_basename"]).encode("ascii", "strict")
        slot_name = _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_SLOT_BASENAME.encode("ascii", "strict")
        if mutation == "missing_outcome":
            os.unlink(outcome_name, dir_fd=directory_descriptor)
        elif mutation == "renamed_outcome":
            os.rename(
                outcome_name,
                outcome_name + b".renamed",
                src_dir_fd=directory_descriptor,
                dst_dir_fd=directory_descriptor,
            )
        elif mutation == "symlink_outcome":
            os.unlink(outcome_name, dir_fd=directory_descriptor)
            os.symlink(slot_name, outcome_name, dir_fd=directory_descriptor)
        elif mutation == "nonregular_outcome":
            os.unlink(outcome_name, dir_fd=directory_descriptor)
            os.mkdir(outcome_name, 0o700, dir_fd=directory_descriptor)
        elif mutation == "outcome_mode":
            outcome_descriptor = os.open(
                outcome_name,
                _native_issuer_checkpoint_l_proof_open_flags(),
                dir_fd=directory_descriptor,
            )
            try:
                os.fchmod(outcome_descriptor, 0o640)
                os.fsync(outcome_descriptor)
            finally:
                os.close(outcome_descriptor)
        elif mutation == "outcome_nlink":
            os.link(
                outcome_name,
                b".checkpoint-l-outcome-hardlink",
                src_dir_fd=directory_descriptor,
                dst_dir_fd=directory_descriptor,
                follow_symlinks=False,
            )
        elif mutation in {"outcome_empty", "outcome_oversize", "outcome_hash"}:
            outcome_descriptor = os.open(
                outcome_name,
                os.O_WRONLY
                | os.O_TRUNC
                | os.O_CLOEXEC
                | os.O_NOFOLLOW
                | os.O_NONBLOCK
                | os.O_NOCTTY,
                dir_fd=directory_descriptor,
            )
            try:
                if mutation == "outcome_oversize":
                    replacement = b"x" * 131073
                elif mutation == "outcome_hash":
                    original = cast(bytes, values["outcome_bytes"])
                    replacement = bytes((original[0] ^ 1,)) + original[1:]
                    assert hashlib.sha256(replacement).hexdigest() != values["outcome_sha256"]
                else:
                    replacement = b""
                _native_issuer_checkpoint_l_write_all(outcome_descriptor, replacement)
                os.fsync(outcome_descriptor)
            finally:
                os.close(outcome_descriptor)
        elif mutation == "slot_bytes":
            slot_descriptor = os.open(
                slot_name,
                os.O_WRONLY
                | os.O_TRUNC
                | os.O_CLOEXEC
                | os.O_NOFOLLOW
                | os.O_NONBLOCK
                | os.O_NOCTTY,
                dir_fd=directory_descriptor,
            )
            try:
                _native_issuer_checkpoint_l_write_all(slot_descriptor, b"{}\n")
                os.fsync(slot_descriptor)
            finally:
                os.close(slot_descriptor)
        elif mutation == "preexisting_commit":
            payload = cast(tuple[object, ...], values["controller_receipt_payload"])
            _native_issuer_checkpoint_l_create_regular(
                directory_descriptor,
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_COMMIT_BASENAME.encode("ascii", "strict"),
                _native_issuer_checkpoint_l_marker_bytes(
                    cast(str, payload[8]),
                    cast(str, values["outcome_sha256"]),
                    status="committed",
                ),
            )
        elif mutation in {"controller_staging", "recovery_staging", "commit_staging"}:
            staging_index = {
                "controller_staging": 0,
                "recovery_staging": 1,
                "commit_staging": 2,
            }[mutation]
            _native_issuer_checkpoint_l_create_regular(
                directory_descriptor,
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_STAGING_BASENAMES[staging_index].encode(
                    "ascii", "strict"
                ),
                b"staging\n",
            )
        elif mutation == "legacy_outcome":
            _native_issuer_checkpoint_l_create_regular(
                directory_descriptor,
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_LEGACY_OUTCOME_BASENAME.encode(
                    "ascii", "strict"
                ),
                b"legacy\n",
            )
        else:
            assert mutation == "second_outcome"
            extra_name = (
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_OUTCOME_PREFIX.encode("ascii", "strict")
                + b"f" * 64
                + _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_OUTCOME_SUFFIX.encode("ascii", "strict")
            )
            assert extra_name != outcome_name
            _native_issuer_checkpoint_l_create_regular(
                directory_descriptor,
                extra_name,
                b"x",
            )
        os.fsync(directory_descriptor)
    finally:
        os.close(directory_descriptor)


def _fork_native_issuer_checkpoint_l_slot_lock_holder(
    artifact_directory: str,
) -> tuple[int, int]:
    ready_read, ready_write = os.pipe()
    release_read, release_write = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - parent asserts exact child status
        os.close(ready_read)
        os.close(release_write)
        directory_descriptor = -1
        slot_descriptor = -1
        status = 3
        try:
            directory_descriptor = os.open(
                os.fsencode(artifact_directory),
                os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
            )
            slot_descriptor = os.open(
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_SLOT_BASENAME.encode("ascii", "strict"),
                _native_issuer_checkpoint_l_proof_open_flags(),
                dir_fd=directory_descriptor,
            )
            fcntl.flock(slot_descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
            os.write(ready_write, b"1")
            status = 0 if os.read(release_read, 1) == b"1" else 2
        except BaseException:
            with suppress(OSError):
                os.write(ready_write, b"E")
        finally:
            if slot_descriptor >= 0:
                with suppress(OSError):
                    fcntl.flock(slot_descriptor, fcntl.LOCK_UN)
                with suppress(OSError):
                    os.close(slot_descriptor)
            if directory_descriptor >= 0:
                with suppress(OSError):
                    os.close(directory_descriptor)
            for descriptor in (ready_write, release_read):
                with suppress(OSError):
                    os.close(descriptor)
        os._exit(status)

    os.close(ready_write)
    os.close(release_read)
    try:
        ready, _, _ = select.select([ready_read], [], [], 5.0)
        assert ready == [ready_read]
        assert os.read(ready_read, 1) == b"1"
    except BaseException:
        with suppress(OSError):
            os.close(release_write)
        os.waitpid(child_pid, 0)
        raise
    finally:
        os.close(ready_read)
    return child_pid, release_write


def _reap_native_issuer_checkpoint_l_slot_lock_holder(actor: tuple[int, int]) -> None:
    child_pid, release_write = actor
    try:
        os.write(release_write, b"1")
    finally:
        try:
            os.close(release_write)
        finally:
            waited_pid, status = os.waitpid(child_pid, 0)
    assert waited_pid == child_pid
    assert os.waitstatus_to_exitcode(status) == 0


def _fork_native_issuer_checkpoint_l_commit_publisher(
    artifact_directory: str,
    *,
    contract_version: str,
    outcome_sha256: str,
    post_publish_mutation: str = "none",
    external_executable: str | None = None,
) -> tuple[int, int, int, int]:
    assert post_publish_mutation in {
        "none",
        "commit_missing",
        "commit_bytes",
        "commit_mode",
        "commit_nlink",
        "commit_symlink",
        "commit_nonregular",
        "outcome_bytes",
        "slot_bytes",
        "pre_entry",
        "extra_entry",
        "path_identity",
        "launch_identity",
        "external_identity",
    }
    assert post_publish_mutation != "external_identity" or type(external_executable) is str
    encoded_directory = os.fsencode(artifact_directory)
    encoded_external_executable = (
        None if external_executable is None else os.fsencode(external_executable)
    )
    slot_name = _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_SLOT_BASENAME.encode("ascii", "strict")
    commit_name = _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_COMMIT_BASENAME.encode("ascii", "strict")
    commit_bytes = _native_issuer_checkpoint_l_marker_bytes(
        contract_version,
        outcome_sha256,
        status="committed",
    )
    slot_bytes = _native_issuer_checkpoint_l_marker_bytes(
        contract_version,
        outcome_sha256,
        status="reserved",
    )
    outcome_name = (
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_OUTCOME_PREFIX.encode("ascii", "strict")
        + outcome_sha256.encode("ascii", "strict")
        + _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_OUTCOME_SUFFIX.encode("ascii", "strict")
    )
    ready_read, ready_write = os.pipe()
    resume_read, resume_write = os.pipe()
    result_read, result_write = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - parent asserts the exact child transcript
        os.close(ready_write)
        os.close(resume_read)
        os.close(result_read)
        directory_descriptor = -1
        slot_descriptor = -1
        staging_descriptor = -1
        commit_descriptor = -1
        outcome_descriptor = -1
        mutation_descriptor = -1
        barrier_entered = False
        status_byte = b"E"
        exit_status = 3
        staging_name = _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_STAGING_BASENAMES[2].encode(
            "ascii", "strict"
        )
        try:
            barrier_entered = os.read(ready_read, 1) == b"1"
            if not barrier_entered:
                status_byte = b"N"
                exit_status = 0
            else:
                directory_descriptor = os.open(
                    encoded_directory,
                    os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
                )
                directory_metadata = os.fstat(directory_descriptor)
                assert stat.S_ISDIR(directory_metadata.st_mode)
                assert directory_metadata.st_uid == os.geteuid()
                assert stat.S_IMODE(directory_metadata.st_mode) == 0o700
                slot_descriptor = os.open(
                    slot_name,
                    _native_issuer_checkpoint_l_proof_open_flags(),
                    dir_fd=directory_descriptor,
                )
                fcntl.flock(slot_descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                slot_metadata = os.fstat(slot_descriptor)
                slot_named = os.stat(
                    slot_name,
                    dir_fd=directory_descriptor,
                    follow_symlinks=False,
                )
                assert stat.S_ISREG(slot_metadata.st_mode)
                assert slot_metadata.st_uid == os.geteuid()
                assert stat.S_IMODE(slot_metadata.st_mode) == 0o600
                assert slot_metadata.st_nlink == 1
                assert slot_metadata.st_dev == directory_metadata.st_dev
                assert (slot_metadata.st_dev, slot_metadata.st_ino) == (
                    slot_named.st_dev,
                    slot_named.st_ino,
                )
                assert _native_issuer_checkpoint_l_read_all(slot_descriptor, 4096) == slot_bytes
                os.fsync(slot_descriptor)
                outcome_descriptor = os.open(
                    outcome_name,
                    _native_issuer_checkpoint_l_proof_open_flags(),
                    dir_fd=directory_descriptor,
                )
                outcome_metadata = os.fstat(outcome_descriptor)
                outcome_named = os.stat(
                    outcome_name,
                    dir_fd=directory_descriptor,
                    follow_symlinks=False,
                )
                assert stat.S_ISREG(outcome_metadata.st_mode)
                assert outcome_metadata.st_uid == os.geteuid()
                assert stat.S_IMODE(outcome_metadata.st_mode) == 0o600
                assert outcome_metadata.st_nlink == 1
                assert outcome_metadata.st_dev == directory_metadata.st_dev
                assert (outcome_metadata.st_dev, outcome_metadata.st_ino) == (
                    outcome_named.st_dev,
                    outcome_named.st_ino,
                )
                assert (outcome_metadata.st_dev, outcome_metadata.st_ino) != (
                    slot_metadata.st_dev,
                    slot_metadata.st_ino,
                )
                outcome_payload = _native_issuer_checkpoint_l_read_all(
                    outcome_descriptor,
                    131072,
                )
                assert hashlib.sha256(outcome_payload).hexdigest() == outcome_sha256
                os.fsync(outcome_descriptor)
                os.close(outcome_descriptor)
                outcome_descriptor = -1
                staging_descriptor = os.open(
                    staging_name,
                    os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC | os.O_NOFOLLOW,
                    0o600,
                    dir_fd=directory_descriptor,
                )
                _native_issuer_checkpoint_l_write_all(staging_descriptor, commit_bytes)
                os.fchmod(staging_descriptor, 0o600)
                os.fsync(staging_descriptor)
                staging_metadata = os.fstat(staging_descriptor)
                directory_metadata = os.fstat(directory_descriptor)
                assert stat.S_ISREG(staging_metadata.st_mode)
                assert staging_metadata.st_uid == os.geteuid()
                assert stat.S_IMODE(staging_metadata.st_mode) == 0o600
                assert staging_metadata.st_nlink == 1
                assert staging_metadata.st_size == len(commit_bytes)
                assert staging_metadata.st_dev == directory_metadata.st_dev
                os.close(staging_descriptor)
                staging_descriptor = -1
                os.fsync(directory_descriptor)
                os.link(
                    staging_name,
                    commit_name,
                    src_dir_fd=directory_descriptor,
                    dst_dir_fd=directory_descriptor,
                    follow_symlinks=False,
                )
                linked_metadata = os.stat(
                    commit_name,
                    dir_fd=directory_descriptor,
                    follow_symlinks=False,
                )
                assert (linked_metadata.st_dev, linked_metadata.st_ino) == (
                    staging_metadata.st_dev,
                    staging_metadata.st_ino,
                )
                assert linked_metadata.st_nlink == 2
                commit_descriptor = os.open(
                    commit_name,
                    _native_issuer_checkpoint_l_proof_open_flags(),
                    dir_fd=directory_descriptor,
                )
                os.fsync(commit_descriptor)
                os.close(commit_descriptor)
                commit_descriptor = -1
                os.fsync(directory_descriptor)
                os.unlink(staging_name, dir_fd=directory_descriptor)
                committed_metadata = os.stat(
                    commit_name,
                    dir_fd=directory_descriptor,
                    follow_symlinks=False,
                )
                directory_metadata = os.fstat(directory_descriptor)
                assert stat.S_ISREG(committed_metadata.st_mode)
                assert committed_metadata.st_uid == os.geteuid()
                assert stat.S_IMODE(committed_metadata.st_mode) == 0o600
                assert committed_metadata.st_nlink == 1
                assert committed_metadata.st_dev == directory_metadata.st_dev
                assert (committed_metadata.st_dev, committed_metadata.st_ino) not in {
                    (slot_metadata.st_dev, slot_metadata.st_ino),
                    (outcome_metadata.st_dev, outcome_metadata.st_ino),
                }
                os.fsync(directory_descriptor)
                commit_descriptor = os.open(
                    commit_name,
                    _native_issuer_checkpoint_l_proof_open_flags(),
                    dir_fd=directory_descriptor,
                )
                assert _native_issuer_checkpoint_l_read_all(commit_descriptor, 4096) == (
                    commit_bytes
                )
                os.fsync(commit_descriptor)
                os.close(commit_descriptor)
                commit_descriptor = -1
                if post_publish_mutation == "commit_missing":
                    os.unlink(commit_name, dir_fd=directory_descriptor)
                    os.fsync(directory_descriptor)
                elif post_publish_mutation in {
                    "commit_bytes",
                    "outcome_bytes",
                    "slot_bytes",
                    "pre_entry",
                }:
                    rewrite_name, replacement = {
                        "commit_bytes": (commit_name, b"{}\n"),
                        "outcome_bytes": (outcome_name, b"postbarrier-outcome\n"),
                        "slot_bytes": (slot_name, b"{}\n"),
                        "pre_entry": (b"a-unrelated", b"postbarrier-unrelated\n"),
                    }[post_publish_mutation]
                    mutation_descriptor = os.open(
                        rewrite_name,
                        os.O_WRONLY
                        | os.O_TRUNC
                        | os.O_CLOEXEC
                        | os.O_NOFOLLOW
                        | os.O_NONBLOCK
                        | os.O_NOCTTY,
                        dir_fd=directory_descriptor,
                    )
                    _native_issuer_checkpoint_l_write_all(
                        mutation_descriptor,
                        replacement,
                    )
                    os.fsync(mutation_descriptor)
                    os.close(mutation_descriptor)
                    mutation_descriptor = -1
                    os.fsync(directory_descriptor)
                elif post_publish_mutation == "commit_mode":
                    mutation_descriptor = os.open(
                        commit_name,
                        _native_issuer_checkpoint_l_proof_open_flags(),
                        dir_fd=directory_descriptor,
                    )
                    os.fchmod(mutation_descriptor, 0o640)
                    os.fsync(mutation_descriptor)
                    os.close(mutation_descriptor)
                    mutation_descriptor = -1
                    os.fsync(directory_descriptor)
                elif post_publish_mutation == "commit_nlink":
                    os.link(
                        commit_name,
                        b".checkpoint-l-commit-hardlink",
                        src_dir_fd=directory_descriptor,
                        dst_dir_fd=directory_descriptor,
                        follow_symlinks=False,
                    )
                    os.fsync(directory_descriptor)
                elif post_publish_mutation == "commit_symlink":
                    os.unlink(commit_name, dir_fd=directory_descriptor)
                    os.symlink(slot_name, commit_name, dir_fd=directory_descriptor)
                    os.fsync(directory_descriptor)
                elif post_publish_mutation == "commit_nonregular":
                    os.unlink(commit_name, dir_fd=directory_descriptor)
                    os.mkdir(commit_name, 0o700, dir_fd=directory_descriptor)
                    os.fsync(directory_descriptor)
                elif post_publish_mutation == "extra_entry":
                    mutation_descriptor = os.open(
                        b".checkpoint-l-post-publish-extra",
                        os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC | os.O_NOFOLLOW,
                        0o600,
                        dir_fd=directory_descriptor,
                    )
                    try:
                        _native_issuer_checkpoint_l_write_all(mutation_descriptor, b"x")
                        os.fchmod(mutation_descriptor, 0o600)
                        os.fsync(mutation_descriptor)
                    finally:
                        os.close(mutation_descriptor)
                        mutation_descriptor = -1
                    os.fsync(directory_descriptor)
                elif post_publish_mutation == "path_identity":
                    os.fchmod(directory_descriptor, 0o750)
                    os.fsync(directory_descriptor)
                elif post_publish_mutation == "launch_identity":
                    mutation_descriptor = os.open(
                        b"trusted-time-launch.lock",
                        _native_issuer_checkpoint_l_proof_open_flags(),
                        dir_fd=directory_descriptor,
                    )
                    os.fchmod(mutation_descriptor, 0o640)
                    os.fsync(mutation_descriptor)
                    os.close(mutation_descriptor)
                    mutation_descriptor = -1
                    os.fsync(directory_descriptor)
                elif post_publish_mutation == "external_identity":
                    assert encoded_external_executable is not None
                    os.chmod(encoded_external_executable, 0o700)
                fcntl.flock(slot_descriptor, fcntl.LOCK_UN)
                status_byte = b"P"
                exit_status = 0
        except BaseException:
            status_byte = b"E"
            exit_status = 3
        finally:
            for descriptor in (
                outcome_descriptor,
                commit_descriptor,
                staging_descriptor,
                mutation_descriptor,
                slot_descriptor,
                directory_descriptor,
            ):
                if descriptor >= 0:
                    with suppress(OSError):
                        os.close(descriptor)
            if barrier_entered:
                with suppress(OSError):
                    os.write(resume_write, b"1")
            with suppress(OSError):
                os.write(result_write, status_byte)
            for descriptor in (ready_read, resume_write, result_write):
                with suppress(OSError):
                    os.close(descriptor)
        os._exit(exit_status)

    os.close(ready_read)
    os.close(resume_write)
    os.close(result_write)
    return child_pid, ready_write, resume_read, result_read


def _reap_native_issuer_checkpoint_l_commit_publisher(
    actor: tuple[int, int, int, int],
    *,
    expected_published: bool,
) -> None:
    child_pid, ready_write, resume_read, result_read = actor
    for descriptor in (ready_write, resume_read):
        with suppress(OSError):
            os.close(descriptor)
    try:
        try:
            result = os.read(result_read, 1)
        finally:
            os.close(result_read)
    finally:
        waited_pid, status = os.waitpid(child_pid, 0)
    assert waited_pid == child_pid
    assert os.waitstatus_to_exitcode(status) == 0
    assert result == (b"P" if expected_published else b"N")


def _native_c_function_slice(source: str, name: str, next_name: str) -> str:
    start = source.index(f"\n{name}(")
    end = source.index(f"\n{next_name}(", start + 1)
    return source[start:end]


def _native_c_function_definition_slice(source: str, name: str, next_name: str) -> str:
    marker = f"\n{name}("
    cursor = 0
    while True:
        start = source.index(marker, cursor)
        opening_brace = source.index("{", start)
        if source.find(";", start, opening_brace) < 0:
            break
        cursor = start + len(marker)
    end = source.index(f"\n{next_name}(", opening_brace)
    return source[start:end]


