def _assert_native_issuer_lifecycle_fault(
    operation: Callable[[], object],
    kind: int,
) -> BaseException:
    expected_type: type[BaseException]
    if kind == 0:
        expected_type = RuntimeError
    elif kind == 1:
        expected_type = KeyboardInterrupt
    else:
        assert kind == 2
        expected_type = SystemExit
    with pytest.raises(expected_type) as retained:
        operation()
    assert type(retained.value) is expected_type
    if kind == 0:
        assert _NATIVE_ISSUER_LIFECYCLE_FAULT_MESSAGE in str(retained.value)
    elif kind == 2:
        assert cast(SystemExit, retained.value).code == 197
    return retained.value


def _native_issuer_initial_snapshot() -> tuple[object, ...]:
    source = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_sha256 = hashlib.sha256(source.read_bytes()).hexdigest()
    if source_sha256 in (
        _COHERENT_NATIVE_ISSUER_LIFECYCLE_C_SHA256
        | _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_C_SHA256
        | _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REGISTER_OR_LATER_C_SHA256
    ):
        return _NATIVE_ISSUER_LIFECYCLE_INERT_SNAPSHOT
    assert source_sha256 in _COHERENT_NATIVE_ISSUER_SHADOW_C_SHA256
    return _NATIVE_ISSUER_SHADOW_SNAPSHOT


