def _native_issuer_lifecycle_hooks(
    native_module: ModuleType,
) -> tuple[
    Callable[[object, object], None],
    Callable[[object], None],
    Callable[[object], None],
    Callable[[object], None],
    Callable[[int, int, int], None],
]:
    hooks = tuple(getattr(native_module, name) for name in _NATIVE_ISSUER_LIFECYCLE_HOOK_NAMES)
    for name, hook in zip(_NATIVE_ISSUER_LIFECYCLE_HOOK_NAMES, hooks, strict=True):
        assert type(hook) is BuiltinFunctionType
        assert hook.__name__ == name
        assert hook.__self__ is native_module
    return cast(
        tuple[
            Callable[[object, object], None],
            Callable[[object], None],
            Callable[[object], None],
            Callable[[object], None],
            Callable[[int, int, int], None],
        ],
        hooks,
    )


