def _assert_native_issuer_snapshot_is_builtin_only(snapshot: object) -> None:
    assert type(snapshot) is tuple
    exact = cast(tuple[object, ...], snapshot)
    assert len(exact) == 21
    assert tuple.__getitem__(exact, 0) == _NATIVE_ISSUER_LIFECYCLE_SNAPSHOT_TAG

    def check(value: object) -> None:
        if type(value) is tuple:
            for item in cast(tuple[object, ...], value):
                check(item)
            return
        assert type(value) in {bool, int, str}
        assert not callable(value)

    check(exact)


