def _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
    native_module: ModuleType,
    shadow: object,
    projection: tuple[object, ...],
    claim: object,
    claim_payload: tuple[str, ...],
    armed_state: tuple[object, ...],
    selector: str,
) -> tuple[object, tuple[object, ...], int]:
    _prepare_authority, prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(native_module)
    )
    recovery_checkpoint = prepare_witness(
        shadow,
        "recovery_checkpoint",
        (claim, selector),
    )
    claim_snapshot = _assert_native_issuer_checkpoint_e_claim_handle(
        snapshot,
        claim,
        claim_payload,
        status="installed",
        status_revision=cast(int, armed_state[3]),
    )
    checkpoint_snapshot = _assert_native_issuer_checkpoint_f_recovery_checkpoint_handle(
        snapshot,
        recovery_checkpoint,
        cast(tuple[object, ...], claim_snapshot[7]),
        _native_issuer_checkpoint_e_roots(projection),
        armed_state,
        expected_observed=None,
        status="prepared",
        status_revision=cast(int, armed_state[3]),
    )
    observed = cast(int, cast(tuple[object, ...], checkpoint_snapshot[7])[1][5])
    expected_by_selector = {
        "same": armed_state[9],
        "rollback": armed_state[9],
        "action_deadline": armed_state[11],
        "retention_deadline": armed_state[12],
    }
    if selector == "sample":
        assert type(observed) is int and 0 <= observed < 2**64
    else:
        assert selector in expected_by_selector
        assert observed == expected_by_selector[selector]
    assert snapshot(shadow) == armed_state
    return recovery_checkpoint, checkpoint_snapshot, observed


def _assert_native_issuer_checkpoint_f_recovery_consuming_snapshot(
    snapshot_hook: Callable[[object], tuple[object, ...]],
    shadow: object,
    lease: object,
    capability: object,
    claim: object,
    claim_payload: tuple[str, ...],
    recovery_checkpoint: object,
    armed_state: tuple[object, ...],
    roots: tuple[str, str],
    *,
    state_revision: int,
    expected_last: int,
    lifecycle_revision: int = 3,
) -> tuple[object, ...]:
    state = _assert_native_issuer_choreography_snapshot_is_builtin_only(
        snapshot_hook(shadow),
        expected_length=24,
    )
    claim_snapshot = _assert_native_issuer_checkpoint_e_claim_handle(
        snapshot_hook,
        claim,
        claim_payload,
        status="installed",
        status_revision=cast(int, armed_state[3]),
    )
    checkpoint_snapshot = _assert_native_issuer_checkpoint_f_recovery_checkpoint_handle(
        snapshot_hook,
        recovery_checkpoint,
        cast(tuple[object, ...], claim_snapshot[7]),
        roots,
        armed_state,
        expected_observed=expected_last,
        status="installed",
        status_revision=state_revision,
        installed_state=state,
    )
    for handle, kind in (
        (lease, "choreography_lease"),
        (capability, "recovery_retention_capability"),
    ):
        _assert_native_issuer_choreography_handle_snapshot(
            snapshot_hook,
            handle,
            record_class="authority",
            kind=kind,
            status="installed",
            status_revision=1,
        )
    assert state[:9] == (
        _NATIVE_ISSUER_CHOREOGRAPHY_STATE_TAG,
        lifecycle_revision,
        True,
        state_revision,
        armed_state[4],
        armed_state[5],
        "recovery_consuming",
        False,
        False,
    )
    assert state[9] == expected_last
    assert state[10:13] == armed_state[10:13]
    assert state[13:] == (
        roots,
        snapshot_hook(lease)[7],
        snapshot_hook(capability)[7],
        claim_snapshot[7],
        claim_payload[5],
        checkpoint_snapshot[7],
        None,
        None,
        None,
        None,
        None,
    )
    return state


