def _prepare_native_issuer_checkpoint_f_operation_source(
    native_module: ModuleType,
    directory: Path,
    operation_tag: str,
    *,
    abandon_source: str = "armed",
) -> dict[str, object]:
    assert operation_tag in {"begin_recovery", "confirm_recovery", "abandon_recovery"}
    assert abandon_source in {"armed", "recovery_consuming", "recovery_confirmed"}
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(native_module)
    )
    transition = _native_issuer_choreography_transition_hook(native_module)
    (
        shadow,
        projection,
        socket_owner,
        lease,
        capability,
        registered,
        binder,
        authorization,
        claim,
        claim_payload,
        armed,
    ) = _prepare_native_issuer_checkpoint_f_armed_source(native_module, directory)
    values: dict[str, object] = {
        "shadow": shadow,
        "projection": projection,
        "socket_owner": socket_owner,
        "lease": lease,
        "capability": capability,
        "registered": registered,
        "binder": binder,
        "authorization": authorization,
        "claim": claim,
        "claim_payload": claim_payload,
        "armed": armed,
        "source_state": armed,
        "recovery_checkpoint": None,
        "checkpoint_snapshot": None,
        "recovery_receipt": None,
        "receipt_snapshot": None,
        "receipt_payload": None,
    }
    if operation_tag == "abandon_recovery" and abandon_source == "armed":
        values["request"] = (capability, None)
        return values

    recovery_checkpoint, checkpoint_snapshot, begin_observed = (
        _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
            native_module,
            shadow,
            projection,
            claim,
            claim_payload,
            armed,
            "same",
        )
    )
    values["recovery_checkpoint"] = recovery_checkpoint
    values["checkpoint_snapshot"] = checkpoint_snapshot
    values["begin_observed"] = begin_observed
    if operation_tag == "begin_recovery":
        values["request"] = (capability, recovery_checkpoint, "same")
        return values

    assert (
        transition(
            shadow,
            "begin_recovery",
            (capability, recovery_checkpoint, "same"),
        )
        is None
    )
    consuming = _assert_native_issuer_checkpoint_f_recovery_consuming_snapshot(
        snapshot,
        shadow,
        lease,
        capability,
        claim,
        claim_payload,
        recovery_checkpoint,
        armed,
        _native_issuer_checkpoint_e_roots(projection),
        state_revision=cast(int, armed[3]) + 1,
        expected_last=begin_observed,
    )
    values["consuming"] = consuming
    values["source_state"] = consuming
    if operation_tag == "abandon_recovery" and abandon_source == "recovery_consuming":
        values["request"] = (capability, recovery_checkpoint)
        return values

    recovery_receipt, receipt_snapshot, receipt_payload = (
        _prepare_native_issuer_checkpoint_f_recovery_receipt(
            native_module,
            shadow,
            claim,
            claim_payload,
            recovery_checkpoint,
            consuming,
        )
    )
    values["recovery_receipt"] = recovery_receipt
    values["receipt_snapshot"] = receipt_snapshot
    values["receipt_payload"] = receipt_payload
    if operation_tag == "confirm_recovery":
        values["request"] = (
            capability,
            recovery_checkpoint,
            recovery_receipt,
            "same",
        )
        return values

    assert operation_tag == "abandon_recovery"
    assert abandon_source == "recovery_confirmed"
    assert (
        transition(
            shadow,
            "confirm_recovery",
            (capability, recovery_checkpoint, recovery_receipt, "same"),
        )
        is None
    )
    confirmed = _assert_native_issuer_checkpoint_f_recovery_confirmed_snapshot(
        snapshot,
        shadow,
        lease,
        capability,
        claim,
        claim_payload,
        recovery_checkpoint,
        recovery_receipt,
        receipt_payload,
        consuming,
        _native_issuer_checkpoint_e_roots(projection),
        state_revision=cast(int, consuming[3]) + 1,
        install_revision=cast(int, consuming[3]) + 1,
        expected_last=cast(int, consuming[9]),
    )
    values["confirmed"] = confirmed
    values["source_state"] = confirmed
    values["request"] = (capability, recovery_checkpoint)
    return values


def _prepare_native_issuer_checkpoint_g_source(
    native_module: ModuleType,
    directory: Path,
    source_phase: str,
) -> dict[str, object]:
    assert source_phase in {"claim_admitted", "armed"}
    _prepare_authority, prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(native_module)
    )
    shadow, projection, socket_owner, lease, capability, registered = (
        _new_registered_native_issuer_choreography_shadow(native_module, directory)
    )
    binder, authorization, claim, claim_payload, source_state = (
        _advance_native_issuer_checkpoint_e_to_phase(
            native_module,
            shadow,
            projection,
            lease,
            capability,
            registered,
            source_phase,
        )
    )
    if source_phase == "claim_admitted":
        assert claim is None and claim_payload is None
        claim_payload = _native_issuer_retained_claim_payload(projection)
        claim = prepare_witness(shadow, "retained_claim", claim_payload)
        _assert_native_issuer_checkpoint_e_claim_handle(
            snapshot,
            claim,
            claim_payload,
            status="prepared",
            status_revision=cast(int, source_state[3]),
        )
        _assert_native_issuer_choreography_handle_snapshot(
            snapshot,
            binder,
            record_class="authority",
            kind="recovery_claim_binder",
            status="installed",
            status_revision=cast(int, source_state[3]) - 1,
        )
    else:
        assert claim is not None and claim_payload is not None
        _assert_native_issuer_checkpoint_e_claim_handle(
            snapshot,
            claim,
            claim_payload,
            status="installed",
            status_revision=cast(int, source_state[3]),
        )
        _assert_native_issuer_choreography_handle_snapshot(
            snapshot,
            binder,
            record_class="authority",
            kind="recovery_claim_binder",
            status="consumed",
            status_revision=cast(int, source_state[3]),
        )
    assert snapshot(shadow) == source_state
    return {
        "shadow": shadow,
        "projection": projection,
        "socket_owner": socket_owner,
        "lease": lease,
        "capability": capability,
        "registered": registered,
        "binder": binder,
        "authorization": authorization,
        "claim": claim,
        "claim_payload": claim_payload,
        "source_state": source_state,
        "request": (binder, claim, "same" if source_phase == "armed" else "sample"),
    }


