def _assert_native_issuer_choreography_unbound_snapshot(
    snapshot_hook: Callable[[object], tuple[object, ...]],
    shadow: object,
    lease: object,
    capability: object,
    *,
    lifecycle_revision: int = 3,
    persistent_revision: int = 1,
    binding_generation: int = 1,
    current_scope_generation: int = 1,
    effective_action: bool = True,
) -> tuple[object, ...]:
    state = _assert_native_issuer_choreography_snapshot_is_builtin_only(
        snapshot_hook(shadow),
        expected_length=24,
    )
    lease_snapshot = _assert_native_issuer_choreography_handle_snapshot(
        snapshot_hook,
        lease,
        record_class="authority",
        kind="choreography_lease",
        status="installed",
        status_revision=persistent_revision,
    )
    capability_snapshot = _assert_native_issuer_choreography_handle_snapshot(
        snapshot_hook,
        capability,
        record_class="authority",
        kind="recovery_retention_capability",
        status="installed",
        status_revision=persistent_revision,
    )
    lease_key = _assert_native_issuer_choreography_record_key(lease_snapshot[7])
    capability_key = _assert_native_issuer_choreography_record_key(capability_snapshot[7])
    assert lease_key[0] == capability_key[0] == lease_snapshot[4] == capability_snapshot[4]
    assert lease_key[1] == capability_key[1] == current_scope_generation
    assert lease_key[2] == lease_snapshot[3]
    assert capability_key[2] == capability_snapshot[3]
    assert lease_key[2] != capability_key[2]
    assert state[:9] == (
        _NATIVE_ISSUER_CHOREOGRAPHY_STATE_TAG,
        lifecycle_revision,
        True,
        persistent_revision,
        binding_generation,
        current_scope_generation,
        "unbound",
        True,
        effective_action,
    )
    assert type(state[9]) is int and cast(int, state[9]) > 0
    assert state[10] == state[9]
    assert state[11] == cast(int, state[9]) + _NATIVE_ISSUER_CHOREOGRAPHY_ACTION_DEADLINE_DELTA_NS
    assert state[12] == (
        cast(int, state[9]) + _NATIVE_ISSUER_CHOREOGRAPHY_RETENTION_DEADLINE_DELTA_NS
    )
    assert state[13:] == (
        (),
        lease_key,
        capability_key,
        None,
        None,
        None,
        None,
        None,
        None,
        None,
        None,
    )
    return state


