    generation_rows = {
        cast(str, row[0]): row for row in _NATIVE_ISSUER_CHOREOGRAPHY_GENERATION_VECTOR
    }
    assert generation_rows["fresh"][1:6] == (1, 0, 0, 0, 0)
    assert generation_rows["first_prepare"][1:8] == (1, 0, 1, 0, 0, 1, 0)
    assert generation_rows["first_register"][1:8] == (1, 1, 0, 1, 1, 1, 0)
    assert generation_rows["first_consume"][1:6] == (1, 2, 0, 1, 2)
    assert generation_rows["first_consume"][8] == 1
    assert generation_rows["second_prepare"][1:8] == (1, 2, 3, 1, 2, 3, 2)
    assert generation_rows["second_register"][1:8] == (1, 3, 0, 2, 3, 3, 2)
    assert generation_rows["second_consume"][1:6] == (1, 4, 0, 2, 4)
    assert generation_rows["second_consume"][8] == 3
    for row in _NATIVE_ISSUER_CHOREOGRAPHY_GENERATION_VECTOR:
        assert type(row) is tuple and len(row) == 9
        assert type(row[1]) is int and row[1] > 0
        for value in row[2:6]:
            assert type(value) is int and value >= 0
        assert row[4] <= row[2]
