def test_native_issuer_checkpoint_a_c_manifests_are_internal_and_exact() -> None:
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_bytes = source_path.read_bytes()
    source_sha256 = hashlib.sha256(source_bytes).hexdigest()
    if source_sha256 not in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_C_SHA256
        | _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REGISTER_OR_LATER_C_SHA256
    ):
        pytest.skip("native issuer choreography source is not at a coherent checkpoint")
    checkpoint_f = source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_RECOVERY_OR_LATER_C_SHA256
    checkpoint_g = source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_SALVAGE_OR_LATER_C_SHA256
    checkpoint_h = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_POST_EFFECT_OR_LATER_C_SHA256
    )
    checkpoint_i = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REQUIRE_POST_EFFECT_OR_LATER_C_SHA256
    )
    checkpoint_o = _native_issuer_choreography_formal_force_revoke_source_is_coherent()
    checkpoint_n = _native_issuer_choreography_formal_expire_source_is_coherent()
    checkpoint_m = _native_issuer_choreography_abandon_controller_source_is_coherent()
    checkpoint_l = _native_issuer_choreography_attest_controller_durable_source_is_coherent()
    checkpoint_k = _native_issuer_choreography_confirm_controller_source_is_coherent()
    checkpoint_j = _native_issuer_choreography_begin_controller_source_is_coherent()
    checkpoint_i_surface_end = (
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_J_SURFACE_HELPER
        if checkpoint_j
        else "aqt_issuer_choreography_build_early_transition_failclosed_origin"
    )
    checkpoint_j_surface_end = (
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_SURFACE_HELPER
        if checkpoint_l
        else _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_K_SURFACE_HELPER
        if checkpoint_k
        else "aqt_issuer_choreography_build_early_transition_failclosed_origin"
    )
    checkpoint_e = source_sha256 in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BINDER_TRANSITIONS_OR_LATER_C_SHA256
    )
    checkpoint_d = checkpoint_e or source_sha256 in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_INFRASTRUCTURE_OR_LATER_C_SHA256
    )
    checkpoint_c = checkpoint_d or source_sha256 in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_OR_LATER_C_SHA256
    )
    checkpoint_b = source_sha256 in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REGISTER_OR_LATER_C_SHA256
    )
    source = source_bytes.decode("utf-8")

    def initializer(identifier: str) -> str:
        start = source.index(identifier)
        start = source.index("{", start)
        end = source.index("};", start)
        return source[start : end + 1]

    def string_literals(identifier: str) -> tuple[str, ...]:
        pieces = initializer(identifier).split('"')
        assert len(pieces) % 2 == 1
        return tuple(pieces[1::2])

    assert string_literals("aqt_issuer_choreography_hook_names[") == (
        _NATIVE_ISSUER_CHOREOGRAPHY_HOOK_NAMES
    )
    assert string_literals("aqt_issuer_choreography_phase_names[") == (
        _NATIVE_ISSUER_CHOREOGRAPHY_PHASES
    )
    assert string_literals("aqt_issuer_choreography_operation_manifest[") == (
        _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS
    )
    assert string_literals("aqt_issuer_choreography_authority_kind_names[") == (
        _NATIVE_ISSUER_CHOREOGRAPHY_AUTHORITY_KINDS
    )
    assert string_literals("aqt_issuer_choreography_witness_kind_names[") == (
        _NATIVE_ISSUER_CHOREOGRAPHY_WITNESS_KINDS
    )
