def test_native_issuer_checkpoint_b_static_register_is_one_native_transaction() -> None:
    _require_coherent_native_issuer_choreography_register_source()
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_bytes = source_path.read_bytes()
    checkpoint_e = hashlib.sha256(source_bytes).hexdigest() in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BINDER_TRANSITIONS_OR_LATER_C_SHA256
    )
    source = source_bytes.decode("utf-8")
    register = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_register",
        "aqt_fstat_owned",
    )
    ordered_markers = (
        "aqt_issuer_choreography_register_retry_is_exact_locked(",
        "aqt_issuer_choreography_register_pair_is_exact_locked(",
        "aqt_issuer_choreography_fault_plan_begin_locked(",
        "AQT_CHOREOGRAPHY_FAULT_REGISTER_POST_LATCH",
        "aqt_issuer_choreography_sample_continuous_ns(&sampled_now)",
        "UINT64_MAX - AQT_ISSUER_CHOREOGRAPHY_RETENTION_INTERVAL_NS",
        "AQT_CHOREOGRAPHY_FAULT_REGISTER_PRE_STATE_STORE",
        "aqt_issuer_external_projection_matches(shadow->projection)",
        "aqt_validate_launch_lock_core_locked(shadow->launch_lease)",
        "aqt_run_issuer_external_projection_barrier(",
        "aqt_issuer_external_projection_matches(shadow->projection)",
        "aqt_issuer_foreign_fork_interpose_locked(",
        "aqt_issuer_choreography_build_unbound_state_locked(",
        "state_was_stored = 1;",
        "AQT_CHOREOGRAPHY_FAULT_REGISTER_POST_STATE_STORE",
        "aqt_issuer_choreography_cell_is_exact_locked(shadow)",
        "aqt_issuer_foreign_fork_commit_locked(",
        "aqt_issuer_choreography_fault_plan_clear(fault_plan);",
        "aqt_unlock_owner_list_or_fail_stop();",
        "Py_RETURN_NONE;",
    )
    cursor = -1
    for marker in ordered_markers:
        cursor = register.index(marker, cursor + 1)
    assert register.count("aqt_issuer_external_projection_matches(shadow->projection)") == 2
    assert register.count("aqt_validate_launch_lock_core_locked(shadow->launch_lease)") == 1
    assert register.count("aqt_issuer_choreography_sample_continuous_ns(&sampled_now)") == 1
    assert register.count("aqt_run_issuer_external_projection_barrier(") == 1
    assert "UINT64_MAX - AQT_ISSUER_CHOREOGRAPHY_RETENTION_INTERVAL_NS" in register
    barrier_clear = "aqt_clear_issuer_external_projection_barrier(module_state);"
    assert register.count(barrier_clear) == (10 if checkpoint_e else 9)
    if checkpoint_e:
        assert (
            register.count(f"{barrier_clear}\n        aqt_free_issuer_projection(&prepared_roots);")
            == 6
        )
        assert register.count("return NULL;") == 7
        assert register.count("Py_RETURN_NONE;") == 2
        assert (
            f"{barrier_clear}\n        aqt_free_issuer_projection(&prepared_roots);\n"
            "        return aqt_issuer_choreography_runtime_error("
        ) in register
    else:
        assert register.count(f"{barrier_clear}\n        return NULL;") == 5
        assert register.count(f"{barrier_clear}\n        Py_RETURN_NONE;") == 2
        assert f"{barrier_clear}\n        return aqt_issuer_choreography_runtime_error(" in register
    final_barrier_clear = register.rindex(barrier_clear)
    assert final_barrier_clear < register.index(
        "aqt_issuer_choreography_detached_records_release(&detached);",
        final_barrier_clear,
    )
    assert final_barrier_clear < register.index(
        "aqt_issuer_choreography_failure_raise(&failure)",
        final_barrier_clear,
    )

    proof_positions = tuple(
        index
        for index in range(len(register))
        if register.startswith("aqt_issuer_external_projection_matches(shadow->projection)", index)
    )
    assert len(proof_positions) == 2
    build_unbound_position = register.index(
        "aqt_issuer_choreography_build_unbound_state_locked(",
        proof_positions[1],
    )
    successful_store_guard = register.rindex(
        "if (primary_kind < 0 && saved_errno == 0)",
        proof_positions[1],
        build_unbound_position,
    )
    successful_proof_to_store = register[successful_store_guard:build_unbound_position]
    assert proof_positions[1] < successful_store_guard
    assert "aqt_issuer_foreign_fork_interpose_locked(" in successful_proof_to_store
    assert all(
        recoverable not in successful_proof_to_store
        for recoverable in (
            "aqt_issuer_choreography_fault_take_locked(",
            "aqt_issuer_choreography_sample_continuous_ns(",
            "PyErr_",
            "return NULL",
        )
    )
    assert all(
        not line.strip().startswith(("saved_errno =", "primary_kind ="))
        for line in successful_proof_to_store.splitlines()[1:]
    )
    interpose_failure = successful_proof_to_store.index("aqt_issuer_foreign_fork_interpose_locked(")
    assert any(
        fail_stop in successful_proof_to_store[interpose_failure:]
        for fail_stop in ("aqt_fail_stop(", "abort();")
    )

    transaction_start = register.index("expected_revision = cell->persistent_state_revision;")
    transaction_end = register.rindex("aqt_unlock_owner_list_or_fail_stop();")
    under_transaction_lock = register[transaction_start:transaction_end]
    assert all(
        forbidden not in under_transaction_lock
        for forbidden in (
            "PyErr_",
            "PyObject_",
            "PyMem_",
            "PyLong_",
            "PyTuple_",
            "Py_BuildValue",
            "PyObject_Call",
        )
    )

    build_unbound = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_build_unbound_state_locked",
        "aqt_issuer_choreography_register_cleanup_reconcile_locked",
    )
    assert "next_revision = cell->persistent_state_revision + 1U;" in build_unbound
    assert "next_binding = cell->binding_generation + 1U;" in build_unbound
    assert "state.value.last_monotonic_ns = sampled_now;" in build_unbound
    assert "state.value.started_monotonic_ns = sampled_now;" in build_unbound
    assert "AQT_ISSUER_CHOREOGRAPHY_ACTION_INTERVAL_NS" in build_unbound
    assert "AQT_ISSUER_CHOREOGRAPHY_RETENTION_INTERVAL_NS" in build_unbound
    assert "state.value.phase = AQT_CHOREOGRAPHY_PHASE_UNBOUND;" in build_unbound
    assert "state.value.action_active = 1U;" in build_unbound
    assert build_unbound.index("cell->pending_scope_generation = 0U;") < build_unbound.index(
        "shadow->choreography_state_present = 1U;"
    )


def test_native_issuer_checkpoint_b_static_single_retirement_status_cannot_be_reused() -> None:
    _require_coherent_native_issuer_choreography_register_source()
    source = (Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c").read_text(
        encoding="utf-8"
    )

    effective_status = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_record_effective_status_locked",
        "aqt_allocate_issuer_choreography_record",
    )
    owner_dead = effective_status.index("if (cell->alive == 0U")
    retired_prepared = effective_status.index(
        "if (record->status == 0U",
        owner_dead,
    )
    assert owner_dead < retired_prepared < effective_status.index("return record->status;")
    compact_effective_status = " ".join(effective_status.split())
    assert (
        "record->status == 0U && cell->last_scope_retirement.kind "
        "== AQT_CHOREOGRAPHY_SCOPE_RETIREMENT_ORDINARY && "
        "cell->last_scope_retirement.old_scope_generation "
        "== record->key.scope_generation"
    ) in compact_effective_status

    cell_gate = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_cell_is_exact_locked",
        "aqt_issuer_choreography_scope_retire_locked",
    )
    ordinary_retirement = cell_gate.index("AQT_CHOREOGRAPHY_SCOPE_RETIREMENT_ORDINARY")
    ordinary_terminal_gate = cell_gate[ordinary_retirement:]
    for exact_terminal_condition in (
        "shadow->state != AQT_ISSUER_NATIVE_STATE_CLOSED",
        "shadow->choreography_state_present",
        "cell->pending_scope_generation != 0U",
        "cell->action_live != 0U",
    ):
        assert exact_terminal_condition in ordinary_terminal_gate

    bounded_retirement = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint_b_retirement_is_bounded_locked",
        "aqt_issuer_choreography_cell_is_exact_locked",
    )
    assert "!= AQT_CHOREOGRAPHY_SCOPE_RETIREMENT_ORDINARY" in bounded_retirement
    assert "shadow->state == AQT_ISSUER_NATIVE_STATE_CLOSED" in bounded_retirement
    assert "!shadow->choreography_state_present" in bounded_retirement
    assert "cell->pending_scope_generation == 0U" in bounded_retirement
    assert "cell->action_live == 0U" in bounded_retirement
    assert "cell->lifecycle_disposition == AQT_CHOREOGRAPHY_CELL_CLOSED" in (bounded_retirement)

    prepare_preflight = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_prepare_preflight",
        "aqt_issuer_choreography_prepare_record",
    )
    assert "shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY" in prepare_preflight
    assert "shadow->choreography_state_present" in prepare_preflight
    assert "!aqt_issuer_shadow_has_live_lease(shadow)" in prepare_preflight

    close = _native_c_function_slice(
        source,
        "aqt_issuer_shadow_close",
        "aqt_issuer_choreography_register",
    )
    close_store = close.index("shadow->state = AQT_ISSUER_NATIVE_STATE_CLOSED;")
    close_retire = close.index("aqt_issuer_choreography_scope_retire_locked(", close_store)
    assert close_store < close_retire
    assert (
        "AQT_CHOREOGRAPHY_SCOPE_RETIREMENT_ORDINARY"
        in close[close_retire : close.index("terminal_committed = 1;", close_retire)]
    )

    owner_dealloc = _native_c_function_slice(
        source,
        "aqt_issuer_shadow_dealloc",
        "aqt_issuer_shadow_self_test",
    )
    dealloc_retire = owner_dealloc.index("aqt_issuer_choreography_scope_retire_locked(")
    dealloc_dead = owner_dealloc.index("authority_cell->alive = 0U;", dealloc_retire)
    dealloc_retired = owner_dealloc.index(
        "authority_cell->lifecycle_disposition = AQT_CHOREOGRAPHY_CELL_RETIRED;",
        dealloc_dead,
    )
    assert dealloc_retire < dealloc_dead < dealloc_retired

    reconcile = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_register_cleanup_reconcile_locked",
        "aqt_issuer_choreography_register",
    )
    precommit_retire = reconcile.index("aqt_issuer_choreography_scope_retire_locked(")
    lease_revoke = reconcile.index(
        "lease_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;",
        precommit_retire,
    )
    capability_revoke = reconcile.index(
        "recovery_record->status = AQT_CHOREOGRAPHY_AUTHORITY_REVOKED;",
        lease_revoke,
    )
    assert precommit_retire < lease_revoke < capability_revoke

    pair_gate = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_register_pair_is_exact_locked",
        "aqt_issuer_choreography_build_unbound_state_locked",
    )
    assert pair_gate.count("== AQT_CHOREOGRAPHY_AUTHORITY_PREPARED") == 2
    assert "return cell_references == 3U" in pair_gate

    # Checkpoint B has exactly three scope-retirement callers. Close is terminal,
    # owner deallocation makes OWNER_DEAD authoritative, and precommit cleanup
    # intrinsically revokes both records before any scope-three pair can register.
    assert source.count("aqt_issuer_choreography_scope_retire_locked(") == 4

    close_self_test = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint_b_close_retirement_self_test",
        "aqt_issuer_choreography_checkpoint_b_failclosed_history_self_test",
    )
    assert close_self_test.count("aqt_issuer_shadow_close(module, shadow)") == 2
    assert "memcmp(\n            &cell->last_scope_retirement" in close_self_test
    assert "aqt_issuer_choreography_prepare_preflight(shadow) >= 0" in close_self_test
    assert "aqt_issuer_choreography_register(" in close_self_test
    assert "AQT_CHOREOGRAPHY_AUTHORITY_OWNER_DEAD" in close_self_test
    assert "AQT_CHOREOGRAPHY_WITNESS_OWNER_DEAD" in close_self_test

    failclosed_history_self_test = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint_b_failclosed_history_self_test",
        "aqt_fstat_owned",
    )
    assert "AQT_CHOREOGRAPHY_SCOPE_RETIREMENT_FAILCLOSED_CLEANUP" in (failclosed_history_self_test)
    assert "aqt_issuer_choreography_register_pair_is_exact_locked(" in (
        failclosed_history_self_test
    )
    assert "aqt_issuer_choreography_build_unbound_state_locked(" in (failclosed_history_self_test)
    assert "aqt_issuer_choreography_register_cleanup_reconcile_locked(" in (
        failclosed_history_self_test
    )
    assert "native issuer choreography U rewrote failclosed history" in (
        failclosed_history_self_test
    )
    assert "native issuer choreography RV rewrote failclosed history" in (
        failclosed_history_self_test
    )

    self_test = _native_c_function_slice(source, "aqt_self_test", "aqt_force_second_exec_for_test")
    assert "aqt_issuer_choreography_checkpoint_b_close_retirement_self_test(" in self_test
    assert "aqt_issuer_choreography_checkpoint_b_failclosed_history_self_test(" in self_test


def test_native_issuer_checkpoint_b_static_cleanup_and_fork_publication_are_exact() -> None:
    _require_coherent_native_issuer_choreography_register_source()
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_bytes = source_path.read_bytes()
    checkpoint_c = (
        hashlib.sha256(source_bytes).hexdigest()
        in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_OR_LATER_C_SHA256
    )
    source = source_bytes.decode("utf-8")
    register = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_register",
        "aqt_fstat_owned",
    )
    cleanup_loop_start = register.index("for (index = 0; index < 4; index++)")
    cleanup_loop_end = register.index(
        "aqt_issuer_choreography_fault_plan_clear", cleanup_loop_start
    )
    cleanup = register[cleanup_loop_start:cleanup_loop_end]
    loop_reconcile = cleanup.index("aqt_issuer_choreography_register_cleanup_reconcile_locked(")
    loop_confirm = cleanup.index("aqt_issuer_choreography_cell_is_exact_locked(shadow)")
    point_take = cleanup.index("AQT_CHOREOGRAPHY_FAULT_REGISTER_CLEANUP_ATTEMPT")
    final_reconcile = cleanup.index(
        "aqt_issuer_choreography_register_cleanup_reconcile_locked(",
        loop_reconcile + 1,
    )
    final_confirm = cleanup.index(
        "aqt_issuer_choreography_cell_is_exact_locked(shadow)",
        loop_confirm + 1,
    )
    assert loop_reconcile < loop_confirm < point_take < final_reconcile < final_confirm
    assert cleanup.count("AQT_CHOREOGRAPHY_FAULT_REGISTER_CLEANUP_ATTEMPT") == 1
    assert cleanup.count("aqt_issuer_choreography_fault_take_locked(") == 1
    assert cleanup.count("aqt_fail_stop(") >= 2
    assert register.index("aqt_unlock_owner_list_or_fail_stop();", final_confirm) < register.index(
        "aqt_issuer_choreography_detached_records_release(&detached);"
    )
    assert register.index("aqt_issuer_choreography_detached_records_release(&detached);") < (
        register.index("aqt_issuer_choreography_failure_raise(&failure)")
    )

    reconcile = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_register_cleanup_reconcile_locked",
        "aqt_issuer_choreography_detached_records_release",
    )
    assert "AQT_CHOREOGRAPHY_SCOPE_RETIREMENT_FAILCLOSED_CLEANUP" in reconcile
    assert "cell->current_scope_generation == selected_scope + 1U" in reconcile
    assert "cell->binding_generation == expected_binding" in reconcile
    assert "cell->last_scope_retirement.terminal_key_is_present" in reconcile
    assert "AQT_CHOREOGRAPHY_PHASE_REVOKED" in reconcile

    point_gate = _native_c_function_slice(
        source,
        "aqt_issuer_foreign_fork_point_accepts_shadow",
        "aqt_test_configure_topology_observation_issuer_shadow_foreign_fork_interposition",
    )
    assert "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_REGISTER_POST_STATE_COMMIT" in point_gate
    transition_point = "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT"
    assert (transition_point in point_gate) is checkpoint_c
    failclosed_point = "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT"
    assert (failclosed_point in point_gate) is checkpoint_c
    assert "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_CONSUME_PRE_STATE_DETACH" not in point_gate
    child_gate = _native_c_function_slice(
        source,
        "aqt_issuer_foreign_fork_child_publication_is_exact",
        "aqt_issuer_foreign_fork_worker",
    )
    assert "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_REGISTER_POST_STATE_COMMIT" in child_gate
    assert "shadow->runtime_ready == 0U" in child_gate
    assert "AQT_CHOREOGRAPHY_PHASE_UNBOUND" in child_gate
    assert "cell->reference_count" in child_gate
    assert "== 3U" in child_gate

    close = _native_c_function_slice(
        source, "aqt_issuer_shadow_close", "aqt_issuer_choreography_register"
    )
    ordinary_retirement = close.index("AQT_CHOREOGRAPHY_SCOPE_RETIREMENT_ORDINARY")
    state_rejection = close.index("shadow->choreography_state_present")
    assert state_rejection < ordinary_retirement
    assert "live_choreography_state_rejected = 1;" in close[:ordinary_retirement]


def test_native_issuer_checkpoint_b_surface_and_fresh_snapshot(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
) -> None:
    _require_coherent_native_issuer_choreography_register_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, prepare_witness, register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    expected_signatures = (
        "(shadow, kind, /)",
        "(shadow, kind, payload, /)",
        "(shadow, lease, recovery_cap, /)",
        "(candidate, /)",
        "(point, kind, occurrence, /)",
    )
    for hook, expected_signature in zip(
        (prepare_authority, prepare_witness, register, snapshot, configure),
        expected_signatures,
        strict=True,
    ):
        assert str(inspect.signature(hook)) == expected_signature
    source = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    checkpoint_c = (
        hashlib.sha256(source.read_bytes()).hexdigest()
        in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_OR_LATER_C_SHA256
    )
    hidden_names = (
        _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_HIDDEN_HOOK_NAMES
        if checkpoint_c
        else _NATIVE_ISSUER_CHOREOGRAPHY_REGISTER_HIDDEN_HOOK_NAMES
    )
    assert all(not hasattr(test_module, name) for name in hidden_names)
    if checkpoint_c:
        transition = _native_issuer_choreography_transition_hook(test_module)
        assert str(inspect.signature(transition)) == "(shadow, tag, request, /)"
    assert all(
        not hasattr(test_module, name) for name in _NATIVE_ISSUER_CHOREOGRAPHY_TYPE_ATTRIBUTES
    )
    shadow = test_module._test_create_inert_topology_observation_issuer_shadow()
    assert snapshot(shadow) == _native_issuer_choreography_absent_snapshot(1)
    assert test_module._test_topology_observation_issuer_shadow_state(shadow) == (
        _NATIVE_ISSUER_LIFECYCLE_INERT_SNAPSHOT
    )
    assert shadow._observation_choreography_is_valid_locked(object()) is False
    with pytest.raises(RuntimeError):
        prepare_authority(shadow, "choreography_lease")
    with pytest.raises(RuntimeError):
        prepare_witness(
            shadow,
            "retained_claim",
            ("", "", "", "", "", ""),
        )
    for candidate in (None, True, 0, object(), (), "shadow"):
        with pytest.raises((RuntimeError, TypeError, ValueError)):
            snapshot(candidate)
    assert configure(-1, 0, 0) is None


def test_native_issuer_checkpoint_b_prepare_wrappers_and_snapshots(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_register_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    shadow, projection, socket_owner = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / "prepare-wrappers",
    )
    try:
        assert snapshot(shadow) == _native_issuer_choreography_absent_snapshot(3)
        lease = prepare_authority(shadow, "choreography_lease")
        capability = prepare_authority(shadow, "recovery_retention_capability")
        payload = _native_issuer_retained_claim_payload(projection)
        claim = prepare_witness(shadow, "retained_claim", payload)

        lease_snapshot = _assert_native_issuer_choreography_handle_snapshot(
            snapshot,
            lease,
            record_class="authority",
            kind="choreography_lease",
            status="prepared",
            status_revision=0,
        )
        capability_snapshot = _assert_native_issuer_choreography_handle_snapshot(
            snapshot,
            capability,
            record_class="authority",
            kind="recovery_retention_capability",
            status="prepared",
            status_revision=0,
        )
        claim_snapshot = _assert_native_issuer_choreography_handle_snapshot(
            snapshot,
            claim,
            record_class="witness",
            kind="retained_claim",
            status="prepared",
            status_revision=0,
        )
        lease_key = _assert_native_issuer_choreography_record_key(lease_snapshot[7])
        capability_key = _assert_native_issuer_choreography_record_key(capability_snapshot[7])
        claim_summary = cast(tuple[object, ...], claim_snapshot[7])
        assert type(claim_summary) is tuple and len(claim_summary) == 3
        claim_key = _assert_native_issuer_choreography_record_key(claim_summary[0])
        assert lease_key[:2] == capability_key[:2] == claim_key[:2]
        assert lease_key[1] == 1
        assert lease_key[2] < capability_key[2] < claim_key[2] == claim_snapshot[3]
        assert claim_summary == (
            claim_key,
            payload[:5],
            payload[5],
        )
        assert repr(lease) == repr(capability) == _NATIVE_ISSUER_CHOREOGRAPHY_AUTHORITY_REPR
        assert repr(claim) == _NATIVE_ISSUER_CHOREOGRAPHY_WITNESS_REPR
        for handle in (lease, capability, claim):
            with pytest.raises(TypeError):
                hash(handle)
            with pytest.raises(TypeError):
                copy(handle)
            with pytest.raises(TypeError):
                deepcopy(handle)
            with pytest.raises((pickle.PickleError, TypeError)):
                pickle.dumps(handle)
            assert not hasattr(handle, "__dict__")
            assert gc.is_tracked(handle) is False
            assert gc.get_referents(handle) == []
        del handle

        authority_type = type(lease)
        witness_type = type(claim)
        assert type(capability) is authority_type
        assert authority_type is not witness_type
        for wrapper_type in (authority_type, witness_type):
            flags = type.__getattribute__(wrapper_type, "__flags__")
            assert flags & (1 << 7)
            assert flags & (1 << 8)
            assert not flags & (1 << 9)
            assert not flags & (1 << 10)
            with pytest.raises(TypeError):
                wrapper_type()
            with pytest.raises(TypeError):
                type("HostileNativeChoreographyHandle", (wrapper_type,), {})
            with pytest.raises(TypeError):
                type.__setattr__(wrapper_type, "hostile", object())

        claim_reference = weakref.ref(claim)
        del claim
        gc.collect()
        assert claim_reference() is None
        assert snapshot(shadow) == _native_issuer_choreography_absent_snapshot(3)
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


