@pytest.mark.parametrize(
    "mutation",
    [
        "kind",
        "kind_subclass",
        "payload_list",
        "payload_subclass",
        "payload_short",
        "operation_upper",
        "operation_non_v4",
        "approval_upper",
        "claim_short",
        "retained_nonhex",
        "artifact_foreign",
        "binding_upper",
        "scalar_subclass",
    ],
)
def test_native_issuer_checkpoint_b_retained_claim_schema_is_exact(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    mutation: str,
) -> None:
    _require_coherent_native_issuer_choreography_register_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _prepare_authority, prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    shadow, projection, socket_owner = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / "claim-schema",
    )
    valid = _native_issuer_retained_claim_payload(projection)

    class TextSubclass(str):
        pass

    class TupleSubclass(tuple):
        pass

    kind: object = "retained_claim"
    payload: object = valid
    if mutation == "kind":
        kind = "recovery_checkpoint"
    elif mutation == "kind_subclass":
        kind = TextSubclass("retained_claim")
    elif mutation == "payload_list":
        payload = list(valid)
    elif mutation == "payload_subclass":
        payload = TupleSubclass(valid)
    elif mutation == "payload_short":
        payload = valid[:-1]
    elif mutation == "operation_upper":
        payload = (valid[0].upper(), *valid[1:])
    elif mutation == "operation_non_v4":
        payload = ("123e4567-e89b-12d3-a456-426614174000", *valid[1:])
    elif mutation == "approval_upper":
        payload = (valid[0], "A" * 64, *valid[2:])
    elif mutation == "claim_short":
        payload = (*valid[:2], "2" * 63, *valid[3:])
    elif mutation == "retained_nonhex":
        payload = (*valid[:3], "g" * 64, *valid[4:])
    elif mutation == "artifact_foreign":
        payload = (*valid[:4], f"{valid[4]}-foreign", valid[5])
    elif mutation == "binding_upper":
        payload = (*valid[:5], "F" * 64)
    else:
        assert mutation == "scalar_subclass"
        payload = (TextSubclass(valid[0]), *valid[1:])
    try:
        with pytest.raises((RuntimeError, TypeError, ValueError)):
            prepare_witness(shadow, kind, payload)  # type: ignore[arg-type]
        assert snapshot(shadow) == _native_issuer_choreography_absent_snapshot(3)
        claim = prepare_witness(shadow, "retained_claim", valid)
        claim_snapshot = _assert_native_issuer_choreography_handle_snapshot(
            snapshot,
            claim,
            record_class="witness",
            kind="retained_claim",
            status="prepared",
            status_revision=0,
        )
        assert claim_snapshot[3] == 1
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


