@pytest.mark.parametrize(
    "mutation",
    ["executable_mode", "executable_identity", "socket_mode", "socket_identity"],
)
def test_native_issuer_checkpoint_b_register_terminal_barrier_rejects_live_swap(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    mutation: str,
) -> None:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    _require_coherent_native_issuer_choreography_register_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    _activate, _burn, close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    configure_barrier = cast(
        Callable[[int, int], None],
        getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME),
    )
    shadow, projection, socket_owner = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / f"register-terminal-{mutation}",
    )
    lease = prepare_authority(shadow, "choreography_lease")
    capability = prepare_authority(shadow, "recovery_retention_capability")
    child_pid = -1
    ready_write = -1
    resume_read = -1
    child_reaped = False
    backup_paths: tuple[Path, ...] = ()
    try:
        child_pid, ready_write, resume_read, backup_paths = (
            _fork_native_issuer_external_projection_mutator(projection, mutation)
        )
        assert configure_barrier(ready_write, resume_read) is None
        with pytest.raises(OSError):
            register(shadow, lease, capability)
        child_status = _reap_native_issuer_external_projection_mutator(
            child_pid,
            ready_write,
            resume_read,
        )
        child_reaped = True
        ready_write = -1
        resume_read = -1
        assert child_status == 0
        assert test_module._test_topology_observation_issuer_shadow_state(shadow) == (
            _native_issuer_explicit_burned_snapshot(projection)
        )
        assert snapshot(shadow) == _native_issuer_choreography_absent_snapshot(
            4,
            persistent_revision=1,
            current_scope_generation=2,
        )
        for handle, expected_kind in (
            (lease, "choreography_lease"),
            (capability, "recovery_retention_capability"),
        ):
            _assert_native_issuer_choreography_handle_snapshot(
                snapshot,
                handle,
                record_class="authority",
                kind=expected_kind,
                status="revoked",
                status_revision=1,
            )
        assert close(shadow) is None
        assert test_module._test_topology_observation_issuer_shadow_state(shadow) == (
            _native_issuer_closed_snapshot(5)
        )

        repaired_projection = _repair_native_issuer_external_projection(
            projection,
            mutation,
        )
        contender = test_module._test_create_inert_topology_observation_issuer_shadow()
        activate, _burn, contender_close, _validate, _configure = _native_issuer_lifecycle_hooks(
            test_module
        )
        assert activate(contender, repaired_projection) is None
        assert contender_close(contender) is None
    finally:
        if child_pid > 0 and not child_reaped:
            child_status = _reap_native_issuer_external_projection_mutator(
                child_pid,
                ready_write,
                resume_read,
            )
            child_reaped = True
            assert child_status == 0
        _close_native_issuer_projection_socket(projection, socket_owner)
        for backup_path in backup_paths:
            with suppress(FileNotFoundError):
                backup_path.unlink()


