@pytest.mark.parametrize("exit_case", ["pair_rejection", "plan_rejection", "exact_retry"])
def test_native_issuer_checkpoint_b_every_register_exit_clears_stale_barrier(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    exit_case: str,
) -> None:
    _require_coherent_native_issuer_choreography_register_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    _activate, burn, _close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    configure_barrier = cast(
        Callable[[int, int], None],
        getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME),
    )
    shadow, projection, socket_owner = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / f"register-exit-barrier-clear-{exit_case}",
    )
    lease = prepare_authority(shadow, "choreography_lease")
    capability = prepare_authority(shadow, "recovery_retention_capability")
    barrier: tuple[int, int, int, int] | None = None
    final_barrier: tuple[int, int, int, int] | None = None
    try:
        if exit_case == "exact_retry":
            assert register(shadow, lease, capability) is None
        elif exit_case == "plan_rejection":
            assert configure(0, 0, 1) is None
        else:
            assert exit_case == "pair_rejection"
        barrier = _configure_native_issuer_preloaded_external_projection_barrier(configure_barrier)
        if exit_case == "exact_retry":
            assert register(shadow, lease, capability) is None
        elif exit_case == "plan_rejection":
            with pytest.raises(RuntimeError):
                register(shadow, lease, capability)
        else:
            with pytest.raises(RuntimeError):
                register(shadow, capability, lease)
        _assert_native_issuer_preloaded_barrier_was_not_consumed(barrier)
        barrier = None

        final_barrier = _configure_native_issuer_preloaded_external_projection_barrier(
            configure_barrier
        )
        assert burn(shadow) is None
        _assert_native_issuer_preloaded_barrier_was_not_consumed(final_barrier)
        final_barrier = None
        if exit_case == "exact_retry":
            _assert_native_issuer_choreography_unbound_snapshot(
                snapshot,
                shadow,
                lease,
                capability,
                lifecycle_revision=4,
                effective_action=False,
            )
        else:
            assert snapshot(shadow) == _native_issuer_choreography_absent_snapshot(4)
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        if barrier is not None:
            _close_native_issuer_external_projection_barrier_descriptors(barrier)
        if final_barrier is not None:
            _close_native_issuer_external_projection_barrier_descriptors(final_barrier)
        _close_native_issuer_projection_socket(projection, socket_owner)


