@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", ["store", "return"])
def test_native_issuer_checkpoint_b_register_lost_python_result_preserves_unbound(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    _require_coherent_native_issuer_choreography_register_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    shadow, projection, socket_owner = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / f"register-lost-{failure_type.__name__}-{boundary}",
    )
    lease = prepare_authority(shadow, "choreography_lease")
    capability = prepare_authority(shadow, "recovery_retention_capability")

    def register_at_boundary() -> object:
        result = register(shadow, lease, capability)
        return result

    offset = _instruction_offset(
        register_at_boundary,
        opname="STORE_FAST" if boundary == "store" else "RETURN_VALUE",
        argval="result" if boundary == "store" else None,
    )
    failure: BaseException = SystemExit(254) if failure_type is SystemExit else KeyboardInterrupt()
    tool_id = _enable_instruction_interrupt(
        register_at_boundary,
        offset,
        tool_name=f"native-issuer-choreography-register-{boundary}",
        interruption=failure,
    )
    try:
        with pytest.raises(failure_type) as retained:
            register_at_boundary()
        assert retained.value is failure
    finally:
        _disable_instruction_interrupt(tool_id, register_at_boundary)
    try:
        registered = _assert_native_issuer_choreography_unbound_snapshot(
            snapshot,
            shadow,
            lease,
            capability,
        )
        assert register(shadow, lease, capability) is None
        assert snapshot(shadow) == registered
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


