@pytest.mark.parametrize("burn_first", [False, True])
def test_native_issuer_checkpoint_b_pending_close_retires_ordinary_and_never_resurrects(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    burn_first: bool,
) -> None:
    _require_coherent_native_issuer_choreography_register_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, prepare_witness, register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    _activate, burn, close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    shadow, projection, socket_owner = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / f"pending-close-{burn_first}",
    )
    lease = prepare_authority(shadow, "choreography_lease")
    capability = prepare_authority(shadow, "recovery_retention_capability")
    claim = prepare_witness(
        shadow,
        "retained_claim",
        _native_issuer_retained_claim_payload(projection),
    )
    try:
        if burn_first:
            assert burn(shadow) is None
            assert test_module._test_topology_observation_issuer_shadow_state(shadow) == (
                _native_issuer_explicit_burned_snapshot(projection)
            )
            for handle, record_class, expected_kind in (
                (lease, "authority", "choreography_lease"),
                (capability, "authority", "recovery_retention_capability"),
                (claim, "witness", "retained_claim"),
            ):
                _assert_native_issuer_choreography_handle_snapshot(
                    snapshot,
                    handle,
                    record_class=record_class,
                    kind=expected_kind,
                    status="prepared",
                    status_revision=0,
                )
            with pytest.raises(RuntimeError):
                register(shadow, lease, capability)
        assert close(shadow) is None
        lifecycle_revision = 5 if burn_first else 4
        closed_lifecycle_snapshot = _native_issuer_closed_snapshot(lifecycle_revision)
        closed_choreography_snapshot = _native_issuer_choreography_absent_snapshot(
            lifecycle_revision,
            persistent_revision=1,
            current_scope_generation=2,
        )
        assert (
            test_module._test_topology_observation_issuer_shadow_state(shadow)
            == closed_lifecycle_snapshot
        )
        assert snapshot(shadow) == closed_choreography_snapshot
        for handle, expected_kind in (
            (lease, "choreography_lease"),
            (capability, "recovery_retention_capability"),
        ):
            _assert_native_issuer_choreography_handle_snapshot(
                snapshot,
                handle,
                record_class="authority",
                kind=expected_kind,
                status="revoked",
                status_revision=1,
            )
        _assert_native_issuer_choreography_handle_snapshot(
            snapshot,
            claim,
            record_class="witness",
            kind="retained_claim",
            status="cleared",
            status_revision=1,
        )
        terminal_handle_snapshots = tuple(snapshot(handle) for handle in (lease, capability, claim))
        assert close(shadow) is None
        assert (
            test_module._test_topology_observation_issuer_shadow_state(shadow)
            == closed_lifecycle_snapshot
        )
        assert snapshot(shadow) == closed_choreography_snapshot
        assert tuple(snapshot(handle) for handle in (lease, capability, claim)) == (
            terminal_handle_snapshots
        )
        with pytest.raises(RuntimeError):
            register(shadow, lease, capability)
        with pytest.raises(RuntimeError):
            prepare_authority(shadow, "choreography_lease")
        with pytest.raises(RuntimeError):
            prepare_witness(
                shadow,
                "retained_claim",
                _native_issuer_retained_claim_payload(projection),
            )

        shadow_reference = weakref.ref(shadow)
        shadow = None
        gc.collect()
        assert shadow_reference() is None
        for handle, record_class, expected_kind in (
            (lease, "authority", "choreography_lease"),
            (capability, "authority", "recovery_retention_capability"),
            (claim, "witness", "retained_claim"),
        ):
            _assert_native_issuer_choreography_handle_snapshot(
                snapshot,
                handle,
                record_class=record_class,
                kind=expected_kind,
                status="owner_dead",
                status_revision=2,
            )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


