def test_native_issuer_checkpoint_b_activation_thread_owns_prepare_and_register(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_register_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    shadow, projection, socket_owner = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / "activation-thread",
    )
    results: list[type[BaseException] | None] = []

    def foreign_prepare() -> None:
        try:
            prepare_authority(shadow, "choreography_lease")
        except BaseException as error:
            results.append(type(error))
        else:
            results.append(None)

    thread = threading.Thread(target=foreign_prepare)
    thread.start()
    thread.join(timeout=5.0)
    assert not thread.is_alive()
    try:
        assert results == [RuntimeError]
        assert snapshot(shadow) == _native_issuer_choreography_absent_snapshot(3)
        lease = prepare_authority(shadow, "choreography_lease")
        capability = prepare_authority(shadow, "recovery_retention_capability")

        register_results: list[type[BaseException] | None] = []

        def foreign_register() -> None:
            try:
                register(shadow, lease, capability)
            except BaseException as error:
                register_results.append(type(error))
            else:
                register_results.append(None)

        register_thread = threading.Thread(target=foreign_register)
        register_thread.start()
        register_thread.join(timeout=5.0)
        assert not register_thread.is_alive()
        assert register_results == [RuntimeError]
        assert snapshot(shadow) == _native_issuer_choreography_absent_snapshot(3)

        assert register(shadow, lease, capability) is None
        _assert_native_issuer_choreography_unbound_snapshot(
            snapshot,
            shadow,
            lease,
            capability,
        )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


