def test_native_issuer_checkpoint_b_inherited_child_rejects_state_and_handles(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_register_source()
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    shadow, projection, socket_owner = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / "ordinary-fork",
    )
    lease = prepare_authority(shadow, "choreography_lease")
    capability = prepare_authority(shadow, "recovery_retention_capability")
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through parent pipe
        os.close(read_descriptor)
        results: list[bool] = []
        for operation in (
            lambda: snapshot(shadow),
            lambda: snapshot(lease),
            lambda: snapshot(capability),
            lambda: register(shadow, lease, capability),
        ):
            try:
                operation()
            except RuntimeError:
                results.append(True)
            except BaseException:
                results.append(False)
            else:
                results.append(False)
        os.write(write_descriptor, bytes(results))
        os.close(write_descriptor)
        os._exit(0 if results == [True, True, True, True] else 1)
    os.close(write_descriptor)
    child_reaped = False
    try:
        ready, _, _ = select.select([read_descriptor], [], [], 5.0)
        if not ready:
            os.kill(child_pid, 9)
            os.waitpid(child_pid, 0)
            child_reaped = True
            raise AssertionError("forked choreography operation did not terminate")
        assert os.read(read_descriptor, 4) == b"\x01\x01\x01\x01"
        waited_pid, status = os.waitpid(child_pid, 0)
        child_reaped = True
        assert waited_pid == child_pid
        assert os.waitstatus_to_exitcode(status) == 0
        assert register(shadow, lease, capability) is None
        _assert_native_issuer_choreography_unbound_snapshot(
            snapshot,
            shadow,
            lease,
            capability,
        )
    finally:
        if not child_reaped:
            with suppress(ProcessLookupError):
                os.kill(child_pid, 9)
            with suppress(ChildProcessError):
                os.waitpid(child_pid, 0)
        os.close(read_descriptor)
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_checkpoint_b_fork_plan_mismatch_and_cancellation_are_transactional(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_register_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    configure_fork, finish_fork = _native_issuer_foreign_fork_hooks(test_module)
    first, first_projection, first_socket = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / "fork-plan-first",
    )
    second, second_projection, second_socket = _new_active_native_issuer_choreography_shadow(
        test_module,
        tmp_path / "fork-plan-second",
    )
    first_lease = prepare_authority(first, "choreography_lease")
    first_capability = prepare_authority(first, "recovery_retention_capability")
    second_lease = prepare_authority(second, "choreography_lease")
    second_capability = prepare_authority(second, "recovery_retention_capability")
    plan_finished = False
    try:
        assert configure_fork(first, 5) is None
        with pytest.raises(RuntimeError):
            configure_fork(first, 5)
        with pytest.raises(RuntimeError):
            configure_fork(second, 5)
        with pytest.raises(RuntimeError):
            register(second, second_lease, second_capability)
        assert snapshot(second) == _native_issuer_choreography_absent_snapshot(3)
        assert register(first, first_lease, first_capability) is None
        _assert_native_issuer_foreign_fork_result(finish_fork(), 5)
        plan_finished = True
        with pytest.raises(RuntimeError):
            finish_fork()

        assert configure_fork(second, 5) is None
        with pytest.raises(RuntimeError):
            finish_fork()
        with pytest.raises(RuntimeError):
            finish_fork()
        assert snapshot(second) == _native_issuer_choreography_absent_snapshot(3)
    finally:
        if not plan_finished:
            with suppress(RuntimeError):
                finish_fork()
        _close_native_issuer_projection_socket(first_projection, first_socket)
        _close_native_issuer_projection_socket(second_projection, second_socket)


