def test_native_issuer_checkpoint_c_contract_is_exact_and_runtime_gated() -> None:
    assert type(_COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_C_SHA256) is frozenset
    assert (
        frozenset({"2e2056d2330abfd808ae38c38007d5fde421af7d939404628072e899795a6a7b"})
        == _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_C_SHA256
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_EXPORTED_HOOK_INDICES == (
        0,
        1,
        2,
        3,
        6,
        7,
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_EXPORTED_HOOK_NAMES == (
        "_test_prepare_topology_observation_issuer_shadow_choreography_authority",
        "_test_prepare_topology_observation_issuer_shadow_choreography_witness",
        "_test_register_topology_observation_issuer_shadow_choreography",
        "_test_transition_topology_observation_issuer_shadow_choreography",
        "_test_topology_observation_issuer_shadow_choreography_snapshot",
        "_test_configure_topology_observation_issuer_shadow_choreography_failure",
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_HIDDEN_HOOK_NAMES == (
        "_test_failclosed_topology_observation_issuer_shadow_choreography",
        "_test_consume_topology_observation_issuer_shadow_choreography",
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_TAG == "checkpoint"
    assert _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_TIME_SELECTORS == (
        "same",
        "sample",
        "rollback",
        "action_deadline",
        "retention_deadline",
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_TIME_VECTORS == (
        ("same", "equal_stored_last", "unbound", "stored_last"),
        ("sample", "stored_last_through_before_action", "unbound", "sample"),
        ("sample", "before_stored_last", "revoked", "stored_last"),
        ("sample", "at_action_through_before_retention", "revoked", "sample"),
        ("sample", "at_or_after_retention", "revoked", "stored_last"),
        ("rollback", "one_before_stored_last", "revoked", "stored_last"),
        ("action_deadline", "exact_action_deadline", "revoked", "action_deadline"),
        ("retention_deadline", "pre_latch_rejection", "unbound", "unchanged"),
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_FAULT_POINTS == (8, 9, 10, 11)
    assert _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_FORK_POINTS == (5, 6, 7, 9)
    assert _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_FAILURE_ORIGIN == (
        "present",
        "group_3",
        "checkpoint",
        "expected_unbound",
        "committed_absent_or_candidate",
        "target_revoked",
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_PREPARED_AUTHORITY_KINDS == (
        "choreography_lease",
        "recovery_retention_capability",
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_PREPARED_WITNESS_KINDS == ("retained_claim",)


def test_native_issuer_checkpoint_c_static_surface_parser_and_origin_are_exact() -> None:
    _require_coherent_native_issuer_choreography_transition_source()
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_bytes = source_path.read_bytes()
    source_sha256 = hashlib.sha256(source_bytes).hexdigest()
    checkpoint_f = source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_RECOVERY_OR_LATER_C_SHA256
    checkpoint_g = source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_SALVAGE_OR_LATER_C_SHA256
    checkpoint_h = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_POST_EFFECT_OR_LATER_C_SHA256
    )
    checkpoint_i = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REQUIRE_POST_EFFECT_OR_LATER_C_SHA256
    )
    checkpoint_d = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_INFRASTRUCTURE_OR_LATER_C_SHA256
    )
    checkpoint_e = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BINDER_TRANSITIONS_OR_LATER_C_SHA256
    )
    source = source_bytes.decode("utf-8")
    for identifier in (
        *_NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_INTERNALS,
        *_NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_HOOK_ENTRYPOINTS,
    ):
        assert f"{identifier}(" in source

    surface = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint_c_surfaces_are_exact",
        "aqt_issuer_choreography_checkpoint_c_origin_self_test",
    )
    assert "{1U,1U,1U,1U,0U,0U,1U,1U,}" in "".join(surface.split())
    assert "AQT_NATIVE_ISSUER_CHOREOGRAPHY_AUTHORITY_TYPE_ATTRIBUTE" in surface
    assert "AQT_NATIVE_ISSUER_CHOREOGRAPHY_WITNESS_TYPE_ATTRIBUTE" in surface
    assert "aqt_issuer_choreography_hook_names[index]" in surface

    parser = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_parse_checkpoint_time_selector",
        "aqt_issuer_choreography_checkpoint_source_is_exact_locked",
    )
    assert "!PyUnicode_CheckExact(candidate)" in parser
    assert "AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT" in parser
    assert "aqt_issuer_choreography_time_selector_names[index]" in parser
    assert "native issuer choreography checkpoint time selector is unavailable" in parser

    hook = _native_c_function_slice(
        source,
        "aqt_test_transition_topology_observation_issuer_shadow_choreography",
        "aqt_test_topology_observation_issuer_shadow_choreography_snapshot",
    )
    ordered_hook_markers = (
        (
            "PyArg_ParseTuple(",
            "!Py_IS_TYPE(shadow_object, &AqtTopologyObservationIssuerShadowType)",
            "!PyUnicode_CheckExact(tag_object)",
            "!PyTuple_CheckExact(payload_object)",
            'PyUnicode_CompareWithASCIIString(tag_object, "checkpoint")',
            "PyTuple_GET_SIZE(payload_object) != 2",
            "!Py_IS_TYPE(lease_object, &AqtIssuerChoreographyAuthorityType)",
            "aqt_issuer_choreography_parse_checkpoint_time_selector(",
            "selector == AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE",
            "return aqt_issuer_choreography_checkpoint(",
        )
        if checkpoint_e
        else (
            "PyArg_ParseTuple(",
            "!Py_IS_TYPE(shadow_object, &AqtTopologyObservationIssuerShadowType)",
            "!PyUnicode_CheckExact(tag_object)",
            "!PyTuple_CheckExact(payload_object)",
            "PyTuple_GET_SIZE(payload_object) != 2",
            'PyUnicode_CompareWithASCIIString(tag_object, "checkpoint")',
            "!Py_IS_TYPE(lease_object, &AqtIssuerChoreographyAuthorityType)",
            "aqt_issuer_choreography_parse_checkpoint_time_selector(",
            "selector == AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE",
            "return aqt_issuer_choreography_checkpoint(",
        )
    )
    hook_positions = tuple(hook.index(marker) for marker in ordered_hook_markers)
    assert hook_positions == tuple(sorted(hook_positions))
    assert "aqt_clear_issuer_external_projection_barrier" not in hook
    assert "aqt_run_issuer_external_projection_barrier" not in hook
    assert "aqt_issuer_choreography_fault_plan_begin_locked" not in hook

    origin_self_test = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint_c_origin_self_test",
        "aqt_issuer_choreography_wrapper_self_test",
    )
    assert "expected.revision = 7U;" in origin_self_test
    assert "committed.revision++;" in origin_self_test
    assert "expected.revision + 2U" in origin_self_test
    assert "state.failclosed_origin.target.revision--;" in origin_self_test
    assert "state.failclosed_origin.committed.last_monotonic_ns = 99U;" in origin_self_test
    assert "expected.revision + 1U" in origin_self_test
    assert "AQT_CHOREOGRAPHY_AUTHORITY_REVOKED" in origin_self_test
    compact_origin_self_test = " ".join(origin_self_test.split())
    assert (
        "memset( &state.failclosed_origin, 0, sizeof(state.failclosed_origin) );"
        in compact_origin_self_test
    )
    assert (
        "&& !(state.failclosed_origin.is_present == 1U && "
        "aqt_issuer_choreography_checkpoint_failclosed_origin_is_exact_locked( &state ))"
        in compact_origin_self_test
    )
    origin_gate = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint_failclosed_origin_is_exact_locked",
        "aqt_issuer_choreography_record_is_exact_locked",
    )
    for required in (
        "origin->operation_group != 3U",
        "origin->operation_tag != AQT_CHOREOGRAPHY_OPERATION_CHECKPOINT",
        "origin->committed_is_present > 1U",
        "origin->target_policy != AQT_CHOREOGRAPHY_FAILCLOSED_REVOKED",
        "target_revision = origin->expected.revision + 2U;",
        "target_last = origin->committed.last_monotonic_ns;",
        "target_revision = origin->expected.revision + 1U;",
        "target_last = origin->expected.last_monotonic_ns;",
        "memcmp(&origin->target, &expected_target",
        "memcmp(&state->value, &expected_target",
    ):
        assert required in origin_gate
    self_test = _native_c_function_slice(source, "aqt_self_test", "aqt_force_second_exec_for_test")
    expected_surface_call = (
        "aqt_issuer_choreography_checkpoint_o_surfaces_are_exact(module)"
        if _native_issuer_choreography_formal_force_revoke_source_is_coherent()
        else "aqt_issuer_choreography_checkpoint_n_surfaces_are_exact(module)"
        if _native_issuer_choreography_formal_expire_source_is_coherent()
        else "aqt_issuer_choreography_checkpoint_m_surfaces_are_exact(module)"
        if _native_issuer_choreography_abandon_controller_source_is_coherent()
        else "aqt_issuer_choreography_checkpoint_l_surfaces_are_exact(module)"
        if _native_issuer_choreography_attest_controller_durable_source_is_coherent()
        else "aqt_issuer_choreography_checkpoint_k_surfaces_are_exact(module)"
        if _native_issuer_choreography_confirm_controller_source_is_coherent()
        else "aqt_issuer_choreography_checkpoint_j_surfaces_are_exact(module)"
        if _native_issuer_choreography_begin_controller_source_is_coherent()
        else "aqt_issuer_choreography_checkpoint_i_surfaces_are_exact(module)"
        if checkpoint_i
        else "aqt_issuer_choreography_checkpoint_h_surfaces_are_exact(module)"
        if checkpoint_h
        else "aqt_issuer_choreography_checkpoint_g_surfaces_are_exact(module)"
        if checkpoint_g
        else "aqt_issuer_choreography_checkpoint_f_surfaces_are_exact(module)"
        if checkpoint_f
        else "aqt_issuer_choreography_checkpoint_e_surfaces_are_exact(module)"
        if checkpoint_e
        else "aqt_issuer_choreography_checkpoint_d_surfaces_are_exact(module)"
        if checkpoint_d
        else "aqt_issuer_choreography_checkpoint_c_surfaces_are_exact(module)"
    )
    assert expected_surface_call in self_test
    assert "aqt_issuer_choreography_checkpoint_c_origin_self_test()" in self_test


def test_native_issuer_checkpoint_c_static_candidate_edges_and_source_gate_are_exact() -> None:
    _require_coherent_native_issuer_choreography_transition_source()
    source = (Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c").read_text(
        encoding="utf-8"
    )
    source_gate = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint_source_is_exact_locked",
        "aqt_issuer_choreography_build_checkpoint_candidate_locked",
    )
    for required in (
        "shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY",
        "shadow->activation_thread_state != current_thread",
        "shadow->activation_thread_id != current_thread_id",
        "!aqt_issuer_shadow_has_live_lease_locked(shadow)",
        "cell->action_live != 1U",
        "!shadow->choreography_state_present",
        "state->value.phase != AQT_CHOREOGRAPHY_PHASE_UNBOUND",
        "state->value.action_active != 1U",
        "state->value.revision > UINT64_MAX - 2U",
        "cell->persistent_state_revision != state->value.revision",
        "cell->binding_generation != state->value.binding_generation",
        "cell->current_scope_generation != state->value.scope_generation",
        "cell->pending_scope_generation != 0U",
        "state_lease == lease_record",
        "lease_record->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED",
        "state_recovery->status == AQT_CHOREOGRAPHY_AUTHORITY_INSTALLED",
    ):
        assert required in source_gate, required

    candidate = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_build_checkpoint_candidate_locked",
        "aqt_issuer_choreography_publish_checkpoint_candidate_locked",
    )
    for selector in (
        "AQT_CHOREOGRAPHY_TIME_SAME",
        "AQT_CHOREOGRAPHY_TIME_SAMPLE",
        "AQT_CHOREOGRAPHY_TIME_ROLLBACK",
        "AQT_CHOREOGRAPHY_TIME_ACTION_DEADLINE",
    ):
        assert f"case {selector}:" in candidate
    assert "sampled_now < source->last_monotonic_ns" in candidate
    assert "sampled_now >= source->retention_deadline_monotonic_ns" in candidate
    assert "sampled_now >= source->action_deadline_monotonic_ns" in candidate
    assert "observed = source->action_deadline_monotonic_ns;" in candidate
    assert "case AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE:" not in candidate
    assert "default:\n            abort();" in candidate
    assert "candidate->revision++;" in candidate
    assert "candidate->last_monotonic_ns = observed;" in candidate

    publish = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_publish_checkpoint_candidate_locked",
        "aqt_issuer_choreography_build_checkpoint_failclosed_origin",
    )
    assert "candidate->revision != cell->persistent_state_revision + 1U" in publish
    assert "candidate->phase == AQT_CHOREOGRAPHY_PHASE_REVOKED" in publish
    assert publish.count("AQT_CHOREOGRAPHY_AUTHORITY_REVOKED") == 2
    assert "candidate->phase != AQT_CHOREOGRAPHY_PHASE_UNBOUND" in publish
    assert "state->value = *candidate;" in publish
    assert "memset(&state->failclosed_origin, 0" in publish
    assert "cell->persistent_state_revision = candidate->revision;" in publish


def test_native_issuer_checkpoint_c_static_transaction_and_cleanup_order_are_exact() -> None:
    _require_coherent_native_issuer_choreography_transition_source()
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_bytes = source_path.read_bytes()
    checkpoint_e = hashlib.sha256(source_bytes).hexdigest() in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BINDER_TRANSITIONS_OR_LATER_C_SHA256
    )
    source = source_bytes.decode("utf-8")
    checkpoint = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint",
        "aqt_issuer_choreography_early_claim_proof_locked" if checkpoint_e else "aqt_fstat_owned",
    )
    latch = checkpoint.index("aqt_issuer_choreography_fault_plan_begin_locked(")
    pre_latch = checkpoint[:latch]
    assert "aqt_clear_issuer_external_projection_barrier" not in pre_latch
    assert "aqt_run_issuer_external_projection_barrier" not in pre_latch

    ordered_markers = (
        "recovery_record = shadow->choreography_state.authority_records[",
        "expected = shadow->choreography_state.value;",
        "aqt_issuer_choreography_sample_continuous_ns(&sampled_now)",
        "aqt_issuer_external_projection_matches(shadow->projection)",
        "aqt_validate_launch_lock_core_locked(shadow->launch_lease)",
        "aqt_run_issuer_external_projection_barrier(module_state);",
        "aqt_issuer_external_projection_matches(shadow->projection)",
        "aqt_issuer_choreography_checkpoint_capture_authority_failure(",
        "aqt_issuer_choreography_build_checkpoint_candidate_locked(",
        "AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE",
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT",
        "aqt_issuer_choreography_publish_checkpoint_candidate_locked(",
        "AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE",
        "aqt_issuer_choreography_cell_is_exact_locked(shadow)",
        "AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN",
        "aqt_issuer_foreign_fork_commit_locked(",
        "aqt_issuer_choreography_fault_plan_clear(fault_plan);",
        "aqt_unlock_owner_list_or_fail_stop();",
        "aqt_clear_issuer_external_projection_barrier(module_state);",
        "aqt_issuer_choreography_detached_records_release(&detached);",
        "Py_RETURN_NONE;",
    )
    positions: list[int] = []
    cursor = latch
    for marker in ordered_markers:
        cursor = checkpoint.index(marker, cursor)
        positions.append(cursor)
        cursor += len(marker)
    assert positions == sorted(positions)
    assert checkpoint.count("aqt_issuer_choreography_sample_continuous_ns(&sampled_now)") == 1
    assert "test_clock" not in checkpoint
    assert "caller_clock" not in checkpoint
    clock_failure = checkpoint.index(
        "aqt_issuer_choreography_sample_continuous_ns(&sampled_now) < 0"
    )
    assert (
        "saved_errno = errno != 0 ? errno : EIO;"
        in checkpoint[
            clock_failure : checkpoint.index(
                "aqt_issuer_external_projection_matches(shadow->projection)",
                clock_failure,
            )
        ]
    )

    terminal_proof = positions[6]
    state_store = positions[11]
    proof_to_store = checkpoint[terminal_proof:state_store]
    assert not any(
        "saved_errno =" in line and "saved_errno ==" not in line
        for line in proof_to_store.splitlines()
    )
    assert "PyErr_" not in proof_to_store
    assert "return NULL" not in proof_to_store
    assert "abort();" in proof_to_store
    assert checkpoint.count("aqt_clear_issuer_external_projection_barrier(module_state);") == 2

    locked_commit = checkpoint[positions[0] : positions[17]]
    failclosed_start = checkpoint.index(
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT",
        positions[-1],
    )
    cleanup_unlock = checkpoint.rindex("aqt_unlock_owner_list_or_fail_stop();")
    locked_cleanup = checkpoint[failclosed_start:cleanup_unlock]
    for locked_region in (locked_commit, locked_cleanup):
        for forbidden in (
            "PyErr_",
            "Py_RETURN",
            "Py_DECREF",
            "Py_XDECREF",
            "Py_CLEAR",
            "PyMem_",
            "aqt_free_issuer_projection",
            "aqt_issuer_choreography_detached_records_release",
            "Py_BEGIN_ALLOW_THREADS",
            "Py_END_ALLOW_THREADS",
        ):
            assert forbidden not in locked_region

    cleanup_loop_start = checkpoint.index("for (index = 0; index < 4; index++)")
    cleanup_loop_end = checkpoint.index("}\n    if (", cleanup_loop_start)
    cleanup_loop = checkpoint[cleanup_loop_start:cleanup_loop_end]
    reconcile = cleanup_loop.index("aqt_issuer_choreography_checkpoint_cleanup_reconcile_locked(")
    point_take = cleanup_loop.index("AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT")
    assert reconcile < point_take
    assert "index + 1" in cleanup_loop[point_take:]
    final_confirmation = checkpoint[cleanup_loop_end:cleanup_unlock]
    assert "aqt_issuer_choreography_checkpoint_cleanup_reconcile_locked(" in final_confirmation
    assert "native issuer choreography checkpoint cleanup confirmation failed" in (
        final_confirmation
    )
    assert "aqt_fail_stop(" in final_confirmation
    assert checkpoint.index("aqt_unlock_owner_list_or_fail_stop();", cleanup_loop_end) < (
        checkpoint.index("aqt_free_issuer_projection(&detached_projection)", cleanup_loop_end)
    )
    assert checkpoint.index("aqt_unlock_owner_list_or_fail_stop();", cleanup_loop_end) < (
        checkpoint.index(
            "aqt_issuer_choreography_detached_records_release(&detached)",
            cleanup_loop_end,
        )
    )

    authority_failure = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint_capture_authority_failure",
        "aqt_issuer_choreography_checkpoint_cleanup_reconcile_locked",
    )
    assert "*saved_errno = errno != 0 ? errno : EIO;" in authority_failure
    assert "*authority_proof_failed = 1;" in authority_failure
    for forbidden in (
        "Py",
        "malloc",
        "calloc",
        "realloc",
        "free(",
        "return",
        "goto",
    ):
        assert forbidden not in authority_failure

    cleanup = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_checkpoint_cleanup_reconcile_locked",
        "aqt_issuer_choreography_checkpoint",
    )
    compact_cleanup = " ".join(cleanup.split())
    assert "expected->revision + (committed_is_present ? 2U : 1U)" in compact_cleanup
    assert "committed->last_monotonic_ns" in cleanup
    assert ": expected->last_monotonic_ns" in cleanup
    assert "state->failclosed_origin = origin;" in cleanup
    assert "shadow->state = AQT_ISSUER_NATIVE_STATE_BURNED;" in cleanup
    assert "shadow->revision = 4U;" in cleanup
    assert "aqt_issuer_projection_is_roots_only(shadow->projection)" in cleanup
    assert "aqt_issuer_shadow_has_live_lease_locked(shadow)" in cleanup
    assert "AQT_CHOREOGRAPHY_CELL_BURNED" in cleanup
    assert "aqt_close_owner_locked" not in cleanup
    assert "aqt_unlink_owner_locked" not in cleanup


def test_native_issuer_checkpoint_c_static_fork_publication_gates_are_exact() -> None:
    _require_coherent_native_issuer_choreography_transition_source()
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_bytes = source_path.read_bytes()
    checkpoint_e = hashlib.sha256(source_bytes).hexdigest() in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BINDER_TRANSITIONS_OR_LATER_C_SHA256
    )
    source = source_bytes.decode("utf-8")
    point_gate = _native_c_function_slice(
        source,
        "aqt_issuer_foreign_fork_point_accepts_shadow",
        "aqt_test_configure_topology_observation_issuer_shadow_foreign_fork_interposition",
    )
    for point in (
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_REGISTER_POST_STATE_COMMIT",
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT",
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT",
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_CLOSE_LIVE_SCOPE_POST_BURN",
    ):
        assert point in point_gate
    assert "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_CONSUME_PRE_STATE_DETACH" not in point_gate
    assert "AQT_CHOREOGRAPHY_PHASE_UNBOUND" in point_gate
    assert "cell->action_live == 1U" in point_gate
    assert "cell->pending_scope_generation == 0U" in point_gate

    require_transition = _native_c_function_slice(
        source,
        "aqt_issuer_foreign_fork_require_transition_operation",
        "aqt_issuer_foreign_fork_interpose_locked",
    )
    assert "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT" in (
        require_transition
    )
    assert "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT" in (
        require_transition
    )
    child_gate = _native_c_function_slice(
        source,
        "aqt_issuer_foreign_fork_child_publication_is_exact",
        "aqt_issuer_foreign_fork_worker",
    )
    transition_case = child_gate.index(
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT"
    )
    failclosed_case = child_gate.index(
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT",
        transition_case,
    )
    assert transition_case < failclosed_case
    transition_child = child_gate[transition_case:failclosed_case]
    if checkpoint_e:
        assert "aqt_issuer_foreign_fork_transition_candidate_is_exact(" in transition_child
    else:
        assert "AQT_CHOREOGRAPHY_PHASE_UNBOUND" in transition_child
        assert "AQT_CHOREOGRAPHY_PHASE_REVOKED" in transition_child
    assert "state->value.revision == cell->persistent_state_revision" in transition_child
    assert "state->value.binding_generation == cell->binding_generation" in transition_child
    assert "state->value.scope_generation == cell->current_scope_generation" in transition_child
    if checkpoint_e:
        assert "aqt_issuer_choreography_memory_is_zero(" not in transition_child
    else:
        assert "aqt_issuer_choreography_memory_is_zero(" in transition_child
        assert "&state->failclosed_origin" in transition_child
    failclosed_child = child_gate[failclosed_case:]
    assert "shadow->state == AQT_ISSUER_NATIVE_STATE_BURNED" in failclosed_child
    assert "shadow->revision == 4U" in failclosed_child
    assert "shadow->lease_was_closed == 0U" in failclosed_child
    assert "aqt_issuer_projection_is_roots_only(shadow->projection)" in failclosed_child
    origin_presence = failclosed_child.index("state->failclosed_origin.is_present == 1U")
    origin_validation = failclosed_child.index(
        "aqt_issuer_foreign_fork_transition_failclosed_is_exact("
        if checkpoint_e
        else "aqt_issuer_choreography_checkpoint_failclosed_origin_is_exact_locked("
    )
    assert origin_presence < origin_validation


def test_native_issuer_checkpoint_c_surface_exposes_only_checkpoint_transition(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_transition_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    assert str(inspect.signature(transition)) == "(shadow, tag, request, /)"
    for name in _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_EXPORTED_HOOK_NAMES:
        assert type(getattr(test_module, name)) is BuiltinFunctionType
    for name in _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_HIDDEN_HOOK_NAMES:
        assert not hasattr(test_module, name)
    assert all(
        not hasattr(test_module, name) for name in _NATIVE_ISSUER_CHOREOGRAPHY_TYPE_ATTRIBUTES
    )

    shadow, projection, socket_owner, lease, capability, registered = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / "checkpoint-c-surface",
        )
    )
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    try:
        assert transition(shadow, "checkpoint", (lease, "same")) is None
        _assert_native_issuer_checkpoint_c_unbound_snapshot(
            snapshot,
            shadow,
            lease,
            capability,
            registered,
            persistent_revision=2,
            expected_last=cast(int, registered[9]),
        )
        assert test_module._test_topology_observation_issuer_shadow_state(shadow) == (
            _native_issuer_active_snapshot(projection)
        )
        assert shadow._observation_choreography_is_valid_locked(lease) is False
        assert test_module._self_test() is None
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


