@pytest.mark.parametrize("rejection", ["duplicate", "group_mix", "fifth", "reset"])
def test_native_issuer_checkpoint_c_fault_configuration_is_transactional(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    rejection: str,
) -> None:
    _require_coherent_native_issuer_choreography_transition_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    shadow, projection, socket_owner, lease, capability, registered = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / f"checkpoint-c-fault-plan-{rejection}",
        )
    )
    try:
        if rejection == "fifth":
            for occurrence in range(1, 5):
                assert configure(8, 0, occurrence) is None
            with pytest.raises(RuntimeError):
                configure(9, 0, 1)
            assert configure(-1, 0, 0) is None
            assert transition(shadow, "checkpoint", (lease, "same")) is None
            _assert_native_issuer_checkpoint_c_unbound_snapshot(
                snapshot,
                shadow,
                lease,
                capability,
                registered,
                persistent_revision=2,
                expected_last=cast(int, registered[9]),
            )
            return

        assert configure(9, 0, 1) is None
        if rejection == "duplicate":
            with pytest.raises(RuntimeError):
                configure(9, 0, 1)
        elif rejection == "group_mix":
            with pytest.raises(RuntimeError):
                configure(4, 0, 1)
        else:
            assert rejection == "reset"
            assert configure(-1, 0, 0) is None
            assert transition(shadow, "checkpoint", (lease, "same")) is None
            _assert_native_issuer_checkpoint_c_unbound_snapshot(
                snapshot,
                shadow,
                lease,
                capability,
                registered,
                persistent_revision=2,
                expected_last=cast(int, registered[9]),
            )
            return
        _assert_native_issuer_choreography_fault(
            lambda: transition(shadow, "checkpoint", (lease, "same")),
            0,
        )
        _assert_native_issuer_checkpoint_c_revoked_snapshot(
            snapshot,
            shadow,
            lease,
            capability,
            registered,
            persistent_revision=2,
            expected_last=cast(int, registered[9]),
        )
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        _close_native_issuer_projection_socket(projection, socket_owner)


