def test_native_issuer_checkpoint_c_inherited_child_rejects_transition_and_state(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    _require_coherent_native_issuer_choreography_transition_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    shadow, projection, socket_owner, lease, capability, registered = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / "checkpoint-c-inherited-child",
        )
    )
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through parent pipe
        os.close(read_descriptor)
        results: list[bool] = []
        for operation in (
            lambda: transition(shadow, "checkpoint", (lease, "same")),
            lambda: snapshot(shadow),
            lambda: snapshot(lease),
        ):
            try:
                operation()
            except RuntimeError:
                results.append(True)
            except BaseException:
                results.append(False)
            else:
                results.append(False)
        os.write(write_descriptor, bytes(results))
        os.close(write_descriptor)
        os._exit(0 if results == [True, True, True] else 1)
    os.close(write_descriptor)
    child_reaped = False
    try:
        ready, _, _ = select.select([read_descriptor], [], [], 5.0)
        if not ready:
            os.kill(child_pid, 9)
            os.waitpid(child_pid, 0)
            child_reaped = True
            raise AssertionError("forked checkpoint operation did not terminate")
        assert os.read(read_descriptor, 3) == b"\x01\x01\x01"
        waited_pid, status = os.waitpid(child_pid, 0)
        child_reaped = True
        assert waited_pid == child_pid
        assert os.waitstatus_to_exitcode(status) == 0
        assert snapshot(shadow) == registered
        assert transition(shadow, "checkpoint", (lease, "same")) is None
        _assert_native_issuer_checkpoint_c_unbound_snapshot(
            snapshot,
            shadow,
            lease,
            capability,
            registered,
            persistent_revision=2,
            expected_last=cast(int, registered[9]),
        )
    finally:
        if not child_reaped:
            with suppress(ProcessLookupError):
                os.kill(child_pid, 9)
            with suppress(ChildProcessError):
                os.waitpid(child_pid, 0)
        os.close(read_descriptor)
        _close_native_issuer_projection_socket(projection, socket_owner)


