def test_native_issuer_checkpoint_d_static_surface_and_dormant_arities_are_exact() -> None:
    _require_coherent_native_issuer_choreography_infrastructure_source()
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_sha256 = hashlib.sha256(source_path.read_bytes()).hexdigest()
    source = source_path.read_text(encoding="utf-8")
    operation_start = source.index("aqt_issuer_choreography_operation_manifest[")
    operation_end = source.index("\n};", operation_start)
    operation_manifest = source[operation_start:operation_end]
    compact_manifest = "".join(operation_manifest.split())
    for tag, arity in _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_D_DORMANT_OPERATION_ARITIES:
        marker = f'{{"{tag}",'
        row_start = compact_manifest.index(marker)
        row_end = compact_manifest.index("},", row_start)
        assert f",{arity}U,0U" in compact_manifest[row_start:row_end]

    module_start = source.index("static PyMethodDef aqt_module_methods[]")
    module_end = source.index("\n};", module_start)
    module_methods = source[module_start:module_end]
    exposed_names = tuple(
        _NATIVE_ISSUER_CHOREOGRAPHY_HOOK_NAMES[index]
        for index in _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_D_EXPORTED_HOOK_INDICES
    )
    hidden_names = tuple(
        name
        for index, name in enumerate(_NATIVE_ISSUER_CHOREOGRAPHY_HOOK_NAMES)
        if index not in _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_D_EXPORTED_HOOK_INDICES
    )
    assert all(name in module_methods for name in exposed_names)
    assert all(name not in module_methods for name in hidden_names)
    transition_hook = _native_c_function_slice(
        source,
        "aqt_test_transition_topology_observation_issuer_shadow_choreography",
        "aqt_test_topology_observation_issuer_shadow_choreography_snapshot",
    )
    assert 'PyUnicode_CompareWithASCIIString(tag_object, "checkpoint")' in transition_hook
    assert "return aqt_issuer_choreography_checkpoint(" in transition_hook
    if source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_INFRASTRUCTURE_D_SHA256:
        for forbidden in (
            "aqt_issuer_choreography_issue_binder(",
            "aqt_issuer_choreography_admit_binder(",
            "aqt_issuer_choreography_arm_claim(",
        ):
            assert forbidden not in source
    else:
        assert (
            source_sha256
            in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BINDER_TRANSITIONS_OR_LATER_C_SHA256
        )


