def test_native_issuer_checkpoint_d_authorization_storage_and_take_are_native_only() -> None:
    _require_coherent_native_issuer_choreography_infrastructure_source()
    source = (Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c").read_text(
        encoding="utf-8"
    )
    authorization_start = source.index("struct AqtIssuerClaimedFenceAuthorization {")
