def test_native_issuer_checkpoint_d_authorization_type_is_opaque_and_noncloneable(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_infrastructure_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    shadow, projection, socket_owner, _lease, _capability, registered = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / "checkpoint-d-auth-type",
        )
    )
    try:
        binder, authorization, _binder_snapshot, _authorization_snapshot = (
            _prepare_native_issuer_checkpoint_d_binder_pair(
                prepare_authority,
                snapshot,
                shadow,
                registered,
                projection,
            )
        )
        assert repr(authorization) == _NATIVE_ISSUER_CHOREOGRAPHY_CLAIMED_AUTHORIZATION_REPR
        assert repr(binder) == _NATIVE_ISSUER_CHOREOGRAPHY_AUTHORITY_REPR
        assert gc.is_tracked(authorization) is False
        assert gc.get_referents(authorization) == []
        assert not hasattr(authorization, "__dict__")
        for candidate in (authorization, binder):
            with pytest.raises(TypeError):
                hash(candidate)
            with pytest.raises(TypeError):
                copy(candidate)
            with pytest.raises(TypeError):
                deepcopy(candidate)
            with pytest.raises((pickle.PickleError, TypeError)):
                pickle.dumps(candidate)

        authorization_type = type(authorization)
        assert authorization_type.__name__ == (
            "_TopologyObservationIssuerClaimedFenceAuthorizationForTest"
        )
        assert authorization_type.__module__ == (
            "packages.adapters.trusted_time._native_owned_file_descriptor"
        )
        flags = type.__getattribute__(authorization_type, "__flags__")
        assert flags & (1 << 7)
        assert flags & (1 << 8)
        assert not flags & (1 << 9)
        assert not flags & (1 << 10)
        with pytest.raises(TypeError):
            authorization_type()
        with pytest.raises(TypeError):
            type("HostileClaimedFenceAuthorization", (authorization_type,), {})
        with pytest.raises(TypeError):
            type.__setattr__(authorization_type, "hostile", object())
        authorization_reference = weakref.ref(authorization)
        assert authorization_reference() is authorization
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


