@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", ["store", "return"])
def test_native_issuer_checkpoint_d_lost_pair_result_retires_both_wrappers(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    _require_coherent_native_issuer_choreography_infrastructure_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    shadow, projection, socket_owner, _lease, capability, registered = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / f"checkpoint-d-lost-pair-{failure_type.__name__}-{boundary}",
        )
    )
    capability_snapshot = snapshot(capability)
    gc.collect()
    descriptor_count = _open_descriptor_count()

    def prepare_pair_at_boundary() -> object:
        candidate = prepare_authority(shadow, "recovery_claim_binder")
        return candidate

    offset = _instruction_offset(
        prepare_pair_at_boundary,
        opname="STORE_FAST" if boundary == "store" else "RETURN_VALUE",
        argval="candidate" if boundary == "store" else None,
    )
    failure: BaseException = SystemExit(253) if failure_type is SystemExit else KeyboardInterrupt()
    tool_id = _enable_instruction_interrupt(
        prepare_pair_at_boundary,
        offset,
        tool_name=f"native-issuer-checkpoint-d-pair-{boundary}",
        interruption=failure,
    )
    try:
        with pytest.raises(failure_type) as retained:
            prepare_pair_at_boundary()
        assert retained.value is failure
    finally:
        _disable_instruction_interrupt(tool_id, prepare_pair_at_boundary)
    failure.__traceback__ = None
    del retained
    del failure
    try:
        gc.collect()
        assert snapshot(shadow) == registered
        binder, authorization, binder_snapshot, authorization_snapshot = (
            _prepare_native_issuer_checkpoint_d_binder_pair(
                prepare_authority,
                snapshot,
                shadow,
                registered,
                projection,
            )
        )
        capability_key = _assert_native_issuer_choreography_record_key(capability_snapshot[7])
        binder_key = _assert_native_issuer_choreography_record_key(binder_snapshot[7])
        assert binder_key[2] == capability_key[2] + 2
        del binder, authorization, binder_snapshot, authorization_snapshot
        gc.collect()
        assert _open_descriptor_count() == descriptor_count
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


