def test_native_issuer_checkpoint_d_revision_phase_and_lifecycle_stale_candidates(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_infrastructure_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    transition = _native_issuer_choreography_transition_hook(test_module)
    _activate, burn, close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )

    shadow, projection, socket_owner, lease, capability, registered = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / "checkpoint-d-revision-stale",
        )
    )
    try:
        binder, authorization, binder_before, auth_before = (
            _prepare_native_issuer_checkpoint_d_binder_pair(
                prepare_authority,
                snapshot,
                shadow,
                registered,
                projection,
            )
        )
        assert transition(shadow, "checkpoint", (lease, "same")) is None
        advanced = _assert_native_issuer_checkpoint_c_unbound_snapshot(
            snapshot,
            shadow,
            lease,
            capability,
            registered,
            persistent_revision=2,
            expected_last=cast(int, registered[9]),
        )
        assert snapshot(binder) == binder_before
        assert snapshot(authorization) == auth_before
        _prepare_native_issuer_checkpoint_d_binder_pair(
            prepare_authority,
            snapshot,
            shadow,
            advanced,
            projection,
        )
        assert burn(shadow) is None
        burned = snapshot(shadow)
        assert snapshot(binder) == binder_before
        assert snapshot(authorization) == auth_before
        with pytest.raises(RuntimeError):
            prepare_authority(shadow, "recovery_claim_binder")
        assert snapshot(shadow) == burned
        with pytest.raises(RuntimeError):
            close(shadow)
        assert snapshot(shadow) == burned
        assert snapshot(binder) == binder_before
        assert snapshot(authorization) == auth_before
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)

    revoked, revoked_projection, revoked_socket, revoked_lease, revoked_cap, revoked_state = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / "checkpoint-d-phase-stale",
        )
    )
    try:
        binder, authorization, binder_before, auth_before = (
            _prepare_native_issuer_checkpoint_d_binder_pair(
                prepare_authority,
                snapshot,
                revoked,
                revoked_state,
                revoked_projection,
            )
        )
        assert transition(revoked, "checkpoint", (revoked_lease, "rollback")) is None
        _assert_native_issuer_checkpoint_c_revoked_snapshot(
            snapshot,
            revoked,
            revoked_lease,
            revoked_cap,
            revoked_state,
            persistent_revision=2,
            expected_last=cast(int, revoked_state[9]),
        )
        assert snapshot(binder) == binder_before
        assert snapshot(authorization) == auth_before
        with pytest.raises(RuntimeError):
            prepare_authority(revoked, "recovery_claim_binder")
        with pytest.raises(RuntimeError):
            close(revoked)
        assert snapshot(binder) == binder_before
        assert snapshot(authorization) == auth_before
    finally:
        _close_native_issuer_projection_socket(revoked_projection, revoked_socket)


