def test_native_issuer_checkpoint_e_static_stale_auth_and_projection_retirement() -> None:
    _require_coherent_native_issuer_choreography_binder_transitions_source()
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_bytes = source_path.read_bytes()
    checkpoint_f = (
        hashlib.sha256(source_bytes).hexdigest()
        in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_RECOVERY_OR_LATER_C_SHA256
    )
    source = source_bytes.decode("utf-8")

    authorization_source = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_issue_authorization_source_is_current_locked",
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_SELF_TESTS[0],
    )
    compact_authorization_source = " ".join(authorization_source.split())
    for required in (
        "binder_record->prepared_at_revision == state->value.revision",
        "binder_record->install_or_terminal_state_revision == 0U",
        "binder_record->key.scope_generation == state->value.scope_generation",
        "authorization->status == AQT_CLAIMED_FENCE_AUTHORIZATION_PREPARED",
        "authorization->prepared_state_revision == state->value.revision",
        "authorization->status_state_revision == state->value.revision",
        "authorization->binding_generation == state->value.binding_generation",
        "authorization->scope_generation == state->value.scope_generation",
        "authorization->origin_thread_state == current_thread",
        "authorization->origin_thread_id == current_thread_id",
        "&authorization->lease_key",
        "&authorization->recovery_capability_key",
        "&authorization->binder_key",
    ):
        assert required in compact_authorization_source

    source_gate = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_early_transition_source_is_exact_locked",
        "aqt_issuer_choreography_checkpoint_source_is_exact_locked",
    )
    assert "aqt_issuer_choreography_issue_authorization_source_is_current_locked(" in source_gate
    transaction = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_early_transition",
        "aqt_issuer_choreography_issue_binder",
    )
    source_recheck = transaction.index(
        "aqt_issuer_choreography_early_transition_source_is_exact_locked("
    )
    latch = transaction.index("aqt_issuer_choreography_fault_plan_begin_locked(")
    take = transaction.index("aqt_issuer_claimed_fence_authorization_take_locked(")
    assert source_recheck < latch < take
    transition_self_test = _native_c_function_slice(
        source,
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_SELF_TESTS[0],
        (
            _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_SELF_TESTS[0]
            if checkpoint_f
            else "aqt_issuer_choreography_checkpoint_c_origin_self_test"
        ),
    )
    first_current = transition_self_test.index(
        "!aqt_issuer_choreography_issue_authorization_source_is_current_locked("
    )
    stale_revision = transition_self_test.index("state.value.revision++;", first_current)
    stale_rejection = transition_self_test.index(
        "aqt_issuer_choreography_issue_authorization_source_is_current_locked(",
        stale_revision,
    )
    assert first_current < stale_revision < stale_rejection

    invariants = _native_c_function_slice(
        source,
        "aqt_issuer_shadow_invariants_are_exact_locked",
        "aqt_issuer_shadow_invariants_are_exact",
    )
    assert "aqt_issuer_projection_is_roots_only(shadow->projection)" in invariants
    assert "shadow->lease_was_closed == 0U" in invariants

    forbidden_locked_release = (
        "aqt_scrub_issuer_projection(",
        "aqt_free_issuer_projection(",
        "aqt_free_issuer_text(",
        "aqt_issuer_choreography_detached_records_release(",
        "PyMem_",
        "PyErr_",
        "PyObject_",
        "Py_DECREF",
        "Py_XDECREF",
        "Py_CLEAR",
        "Py_BEGIN_ALLOW_THREADS",
        "Py_END_ALLOW_THREADS",
    )
    publication_corridors = (
        (
            "aqt_issuer_shadow_burn",
            "aqt_issuer_shadow_validate_launch_lock",
            "AQT_ISSUER_FOREIGN_FORK_BURN_PRE_SCRUB",
        ),
        (
            "aqt_issuer_shadow_validate_launch_lock",
            "aqt_issuer_shadow_close",
            "AQT_ISSUER_FOREIGN_FORK_VALIDATE_FAILURE_PRE_SCRUB",
        ),
        (
            "aqt_issuer_shadow_close",
            "aqt_issuer_choreography_register",
            "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_CLOSE_LIVE_SCOPE_POST_BURN",
        ),
    )
    for function_name, next_name, fork_marker in publication_corridors:
        corridor = _native_c_function_slice(source, function_name, next_name)
        clone = corridor.index("prepared_roots = aqt_clone_issuer_roots_projection(")
        owner_lock = corridor.index("aqt_lock_owner_list_or_fail_stop();", clone)
        interpose = corridor.index(fork_marker, owner_lock)
        detach = corridor.index("detached_projection = shadow->projection;", interpose)
        swap = corridor.index("shadow->projection = prepared_roots;", detach)
        clear_prepared = corridor.index("prepared_roots = NULL;", swap)
        publish = corridor.index(
            "aqt_issuer_choreography_cell_publish_lifecycle_locked(", clear_prepared
        )
        commit = corridor.index("aqt_issuer_foreign_fork_commit_locked(", publish)
        owner_unlock = corridor.index("aqt_unlock_owner_list_or_fail_stop();", commit)
        free_prepared = corridor.index("aqt_free_issuer_projection(&prepared_roots);", owner_unlock)
        free_detached = corridor.index(
            "aqt_free_issuer_projection(&detached_projection);", owner_unlock
        )
        assert (
            clone
            < owner_lock
            < interpose
            < detach
            < swap
            < clear_prepared
            < publish
            < commit
            < owner_unlock
            < free_prepared
        )
        assert owner_unlock < free_detached
        locked_publication = corridor[owner_lock:owner_unlock]
        for forbidden in forbidden_locked_release:
            assert forbidden not in locked_publication
        assert "aqt_scrub_issuer_projection(shadow->projection" not in corridor

    register = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_register",
        "aqt_fstat_owned",
    )
    clone = register.index("prepared_roots = aqt_clone_issuer_roots_projection(")
    owner_lock = register.index("aqt_lock_owner_list_or_fail_stop();", clone)
    proof_failure = register.index("if (authority_proof_failed)", owner_lock)
    detach = register.index("detached_projection = shadow->projection;", proof_failure)
    swap = register.index("shadow->projection = prepared_roots;", detach)
    clear_prepared = register.index("prepared_roots = NULL;", swap)
    publish = register.index(
        "aqt_issuer_choreography_cell_publish_lifecycle_locked(", clear_prepared
    )
    success_unlock = register.index("aqt_unlock_owner_list_or_fail_stop();", publish)
    success_free_prepared = register.index(
        "aqt_free_issuer_projection(&prepared_roots);", success_unlock
    )
    success_free_detached = register.index(
        "aqt_free_issuer_projection(&detached_projection);", success_unlock
    )
    assert (
        clone
        < owner_lock
        < proof_failure
        < detach
        < swap
        < clear_prepared
        < publish
        < success_unlock
        < success_free_prepared
    )
    assert success_unlock < success_free_detached
    proof_publication = register[proof_failure:success_unlock]
    for forbidden in forbidden_locked_release:
        assert forbidden not in proof_publication
    final_reconcile = register.rindex("aqt_issuer_choreography_register_cleanup_reconcile_locked(")
    final_unlock = register.index("aqt_unlock_owner_list_or_fail_stop();", final_reconcile)
    final_free_prepared = register.index(
        "aqt_free_issuer_projection(&prepared_roots);", final_unlock
    )
    final_free_detached = register.index(
        "aqt_free_issuer_projection(&detached_projection);", final_unlock
    )
    assert final_reconcile < final_unlock < final_free_prepared
    assert final_unlock < final_free_detached
    assert "aqt_scrub_issuer_projection(shadow->projection" not in register


def test_native_issuer_checkpoint_e_contract_is_exact_and_runtime_gated() -> None:
    assert type(_COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BINDER_TRANSITIONS_E_SHA256) is frozenset
    assert (
        frozenset({"430473ca0f7d3aa43fe00a5fa870f14c61c82639e529d13d99172c9763e386f3"})
        == _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BINDER_TRANSITIONS_E_SHA256
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_EXPORTED_HOOK_INDICES == (
        0,
        1,
        2,
        3,
        6,
        7,
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_OPERATION_ARITIES == (
        ("issue_binder", 5),
        ("admit_binder", 1),
        ("arm_claim", 5),
    )
    assert tuple(
        tag for tag, _arity in _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_OPERATION_ARITIES
    ) == (
        "issue_binder",
        "admit_binder",
        "arm_claim",
    )
    assert (
        tuple(
            (tag, len(slots))
            for tag, slots in _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_REQUEST_SLOTS
        )
        == _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_OPERATION_ARITIES
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_SUCCESS_EDGES == (
        ("issue_binder", "unbound", "binder_issued", "auth_consumed_binder_installed"),
        ("admit_binder", "binder_issued", "claim_admitted", "phase_revision_only"),
        ("arm_claim", "claim_admitted", "armed", "binder_consumed_claim_installed"),
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_TIME_VECTORS == (
        ("same", "stored_last", "armed", "stored_last"),
        ("sample", "before_stored_last", "revoked", "stored_last"),
        ("sample", "stored_last_through_before_action", "armed", "sample"),
        ("sample", "at_action_through_before_retention", "revoked", "stored_last"),
        ("sample", "at_or_after_retention", "expired", "stored_last"),
        ("rollback", "one_before_stored_last", "revoked", "stored_last"),
        ("action_deadline", "exact_action_deadline", "revoked", "stored_last"),
        ("retention_deadline", "exact_retention_deadline", "expired", "stored_last"),
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_PROOF_PLANS[-1] == (
        "arm_claim",
        "poststore_terminal",
        ("claim", "external", "launch", "barrier", "external"),
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_FAULT_POINTS == (8, 9, 10, 11)
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_FORK_POINTS == (5, 6, 7, 9)
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_LOST_RETURN_BOUNDARY == (
        "native_transition_pre_return_fault_point_11",
        "committed_candidate_failclosed_before_none_return",
        "python_after_c_return_not_observed",
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_POSTSTORE_ORDER == (
        ("issue_binder", ("state_store", "fault_10", "fault_11", "return_none")),
        ("admit_binder", ("state_store", "fault_10", "fault_11", "return_none")),
        (
            "arm_claim",
            (
                "state_store",
                "fault_10",
                "terminal_claim_external_launch_barrier_external_proof",
                "fault_11",
                "return_none",
            ),
        ),
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_ERROR_MESSAGES == (
        (
            "validation_or_crossbinding",
            "native issuer choreography recovery claim binder is unavailable",
        ),
        (
            "semantic_revoked_or_expired",
            "native issuer choreography recovery retention deadline is unavailable",
        ),
        ("synthetic_runtime", "forced native issuer shadow choreography failure"),
        ("external_proof", "OSError"),
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_FAILURE_TARGETS == (
        ("issue_binder", "prestore", "revoked", 1, "source_last"),
        ("issue_binder", "poststore", "revoked", 2, "source_last"),
        ("admit_binder", "prestore", "revoked", 1, "source_last"),
        ("admit_binder", "poststore", "revoked", 2, "source_last"),
        ("arm_claim", "prestore", "revoked", 1, "source_last"),
        (
            "arm_claim",
            "poststore_preproof",
            "recovery_unconfirmed",
            2,
            "candidate_last",
        ),
        ("arm_claim", "postproof_prereturn", "armed", 2, "candidate_last"),
        ("arm_claim", "semantic_revoked", "revoked", 2, "source_last"),
        ("arm_claim", "semantic_expired", "expired", 2, "source_last"),
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_E_FAILURE_ORIGIN_POLICIES == (
        ("issue_binder", "prestore_or_poststore", "revoked"),
        ("admit_binder", "prestore_or_poststore", "revoked"),
        ("arm_claim", "prestore", "revoked"),
        ("arm_claim", "committed_preproof", "recovery_unconfirmed"),
        ("arm_claim", "postproof_prereturn", "armed"),
        ("arm_claim", "semantic_revoked", "revoked"),
        ("arm_claim", "semantic_expired", "expired"),
    )


