def test_native_issuer_checkpoint_e_preflight_rejection_preserves_barrier_and_fault_plan(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_binder_transitions_source()
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_sha256 = hashlib.sha256(source_path.read_bytes()).hexdigest()
    checkpoint_f = source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_RECOVERY_OR_LATER_C_SHA256
    checkpoint_g = source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_SALVAGE_OR_LATER_C_SHA256
    checkpoint_h = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_POST_EFFECT_OR_LATER_C_SHA256
    )
    checkpoint_i = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REQUIRE_POST_EFFECT_OR_LATER_C_SHA256
    )
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    transition = _native_issuer_choreography_transition_hook(test_module)
    configure_barrier = cast(
        Callable[[int, int], None],
        getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME),
    )
    (
        shadow,
        projection,
        socket_owner,
        lease,
        capability,
        _registered,
        source_state,
        binder,
        authorization,
        claim,
        claim_payload,
        request,
    ) = _prepare_native_issuer_checkpoint_e_operation_source(
        test_module,
        tmp_path / "checkpoint-e-preflight-barrier",
        "issue_binder",
    )
    barrier: tuple[int, int, int, int] | None = (
        _configure_native_issuer_preloaded_external_projection_barrier(configure_barrier)
    )
    try:
        assert configure(9, 0, 1) is None
        before = snapshot(shadow)
        if _native_issuer_choreography_formal_force_revoke_source_is_coherent():
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[16:]
        elif _native_issuer_choreography_formal_expire_source_is_coherent():
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[15:]
        elif _native_issuer_choreography_abandon_controller_source_is_coherent():
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[14:]
        elif _native_issuer_choreography_attest_controller_durable_source_is_coherent():
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[13:]
        elif _native_issuer_choreography_confirm_controller_source_is_coherent():
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[12:]
        elif _native_issuer_choreography_begin_controller_source_is_coherent():
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[11:]
        elif checkpoint_i:
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[10:]
        elif checkpoint_h:
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[9:]
        elif checkpoint_g:
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[8:]
        elif checkpoint_f:
            unavailable_tags = (
                _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[4:5]
                + _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[8:]
            )
        else:
            unavailable_tags = _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[4:]
        for tag in unavailable_tags:
            with pytest.raises(RuntimeError):
                transition(shadow, tag, request)
            assert snapshot(shadow) == before
            assert barrier is not None
            _assert_native_issuer_preloaded_barrier_is_pending(barrier)

        _assert_native_issuer_choreography_fault(
            lambda: transition(shadow, "issue_binder", request),
            0,
        )
        assert barrier is not None
        _assert_native_issuer_preloaded_barrier_was_consumed(barrier)
        barrier = None
        _assert_native_issuer_checkpoint_e_operation_fault_result(
            test_module,
            snapshot,
            shadow,
            projection,
            lease,
            capability,
            binder,
            authorization,
            claim,
            claim_payload,
            source_state,
            "issue_binder",
            9,
        )
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        if barrier is not None:
            _close_native_issuer_external_projection_barrier_descriptors(barrier)
        _close_native_issuer_projection_socket(projection, socket_owner)


