def test_native_issuer_checkpoint_e_foreign_thread_rejects_before_authorization_take(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_binder_transitions_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    transition = _native_issuer_choreography_transition_hook(test_module)
    shadow, projection, socket_owner, lease, capability, registered = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / "checkpoint-e-foreign-thread",
        )
    )
    binder, authorization, binder_before, authorization_before = (
        _prepare_native_issuer_checkpoint_d_binder_pair(
            prepare_authority,
            snapshot,
            shadow,
            registered,
            projection,
        )
    )
    errors: list[tuple[type[BaseException], str]] = []

    def foreign_transition() -> None:
        try:
            transition(
                shadow,
                "issue_binder",
                (
                    lease,
                    capability,
                    binder,
                    authorization,
                    _native_issuer_checkpoint_e_roots(projection),
                ),
            )
        except BaseException as error:
            errors.append((type(error), str(error)))

    thread = threading.Thread(target=foreign_transition)
    thread.start()
    thread.join(timeout=5.0)
    assert not thread.is_alive()
    try:
        assert errors == [(RuntimeError, _NATIVE_ISSUER_CHOREOGRAPHY_BINDER_UNAVAILABLE_MESSAGE)]
        assert snapshot(shadow) == registered
        assert snapshot(binder) == binder_before
        assert snapshot(authorization) == authorization_before
        assert (
            transition(
                shadow,
                "issue_binder",
                (
                    lease,
                    capability,
                    binder,
                    authorization,
                    _native_issuer_checkpoint_e_roots(projection),
                ),
            )
            is None
        )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_checkpoint_e_inherited_child_rejects_transition_before_take(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    _require_coherent_native_issuer_choreography_binder_transitions_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    transition = _native_issuer_choreography_transition_hook(test_module)
    shadow, projection, socket_owner, lease, capability, registered = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / "checkpoint-e-ordinary-child",
        )
    )
    binder, authorization, binder_before, authorization_before = (
        _prepare_native_issuer_checkpoint_d_binder_pair(
            prepare_authority,
            snapshot,
            shadow,
            registered,
            projection,
        )
    )
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through parent pipe
        os.close(read_descriptor)
        accepted = False
        try:
            transition(
                shadow,
                "issue_binder",
                (
                    lease,
                    capability,
                    binder,
                    authorization,
                    _native_issuer_checkpoint_e_roots(projection),
                ),
            )
        except RuntimeError:
            accepted = True
        except BaseException:
            accepted = False
        os.write(write_descriptor, bytes([accepted]))
        os.close(write_descriptor)
        os._exit(0 if accepted else 1)
    os.close(write_descriptor)
    child_reaped = False
    try:
        ready, _, _ = select.select([read_descriptor], [], [], 5.0)
        if not ready:
            os.kill(child_pid, 9)
            os.waitpid(child_pid, 0)
            child_reaped = True
            raise AssertionError("forked Checkpoint-E transition did not terminate")
        assert os.read(read_descriptor, 1) == b"\x01"
        waited_pid, status = os.waitpid(child_pid, 0)
        child_reaped = True
        assert waited_pid == child_pid
        assert os.waitstatus_to_exitcode(status) == 0
        assert snapshot(shadow) == registered
        assert snapshot(binder) == binder_before
        assert snapshot(authorization) == authorization_before
        assert (
            transition(
                shadow,
                "issue_binder",
                (
                    lease,
                    capability,
                    binder,
                    authorization,
                    _native_issuer_checkpoint_e_roots(projection),
                ),
            )
            is None
        )
    finally:
        if not child_reaped:
            with suppress(ProcessLookupError):
                os.kill(child_pid, 9)
            with suppress(ChildProcessError):
                os.waitpid(child_pid, 0)
        os.close(read_descriptor)
        _close_native_issuer_projection_socket(projection, socket_owner)


@pytest.mark.parametrize("operation_tag", ["issue_binder", "admit_binder", "arm_claim"])
@pytest.mark.parametrize("point", [9, 10, 11])
def test_native_issuer_checkpoint_e_latched_exit_owns_and_clears_barrier(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    operation_tag: str,
    point: int,
) -> None:
    _require_coherent_native_issuer_choreography_binder_transitions_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    transition = _native_issuer_choreography_transition_hook(test_module)
    configure_barrier = cast(
        Callable[[int, int], None],
        getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME),
    )
    (
        shadow,
        projection,
        socket_owner,
        lease,
        capability,
        _registered,
        source_state,
        binder,
        authorization,
        claim,
        claim_payload,
        request,
    ) = _prepare_native_issuer_checkpoint_e_operation_source(
        test_module,
        tmp_path / f"checkpoint-e-barrier-owner-{operation_tag}-{point}",
        operation_tag,
    )
    barrier: tuple[int, int, int, int] | None = (
        _configure_native_issuer_preloaded_external_projection_barrier(configure_barrier)
    )
    replacement: tuple[int, int, int, int] | None = None
    try:
        assert configure(point, 0, 1) is None
        _assert_native_issuer_choreography_fault(
            lambda: transition(shadow, operation_tag, request),
            0,
        )
        assert barrier is not None
        barrier_was_reached = operation_tag in {"issue_binder", "admit_binder"}
        barrier_was_reached = barrier_was_reached or (operation_tag == "arm_claim" and point == 11)
        if barrier_was_reached:
            _assert_native_issuer_preloaded_barrier_was_consumed(barrier)
        else:
            _assert_native_issuer_preloaded_barrier_was_not_consumed(barrier)
        barrier = None

        # Ownership is also observable by the ability to atomically install a
        # fresh plan after every latched terminal exit.
        replacement = _configure_native_issuer_preloaded_external_projection_barrier(
            configure_barrier
        )
        _activate, burn, _close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
            test_module
        )
        assert burn(shadow) is None
        _assert_native_issuer_preloaded_barrier_was_not_consumed(replacement)
        replacement = None
        _assert_native_issuer_checkpoint_e_operation_fault_result(
            test_module,
            snapshot,
            shadow,
            projection,
            lease,
            capability,
            binder,
            authorization,
            claim,
            claim_payload,
            source_state,
            operation_tag,
            point,
        )
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        if barrier is not None:
            _close_native_issuer_external_projection_barrier_descriptors(barrier)
        if replacement is not None:
            _close_native_issuer_external_projection_barrier_descriptors(replacement)
        _close_native_issuer_projection_socket(projection, socket_owner)


