@pytest.mark.parametrize("phase", ["binder_issued", "claim_admitted", "armed"])
@pytest.mark.parametrize("terminal_entry", ["burn_then_close", "close_direct"])
def test_native_issuer_checkpoint_e_burn_close_and_owner_death_preserve_live_state(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    phase: str,
    terminal_entry: str,
) -> None:
    _require_coherent_native_issuer_choreography_binder_transitions_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    _activate, burn, close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    shadow, projection, socket_owner, lease, capability, registered = (
        _new_registered_native_issuer_choreography_shadow(
            test_module,
            tmp_path / f"checkpoint-e-lifecycle-{phase}-{terminal_entry}",
        )
    )
    binder, authorization, claim, claim_payload, state = (
        _advance_native_issuer_checkpoint_e_to_phase(
            test_module,
            shadow,
            projection,
            lease,
            capability,
            registered,
            phase,
        )
    )
    shadow_reference = weakref.ref(shadow)
    intrinsic_snapshots = tuple(snapshot(handle) for handle in (lease, capability, binder))
    authorization_snapshot = snapshot(authorization)
    claim_snapshot = snapshot(claim) if claim is not None else None
    try:
        if terminal_entry == "burn_then_close":
            assert burn(shadow) is None
            with pytest.raises(RuntimeError):
                close(shadow)
        else:
            assert terminal_entry == "close_direct"
            with pytest.raises(RuntimeError):
                close(shadow)
        burned_state = list(state)
        burned_state[1] = 4
        burned_state[8] = False
        assert snapshot(shadow) == tuple(burned_state)
        assert test_module._test_topology_observation_issuer_shadow_state(shadow) == (
            _native_issuer_explicit_burned_snapshot(projection)
        )
        with pytest.raises(RuntimeError):
            close(shadow)
        assert snapshot(shadow) == tuple(burned_state)
        assert tuple(snapshot(handle) for handle in (lease, capability, binder)) == (
            intrinsic_snapshots
        )
        assert snapshot(authorization) == authorization_snapshot
        if claim is not None:
            assert snapshot(claim) == claim_snapshot

        owner_dead_revision = cast(int, state[3]) + 1
        shadow = None
        gc.collect()
        assert shadow_reference() is None
        for handle, kind in (
            (lease, "choreography_lease"),
            (capability, "recovery_retention_capability"),
            (binder, "recovery_claim_binder"),
        ):
            _assert_native_issuer_choreography_handle_snapshot(
                snapshot,
                handle,
                record_class="authority",
                kind=kind,
                status="owner_dead",
                status_revision=owner_dead_revision,
            )
        if claim is not None:
            assert claim_payload is not None
            _assert_native_issuer_checkpoint_e_claim_handle(
                snapshot,
                claim,
                claim_payload,
                status="owner_dead",
                status_revision=owner_dead_revision,
            )
        binder_key = _assert_native_issuer_choreography_record_key(snapshot(binder)[7])
        _assert_native_issuer_choreography_claimed_authorization_snapshot(
            snapshot,
            authorization,
            state=state,
            binder_key=binder_key,
            activation_roots=_native_issuer_checkpoint_e_roots(projection),
            status="owner_dead",
            status_revision=owner_dead_revision,
            prepared_state_revision=1,
        )

        contender = test_module._test_create_inert_topology_observation_issuer_shadow()
        assert _activate(contender, projection) is None
        assert close(contender) is None
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_checkpoint_f_static_surface_parsers_and_preparation_are_exact() -> None:
    _require_coherent_native_issuer_choreography_recovery_source()
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_bytes = source_path.read_bytes()
    checkpoint_g = (
        hashlib.sha256(source_bytes).hexdigest()
        in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_SALVAGE_G_SHA256
    )
    source = source_bytes.decode("utf-8")
    for identifier in _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_STORAGE_TYPES:
        assert identifier in source
    for identifier in (
        *_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_PREPARATION_INTERNALS,
        *_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_SUMMARY_INTERNALS,
        *_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_VALUE_INTERNALS,
        *_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_RUNTIME_INTERNALS,
        *_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_FORK_INTERNALS,
        *_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_SELF_TESTS,
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_SURFACE_HELPER,
    ):
        assert f"{identifier}(" in source

    surface = _native_c_function_slice(
        source,
        _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_SURFACE_HELPER,
        (
            _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_G_SURFACE_HELPER
            if checkpoint_g
            else "aqt_issuer_choreography_build_early_transition_failclosed_origin"
        ),
    )
    compact_surface = "".join(surface.split())
    assert "aqt_issuer_choreography_checkpoint_e_surfaces_are_exact(module)" in surface
    for local_name, tag, phase, arity in (
        ("begin", "begin_recovery", "AQT_CHOREOGRAPHY_PHASE_ARMED", 3),
        (
            "confirm",
            "confirm_recovery",
            "AQT_CHOREOGRAPHY_PHASE_RECOVERY_CONSUMING",
            4,
        ),
    ):
        assert f'strcmp({local_name}->name,"{tag}")==0' in compact_surface
        assert f"{local_name}->source_mask==(uint16_t)(1U<<{phase})" in compact_surface
        assert f"{local_name}->payload_arity=={arity}U" in compact_surface
        assert f"{local_name}->reserved==0U" in compact_surface
    assert 'strcmp(abandon->name,"abandon_recovery")==0' in compact_surface
    for phase in (
        "AQT_CHOREOGRAPHY_PHASE_ARMED",
        "AQT_CHOREOGRAPHY_PHASE_RECOVERY_CONSUMING",
        "AQT_CHOREOGRAPHY_PHASE_RECOVERY_CONFIRMED",
    ):
        assert f"(1U<<{phase})" in compact_surface
    assert "abandon->payload_arity==2U" in compact_surface
    assert "abandon->reserved==0U" in compact_surface

    selector_parser = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_parse_recovery_time_selector",
        "aqt_issuer_choreography_parse_recovery_checkpoint_payload",
    )
    for required in (
        "!PyUnicode_CheckExact(candidate)",
        "AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT",
        "aqt_issuer_choreography_time_selector_names[index]",
        "native issuer recovery time selector must be an exact str",
        "native issuer recovery time selector is unavailable",
    ):
        assert required in selector_parser
    checkpoint_parser = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_parse_recovery_checkpoint_payload",
        "aqt_issuer_choreography_parse_recovery_receipt_payload",
    )
    for required in (
        "!PyTuple_CheckExact(payload)",
        "PyTuple_GET_SIZE(payload) != 2",
        "&AqtIssuerChoreographyWitnessType",
        "aqt_issuer_choreography_parse_recovery_time_selector(",
        "AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT",
        "native recovery-checkpoint payload must be an exact len-2 tuple",
    ):
        assert required in checkpoint_parser
    receipt_parser = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_parse_recovery_receipt_payload",
        "aqt_allocate_issuer_choreography_record",
    )
    for required in (
        "!PyTuple_CheckExact(payload)",
        "PyTuple_GET_SIZE(payload) != 8",
        "&AqtIssuerChoreographyWitnessType",
        "aqt_issuer_choreography_uuid4_is_exact",
        "aqt_issuer_choreography_sha256_is_exact",
        "aqt_issuer_choreography_recovery_receipt_literals[0]",
        "aqt_issuer_choreography_recovery_receipt_literals[1]",
        "AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT",
        "native recovery-receipt payload must be an exact len-8 tuple",
    ):
        assert required in receipt_parser

    record_start = source.index("struct AqtIssuerChoreographyRecord {")
    record_end = source.index("\n};", record_start)
    record = source[record_start:record_end]
    for field in (
        "uint64_t prepared_source_last_monotonic_ns;",
        "unsigned int prepared_time_selector_present;",
        "unsigned int prepared_time_selector;",
    ):
        assert record.count(field) == 1
    recovery_request_start = source.index(
        "typedef struct {\n"
        "    unsigned int operation_tag;\n"
        "    unsigned int selector;\n"
        "    unsigned int checkpoint_is_present;"
    )
    recovery_request_end = source.index(
        "} AqtIssuerChoreographyRecoveryTransitionRequest;",
        recovery_request_start,
    )
    recovery_request = source[recovery_request_start:recovery_request_end]
    for field in (
        "unsigned int source_was_burned;",
        "uint64_t lease_initial_status_revision;",
        "uint64_t recovery_initial_status_revision;",
        "uint64_t claim_initial_status_revision;",
        "uint64_t checkpoint_initial_status_revision;",
        "uint64_t receipt_initial_status_revision;",
        "uint64_t source_lifecycle_revision;",
        "AqtIssuerActivationProjection *source_projection;",
        "AqtTrustedTimeLaunchLockLease *source_launch_lease;",
    ):
        assert recovery_request.count(field) == 1
    provenance = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_record_recovery_provenance_is_exact_locked",
        "aqt_issuer_choreography_record_is_exact_locked",
    )
    compact_provenance = " ".join(provenance.split())
    for required in (
        "record->prepared_time_selector_present == 0U",
        "record->prepared_time_selector == 0U",
        "record->prepared_source_last_monotonic_ns == 0U",
        "record->prepared_time_selector_present != 1U",
        "record->prepared_time_selector >= AQT_ISSUER_CHOREOGRAPHY_TIME_SELECTOR_COUNT",
        "aqt_issuer_choreography_recovery_checkpoint_summary_is_standalone_exact(",
        "record->prepared_source_last_monotonic_ns <",
        "record->prepared_source_last_monotonic_ns >=",
        "case AQT_CHOREOGRAPHY_TIME_SAME:",
        "case AQT_CHOREOGRAPHY_TIME_ROLLBACK:",
        "case AQT_CHOREOGRAPHY_TIME_SAMPLE:",
        "case AQT_CHOREOGRAPHY_TIME_ACTION_DEADLINE:",
        "case AQT_CHOREOGRAPHY_TIME_RETENTION_DEADLINE:",
    ):
        assert required in compact_provenance

    source_gate = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_recovery_preparation_source_is_exact_locked",
        "aqt_issuer_choreography_recovery_preparation_source_matches_locked",
    )
    for required in (
        "AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT",
        "AQT_CHOREOGRAPHY_WITNESS_RECOVERY_RECEIPT",
        "shadow->state != AQT_ISSUER_NATIVE_STATE_ACTIVE_LOCK_ONLY",
        "shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED",
        "shadow->activation_thread_state != current_thread",
        "shadow->activation_thread_id != current_thread_id",
        "!aqt_issuer_shadow_has_live_lease_locked(shadow)",
        "cell->pending_scope_generation != 0U",
        "value->revision != cell->persistent_state_revision",
        "value->binding_generation != cell->binding_generation",
        "value->scope_generation != cell->current_scope_generation",
        "AQT_CHOREOGRAPHY_PHASE_ARMED",
        "AQT_CHOREOGRAPHY_PHASE_RECOVERY_CONSUMING",
        "!claim->wrapper_live",
    ):
        assert required in source_gate
    assert "&&checkpoint->wrapper_live" in "".join(source_gate.split())
    source_match = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_recovery_preparation_source_matches_locked",
        "aqt_issuer_choreography_build_recovery_preparation_payload_locked",
    )
    assert "memcmp(\n            &source->state,\n            &shadow->choreography_state" in (
        source_match
    )
    assert "source->artifact_directory_length" in source_match
    assert "source->ignored_root_length" in source_match

    payload_builder = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_build_recovery_preparation_payload_locked",
        "aqt_issuer_choreography_prepare_recovery_witness",
    )
    for selector, value in (
        ("SAME", "value->last_monotonic_ns"),
        ("ROLLBACK", "value->last_monotonic_ns"),
        ("SAMPLE", "sampled_now"),
        ("ACTION_DEADLINE", "value->action_deadline_monotonic_ns"),
        ("RETENTION_DEADLINE", "value->retention_deadline_monotonic_ns"),
    ):
        assert f"case AQT_CHOREOGRAPHY_TIME_{selector}:" in payload_builder
        assert value in payload_builder
    assert "payload->recovery_receipt.mode = AQT_CHOREOGRAPHY_RECEIPT_DURABLE;" in (payload_builder)
    assert "payload->recovery_receipt.claim_tombstone = value->claim;" in payload_builder
    assert "value->recovery_checkpoint" in payload_builder

    prepare = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_prepare_recovery_witness",
        "aqt_issuer_choreography_recovery_checkpoint_summary_snapshot",
    )
    assert prepare.count("aqt_issuer_choreography_sample_continuous_ns(&sampled_now)") == 1
    sample_guard = prepare.index("request->selector == AQT_CHOREOGRAPHY_TIME_SAMPLE")
    sample_call = prepare.index("aqt_issuer_choreography_sample_continuous_ns(&sampled_now)")
    first_unlock = prepare.index("aqt_unlock_owner_list_or_fail_stop();", sample_call)
    allocation = prepare.index("record = aqt_allocate_issuer_choreography_record(")
    assert sample_guard < sample_call < first_unlock < allocation
    for required in (
        "request->kind == AQT_CHOREOGRAPHY_WITNESS_RECOVERY_CHECKPOINT",
        "record->prepared_time_selector_present = 1U;",
        "record->prepared_time_selector = request->selector;",
        "record->prepared_source_last_monotonic_ns =",
        "source.state.value.last_monotonic_ns;",
        "record->payload.recovery_receipt.key = record->key;",
        "aqt_publish_unpublished_issuer_choreography_wrapper_locked(",
    ):
        assert required in prepare
    lock_cursor = 0
    locked_regions = 0
    while True:
        lock_start = prepare.find("aqt_lock_owner_list_or_fail_stop();", lock_cursor)
        if lock_start < 0:
            break
        unlock = prepare.index("aqt_unlock_owner_list_or_fail_stop();", lock_start)
        locked = prepare[lock_start:unlock]
        for forbidden in (
            "PyErr_",
            "PyObject_",
            "PyMem_",
            "Py_DECREF",
            "Py_CLEAR",
            "aqt_allocate_",
            "aqt_issuer_choreography_record_decref",
            "free(",
        ):
            assert forbidden not in locked
        locked_regions += 1
        lock_cursor = unlock + 1
    assert locked_regions >= 3
    for locked_helper in (provenance, source_gate, source_match, payload_builder):
        for forbidden in (
            "PyErr_",
            "PyObject_",
            "PyMem_",
            "Py_DECREF",
            "Py_CLEAR",
            "aqt_allocate_",
            "free(",
        ):
            assert forbidden not in locked_helper

    checkpoint_snapshot = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_recovery_checkpoint_summary_snapshot",
        "aqt_issuer_choreography_recovery_receipt_summary_snapshot",
    )
    receipt_snapshot = _native_c_function_slice(
        source,
        "aqt_issuer_choreography_recovery_receipt_summary_snapshot",
        "aqt_issuer_choreography_empty_snapshot",
    )
    assert "PyTuple_New(2)" in checkpoint_snapshot
    assert 'Py_BuildValue(\n            "(NssKKK)"' in checkpoint_snapshot
    assert "PyTuple_New(5)" in receipt_snapshot
    assert 'Py_BuildValue(\n            "(Nsss)"' in receipt_snapshot
    assert "aqt_issuer_choreography_claim_summary_snapshot(" in receipt_snapshot
    assert "aqt_issuer_choreography_recovery_checkpoint_summary_snapshot(" in receipt_snapshot


