        ("action_deadline", "action_deadline", "recovery_confirmed", "action_deadline"),
        ("sample", "source_last_through_before_retention", "recovery_confirmed", "sample"),
        ("rollback", "source_last", "recovery_unconfirmed", "source_last"),
        ("retention_deadline", "retention_deadline", "recovery_unconfirmed", "source_last"),
        (
            "sample",
            "outside_source_last_through_before_retention",
            "recovery_unconfirmed",
            "source_last",
        ),
