        "selected_witness_preproof",
        "active_external_launch_external_or_burned_launch_launch",
        "candidate_build_and_fault9",
        "fork6_and_state_publish_and_fault10",
        "terminal_state_and_record_reproof",
        "active_external_launch_barrier_external_or_burned_launch_barrier_launch",
        "fault11",
