@pytest.mark.parametrize("operation_tag", ["begin_recovery", "confirm_recovery"])
def test_native_issuer_checkpoint_f_request_shape_and_source_reject_before_latch(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    operation_tag: str,
) -> None:
    _require_coherent_native_issuer_choreography_recovery_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    configure_barrier = cast(
        Callable[[int, int], None],
        getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME),
    )
    values = _prepare_native_issuer_checkpoint_f_operation_source(
        test_module,
        tmp_path / f"checkpoint-f-preflight-{operation_tag}",
        operation_tag,
    )
    foreign = _prepare_native_issuer_checkpoint_f_operation_source(
        test_module,
        tmp_path / f"checkpoint-f-preflight-{operation_tag}-foreign",
        operation_tag,
    )
    projection = cast(tuple[object, ...], values["projection"])
    foreign_projection = cast(tuple[object, ...], foreign["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    foreign_socket_owner = cast(socket.socket, foreign["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    request = cast(tuple[object, ...], values["request"])
    barrier = _configure_native_issuer_preloaded_external_projection_barrier(configure_barrier)
    try:
        assert configure(9, 0, 1) is None
        with pytest.raises(TypeError):
            transition(values["shadow"], operation_tag, list(request))  # type: ignore[arg-type]
        with pytest.raises(TypeError):
            transition(values["shadow"], operation_tag, request[:-1])
        unavailable_message = (
            _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_BEGIN_UNAVAILABLE_MESSAGE
            if operation_tag == "begin_recovery"
            else _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_CONFIRM_UNAVAILABLE_MESSAGE
        )
        crossbound_requests = (
            (foreign["capability"], *request[1:]),
            (request[0], foreign["recovery_checkpoint"], *request[2:]),
        )
        if operation_tag == "confirm_recovery":
            crossbound_requests += ((*request[:2], foreign["recovery_receipt"], request[3]),)
        for crossbound in crossbound_requests:
            with pytest.raises(RuntimeError, match=unavailable_message):
                transition(values["shadow"], operation_tag, crossbound)
            assert snapshot(values["shadow"]) == source
            _assert_native_issuer_preloaded_barrier_is_pending(barrier)
        _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)
        assert configure(-1, 0, 0) is None
        _activate, burn, _close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
            test_module
        )
        assert burn(values["shadow"]) is None
        _assert_native_issuer_preloaded_barrier_was_not_consumed(barrier)
        barrier = None
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        if barrier is not None:
            _close_native_issuer_external_projection_barrier_descriptors(barrier)
        _close_native_issuer_projection_socket(projection, socket_owner)
        _close_native_issuer_projection_socket(foreign_projection, foreign_socket_owner)


@pytest.mark.parametrize("mismatch", ["capability", "recovery_checkpoint"])
def test_native_issuer_checkpoint_f_abandon_parser_and_typed_mismatch_are_transactional(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    mismatch: str,
) -> None:
    _require_coherent_native_issuer_choreography_recovery_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    configure_barrier = cast(
        Callable[[int, int], None],
        getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME),
    )
    values = _prepare_native_issuer_checkpoint_f_operation_source(
        test_module,
        tmp_path / f"checkpoint-f-abandon-preflight-{mismatch}",
        "abandon_recovery",
        abandon_source="recovery_consuming",
    )
    foreign = _prepare_native_issuer_checkpoint_f_operation_source(
        test_module,
        tmp_path / f"checkpoint-f-abandon-preflight-{mismatch}-foreign",
        "abandon_recovery",
        abandon_source="recovery_consuming",
    )
    projection = cast(tuple[object, ...], values["projection"])
    foreign_projection = cast(tuple[object, ...], foreign["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    foreign_socket_owner = cast(socket.socket, foreign["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    barrier = _configure_native_issuer_preloaded_external_projection_barrier(configure_barrier)
    replacement: tuple[int, int, int, int] | None = None
    try:
        assert configure(9, 0, 1) is None
        with pytest.raises(TypeError):
            transition(
                values["shadow"],
                "abandon_recovery",
                [values["capability"], values["recovery_checkpoint"]],
            )
        assert snapshot(values["shadow"]) == source
        _assert_native_issuer_preloaded_barrier_is_pending(barrier)
        for invalid_request in (
            (values["capability"],),
            (values["capability"], object()),
        ):
            with pytest.raises(
                TypeError,
                match=_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_ABANDON_REQUEST_MESSAGE,
            ):
                transition(values["shadow"], "abandon_recovery", invalid_request)  # type: ignore[arg-type]
            assert snapshot(values["shadow"]) == source
            _assert_native_issuer_preloaded_barrier_is_pending(barrier)
        mismatch_request = (
            (foreign["capability"], values["recovery_checkpoint"])
            if mismatch == "capability"
            else (values["capability"], foreign["recovery_checkpoint"])
        )
        assert transition(values["shadow"], "abandon_recovery", mismatch_request) is None
        assert snapshot(values["shadow"]) == source
        _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)
        assert configure(-1, 0, 0) is None
        _assert_native_issuer_preloaded_barrier_was_not_consumed(barrier)
        barrier = None
        replacement = _configure_native_issuer_preloaded_external_projection_barrier(
            configure_barrier
        )
        _activate, burn, _close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
            test_module
        )
        assert burn(values["shadow"]) is None
        _assert_native_issuer_preloaded_barrier_was_not_consumed(replacement)
        replacement = None
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        if barrier is not None:
            _close_native_issuer_external_projection_barrier_descriptors(barrier)
        if replacement is not None:
            _close_native_issuer_external_projection_barrier_descriptors(replacement)
        _close_native_issuer_projection_socket(projection, socket_owner)
        _close_native_issuer_projection_socket(foreign_projection, foreign_socket_owner)


@pytest.mark.parametrize(
    ("selector", "expected_slot"),
    [
        ("same", 9),
        ("rollback", 9),
        ("action_deadline", 11),
        ("retention_deadline", 12),
        ("sample", None),
    ],
)
def test_native_issuer_checkpoint_f_recovery_checkpoint_preparation_preserves_selector_provenance(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    selector: str,
    expected_slot: int | None,
) -> None:
    _require_coherent_native_issuer_choreography_recovery_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    (
        shadow,
        projection,
        socket_owner,
        _lease,
        _capability,
        _registered,
        _binder,
        _authorization,
        claim,
        claim_payload,
        armed,
    ) = _prepare_native_issuer_checkpoint_f_armed_source(
        test_module,
        tmp_path / f"checkpoint-f-rk-{selector}",
    )
    try:
        recovery_checkpoint, checkpoint_snapshot, observed = (
            _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
                test_module,
                shadow,
                projection,
                claim,
                claim_payload,
                armed,
                selector,
            )
        )
        if expected_slot is not None:
            assert observed == armed[expected_slot]
        assert snapshot(shadow) == armed
        assert repr(recovery_checkpoint) == _NATIVE_ISSUER_CHOREOGRAPHY_WITNESS_REPR
        with pytest.raises(TypeError):
            hash(recovery_checkpoint)
        assert gc.is_tracked(recovery_checkpoint) is False
        assert gc.get_referents(recovery_checkpoint) == []
        assert checkpoint_snapshot[5:7] == ("prepared", armed[3])
        checkpoint_reference = weakref.ref(recovery_checkpoint)
        recovery_checkpoint = None
        gc.collect()
        assert checkpoint_reference() is None
        assert snapshot(shadow) == armed
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_checkpoint_f_same_and_rollback_share_projection_but_not_authority(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_recovery_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    for selector in ("same", "rollback"):
        (
            shadow,
            projection,
            socket_owner,
            _lease,
            capability,
            _registered,
            _binder,
            _authorization,
            claim,
            claim_payload,
            armed,
        ) = _prepare_native_issuer_checkpoint_f_armed_source(
            test_module,
            tmp_path / f"checkpoint-f-selector-provenance-{selector}",
        )
        try:
            same_checkpoint, same_snapshot, same_observed = (
                _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
                    test_module,
                    shadow,
                    projection,
                    claim,
                    claim_payload,
                    armed,
                    "same",
                )
            )
            rollback_checkpoint, rollback_snapshot, rollback_observed = (
                _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
                    test_module,
                    shadow,
                    projection,
                    claim,
                    claim_payload,
                    armed,
                    "rollback",
                )
            )
            same_summary = cast(tuple[object, ...], same_snapshot[7])
            rollback_summary = cast(tuple[object, ...], rollback_snapshot[7])
            assert same_summary[0] != rollback_summary[0]
            assert same_summary[1] == rollback_summary[1]
            assert same_observed == rollback_observed == armed[9]
            recovery_checkpoint = same_checkpoint if selector == "same" else rollback_checkpoint
            if selector == "same":
                assert (
                    transition(
                        shadow,
                        "begin_recovery",
                        (capability, recovery_checkpoint, selector),
                    )
                    is None
                )
                assert snapshot(shadow)[6] == "recovery_consuming"
            else:
                with pytest.raises(
                    RuntimeError,
                    match=_NATIVE_ISSUER_CHOREOGRAPHY_RETENTION_UNAVAILABLE_MESSAGE,
                ):
                    transition(
                        shadow,
                        "begin_recovery",
                        (capability, recovery_checkpoint, selector),
                    )
                assert snapshot(shadow)[6] == "recovery_unconfirmed"
        finally:
            _close_native_issuer_projection_socket(projection, socket_owner)


