    serial_before = max(
        cast(int, snapshot(values[name])[3])
        for name in live_handle_names
        if values.get(name) is not None
    )

    def prepare_at_boundary() -> object:
        candidate = prepare_witness(values["shadow"], witness_kind, payload)
        return candidate

    offset = _instruction_offset(
        prepare_at_boundary,
        opname="STORE_FAST" if boundary == "store" else "RETURN_VALUE",
        argval="candidate" if boundary == "store" else None,
    )
    interruption: BaseException = (
        SystemExit(253) if failure_type is SystemExit else KeyboardInterrupt()
    )
    tool_id = _enable_instruction_interrupt(
        prepare_at_boundary,
        offset,
        tool_name=f"native-issuer-checkpoint-f-prepare-{witness_kind}-{boundary}",
        interruption=interruption,
    )
    try:
        with pytest.raises(failure_type) as retained:
            prepare_at_boundary()
        assert retained.value is interruption
    finally:
        _disable_instruction_interrupt(tool_id, prepare_at_boundary)
    try:
        gc.collect()
        assert snapshot(values["shadow"]) == source
        replacement = prepare_at_boundary()
        replacement_snapshot = snapshot(replacement)
        assert replacement_snapshot[3] == serial_before + 2
        assert replacement_snapshot[5:7] == ("prepared", source[3])
        assert snapshot(values["shadow"]) == source
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


