@pytest.mark.parametrize("witness_kind", ["recovery_checkpoint", "recovery_receipt"])
def test_native_issuer_checkpoint_f_witness_preparation_rejects_foreign_thread(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    witness_kind: str,
) -> None:
    _require_coherent_native_issuer_choreography_recovery_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _prepare_authority, prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_f_operation_source(
        test_module,
        tmp_path / f"checkpoint-f-prep-thread-{witness_kind}",
        "begin_recovery" if witness_kind == "recovery_checkpoint" else "confirm_recovery",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    payload = (
        (values["claim"], "same")
        if witness_kind == "recovery_checkpoint"
        else _native_issuer_checkpoint_f_recovery_receipt_payload(
            values["claim"],
            values["recovery_checkpoint"],
            cast(tuple[str, ...], values["claim_payload"]),
        )
    )
    outcomes: list[BaseException | None] = []

    def prepare_on_foreign_thread() -> None:
        try:
            prepare_witness(values["shadow"], witness_kind, payload)
        except BaseException as error:
            outcomes.append(error)
        else:
            outcomes.append(None)

    try:
        assert configure(2, 0, 1) is None
        worker = threading.Thread(target=prepare_on_foreign_thread)
        worker.start()
        worker.join(timeout=5.0)
        assert not worker.is_alive()
        assert len(outcomes) == 1 and type(outcomes[0]) is RuntimeError
        assert snapshot(values["shadow"]) == source
        _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 2, 0)
        assert configure(-1, 0, 0) is None
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_checkpoint_f_multiple_candidates_are_unique_and_become_revision_stale(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_recovery_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    (
        shadow,
        projection,
        socket_owner,
        _lease,
        capability,
        _registered,
        _binder,
        _authorization,
        claim,
        claim_payload,
        armed,
    ) = _prepare_native_issuer_checkpoint_f_armed_source(
        test_module,
        tmp_path / "checkpoint-f-multiple-candidates",
    )
    try:
        first, first_snapshot, _first_observed = (
            _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
                test_module,
                shadow,
                projection,
                claim,
                claim_payload,
                armed,
                "same",
            )
        )
        second, second_snapshot, _second_observed = (
            _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
                test_module,
                shadow,
                projection,
                claim,
                claim_payload,
                armed,
                "same",
            )
        )
        assert first_snapshot[3] != second_snapshot[3]
        assert first_snapshot[7] != second_snapshot[7]
        assert transition(shadow, "begin_recovery", (capability, first, "same")) is None
        consuming = cast(tuple[object, ...], snapshot(shadow))
        assert consuming[6] == "recovery_consuming"
        with pytest.raises(
            RuntimeError,
            match=_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_BEGIN_UNAVAILABLE_MESSAGE,
        ):
            transition(shadow, "begin_recovery", (capability, second, "same"))
        assert snapshot(shadow) == consuming
        assert snapshot(second)[5:7] == ("prepared", armed[3])

        first_receipt_payload = _native_issuer_checkpoint_f_recovery_receipt_payload(
            claim,
            first,
            claim_payload,
        )
        first_receipt = prepare_witness(
            shadow,
            "recovery_receipt",
            first_receipt_payload,
        )
        second_receipt = prepare_witness(
            shadow,
            "recovery_receipt",
            first_receipt_payload,
        )
        assert snapshot(first_receipt)[3] != snapshot(second_receipt)[3]
        assert (
            transition(
                shadow,
                "confirm_recovery",
                (capability, first, first_receipt, "same"),
            )
            is None
        )
        confirmed = cast(tuple[object, ...], snapshot(shadow))
        with pytest.raises(
            RuntimeError,
            match=_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_CONFIRM_UNAVAILABLE_MESSAGE,
        ):
            transition(
                shadow,
                "confirm_recovery",
                (capability, first, second_receipt, "same"),
            )
        assert snapshot(shadow) == confirmed
        assert snapshot(second_receipt)[5:7] == ("prepared", consuming[3])
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


