def test_native_issuer_checkpoint_f_selector_echo_and_stale_source_reject_before_latch(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_recovery_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    _activate, burn, _close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    configure_barrier = getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME)
    (
        shadow,
        projection,
        socket_owner,
        _lease,
        capability,
        _registered,
        _binder,
        _authorization,
        claim,
        claim_payload,
        armed,
    ) = _prepare_native_issuer_checkpoint_f_armed_source(
        test_module,
        tmp_path / "checkpoint-f-selector-echo",
    )
    barrier: tuple[int, int, int, int] | None = None
    try:
        recovery_checkpoint, checkpoint_snapshot, _observed = (
            _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
                test_module,
                shadow,
                projection,
                claim,
                claim_payload,
                armed,
                "same",
            )
        )
        assert configure(9, 0, 1) is None
        barrier = _configure_native_issuer_preloaded_external_projection_barrier(configure_barrier)
        with pytest.raises(
            RuntimeError,
            match=_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_BEGIN_UNAVAILABLE_MESSAGE,
        ):
            transition(
                shadow,
                "begin_recovery",
                (capability, recovery_checkpoint, "rollback"),
            )
        assert snapshot(shadow) == armed
        assert snapshot(recovery_checkpoint) == checkpoint_snapshot
        _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)
        _assert_native_issuer_preloaded_barrier_is_pending(barrier)
        assert configure(-1, 0, 0) is None
        assert burn(shadow) is None
        _assert_native_issuer_preloaded_barrier_was_not_consumed(barrier)
        barrier = None
        burned_armed = list(armed)
        burned_armed[1] = 4
        burned_armed[8] = False
        assert snapshot(shadow) == tuple(burned_armed)

        selected_checkpoint, _selected_snapshot, _selected_observed = (
            _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
                test_module,
                shadow,
                projection,
                claim,
                claim_payload,
                tuple(burned_armed),
                "same",
            )
        )
        assert (
            transition(
                shadow,
                "begin_recovery",
                (capability, selected_checkpoint, "same"),
            )
            is None
        )
        advanced = cast(tuple[object, ...], snapshot(shadow))
        assert advanced[3] == cast(int, armed[3]) + 1
        assert advanced[6] == "recovery_consuming"
        assert configure(9, 0, 1) is None
        barrier = _configure_native_issuer_preloaded_external_projection_barrier(configure_barrier)
        with pytest.raises(
            RuntimeError,
            match=_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_BEGIN_UNAVAILABLE_MESSAGE,
        ):
            transition(
                shadow,
                "begin_recovery",
                (capability, recovery_checkpoint, "same"),
            )
        assert snapshot(shadow) == advanced
        assert snapshot(recovery_checkpoint) == checkpoint_snapshot
        _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)
        _assert_native_issuer_preloaded_barrier_is_pending(barrier)
        assert configure(-1, 0, 0) is None
        assert burn(shadow) is None
        _assert_native_issuer_preloaded_barrier_was_not_consumed(barrier)
        barrier = None
    finally:
        if barrier is not None:
            _close_native_issuer_external_projection_barrier_descriptors(barrier)
        _close_native_issuer_projection_socket(projection, socket_owner)


