def test_native_issuer_checkpoint_f_fork_point_seven_publishes_full_cleanup_origin(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    operation_tag: str,
    selector: str | None,
    abandon_source: str,
    source_lifecycle: str,
    expected_phase: str,
    expected_error: str,
) -> None:
    _require_coherent_native_issuer_choreography_recovery_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    configure_fork, finish_fork = _native_issuer_foreign_fork_hooks(test_module)
    values = _prepare_native_issuer_checkpoint_f_operation_source(
        test_module,
        tmp_path / f"checkpoint-f-fork7-{operation_tag}-{abandon_source}-{selector}",
        operation_tag,
        abandon_source=abandon_source,
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    request = cast(tuple[object, ...], values["request"])
    if operation_tag == "begin_recovery":
        assert selector is not None
        checkpoint, _checkpoint_snapshot, _observed = (
            _prepare_native_issuer_checkpoint_f_recovery_checkpoint(
                test_module,
                values["shadow"],
                projection,
                values["claim"],
                cast(tuple[str, ...], values["claim_payload"]),
                cast(tuple[object, ...], values["armed"]),
                selector,
            )
        )
        request = (values["capability"], checkpoint, selector)
    elif operation_tag == "confirm_recovery":
        request = (*request[:-1], selector)
    if source_lifecycle == "burned":
        _activate, burn, _close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
            test_module
        )
        assert burn(values["shadow"]) is None
        burned_source = list(source)
        burned_source[1] = 4
        burned_source[8] = False
        source = tuple(burned_source)
        assert snapshot(values["shadow"]) == source
    else:
        assert source_lifecycle == "active"
    try:
        assert configure_fork(values["shadow"], 7) is None
        if expected_error == "forced":
            _assert_native_issuer_choreography_fault(
                lambda: transition(values["shadow"], operation_tag, request),
                0,
            )
        else:
            expected_message = (
                _NATIVE_ISSUER_CHOREOGRAPHY_RETENTION_UNAVAILABLE_MESSAGE
                if expected_error == "deadline"
                else _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_F_CONFIRM_UNAVAILABLE_MESSAGE
            )
            with pytest.raises(RuntimeError) as retained:
                transition(values["shadow"], operation_tag, request)
            assert type(retained.value) is RuntimeError
            assert str(retained.value) == expected_message
        _assert_native_issuer_foreign_fork_result(finish_fork(), 7)
        terminal = cast(tuple[object, ...], snapshot(values["shadow"]))
        assert terminal[3] == cast(int, source[3]) + 2
        assert terminal[6] == expected_phase
        expected_lifecycle = (
            _native_issuer_active_snapshot(projection)
            if expected_phase == "recovery_confirmed" and source_lifecycle == "active"
            else _native_issuer_explicit_burned_snapshot(projection)
        )
        assert test_module._test_topology_observation_issuer_shadow_state(values["shadow"]) == (
            expected_lifecycle
        )
    finally:
        with suppress(RuntimeError):
            finish_fork()
        _close_native_issuer_projection_socket(projection, socket_owner)


