def test_native_issuer_checkpoint_g_surface_admits_only_tag_four_and_returns_exact_bool(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_salvage_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    source_path = Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c"
    source_sha256 = hashlib.sha256(source_path.read_bytes()).hexdigest()
    checkpoint_h = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_POST_EFFECT_OR_LATER_C_SHA256
    )
    checkpoint_i = (
        source_sha256 in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REQUIRE_POST_EFFECT_OR_LATER_C_SHA256
    )
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_g_source(
        test_module,
        tmp_path / "checkpoint-g-surface",
        "claim_admitted",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    try:
        result = transition(
            values["shadow"],
            "salvage_claim",
            (values["binder"], values["claim"], "action_deadline"),
        )
        assert type(result) is bool and result is True
        armed = cast(tuple[object, ...], snapshot(values["shadow"]))
        assert armed[6:9] == ("armed", False, False)
        first_unavailable_tag = (
            16
            if _native_issuer_choreography_formal_force_revoke_source_is_coherent()
            else 15
            if _native_issuer_choreography_formal_expire_source_is_coherent()
            else 14
            if _native_issuer_choreography_abandon_controller_source_is_coherent()
            else 13
            if _native_issuer_choreography_attest_controller_durable_source_is_coherent()
            else 12
            if _native_issuer_choreography_confirm_controller_source_is_coherent()
            else 11
            if _native_issuer_choreography_begin_controller_source_is_coherent()
            else 10
            if checkpoint_i
            else 9
            if checkpoint_h
            else 8
        )
        for tag in _NATIVE_ISSUER_CHOREOGRAPHY_OPERATION_TAGS[first_unavailable_tag:]:
            with pytest.raises(RuntimeError):
                transition(values["shadow"], tag, ())
        assert snapshot(values["shadow"]) == armed
        assert all(
            not hasattr(test_module, _NATIVE_ISSUER_CHOREOGRAPHY_HOOK_NAMES[index])
            for index in (4, 5)
        )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


@pytest.mark.parametrize("selector", ["sample", "action_deadline"])
def test_native_issuer_checkpoint_g_claim_admitted_success_installs_exact_claim(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    selector: str,
) -> None:
    _require_coherent_native_issuer_choreography_salvage_source()
