    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_g_source(
        test_module,
        tmp_path / f"checkpoint-g-success-{selector}",
        "claim_admitted",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    payload = cast(tuple[str, ...], values["claim_payload"])
    try:
        result = transition(
            values["shadow"],
            "salvage_claim",
            (values["binder"], values["claim"], selector),
        )
        assert type(result) is bool and result is True
        candidate = cast(tuple[object, ...], snapshot(values["shadow"]))
        if selector == "sample":
            assert cast(int, source[9]) <= cast(int, candidate[9]) < cast(int, source[12])
            expected_last = cast(int, candidate[9])
            expected_action = cast(int, candidate[9]) < cast(int, source[11])
        else:
            assert selector == "action_deadline"
            expected_last = cast(int, source[11])
            expected_action = False
        _assert_native_issuer_checkpoint_e_armed_snapshot(
            snapshot,
            values["shadow"],
            values["lease"],
            values["capability"],
            values["binder"],
            values["claim"],
            payload,
            source,
            _native_issuer_checkpoint_e_roots(projection),
            state_revision=cast(int, source[3]) + 1,
            install_revision=cast(int, source[3]) + 1,
            expected_last=expected_last,
            stored_action=expected_action,
        )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


