@pytest.mark.parametrize("source_lifecycle", ["active", "burned"])
@pytest.mark.parametrize("source_action", [True, False])
def test_native_issuer_checkpoint_g_armed_same_is_byte_identical_identity_confirmation(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    source_lifecycle: str,
    source_action: bool,
) -> None:
    _require_coherent_native_issuer_choreography_salvage_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    _activate, burn, _close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    values = _prepare_native_issuer_checkpoint_g_source(
        test_module,
        tmp_path / f"checkpoint-g-identity-{source_lifecycle}-{source_action}",
        "claim_admitted",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    selector = "sample" if source_action else "action_deadline"
    try:
        assert (
            transition(
                values["shadow"],
                "salvage_claim",
                (values["binder"], values["claim"], selector),
            )
            is True
        )
        source = cast(tuple[object, ...], snapshot(values["shadow"]))
        if source_lifecycle == "burned":
            assert burn(values["shadow"]) is None
            burned = list(source)
            burned[1] = 4
            burned[8] = False
            source = tuple(burned)
        else:
            assert source_lifecycle == "active"
        handle_snapshots = tuple(
            snapshot(values[name]) for name in ("lease", "capability", "binder", "claim")
        )
        assert snapshot(values["shadow"]) == source
        result = transition(
            values["shadow"],
            "salvage_claim",
            (values["binder"], values["claim"], "same"),
        )
        assert type(result) is bool and result is True
        assert snapshot(values["shadow"]) == source
        assert (
            tuple(snapshot(values[name]) for name in ("lease", "capability", "binder", "claim"))
            == handle_snapshots
        )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_checkpoint_g_armed_retry_preserves_prior_exact_origin(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_salvage_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    (
        shadow,
        projection,
        socket_owner,
        _lease,
        _capability,
        _registered,
        _source_state,
        binder,
        _authorization,
        claim,
        _claim_payload,
        request,
    ) = _prepare_native_issuer_checkpoint_e_operation_source(
        test_module,
        tmp_path / "checkpoint-g-prior-origin",
        "arm_claim",
    )
    assert claim is not None
    try:
        assert configure(11, 0, 1) is None
        _assert_native_issuer_choreography_fault(
            lambda: transition(shadow, "arm_claim", request),
            0,
        )
        source = cast(tuple[object, ...], snapshot(shadow))
        assert source[6:9] == ("armed", False, False)
        intrinsic = (snapshot(binder), snapshot(claim))
        result = transition(
            shadow,
            "salvage_claim",
            (binder, claim, "same"),
        )
        assert type(result) is bool and result is True
        assert snapshot(shadow) == source
        assert (snapshot(binder), snapshot(claim)) == intrinsic
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        _close_native_issuer_projection_socket(projection, socket_owner)


