    checkpoint_i = (
        hashlib.sha256(source_path.read_bytes()).hexdigest()
        in _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REQUIRE_POST_EFFECT_OR_LATER_C_SHA256
    )
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
