@pytest.mark.parametrize("boundary", ["initial", "terminal"])
@pytest.mark.parametrize("mutation", ["executable_identity", "socket_identity"])
def test_native_issuer_checkpoint_h_external_proof_failure_burns_exact_target(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    boundary: str,
    mutation: str,
) -> None:
    _require_coherent_native_issuer_choreography_post_effect_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    configure_barrier = cast(
        Callable[[int, int], None],
        getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME),
    )
    values = _prepare_native_issuer_checkpoint_h_source(
        test_module,
        tmp_path / f"checkpoint-h-proof-{boundary}-{mutation}",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    replacement_socket: socket.socket | None = None
    backup_paths: tuple[Path, ...] = ()
    child_pid = -1
    ready_write = -1
    resume_read = -1
    child_reaped = False
    try:
        if boundary == "initial":
            replacement_socket, backup_paths = _mutate_native_issuer_external_identity(
                projection,
                mutation,
            )
        else:
            assert boundary == "terminal"
            child_pid, ready_write, resume_read, backup_paths = (
                _fork_native_issuer_external_projection_mutator(projection, mutation)
            )
            assert configure_barrier(ready_write, resume_read) is None
        with pytest.raises(OSError):
            transition(values["shadow"], "arm_post_effect", values["request"])
        if boundary == "terminal":
            assert (
                _reap_native_issuer_external_projection_mutator(
                    child_pid,
                    ready_write,
                    resume_read,
                )
                == 0
            )
            child_reaped = True
            ready_write = -1
            resume_read = -1
            _assert_native_issuer_checkpoint_h_post_effect_unconfirmed_snapshot(
                snapshot,
                values,
                state_revision=cast(int, source[3]) + 2,
                expected_last=cast(int, source[9]),
            )
        else:
            _assert_native_issuer_checkpoint_h_recovery_unconfirmed_snapshot(
                snapshot,
                values,
                state_revision=cast(int, source[3]) + 1,
            )
        assert test_module._test_topology_observation_issuer_shadow_state(values["shadow"]) == (
            _native_issuer_explicit_burned_snapshot(projection)
        )
    finally:
        if child_pid > 0 and not child_reaped:
            assert (
                _reap_native_issuer_external_projection_mutator(
                    child_pid,
                    ready_write,
                    resume_read,
                )
                == 0
            )
        if replacement_socket is not None:
            replacement_socket.close()
        _close_native_issuer_projection_socket(projection, socket_owner)
        for backup_path in backup_paths:
            with suppress(FileNotFoundError):
                backup_path.unlink()


@pytest.mark.parametrize(
    ("point", "selector", "expected_phase"),
    [
        (6, "same", "post_effect_armed"),
        (6, "rollback", "revoked"),
        (6, "action_deadline", "armed"),
        (7, "rollback", "revoked"),
        (7, "action_deadline", "armed"),
        (7, "same", "post_effect_armed"),
    ],
)
def test_native_issuer_checkpoint_h_fork_points_validate_candidates_and_cleanup_targets(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    point: int,
    selector: str,
    expected_phase: str,
) -> None:
    _require_coherent_native_issuer_choreography_post_effect_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    configure_fork, finish_fork = _native_issuer_foreign_fork_hooks(test_module)
    values = _prepare_native_issuer_checkpoint_h_source(
        test_module,
        tmp_path / f"checkpoint-h-fork-{point}-{selector}",
        selector,
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    try:
        assert configure_fork(values["shadow"], point) is None
        if selector == "same" and point == 6:
            assert transition(values["shadow"], "arm_post_effect", values["request"]) is None
        elif selector == "same":
            _assert_native_issuer_choreography_fault(
                lambda: transition(
                    values["shadow"],
                    "arm_post_effect",
                    values["request"],
                ),
                0,
            )
        else:
            with pytest.raises(RuntimeError) as retained:
                transition(values["shadow"], "arm_post_effect", values["request"])
            assert (
                str(retained.value) == _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_H_UNAVAILABLE_MESSAGE
            )
        _assert_native_issuer_foreign_fork_result(finish_fork(), point)
        terminal = cast(tuple[object, ...], snapshot(values["shadow"]))
        assert terminal[6] == expected_phase
        assert terminal[9] == source[9]
        if point == 6 and selector == "same":
            assert terminal[1] == 3
            assert terminal[3] == cast(int, source[3]) + 1
            assert test_module._test_topology_observation_issuer_shadow_state(
                values["shadow"]
            ) == _native_issuer_active_snapshot(projection)
        elif point == 7 and selector == "same":
            _assert_native_issuer_checkpoint_h_post_effect_armed_snapshot(
                snapshot,
                values,
                state_revision=cast(int, source[3]) + 2,
                expected_last=cast(int, source[9]),
                stored_action=False,
                post_effect_install_revision=cast(int, source[3]) + 1,
                lifecycle_revision=4,
            )
        else:
            assert terminal[1] == 4
            assert terminal[3] == cast(int, source[3]) + 1
    finally:
        with suppress(RuntimeError):
            finish_fork()
        _close_native_issuer_projection_socket(projection, socket_owner)


