def test_native_issuer_checkpoint_h_burn_close_and_owner_death_are_bounded(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_post_effect_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    _activate, burn, close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    values = _prepare_native_issuer_checkpoint_h_source(
        test_module,
        tmp_path / "checkpoint-h-lifecycle",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    post_effect_before = snapshot(values["post_effect"])
    shadow_reference = weakref.ref(values["shadow"])
    live_handles = ("lease", "capability", "binder", "claim", "post_effect")
    try:
        assert burn(values["shadow"]) is None
        burned = list(source)
        burned[1] = 4
        burned[8] = False
        assert snapshot(values["shadow"]) == tuple(burned)
        with pytest.raises(RuntimeError) as retained:
            transition(values["shadow"], "arm_post_effect", values["request"])
        assert str(retained.value) == _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_H_UNAVAILABLE_MESSAGE
        assert snapshot(values["shadow"]) == tuple(burned)
        assert snapshot(values["post_effect"]) == post_effect_before
        with pytest.raises(RuntimeError):
            prepare_authority(
                values["shadow"],
                "post_effect_outcome_capability",
            )
        with pytest.raises(RuntimeError):
            close(values["shadow"])
        assert snapshot(values["shadow"]) == tuple(burned)

        owner_dead_revision = cast(int, source[3]) + 1
        values["shadow"] = None
        gc.collect()
        assert shadow_reference() is None
        for name in live_handles:
            handle_snapshot = cast(tuple[object, ...], snapshot(values[name]))
            assert handle_snapshot[5:7] == ("owner_dead", owner_dead_revision)
        contender = test_module._test_create_inert_topology_observation_issuer_shadow()
        assert _activate(contender, projection) is None
        assert close(contender) is None
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


