        "aqt_issuer_choreography_detached_record_append_locked(detached, recovery);",
        "aqt_issuer_choreography_detached_record_append_locked(detached, post_effect);",
        "aqt_issuer_choreography_detached_record_append_locked(detached, claim);",
        "AQT_CHOREOGRAPHY_AUTHORITY_REVOKED",
