        "request->source_projection == shadow->projection",
        "request->source_launch_lease != shadow->launch_lease",
        "shadow->state != AQT_ISSUER_NATIVE_STATE_BURNED",
        "shadow->revision != 4U",
        "shadow->poisoned != 1U",
