    unlock = core.index("aqt_unlock_owner_list_or_fail_stop();", confirmation)
    assert cleanup_loop < loop_reconcile < cleanup_take < loop_end < fifth < confirmation < unlock
    assert (
        core.count("aqt_issuer_choreography_post_effect_requirement_cleanup_reconcile_locked(") == 2
    )

