def test_native_issuer_checkpoint_j_contract_is_exact_and_runtime_gated() -> None:
    assert type(_COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BEGIN_CONTROLLER_J_SHA256) is frozenset
    assert (
        frozenset({"f9934cb8f3aef905e96ecfd307de13b0967e97e7d008e8e42b741e4950d32403"})
        == _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BEGIN_CONTROLLER_J_SHA256
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_J_EXPORTED_HOOK_INDICES == (
        0,
        1,
        2,
        3,
        6,
        7,
    )
