    for marker in core_order:
        cursor = compact_core.index("".join(marker.split()), cursor + 1)
    assert core.count("aqt_issuer_choreography_sample_continuous_ns(") == 1
    assert "request->selector == AQT_CHOREOGRAPHY_TIME_SAMPLE" in core
    assert (
        core.count("aqt_issuer_choreography_controller_confirmation_authority_proof_locked(") == 2
    )
    assert core.count("aqt_issuer_foreign_fork_bind_controller_confirmation_locked(") == 2
    assert (
        core.count("aqt_issuer_choreography_controller_confirmation_cleanup_reconcile_locked(") == 2
    )
    assert "AQT_ISSUER_FAULT_KIND_RUNTIME_ERROR" in core
    assert "committed_is_present && terminal_proof_completed" in core

    for corridor in (
        source_gate,
        selected_proof,
        authority_proof,
        publisher,
        parent_lifecycle,
        cleanup_records,
        reconcile,
    ):
        for forbidden in (
            "PyErr_",
            "PyObject_",
            "PyMem_",
            "Py_DECREF",
            "Py_XDECREF",
            "Py_CLEAR",
            "aqt_allocate_",
            "aqt_issuer_choreography_record_decref",
            "free(",
            "Py_BEGIN_ALLOW_THREADS",
            "Py_END_ALLOW_THREADS",
        ):
            assert forbidden not in corridor

    lock_cursor = 0
    while True:
        lock_start = core.find("aqt_lock_owner_list_or_fail_stop();", lock_cursor)
        if lock_start < 0:
            break
        lock_end = core.index("aqt_unlock_owner_list_or_fail_stop();", lock_start)
        lock_span = core[lock_start:lock_end]
        for forbidden in (
            "PyErr_",
            "PyObject_",
            "PyMem_",
            "Py_DECREF",
            "Py_XDECREF",
            "Py_CLEAR",
            "aqt_allocate_",
            "aqt_issuer_choreography_record_decref",
            "free(",
            "Py_BEGIN_ALLOW_THREADS",
            "Py_END_ALLOW_THREADS",
        ):
            assert forbidden not in lock_span
        lock_cursor = lock_end + 1


