def test_native_issuer_checkpoint_l_contract_is_exact_and_runtime_gated() -> None:
    assert (
        type(_COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_ATTEST_CONTROLLER_DURABLE_L_SHA256) is frozenset
    )
    assert (
        frozenset({"7acd36f4115a34da3d6b01743f7779c67c078035b606e575d4efa9ab207ffafb"})
        == _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_ATTEST_CONTROLLER_DURABLE_L_SHA256
    )
    assert _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_CONFIRM_CONTROLLER_OR_LATER_C_SHA256 == (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_CONFIRM_CONTROLLER_K_SHA256
        | _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_ATTEST_CONTROLLER_DURABLE_OR_LATER_C_SHA256
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_REQUEST_SLOTS == ("controller_receipt",)
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_OPERATION_ARITIES == (
        ("attest_controller_durable", 1),
    )
    assert len(_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_SOURCE_ROWS) == 3
    assert len(_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_FAILURE_TARGETS) == 3
    assert len(_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_PROOF_ORDER) == 15
    assert len(_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_CLEANUP_RULES) == 8
    assert len(_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_FORK_ROWS) == 6
    assert len(_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_LIFECYCLE_RULES) == 6
    assert len(_NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_BINDING_CORRUPTION_FIELDS) == 43
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_SUMMARY_SLOTS == (
        "controller_receipt_key",
        "prepared",
        "controller_receipt_projection7",
        "claim_summary3",
        "controller_checkpoint_summary2",
        "durability_binding_sha256_or_none",
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_DOMAINS == (
        "trusted-time-native-controller-durability-path-v1",
        "trusted-time-native-controller-durability-inventory-v1",
        "trusted-time-native-controller-durability-binding-v1",
    )
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_OPEN_FLAGS == (
        "O_RDONLY",
        "O_CLOEXEC",
        "O_NOFOLLOW",
        "O_NONBLOCK",
        "O_NOCTTY",
    )
    assert dict(
        (name, (minimum, maximum))
        for name, minimum, maximum in _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_LIMITS
    ) == {
        "outcome_bytes": (1, 131072),
        "ignored_root_components": (1, 256),
        "artifact_components": (2, 257),
        "path_s5_nodes": (2, 258),
        "path_bytes": (1, 4095),
        "component_bytes": (1, 255),
        "prepared_entries": (0, 4095),
        "durable_entries": (1, 4096),
        "inventory_name_bytes": (0, 1024 * 1024),
        "directory_buffer_bytes": (65536, 65536),
    }
    for payload, digest in _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_SHA256_KATS:
        assert hashlib.sha256(payload).hexdigest() == digest
        chunks = tuple(payload[index : index + 3] for index in range(0, len(payload), 3))
        context = hashlib.sha256()
        for chunk in chunks:
            context.update(chunk)
        assert context.hexdigest() == digest
    assert _native_issuer_checkpoint_l_text("abc") == (_native_issuer_checkpoint_l_bytes(b"abc"))
    assert _native_issuer_checkpoint_l_hex("a" * 64) == (
        _native_issuer_checkpoint_l_bytes(b"a" * 64)
    )
    assert _native_issuer_checkpoint_l_marker_bytes(
        "contract-v1",
        "a" * 64,
        status="reserved",
    ) == (
        b'{"contract_version":"contract-v1","outcome_sha256":"'
        + b"a" * 64
        + b'","status":"reserved"}\n'
    )
    assert _native_issuer_checkpoint_l_marker_bytes(
        "contract-v1",
        "a" * 64,
        status="committed",
    ) == (
        b'{"contract_version":"contract-v1","outcome_sha256":"'
        + b"a" * 64
        + b'","status":"committed"}\n'
    )


def test_native_issuer_checkpoint_l_nanosecond_and_selected_inventory_kats_are_exact() -> None:
    signed_minimum = -(2**63)
    signed_maximum = 2**63 - 1
    minimum_seconds, minimum_nanoseconds = divmod(signed_minimum, 1_000_000_000)
    maximum_seconds, maximum_nanoseconds = divmod(signed_maximum, 1_000_000_000)
    assert (
        _native_issuer_checkpoint_l_checked_nanoseconds(
            minimum_seconds,
            minimum_nanoseconds,
        )
        == signed_minimum
    )
    assert (
        _native_issuer_checkpoint_l_checked_nanoseconds(
            maximum_seconds,
            maximum_nanoseconds,
        )
        == signed_maximum
    )
    assert _native_issuer_checkpoint_l_i64(signed_minimum) == b"\x80" + b"\0" * 7
    assert _native_issuer_checkpoint_l_i64(signed_maximum) == b"\x7f" + b"\xff" * 7
    with pytest.raises(OverflowError):
        _native_issuer_checkpoint_l_checked_nanoseconds(
            minimum_seconds,
            minimum_nanoseconds - 1,
        )
    with pytest.raises(OverflowError):
        _native_issuer_checkpoint_l_checked_nanoseconds(
            maximum_seconds,
            maximum_nanoseconds + 1,
        )

    unsigned_maximum = 2**64 - 1
    assert _native_issuer_checkpoint_l_artifact_link_count_transition_is_exact(7, 7)
    assert _native_issuer_checkpoint_l_artifact_link_count_transition_is_exact(7, 8)
    assert not _native_issuer_checkpoint_l_artifact_link_count_transition_is_exact(7, 6)
    assert not _native_issuer_checkpoint_l_artifact_link_count_transition_is_exact(7, 9)
    assert _native_issuer_checkpoint_l_artifact_link_count_transition_is_exact(
        unsigned_maximum,
        unsigned_maximum,
    )
    assert not _native_issuer_checkpoint_l_artifact_link_count_transition_is_exact(
        unsigned_maximum,
        0,
    )

    outcome_name = b"trusted-time-post-enrollment-start-outcome-" + b"6" * 64 + b".json"
    slot_name = _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_SLOT_BASENAME.encode("ascii", "strict")
    commit_name = _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_L_COMMIT_BASENAME.encode("ascii", "strict")
    outcome_identity = (1, 2, stat.S_IFREG | 0o600, 3, 4, 1, 17, 19, 23)
    slot_identity = (1, 5, stat.S_IFREG | 0o600, 3, 4, 1, 29, 31, 37)
    commit_identity = (1, 6, stat.S_IFREG | 0o600, 3, 4, 1, 41, 43, 47)
    prepared_entries = (
        (outcome_name, outcome_identity),
        (slot_name, slot_identity),
    )
    durable_entries = (*prepared_entries, (commit_name, commit_identity))
    prepared = _native_issuer_checkpoint_l_inventory_digest(
        prepared_entries,
        reserve_commit=True,
    )
    durable_base = _native_issuer_checkpoint_l_inventory_digest(
        tuple(entry for entry in durable_entries if entry[0] != commit_name),
        reserve_commit=True,
    )
    assert durable_base == prepared
    durable = _native_issuer_checkpoint_l_inventory_digest(
        durable_entries,
        reserve_commit=False,
    )
    assert durable[:2] == (prepared[0] + 1, prepared[1] + len(commit_name))
    for selected_index in range(2):
        for stat_index in range(9):
            mutated = list(prepared_entries)
            selected_name, selected_identity = mutated[selected_index]
            changed_identity = list(selected_identity)
            changed_identity[stat_index] += 1
            mutated[selected_index] = (selected_name, tuple(changed_identity))
            mutated_tuple = tuple(mutated)
            assert (
                _native_issuer_checkpoint_l_inventory_digest(
                    mutated_tuple,
                    reserve_commit=True,
                )[2]
                != prepared[2]
            )
            mutated_durable = (*mutated_tuple, (commit_name, commit_identity))
            assert (
                _native_issuer_checkpoint_l_inventory_digest(
                    mutated_durable,
                    reserve_commit=False,
                )[2]
                != durable[2]
            )


