def test_native_issuer_checkpoint_n_static_transition_and_cleanup_are_exact() -> None:
    _require_coherent_native_issuer_choreography_formal_expire_source()
    source = (Path(__file__).resolve().parents[2] / "native/owned_file_descriptor.c").read_text(
        encoding="utf-8"
    )
    core = _native_c_function_definition_slice(
        source,
        "aqt_issuer_choreography_formal_expire_transition",
        "aqt_issuer_choreography_formal_expire",
    )
    fault_configuration = _native_c_function_definition_slice(
        source,
        "aqt_test_configure_topology_observation_issuer_shadow_choreography_failure",
        "aqt_test_activate_topology_observation_issuer_shadow",
    )
    fork_configuration = _native_c_function_definition_slice(
        source,
        "aqt_test_configure_topology_observation_issuer_shadow_foreign_fork_interposition",
        "aqt_test_finish_topology_observation_issuer_shadow_foreign_fork_interposition",
    )
    compact_fault_configuration = "".join(fault_configuration.split())
    compact_fork_configuration = "".join(fork_configuration.split())
    assert (
        "(group==3&&fork_plan!=NULL&&(fork_plan->point=="
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT||"
        "fork_plan->point=="
        "AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT))"
        in compact_fault_configuration
    )
    assert (
        "((point==AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_TRANSITION_POST_STATE_COMMIT||"
        "point==AQT_ISSUER_FOREIGN_FORK_CHOREOGRAPHY_FAILCLOSED_POST_STATE_COMMIT)&&"
        "module_state->issuer_choreography_fault_plan.row_count!=0&&"
        "module_state->issuer_choreography_fault_plan.group==3)" in compact_fork_configuration
    )
    order = (
        "aqt_clone_issuer_roots_projection",
        "aqt_lock_owner_list_or_fail_stop();",
        "aqt_issuer_choreography_formal_expire_source_is_exact_locked(",
        "if ((fault_plan->row_count != 0 && fault_plan->group == 3",
        "aqt_issuer_choreography_runtime_error(",
        "fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(",
        "aqt_issuer_choreography_fault_plan_begin_locked(",
        "aqt_issuer_choreography_formal_expire_selected_records_proof_locked(",
        "AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_STATE_STORE",
        "aqt_issuer_choreography_publish_formal_expired_candidate_locked(",
        "aqt_issuer_foreign_fork_bind_formal_expire_locked(",
        "AQT_CHOREOGRAPHY_FAULT_TRANSITION_POST_STATE_STORE",
        "AQT_CHOREOGRAPHY_FAULT_TRANSITION_PRE_RETURN",
        "for (index = 0; index < 4; index++)",
    )
    cursor = -1
    for marker in order:
        cursor = core.index(marker, cursor + 1)
    conflict_start = core.index("if ((fault_plan->row_count != 0 && fault_plan->group == 3")
    conflict_end = core.index(
        "fork_point = aqt_issuer_choreography_active_foreign_fork_point_locked(",
        conflict_start,
    )
    conflict_rejection = core[conflict_start:conflict_end]
    assert "&aqt_active_issuer_foreign_fork_plan" in conflict_rejection
    assert "memory_order_acquire" in conflict_rejection
    assert "!= NULL" in conflict_rejection
    assert "aqt_unlock_owner_list_or_fail_stop();" in conflict_rejection
    assert "aqt_free_issuer_projection(&prepared_roots);" in conflict_rejection
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_N_UNAVAILABLE_MESSAGE in conflict_rejection
    assert core.count("aqt_issuer_choreography_formal_expire_selected_records_proof_locked(") == 1
    assert core.count("aqt_issuer_choreography_formal_expire_normal_is_exact_locked(") >= 1
    assert core.count("aqt_issuer_choreography_formal_expire_cleanup_reconcile_locked(") == 2
    assert "AQT_CHOREOGRAPHY_FAULT_TRANSITION_CLEANUP_ATTEMPT" in core
    assert _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_N_UNAVAILABLE_MESSAGE in core
    for forbidden in (
        "aqt_issuer_choreography_sample_continuous_ns",
        "clock_gettime",
        "mach_continuous_time",
        "PyObject_Call",
        "PyObject_CallNoArgs",
        "aqt_run_issuer_external_projection_barrier",
        "aqt_issuer_external_projection_matches",
        "aqt_issuer_controller_durability",
        "openat(",
        "fstatat(",
        "readlinkat(",
        "getdirentries64(",
        "fsync(",
    ):
        assert forbidden not in core

    lock_marker = "aqt_lock_owner_list_or_fail_stop();"
    unlock_marker = "aqt_unlock_owner_list_or_fail_stop();"
    cursor = 0
    locked_count = 0
    while lock_marker in core[cursor:]:
        start = core.index(lock_marker, cursor)
        end = core.index(unlock_marker, start)
        locked = core[start:end]
        for forbidden in (
            "PyErr_",
            "PyObject_",
            "PyMem_",
            "Py_DECREF",
            "Py_XDECREF",
            "Py_CLEAR",
            "aqt_allocate_",
            "aqt_issuer_choreography_record_decref",
            "aqt_free_issuer_projection",
            "aqt_issuer_choreography_detached_records_release",
            "free(",
            "Py_BEGIN_ALLOW_THREADS",
            "Py_END_ALLOW_THREADS",
        ):
            assert forbidden not in locked
        locked_count += 1
        cursor = end + len(unlock_marker)
    assert locked_count >= 1
    assert core.rindex(unlock_marker) < core.rindex(
        "aqt_issuer_choreography_detached_records_release(&detached)"
    )


