@pytest.mark.parametrize(
    "mutation",
    [
        "request_list",
        "request_short",
        "post_effect_bool",
        "claim_authority",
        "selector_unknown",
        "selector_subclass",
        "swapped_authorities",
        "foreign_lease",
        "foreign_post_effect",
        "foreign_claim",
    ],
)
def test_native_issuer_checkpoint_i_preflight_and_crossbinding_reject_before_plan_take(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    mutation: str,
) -> None:
    _require_coherent_native_issuer_choreography_require_post_effect_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_i_source(
        test_module,
        tmp_path / f"checkpoint-i-preflight-{mutation}",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    request: object = values["request"]
    foreign: dict[str, object] | None = None
    foreign_projection: tuple[object, ...] | None = None
    foreign_socket: socket.socket | None = None

    class TextSubclass(str):
        pass

    if mutation == "request_list":
        request = list(cast(tuple[object, ...], request))
    elif mutation == "request_short":
        request = cast(tuple[object, ...], request)[:-1]
    elif mutation == "post_effect_bool":
        request = (values["lease"], True, values["claim"], "same")
    elif mutation == "claim_authority":
        request = (values["lease"], values["post_effect"], values["lease"], "same")
    elif mutation == "selector_unknown":
        request = (*cast(tuple[object, ...], request)[:-1], "unknown")
    elif mutation == "selector_subclass":
        request = (*cast(tuple[object, ...], request)[:-1], TextSubclass("same"))
    elif mutation == "swapped_authorities":
        request = (values["post_effect"], values["lease"], values["claim"], "same")
    else:
        foreign = _prepare_native_issuer_checkpoint_i_source(
            test_module,
            tmp_path / f"checkpoint-i-preflight-{mutation}-foreign",
        )
        foreign_projection = cast(tuple[object, ...], foreign["projection"])
        foreign_socket = cast(socket.socket, foreign["socket_owner"])
        if mutation == "foreign_lease":
            request = (foreign["lease"], values["post_effect"], values["claim"], "same")
        elif mutation == "foreign_post_effect":
            request = (values["lease"], foreign["post_effect"], values["claim"], "same")
        else:
            assert mutation == "foreign_claim"
            request = (values["lease"], values["post_effect"], foreign["claim"], "same")
    try:
        assert configure(9, 0, 1) is None
        with pytest.raises((RuntimeError, TypeError)) as retained:
            transition(values["shadow"], "require_post_effect", request)  # type: ignore[arg-type]
        if mutation == "request_list":
            assert type(retained.value) is TypeError
            assert str(retained.value) == (
                "native issuer choreography transition arguments are invalid"
            )
        elif mutation in {
            "request_short",
            "post_effect_bool",
            "claim_authority",
            "selector_subclass",
        }:
            assert type(retained.value) is TypeError
            assert str(retained.value) == (
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_I_REQUEST_INVALID_MESSAGE
            )
        else:
            assert type(retained.value) is RuntimeError
            assert (
                str(retained.value) == _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_I_UNAVAILABLE_MESSAGE
            )
        assert snapshot(values["shadow"]) == source
        _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)
        assert configure(-1, 0, 0) is None
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        if foreign_projection is not None and foreign_socket is not None:
            _close_native_issuer_projection_socket(foreign_projection, foreign_socket)
        _close_native_issuer_projection_socket(projection, socket_owner)


