def test_native_issuer_checkpoint_i_foreign_thread_and_inherited_child_reject_transactionally(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_require_post_effect_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_i_source(
        test_module,
        tmp_path / "checkpoint-i-thread-child",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    outcomes: list[BaseException | None] = []

    def foreign_operation() -> None:
        try:
            transition(values["shadow"], "require_post_effect", values["request"])
        except BaseException as error:
            outcomes.append(error)
        else:
            outcomes.append(None)

    read_descriptor = -1
    child_pid = -1
    try:
        assert configure(9, 0, 1) is None
        worker = threading.Thread(target=foreign_operation)
        worker.start()
        worker.join(timeout=5.0)
        assert not worker.is_alive()
        assert len(outcomes) == 1 and type(outcomes[0]) is RuntimeError
        assert snapshot(values["shadow"]) == values["source_state"]
        _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)
        assert configure(-1, 0, 0) is None

        if not hasattr(os, "fork"):
            return
        read_descriptor, write_descriptor = os.pipe()
        child_pid = os.fork()
        if child_pid == 0:  # pragma: no cover - asserted through parent pipe
            os.close(read_descriptor)
            rejected = False
            try:
                transition(values["shadow"], "require_post_effect", values["request"])
            except RuntimeError:
                rejected = True
            except BaseException:
                rejected = False
            os.write(write_descriptor, bytes((rejected,)))
            os.close(write_descriptor)
            os._exit(0 if rejected else 1)
        os.close(write_descriptor)
        ready, _, _ = select.select([read_descriptor], [], [], 5.0)
        if not ready:
            os.kill(child_pid, 9)
            os.waitpid(child_pid, 0)
            child_pid = -1
            raise AssertionError("forked Checkpoint-I operation did not terminate")
        assert os.read(read_descriptor, 1) == b"\x01"
        waited_pid, status = os.waitpid(child_pid, 0)
        child_pid = -1
        assert waited_pid > 0 and os.waitstatus_to_exitcode(status) == 0
        assert snapshot(values["shadow"]) == values["source_state"]
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        if child_pid > 0:
            os.kill(child_pid, 9)
            os.waitpid(child_pid, 0)
        if read_descriptor >= 0:
            os.close(read_descriptor)
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_checkpoint_i_close_and_owner_death_preserve_latest_live_state(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_require_post_effect_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    _activate, _burn, close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    values = _prepare_native_issuer_checkpoint_i_source(
        test_module,
        tmp_path / "checkpoint-i-close-owner-death",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    shadow_reference = weakref.ref(values["shadow"])
    try:
        assert transition(values["shadow"], "require_post_effect", values["request"]) is None
        committed = _assert_native_issuer_checkpoint_i_post_effect_armed_snapshot(
            snapshot,
            values,
            state_revision=cast(int, source[3]) + 1,
            expected_last=cast(int, source[9]),
            stored_action=True,
            lifecycle_revision=3,
        )
        intrinsic = tuple(
            snapshot(values[name]) for name in ("lease", "capability", "claim", "post_effect")
        )
        with pytest.raises(RuntimeError):
            close(values["shadow"])
        burned = list(committed)
        burned[1] = 4
        burned[8] = False
        assert snapshot(values["shadow"]) == tuple(burned)
        assert (
            tuple(
                snapshot(values[name]) for name in ("lease", "capability", "claim", "post_effect")
            )
            == intrinsic
        )
        owner_dead_revision = cast(int, committed[3]) + 1
        values["shadow"] = None
        gc.collect()
        assert shadow_reference() is None
        for name in ("lease", "capability", "claim", "post_effect"):
            assert cast(tuple[object, ...], snapshot(values[name]))[5:7] == (
                "owner_dead",
                owner_dead_revision,
            )
        contender = test_module._test_create_inert_topology_observation_issuer_shadow()
        assert _activate(contender, projection) is None
        assert close(contender) is None
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


