def test_native_issuer_checkpoint_j_preparation_parser_and_crossbinding_are_exact(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_begin_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _prepare_authority, prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_i_source(
        test_module,
        tmp_path / "checkpoint-j-preparation-validation",
    )
    foreign = _prepare_native_issuer_checkpoint_i_source(
        test_module,
        tmp_path / "checkpoint-j-preparation-validation-foreign",
    )
    projection = cast(tuple[object, ...], values["projection"])
    foreign_projection = cast(tuple[object, ...], foreign["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    foreign_socket_owner = cast(socket.socket, foreign["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])

    class TextSubclass(str):
        pass

    try:
        malformed = (
            (),
            (values["claim"],),
            (values["claim"], "success"),
            (values["claim"], "pending", "same"),
            (values["claim"], "success", "unknown"),
            (values["claim"], TextSubclass("success"), "same"),
            (values["claim"], "success", TextSubclass("same")),
            (values["claim"], "success", "same", None),
        )
        for payload in malformed:
            with pytest.raises(TypeError) as retained:
                prepare_witness(values["shadow"], "controller_checkpoint", payload)
            assert str(retained.value) == (
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_J_PAYLOAD_INVALID_MESSAGE
            )
            assert snapshot(values["shadow"]) == source
        with pytest.raises(RuntimeError) as retained:
            prepare_witness(
                values["shadow"],
                "controller_checkpoint",
                (foreign["claim"], "success", "same"),
            )
        assert str(retained.value) == (
            _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_J_PREPARATION_UNAVAILABLE_MESSAGE
        )
        assert snapshot(values["shadow"]) == source
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)
        _close_native_issuer_projection_socket(foreign_projection, foreign_socket_owner)


def test_native_issuer_checkpoint_j_transition_preflight_preserves_armed_plan(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_begin_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_j_source(
        test_module,
        tmp_path / "checkpoint-j-transition-preflight",
        outcome="success",
        selector="same",
    )
    foreign = _prepare_native_issuer_checkpoint_j_source(
        test_module,
        tmp_path / "checkpoint-j-transition-preflight-foreign",
        outcome="success",
        selector="same",
    )
    projection = cast(tuple[object, ...], values["projection"])
    foreign_projection = cast(tuple[object, ...], foreign["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    foreign_socket_owner = cast(socket.socket, foreign["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    request = cast(tuple[object, ...], values["request"])

    class TextSubclass(str):
        pass

    try:
        assert configure(9, 0, 1) is None
        with pytest.raises(TypeError) as retained:
            transition(values["shadow"], "begin_controller", [])
        assert str(retained.value) == (
            "native issuer choreography transition arguments are invalid"
        )
        assert snapshot(values["shadow"]) == source
        _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)

        malformed_requests = (
            request[:-1],
            (*request, None),
            (request[0], request[1], request[2], object()),
            (request[0], request[1], request[2], TextSubclass("same")),
        )
        for malformed in malformed_requests:
            with pytest.raises(TypeError) as retained:
                transition(values["shadow"], "begin_controller", malformed)
            assert str(retained.value) == (
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_J_REQUEST_INVALID_MESSAGE
            )
            assert snapshot(values["shadow"]) == source
            _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)

        for crossbound in (
            (foreign["post_effect"], request[1], request[2], request[3]),
            (request[0], foreign["claim"], request[2], request[3]),
            (request[0], request[1], foreign["controller_checkpoint"], request[3]),
            (*request[:-1], "sample"),
            (*request[:-1], "unknown"),
        ):
            with pytest.raises(RuntimeError) as retained:
                transition(values["shadow"], "begin_controller", crossbound)
            assert (
                str(retained.value) == _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_J_UNAVAILABLE_MESSAGE
            )
            assert snapshot(values["shadow"]) == source
            _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)

        _assert_native_issuer_choreography_fault(
            lambda: transition(values["shadow"], "begin_controller", request),
            0,
        )
        _assert_native_issuer_checkpoint_j_terminal_snapshot(
            snapshot,
            values,
            phase="post_effect_unconfirmed",
            state_revision=cast(int, source[3]) + 1,
            expected_last=cast(int, source[9]),
            controller_checkpoint_in_state=False,
        )
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        _close_native_issuer_projection_socket(projection, socket_owner)
        _close_native_issuer_projection_socket(foreign_projection, foreign_socket_owner)


