@pytest.mark.parametrize(
    ("point", "outcome", "selector", "phase", "checkpoint_in_state", "burned"),
    [
        (6, "success", "same", "post_effect_consuming", True, False),
        (6, "failure", "same", "post_effect_consuming", True, True),
        (6, "success", "action_deadline", "post_effect_armed", False, False),
        (6, "success", "rollback", "post_effect_unconfirmed", False, False),
        (6, "failure", "retention_deadline", "expired", False, False),
        (7, "success", "same", "post_effect_unconfirmed", True, False),
        (7, "failure", "same", "post_effect_unconfirmed", True, True),
        (7, "success", "action_deadline", "post_effect_armed", False, False),
        (7, "success", "rollback", "post_effect_unconfirmed", False, False),
        (7, "failure", "retention_deadline", "expired", False, False),
    ],
)
def test_native_issuer_checkpoint_j_foreign_fork_validates_candidates_and_targets(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    point: int,
    outcome: str,
    selector: str,
    phase: str,
    checkpoint_in_state: bool,
    burned: bool,
) -> None:
    _require_coherent_native_issuer_choreography_begin_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    configure_fork, finish_fork = _native_issuer_foreign_fork_hooks(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_j_source(
        test_module,
        tmp_path / f"checkpoint-j-fork-{point}-{outcome}-{selector}-{burned}",
        outcome=outcome,
        selector=selector,
        burned=burned,
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    fork_finished = False
    try:
        assert configure_fork(values["shadow"], point) is None
        if point == 6 and phase == "post_effect_consuming":
            assert transition(values["shadow"], "begin_controller", values["request"]) is None
        else:
            with pytest.raises(RuntimeError) as retained:
                transition(values["shadow"], "begin_controller", values["request"])
            expected_message = (
                _NATIVE_ISSUER_CHOREOGRAPHY_FAILURE_MESSAGE
                if point == 7 and selector == "same"
                else _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_J_UNAVAILABLE_MESSAGE
            )
            assert str(retained.value) == expected_message
        if phase == "post_effect_consuming":
            _assert_native_issuer_checkpoint_j_post_effect_consuming_snapshot(
                snapshot,
                values,
                state_revision=cast(int, source[3]) + 1,
                expected_last=cast(int, values["controller_checkpoint_observed"]),
                install_revision=cast(int, source[3]) + 1,
            )
        else:
            target_revision = cast(int, source[3]) + (2 if point == 7 and selector == "same" else 1)
            _assert_native_issuer_checkpoint_j_terminal_snapshot(
                snapshot,
                values,
                phase=phase,
                state_revision=target_revision,
                expected_last=(
                    cast(int, values["controller_checkpoint_observed"])
                    if point == 7 and selector == "same"
                    else cast(int, source[9])
                ),
                controller_checkpoint_in_state=checkpoint_in_state,
            )
        expected_outer = (
            _native_issuer_active_snapshot(projection)
            if point == 6 and phase == "post_effect_consuming" and not burned
            else _native_issuer_explicit_burned_snapshot(projection)
        )
        assert test_module._test_topology_observation_issuer_shadow_state(values["shadow"]) == (
            expected_outer
        )
        _assert_native_issuer_foreign_fork_result(finish_fork(), point)
        fork_finished = True
    finally:
        if not fork_finished:
            with suppress(RuntimeError):
                finish_fork()
        _close_native_issuer_projection_socket(projection, socket_owner)


