def test_native_issuer_checkpoint_k_preparation_parser_disposition_and_crossbinding_are_exact(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_confirm_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _prepare_authority, prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_k_source(
        test_module,
        tmp_path / "checkpoint-k-preparation-validation",
    )
    foreign = _prepare_native_issuer_checkpoint_k_source(
        test_module,
        tmp_path / "checkpoint-k-preparation-validation-foreign",
    )
    projection = cast(tuple[object, ...], values["projection"])
    foreign_projection = cast(tuple[object, ...], foreign["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    foreign_socket = cast(socket.socket, foreign["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    payload = cast(tuple[object, ...], values["controller_receipt_payload"])

    class TextSubclass(str):
        pass

    malformed = (
        payload[:-1],
        (*payload, None),
        (*payload[:2], "not-a-uuid4", *payload[3:]),
        (*payload[:3], "A" * 64, *payload[4:]),
        (*payload[:7], True, *payload[8:]),
        (*payload[:8], "future-contract", *payload[9:]),
        (*payload[:9], "recovery_required", *payload[10:]),
        (*payload[:10], "sequence_2_unconfirmed", *payload[11:]),
        (*payload[:12], "7" * 64),
        (*payload[:12], "A" * 64),
        (*payload[:12], False),
        (*payload[:8], TextSubclass(cast(str, payload[8])), *payload[9:]),
    )
    try:
        for candidate in malformed:
            with pytest.raises(TypeError) as retained:
                prepare_witness(values["shadow"], "controller_receipt", candidate)
            assert str(retained.value) == (
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_K_PAYLOAD_INVALID_MESSAGE
            )
            assert snapshot(values["shadow"]) == source
        for crossbound in (
            (foreign["claim"], *payload[1:]),
            (payload[0], foreign["controller_checkpoint"], *payload[2:]),
        ):
            with pytest.raises(RuntimeError) as retained:
                prepare_witness(values["shadow"], "controller_receipt", crossbound)
            assert str(retained.value) == (
                _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_K_PREPARATION_UNAVAILABLE_MESSAGE
            )
            assert snapshot(values["shadow"]) == source
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)
        _close_native_issuer_projection_socket(foreign_projection, foreign_socket)


