@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", ["store", "return"])
def test_native_issuer_checkpoint_k_lost_none_return_preserves_prepared_confirmation(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    _require_coherent_native_issuer_choreography_confirm_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_k_source(
        test_module,
        tmp_path / f"checkpoint-k-lost-{failure_type.__name__}-{boundary}",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])

    def transition_at_boundary() -> object:
        result = transition(values["shadow"], "confirm_controller", values["request"])
        return result

    offset = _instruction_offset(
        transition_at_boundary,
        opname="STORE_FAST" if boundary == "store" else "RETURN_VALUE",
        argval="result" if boundary == "store" else None,
    )
    interruption: BaseException = (
        SystemExit(263) if failure_type is SystemExit else KeyboardInterrupt()
    )
    tool_id = _enable_instruction_interrupt(
        transition_at_boundary,
        offset,
        tool_name=f"native-issuer-checkpoint-k-{boundary}",
        interruption=interruption,
    )
    try:
        with pytest.raises(failure_type) as retained:
            transition_at_boundary()
        assert retained.value is interruption
    finally:
        _disable_instruction_interrupt(tool_id, transition_at_boundary)
    try:
        _assert_native_issuer_checkpoint_k_post_effect_confirmed_snapshot(
            snapshot,
            values,
            state_revision=cast(int, source[3]) + 1,
            expected_last=cast(int, source[9]),
            install_revision=cast(int, source[3]) + 1,
        )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


@pytest.mark.parametrize("boundary", ["initial", "terminal"])
def test_native_issuer_checkpoint_k_external_proof_failure_burns_exact_target(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    boundary: str,
) -> None:
    _require_coherent_native_issuer_choreography_confirm_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    configure_barrier = cast(
        Callable[[int, int], None],
        getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME),
    )
    values = _prepare_native_issuer_checkpoint_k_source(
        test_module,
        tmp_path / f"checkpoint-k-proof-{boundary}",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    replacement_socket: socket.socket | None = None
    backup_paths: tuple[Path, ...] = ()
    child_pid = -1
    ready_write = -1
    resume_read = -1
    child_reaped = False
    try:
        if boundary == "initial":
            replacement_socket, backup_paths = _mutate_native_issuer_external_identity(
                projection,
                "executable_identity",
            )
        else:
            child_pid, ready_write, resume_read, backup_paths = (
                _fork_native_issuer_external_projection_mutator(
                    projection,
                    "executable_identity",
                )
            )
            assert configure_barrier(ready_write, resume_read) is None
        with pytest.raises(OSError):
            transition(values["shadow"], "confirm_controller", values["request"])
        if boundary == "terminal":
            assert (
                _reap_native_issuer_external_projection_mutator(
                    child_pid,
                    ready_write,
                    resume_read,
                )
                == 0
            )
            child_reaped = True
            ready_write = -1
            resume_read = -1
        _assert_native_issuer_checkpoint_k_unconfirmed_snapshot(
            snapshot,
            values,
            state_revision=cast(int, source[3]) + (2 if boundary == "terminal" else 1),
            expected_last=cast(int, source[9]),
            committed=boundary == "terminal",
        )
        assert test_module._test_topology_observation_issuer_shadow_state(values["shadow"]) == (
            _native_issuer_explicit_burned_snapshot(projection)
        )
    finally:
        if child_pid > 0 and not child_reaped:
            assert (
                _reap_native_issuer_external_projection_mutator(
                    child_pid,
                    ready_write,
                    resume_read,
                )
                == 0
            )
        if replacement_socket is not None:
            replacement_socket.close()
        _close_native_issuer_projection_socket(projection, socket_owner)
        for backup_path in backup_paths:
            with suppress(FileNotFoundError):
                backup_path.unlink()


