@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", ["store", "return"])
def test_native_issuer_checkpoint_k_lost_prepared_return_preserves_source_and_existing_candidate(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    _require_coherent_native_issuer_choreography_confirm_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _prepare_authority, prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_k_source(
        test_module,
        tmp_path / f"checkpoint-k-lost-prepared-{failure_type.__name__}-{boundary}",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    existing = snapshot(values["controller_receipt"])

    def prepare_at_boundary() -> object:
        result = prepare_witness(
            values["shadow"],
            "controller_receipt",
            values["controller_receipt_payload"],
        )
        return result

    offset = _instruction_offset(
        prepare_at_boundary,
        opname="STORE_FAST" if boundary == "store" else "RETURN_VALUE",
        argval="result" if boundary == "store" else None,
    )
    interruption: BaseException = (
        SystemExit(269) if failure_type is SystemExit else KeyboardInterrupt()
    )
    tool_id = _enable_instruction_interrupt(
        prepare_at_boundary,
        offset,
        tool_name=f"native-issuer-checkpoint-k-prepared-{boundary}",
        interruption=interruption,
    )
    try:
        with pytest.raises(failure_type) as retained:
            prepare_at_boundary()
        assert retained.value is interruption
    finally:
        _disable_instruction_interrupt(tool_id, prepare_at_boundary)
    try:
        assert snapshot(values["shadow"]) == source
        assert snapshot(values["controller_receipt"]) == existing
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


