@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", ["store", "return"])
def test_native_issuer_checkpoint_l_lost_none_return_preserves_durable_binding(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    _require_coherent_native_issuer_choreography_attest_controller_durable_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    configure_barrier = cast(
        Callable[[int, int], None],
        getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME),
    )
    values = _prepare_native_issuer_checkpoint_l_source(
        test_module,
        tmp_path / f"checkpoint-l-lost-{failure_type.__name__}-{boundary}",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["prepared_state"])
    receipt_payload = cast(tuple[object, ...], values["controller_receipt_payload"])
    actor: tuple[int, int, int, int] | None = None
    actor_reaped = False

    def transition_at_boundary() -> object:
        result = transition(
            values["shadow"],
            "attest_controller_durable",
            values["request"],
        )
        return result

    try:
        actor = _fork_native_issuer_checkpoint_l_commit_publisher(
            cast(str, values["artifact_directory"]),
            contract_version=cast(str, receipt_payload[8]),
            outcome_sha256=cast(str, values["outcome_sha256"]),
        )
        assert configure_barrier(actor[1], actor[2]) is None
        offset = _instruction_offset(
            transition_at_boundary,
            opname="STORE_FAST" if boundary == "store" else "RETURN_VALUE",
            argval="result" if boundary == "store" else None,
        )
        interruption: BaseException = (
            SystemExit(271) if failure_type is SystemExit else KeyboardInterrupt()
        )
        tool_id = _enable_instruction_interrupt(
            transition_at_boundary,
            offset,
            tool_name=f"native-issuer-checkpoint-l-{boundary}",
            interruption=interruption,
        )
        try:
            with pytest.raises(failure_type) as retained:
                transition_at_boundary()
            assert retained.value is interruption
        finally:
            _disable_instruction_interrupt(tool_id, transition_at_boundary)
        _reap_native_issuer_checkpoint_l_commit_publisher(
            actor,
            expected_published=True,
        )
        actor_reaped = True
        binding_sha256 = _native_issuer_checkpoint_l_expected_binding_sha256(snapshot, values)
        _assert_native_issuer_checkpoint_l_durable_snapshot(
            snapshot,
            values,
            state_revision=cast(int, source[3]) + 1,
            receipt_status_revision=cast(int, source[3]) + 1,
            durability_binding_sha256=binding_sha256,
        )
    finally:
        if actor is not None and not actor_reaped:
            _reap_native_issuer_checkpoint_l_commit_publisher(
                actor,
                expected_published=True,
            )
        _close_native_issuer_projection_socket(projection, socket_owner)


