@pytest.mark.parametrize(
    "malformed_kind",
    [
        "tuple_subclass",
        "empty",
        "short",
        "long",
        "wrong_post_effect",
        "wrong_checkpoint",
        "wrong_receipt",
    ],
)
def test_native_issuer_checkpoint_m_malformed_payload_matrix_is_exact_and_transactional(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    malformed_kind: str,
) -> None:
    _require_coherent_native_issuer_choreography_abandon_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_m_source(
        test_module,
        tmp_path / f"checkpoint-m-malformed-{malformed_kind}",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    expected = _native_issuer_checkpoint_m_snapshot_bundle(test_module, snapshot, values)

    class TupleSubclass(tuple[object, ...]):
        pass

    exact = cast(tuple[object, ...], values["request"])
    malformed: object
    if malformed_kind == "tuple_subclass":
        malformed = TupleSubclass(exact)
    elif malformed_kind == "empty":
        malformed = ()
    elif malformed_kind == "short":
        malformed = exact[:2]
    elif malformed_kind == "long":
        malformed = (*exact, None)
    elif malformed_kind == "wrong_post_effect":
        malformed = (values["controller_receipt"], *exact[1:])
    elif malformed_kind == "wrong_checkpoint":
        malformed = (exact[0], values["post_effect"], exact[2])
    else:
        assert malformed_kind == "wrong_receipt"
        malformed = (*exact[:2], values["post_effect"])
    try:
        with pytest.raises(TypeError) as retained:
            transition(
                values["shadow"],
                "abandon_controller",
                cast(tuple[object, ...], malformed),
            )
        expected_message = (
            "native issuer choreography transition arguments are invalid"
            if malformed_kind == "tuple_subclass"
            else _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_M_REQUEST_INVALID_MESSAGE
        )
        assert str(retained.value) == expected_message
        assert (
            _native_issuer_checkpoint_m_snapshot_bundle(test_module, snapshot, values) == expected
        )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


