    actor: tuple[int, int, int, int] | None = None
    actor_reaped = False
    try:
        actor = _fork_native_issuer_checkpoint_l_commit_publisher(
            cast(str, values["artifact_directory"]),
            contract_version=cast(str, receipt_payload[8]),
            outcome_sha256=cast(str, values["outcome_sha256"]),
        )
        assert configure_barrier(actor[1], actor[2]) is None
        assert configure(10, 0, 1) is None
        _assert_native_issuer_choreography_fault(
            lambda: transition(
                values["shadow"],
                "attest_controller_durable",
                values["request"],
            ),
            0,
        )
        _reap_native_issuer_checkpoint_l_commit_publisher(actor, expected_published=True)
        actor_reaped = True
        binding_sha256 = _native_issuer_checkpoint_l_expected_binding_sha256(snapshot, values)
        safe = _assert_native_issuer_checkpoint_l_durable_snapshot(
            snapshot,
            values,
            state_revision=cast(int, prepared[3]) + 2,
            receipt_status_revision=cast(int, prepared[3]) + 1,
            durability_binding_sha256=binding_sha256,
        )
        request = (
            values["post_effect"],
            values["controller_checkpoint"],
            values["controller_receipt"],
        )
        with pytest.raises(RuntimeError) as retained:
            transition(values["shadow"], "abandon_controller", request)
        assert str(retained.value) == _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_M_UNAVAILABLE_MESSAGE
        assert snapshot(values["shadow"]) == safe
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        if actor is not None and not actor_reaped:
            _reap_native_issuer_checkpoint_l_commit_publisher(actor, expected_published=True)
        _close_native_issuer_projection_socket(projection, socket_owner)


