@pytest.mark.parametrize("invalid_source", ["prepared", "burned_success"])
def test_native_issuer_checkpoint_m_foreign_fork_rejects_non_source_and_preserves_plan(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    invalid_source: str,
) -> None:
    _require_coherent_native_issuer_choreography_abandon_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _activate, burn, _close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    configure_fork, finish_fork = _native_issuer_foreign_fork_hooks(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    valid = _prepare_native_issuer_checkpoint_m_source(
        test_module,
        tmp_path / f"checkpoint-m-fork-valid-{invalid_source}",
        outcome="failure",
    )
    if invalid_source == "prepared":
        invalid = _prepare_native_issuer_checkpoint_l_source(
            test_module,
            tmp_path / "checkpoint-m-fork-invalid-prepared",
            outcome="failure",
        )
    else:
        invalid = _prepare_native_issuer_checkpoint_m_source(
            test_module,
            tmp_path / "checkpoint-m-fork-invalid-burned-success",
            outcome="success",
        )
        assert burn(invalid["shadow"]) is None
    valid_projection = cast(tuple[object, ...], valid["projection"])
    valid_socket = cast(socket.socket, valid["socket_owner"])
    invalid_projection = cast(tuple[object, ...], invalid["projection"])
    invalid_socket = cast(socket.socket, invalid["socket_owner"])
    valid_source = snapshot(valid["shadow"])
    invalid_state = snapshot(invalid["shadow"])
    plan_cancelled = False
    try:
        assert configure_fork(valid["shadow"], 6) is None
        with pytest.raises(RuntimeError) as retained:
            configure_fork(invalid["shadow"], 6)
        expected_message = (
            "native issuer foreign-fork interposition is already armed"
            if invalid_source == "prepared"
            or _native_issuer_choreography_formal_force_revoke_source_is_coherent()
            else "native issuer shadow cannot arm foreign-fork interposition"
        )
        assert str(retained.value) == expected_message
        with pytest.raises(RuntimeError):
            configure_fork(valid["shadow"], 6)
        assert snapshot(valid["shadow"]) == valid_source
        assert snapshot(invalid["shadow"]) == invalid_state
        with pytest.raises(RuntimeError):
            finish_fork()
        plan_cancelled = True
    finally:
        if not plan_cancelled:
            with suppress(RuntimeError):
                finish_fork()
        _close_native_issuer_projection_socket(valid_projection, valid_socket)
        _close_native_issuer_projection_socket(invalid_projection, invalid_socket)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", ["store", "return"])
def test_native_issuer_checkpoint_m_lost_none_return_preserves_replayable_source(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    _require_coherent_native_issuer_choreography_abandon_controller_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_m_source(
        test_module,
        tmp_path / f"checkpoint-m-lost-{failure_type.__name__}-{boundary}",
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    expected = _native_issuer_checkpoint_m_snapshot_bundle(test_module, snapshot, values)

    def transition_at_boundary() -> object:
        result = transition(values["shadow"], "abandon_controller", values["request"])
        return result

    offset = _instruction_offset(
        transition_at_boundary,
        opname="STORE_FAST" if boundary == "store" else "RETURN_VALUE",
        argval="result" if boundary == "store" else None,
    )
    interruption: BaseException = (
        SystemExit(273) if failure_type is SystemExit else KeyboardInterrupt()
    )
    tool_id = _enable_instruction_interrupt(
        transition_at_boundary,
        offset,
        tool_name=f"native-issuer-checkpoint-m-{boundary}",
        interruption=interruption,
    )
    try:
        with pytest.raises(failure_type) as retained:
            transition_at_boundary()
        assert retained.value is interruption
    finally:
        _disable_instruction_interrupt(tool_id, transition_at_boundary)
    try:
        assert (
            _native_issuer_checkpoint_m_snapshot_bundle(test_module, snapshot, values) == expected
        )
        assert transition(values["shadow"], "abandon_controller", values["request"]) is None
        assert (
            _native_issuer_checkpoint_m_snapshot_bundle(test_module, snapshot, values) == expected
        )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


