def test_native_issuer_checkpoint_o_malformed_payload_preserves_armed_fork_plan(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_formal_force_revoke_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    configure_fork, finish_fork = _native_issuer_foreign_fork_hooks(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_o_source(
        test_module,
        tmp_path / "checkpoint-o-malformed-fork-preserved",
        ("armed", False, False, "ordinary"),
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    expected = _native_issuer_checkpoint_o_snapshot_bundle(test_module, snapshot, values)
    fork_finished = False
    try:
        assert configure_fork(values["shadow"], 6) is None
        with pytest.raises(TypeError) as retained:
            transition(values["shadow"], "formal_force_revoke", ("unexpected",))
        assert (
            str(retained.value) == _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_O_REQUEST_INVALID_MESSAGE
        )
        assert _native_issuer_checkpoint_o_snapshot_bundle(test_module, snapshot, values) == (
            expected
        )
        with pytest.raises(RuntimeError) as retained:
            configure_fork(values["shadow"], 6)
        assert str(retained.value) == "native issuer foreign-fork interposition is already armed"
        assert transition(values["shadow"], "formal_force_revoke", ()) is None
        _assert_native_issuer_checkpoint_o_terminal_snapshot(
            test_module,
            snapshot,
            values,
            terminal_revision=cast(int, source[3]) + 1,
            publication_revision=cast(int, source[3]) + 1,
            hard=False,
        )
        _assert_native_issuer_foreign_fork_result(finish_fork(), 6)
        fork_finished = True
    finally:
        if not fork_finished:
            with suppress(RuntimeError):
                finish_fork()
        _close_native_issuer_projection_socket(projection, socket_owner)


