def test_native_issuer_checkpoint_o_foreign_thread_rejects_before_plan_take(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_formal_force_revoke_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_o_source(
        test_module,
        tmp_path / "checkpoint-o-foreign-thread",
        ("post_effect_armed", True, True, "ordinary"),
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    expected = _native_issuer_checkpoint_o_snapshot_bundle(test_module, snapshot, values)
    observed: list[BaseException] = []

    def foreign_operation() -> None:
        try:
            transition(values["shadow"], "formal_force_revoke", ())
        except BaseException as error:
            observed.append(error)

    try:
        assert configure(9, 0, 1) is None
        worker = threading.Thread(target=foreign_operation)
        worker.start()
        worker.join()
        assert len(observed) == 1 and type(observed[0]) is RuntimeError
        assert str(observed[0]) == _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_O_UNAVAILABLE_MESSAGE
        assert _native_issuer_checkpoint_o_snapshot_bundle(test_module, snapshot, values) == (
            expected
        )
        _assert_native_issuer_choreography_fault_plan_is_still_configured(configure, 9, 0)
    finally:
        with suppress(RuntimeError):
            configure(-1, 0, 0)
        _close_native_issuer_projection_socket(projection, socket_owner)


@pytest.mark.parametrize(
    "source_row",
    _NATIVE_ISSUER_CHOREOGRAPHY_CHECKPOINT_O_RUNTIME_SOURCE_ROWS,
)
def test_native_issuer_checkpoint_o_live_state_close_preserves_every_source_then_revokes(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    source_row: tuple[object, ...],
) -> None:
    _require_coherent_native_issuer_choreography_formal_force_revoke_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _activate, _burn, close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_o_source(
        test_module,
        tmp_path / f"checkpoint-o-close-{abs(hash(source_row))}",
        source_row,
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    before_handles = cast(dict[str, tuple[object, ...]], values["source_handle_snapshots"])
    try:
        with pytest.raises(
            RuntimeError,
            match="native issuer with live choreography State cannot be closed",
        ):
            close(values["shadow"])
        assert {
            name: snapshot(values[name])
            for name in _native_issuer_checkpoint_o_live_handle_names(values)
        } == before_handles
        source = cast(tuple[object, ...], snapshot(values["shadow"]))
        expected_source = list(cast(tuple[object, ...], values["source_state"]))
        expected_source[1] = 4
        expected_source[8] = False
        assert source == tuple(expected_source)
        assert test_module._test_topology_observation_issuer_shadow_state(
            values["shadow"]
        ) == _native_issuer_explicit_burned_snapshot(projection)
        values["source_state"] = source
        values["source_outer"] = _native_issuer_explicit_burned_snapshot(projection)
        assert transition(values["shadow"], "formal_force_revoke", ()) is None
        _assert_native_issuer_checkpoint_o_terminal_snapshot(
            test_module,
            snapshot,
            values,
            terminal_revision=cast(int, source[3]) + 1,
            publication_revision=cast(int, source[3]) + 1,
            hard=False,
        )
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


@pytest.mark.parametrize("receipt_mode", ["prepared", "durable"])
def test_native_issuer_checkpoint_o_controller_receipt_clears_with_exact_binding_mode(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    receipt_mode: str,
) -> None:
    _require_coherent_native_issuer_choreography_formal_force_revoke_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    transition = _native_issuer_choreography_transition_hook(test_module)
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_o_source(
        test_module,
        tmp_path / f"checkpoint-o-receipt-binding-{receipt_mode}",
        (
            "post_effect_confirmed",
            False,
            False,
            receipt_mode,
            "success",
            "phase6d-post-enrollment-start-retained-controller-outcome-v1",
            False,
        ),
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    before = cast(tuple[object, ...], snapshot(values["controller_receipt"]))
    try:
        assert cast(tuple[object, ...], before[7])[1] == receipt_mode
        assert transition(values["shadow"], "formal_force_revoke", ()) is None
        after = cast(tuple[object, ...], snapshot(values["controller_receipt"]))
        assert after[:5] == before[:5]
        assert after[5:7] == ("cleared", cast(int, source[3]) + 1)
        assert after[7:] == before[7:]
        summary = cast(tuple[object, ...], after[7])
        if receipt_mode == "prepared":
            assert summary[5] is None
        else:
            assert summary[5] == values["durability_binding_sha256"]
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_checkpoint_o_close_then_deallocation_retires_preserved_durable_source(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_choreography_formal_force_revoke_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    _activate, _burn, close, _validate, _configure_lifecycle = _native_issuer_lifecycle_hooks(
        test_module
    )
    _prepare_authority, _prepare_witness, _register, snapshot, _configure = (
        _native_issuer_choreography_register_hooks(test_module)
    )
    values = _prepare_native_issuer_checkpoint_o_source(
        test_module,
        tmp_path / "checkpoint-o-close-deallocate-durable",
        (
            "post_effect_confirmed",
            False,
            False,
            "durable",
            "success",
            "phase6d-post-enrollment-start-retained-controller-outcome-v2",
            True,
        ),
    )
    projection = cast(tuple[object, ...], values["projection"])
    socket_owner = cast(socket.socket, values["socket_owner"])
    source = cast(tuple[object, ...], values["source_state"])
    before = _native_issuer_checkpoint_o_snapshot_bundle(test_module, snapshot, values)
    binding_sha256 = cast(str, values["durability_binding_sha256"])
    try:
        with pytest.raises(
            RuntimeError,
            match="native issuer with live choreography State cannot be closed",
        ):
            close(values["shadow"])
        after_close = cast(tuple[object, ...], snapshot(values["shadow"]))
        assert after_close[1] == 4
        assert after_close[2:] == cast(tuple[object, ...], before[0])[2:]
        assert {
            name: snapshot(values[name])
            for name in _native_issuer_checkpoint_o_live_handle_names(values)
        } == dict(cast(tuple[tuple[str, tuple[object, ...]], ...], before[1]))
        shadow_reference = weakref.ref(values["shadow"])
        values["shadow"] = None
        gc.collect()
        assert shadow_reference() is None
        owner_dead = cast(tuple[object, ...], snapshot(values["controller_receipt"]))
        assert owner_dead[5:7] == ("owner_dead", cast(int, source[3]) + 1)
        assert cast(tuple[object, ...], owner_dead[7])[5] == binding_sha256
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


