    checkpoint_l = source_sha256 in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_ATTEST_CONTROLLER_DURABLE_OR_LATER_C_SHA256
    )
    checkpoint_e = source_sha256 in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_BINDER_TRANSITIONS_OR_LATER_C_SHA256
    )
    checkpoint_b = source_sha256 in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REGISTER_OR_LATER_C_SHA256
    )
    choreography_or_later = source_sha256 in (
        _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_C_SHA256
        | _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REGISTER_OR_LATER_C_SHA256
    )
    lifecycle_or_later = source_sha256 in (
        _COHERENT_NATIVE_ISSUER_LIFECYCLE_C_SHA256
        | _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_C_SHA256
        | _COHERENT_NATIVE_ISSUER_CHOREOGRAPHY_REGISTER_OR_LATER_C_SHA256
    )
    expected_hook_names = (
        (
            *_NATIVE_ISSUER_SHADOW_HOOK_NAMES,
            *_NATIVE_ISSUER_LIFECYCLE_HOOK_NAMES,
            _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME,
            *_NATIVE_ISSUER_FOREIGN_FORK_HOOK_NAMES,
            *(
                _NATIVE_ISSUER_CHOREOGRAPHY_TRANSITION_EXPORTED_HOOK_NAMES
                if checkpoint_c
                else _NATIVE_ISSUER_CHOREOGRAPHY_REGISTER_EXPORTED_HOOK_NAMES
                if checkpoint_b
                else ()
            ),
        )
        if lifecycle_or_later
        else _NATIVE_ISSUER_SHADOW_HOOK_NAMES
    )
    for name in expected_hook_names:
        hook = getattr(test_module, name)
