@pytest.mark.parametrize(
    "mutation",
    [
        "projection_list",
        "projection_short",
        "tag",
        "root_empty",
        "root_path",
        "root_noncanonical",
        "session_nonhex",
        "session_upperhex",
        "environment_list",
        "environment_missing_path",
        "environment_duplicate",
        "environment_foreign_key",
        "environment_empty_value",
        "environment_order",
        "environment_nul",
        "environment_sha_upperhex",
        "daemon_list",
        "daemon_context",
        "daemon_endpoint_syntax",
        "daemon_endpoint_crossbind",
        "daemon_id_empty",
        "executable_path",
        "executable_stat_bool",
        "executable_stat",
        "socket_stat_bool",
        "socket_stat",
    ],
)
def test_native_issuer_activation_projection_rejects_malformed_and_crossbound_roots(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    mutation: str,
) -> None:
    _require_coherent_native_issuer_lifecycle_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    create = test_module._test_create_inert_topology_observation_issuer_shadow
    state = test_module._test_topology_observation_issuer_shadow_state
    activate, _burn, close, _validate, _configure = _native_issuer_lifecycle_hooks(test_module)
    projection, socket_owner = _new_native_issuer_activation_projection(tmp_path / mutation)
    try:
        malformed: object
        if mutation == "projection_list":
            malformed = list(projection)
        elif mutation == "projection_short":
            malformed = projection[:-1]
        elif mutation == "tag":
            malformed = _tuple_with_item(projection, 0, "wrong-activation-tag")
        elif mutation == "root_empty":
            malformed = _tuple_with_item(projection, 1, "")
        elif mutation == "root_path":
            malformed = _tuple_with_item(projection, 1, Path(cast(str, projection[1])))
        elif mutation == "root_noncanonical":
            malformed = _tuple_with_item(projection, 1, f"{projection[1]}/.")
        elif mutation == "session_nonhex":
            malformed = _tuple_with_item(projection, 2, "g" * 64)
        elif mutation == "session_upperhex":
            malformed = _tuple_with_item(
                projection,
                2,
                "A" * 64,
            )
        elif mutation == "environment_list":
            malformed = _tuple_with_item(
                projection, 3, list(cast(tuple[object, ...], projection[3]))
            )
        elif mutation in {
            "environment_missing_path",
            "environment_duplicate",
            "environment_foreign_key",
            "environment_empty_value",
            "environment_order",
            "environment_nul",
        }:
            environment = cast(tuple[tuple[str, str], ...], tuple.__getitem__(projection, 3))
            if mutation == "environment_missing_path":
                changed_environment = (environment[0],)
            elif mutation == "environment_duplicate":
                changed_environment = (environment[0], environment[0], environment[1])
            elif mutation == "environment_foreign_key":
                changed_environment = (environment[0], ("USER", "hostile"), environment[1])
            elif mutation == "environment_empty_value":
                changed_environment = (environment[0], ("PATH", ""))
            elif mutation == "environment_order":
                changed_environment = tuple(reversed(environment))
            else:
                assert mutation == "environment_nul"
                changed_environment = (
                    environment[0],
                    ("PATH", f"{environment[1][1]}\x00"),
                )
            malformed = _tuple_with_item(projection, 3, changed_environment)
            malformed = _tuple_with_item(
                malformed,
                4,
                _native_issuer_environment_sha256(changed_environment),
            )
        elif mutation == "environment_sha_upperhex":
            malformed = _tuple_with_item(projection, 4, "A" * 64)
        elif mutation == "daemon_list":
            malformed = _tuple_with_item(
                projection,
                5,
                list(cast(tuple[object, ...], projection[5])),
            )
        elif mutation in {
            "daemon_context",
            "daemon_endpoint_syntax",
            "daemon_endpoint_crossbind",
            "daemon_id_empty",
        }:
            daemon = cast(tuple[object, ...], tuple.__getitem__(projection, 5))
            daemon_projection = projection
            if mutation == "daemon_context":
                changed_daemon = _tuple_with_item(daemon, 1, "invalid context")
            elif mutation == "daemon_endpoint_syntax":
                changed_endpoint = "unix:////tmp/invalid-daemon.sock"
                changed_daemon = _tuple_with_item(daemon, 2, changed_endpoint)
                environment = cast(
                    tuple[tuple[str, str], ...],
                    tuple.__getitem__(projection, 3),
                )
                changed_environment = (("DOCKER_HOST", changed_endpoint), environment[1])
                daemon_projection = _tuple_with_item(projection, 3, changed_environment)
                daemon_projection = _tuple_with_item(
                    daemon_projection,
                    4,
                    _native_issuer_environment_sha256(changed_environment),
                )
            elif mutation == "daemon_endpoint_crossbind":
                changed_daemon = _tuple_with_item(
                    daemon,
                    2,
                    "unix:///tmp/foreign-daemon.sock",
                )
            else:
                assert mutation == "daemon_id_empty"
                changed_daemon = _tuple_with_item(daemon, 3, "")
            malformed = _tuple_with_item(
                daemon_projection,
                5,
                changed_daemon,
            )
        elif mutation == "executable_path":
            malformed = _tuple_with_item(projection, 6, Path(cast(str, projection[6])))
        elif mutation in {"executable_stat_bool", "executable_stat"}:
            executable_stat = cast(tuple[object, ...], tuple.__getitem__(projection, 7))
            malformed = _tuple_with_item(
                projection,
                7,
                _tuple_with_item(
                    executable_stat,
                    1,
                    True
                    if mutation == "executable_stat_bool"
                    else cast(int, tuple.__getitem__(executable_stat, 1)) + 1,
                ),
            )
        else:
            assert mutation in {"socket_stat_bool", "socket_stat"}
            socket_stat = cast(tuple[object, ...], tuple.__getitem__(projection, 8))
            malformed = _tuple_with_item(
                projection,
                8,
                _tuple_with_item(
                    socket_stat,
                    1,
                    True
                    if mutation == "socket_stat_bool"
                    else cast(int, tuple.__getitem__(socket_stat, 1)) + 1,
                ),
            )
        shadow = create()
        if mutation in {"executable_stat", "socket_stat"}:
            with pytest.raises(OSError):
                activate(shadow, malformed)
            assert state(shadow) == _native_issuer_failed_burned_snapshot(3)
            assert close(shadow) is None
            assert state(shadow) == _native_issuer_closed_snapshot(4)
            shadow = create()
        else:
            with pytest.raises((RuntimeError, TypeError, ValueError)):
                activate(shadow, malformed)
            assert state(shadow) == _NATIVE_ISSUER_LIFECYCLE_INERT_SNAPSHOT
        assert activate(shadow, projection) is None
        assert close(shadow) is None
        assert state(shadow) == _native_issuer_closed_snapshot(4)
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


