@pytest.mark.parametrize("operation", ["activate", "validate"])
@pytest.mark.parametrize(
    "mutation",
    ["executable_mode", "executable_identity", "socket_mode", "socket_identity"],
)
def test_native_issuer_terminal_external_projection_barrier_rejects_live_swap(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    operation: str,
    mutation: str,
) -> None:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    _require_coherent_native_issuer_lifecycle_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    create = test_module._test_create_inert_topology_observation_issuer_shadow
    state = test_module._test_topology_observation_issuer_shadow_state
    activate, _burn, close, validate, _configure = _native_issuer_lifecycle_hooks(test_module)
    configure_barrier = getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME)
    assert type(configure_barrier) is BuiltinFunctionType
    projection, socket_owner = _new_native_issuer_activation_projection(
        tmp_path / f"terminal-{operation}-{mutation}"
    )
    child_pid = -1
    ready_write = -1
    resume_read = -1
    child_reaped = False
    backup_paths: tuple[Path, ...] = ()
    try:
        shadow = create()
        if operation == "validate":
            assert activate(shadow, projection) is None
        else:
            assert operation == "activate"
        child_pid, ready_write, resume_read, backup_paths = (
            _fork_native_issuer_external_projection_mutator(projection, mutation)
        )
        assert configure_barrier(ready_write, resume_read) is None
        with pytest.raises(OSError):
            if operation == "activate":
                activate(shadow, projection)
            else:
                validate(shadow)
        child_status = _reap_native_issuer_external_projection_mutator(
            child_pid,
            ready_write,
            resume_read,
        )
        child_reaped = True
        ready_write = -1
        resume_read = -1
        assert child_status == 0
        if operation == "activate":
            assert state(shadow) == _native_issuer_failed_burned_snapshot(3)
            expected_closed_revision = 4
        else:
            assert state(shadow) == _native_issuer_explicit_burned_snapshot(projection)
            expected_closed_revision = 5
        stale_ready_read, stale_ready_write = os.pipe()
        stale_resume_read, stale_resume_write = os.pipe()
        try:
            assert configure_barrier(stale_ready_write, stale_resume_read) is None
            assert close(shadow) is None
            ready, _, _ = select.select([stale_ready_read], [], [], 0.0)
            assert ready == []
        finally:
            for descriptor in (
                stale_ready_read,
                stale_ready_write,
                stale_resume_read,
                stale_resume_write,
            ):
                with suppress(OSError):
                    os.close(descriptor)
        assert state(shadow) == _native_issuer_closed_snapshot(expected_closed_revision)

        repaired_projection = _repair_native_issuer_external_projection(
            projection,
            mutation,
        )
        fresh = create()
        assert activate(fresh, repaired_projection) is None
        assert state(fresh) == _native_issuer_active_snapshot(repaired_projection)
        assert close(fresh) is None
    finally:
        if child_pid > 0 and not child_reaped:
            child_status = _reap_native_issuer_external_projection_mutator(
                child_pid,
                ready_write,
                resume_read,
            )
            child_reaped = True
            assert child_status == 0
        _close_native_issuer_projection_socket(projection, socket_owner)
        for backup_path in backup_paths:
            with suppress(FileNotFoundError):
                backup_path.unlink()


