def test_native_issuer_external_projection_barrier_duplicate_is_atomic_and_stale_clears(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_lifecycle_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    create = test_module._test_create_inert_topology_observation_issuer_shadow
    state = test_module._test_topology_observation_issuer_shadow_state
    activate, burn, close, _validate, _configure = _native_issuer_lifecycle_hooks(test_module)
    configure_barrier = getattr(test_module, _NATIVE_ISSUER_EXTERNAL_BARRIER_HOOK_NAME)
    projection, socket_owner = _new_native_issuer_activation_projection(
        tmp_path / "barrier-transaction"
    )
    first_ready_read, first_ready_write = os.pipe()
    first_resume_read, first_resume_write = os.pipe()
    second_ready_read, second_ready_write = os.pipe()
    second_resume_read, second_resume_write = os.pipe()
    try:
        shadow = create()
        assert activate(shadow, projection) is None
        assert configure_barrier(first_ready_write, first_resume_read) is None
        with pytest.raises(RuntimeError, match="barrier is unavailable"):
            configure_barrier(second_ready_write, second_resume_read)
        assert burn(shadow) is None
        assert state(shadow) == _native_issuer_explicit_burned_snapshot(projection)
        ready, _, _ = select.select([first_ready_read, second_ready_read], [], [], 0.0)
        assert ready == []

        assert configure_barrier(second_ready_write, second_resume_read) is None
        assert close(shadow) is None
        assert state(shadow) == _native_issuer_closed_snapshot(5)
        ready, _, _ = select.select([first_ready_read, second_ready_read], [], [], 0.0)
        assert ready == []
    finally:
        for descriptor in (
            first_ready_read,
            first_ready_write,
            first_resume_read,
            first_resume_write,
            second_ready_read,
            second_ready_write,
            second_resume_read,
            second_resume_write,
        ):
            with suppress(OSError):
                os.close(descriptor)
        _close_native_issuer_projection_socket(projection, socket_owner)


@pytest.mark.parametrize("point", range(5))
def test_native_issuer_foreign_fork_interposition_observes_committed_detach(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    point: int,
) -> None:
    _require_coherent_native_issuer_lifecycle_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    create = test_module._test_create_inert_topology_observation_issuer_shadow
    state = test_module._test_topology_observation_issuer_shadow_state
    activate, burn, close, validate, configure_fault = _native_issuer_lifecycle_hooks(test_module)
    configure_fork, finish_fork = _native_issuer_foreign_fork_hooks(test_module)
    projection, socket_owner = _new_native_issuer_activation_projection(
        tmp_path / f"foreign-fork-{point}"
    )
    shadow = create()
    plan_finished = False
    reopen_projection = projection
    try:
        if point != 0:
            assert activate(shadow, projection) is None
        assert configure_fork(shadow, point) is None
        if point == 0:
            assert configure_fault(9, 0, 1) is None
            _assert_native_issuer_lifecycle_fault(
                lambda: activate(shadow, projection),
                0,
            )
            assert state(shadow) == _native_issuer_failed_burned_snapshot(4)
        elif point == 1:
            assert burn(shadow) is None
            assert state(shadow) == _native_issuer_explicit_burned_snapshot(projection)
        elif point == 2:
            _mutate_native_issuer_external_identity(projection, "executable_mode")
            with pytest.raises(OSError):
                validate(shadow)
            assert state(shadow) == _native_issuer_explicit_burned_snapshot(projection)
            reopen_projection = _repair_native_issuer_external_projection(
                projection,
                "executable_mode",
            )
        elif point == 3:
            assert close(shadow) is None
            assert state(shadow) == _native_issuer_closed_snapshot(4)
        else:
            assert point == 4
            retired = weakref.ref(shadow)
            del shadow
            gc.collect()
            assert retired() is None

        _assert_native_issuer_foreign_fork_result(finish_fork(), point)
        plan_finished = True
        if point == 1:
            assert validate(shadow) is None
        if point in {0, 1, 2}:
            expected_revision = 5 if point in {0, 1, 2} else 4
            assert close(shadow) is None
            assert state(shadow) == _native_issuer_closed_snapshot(expected_revision)

        contender = create()
        assert activate(contender, reopen_projection) is None
        assert state(contender) == _native_issuer_active_snapshot(reopen_projection)
        assert close(contender) is None
        assert state(contender) == _native_issuer_closed_snapshot(4)
    finally:
        if not plan_finished:
            with suppress(RuntimeError):
                finish_fork()
        _close_native_issuer_projection_socket(projection, socket_owner)


