def test_native_issuer_foreign_fork_hooks_reject_inherited_child_process(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    _require_coherent_native_issuer_lifecycle_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    create = test_module._test_create_inert_topology_observation_issuer_shadow
    activate, burn, close, _validate, _configure_fault = _native_issuer_lifecycle_hooks(test_module)
    configure_fork, finish_fork = _native_issuer_foreign_fork_hooks(test_module)
    projection, socket_owner = _new_native_issuer_activation_projection(
        tmp_path / "foreign-fork-inherited-child"
    )
    result_read, result_write = os.pipe()
    shadow = create()
    child_pid = -1
    reaped = False
    plan_finished = False
    try:
        assert activate(shadow, projection) is None
        assert configure_fork(shadow, 1) is None
        child_pid = os.fork()
        if child_pid == 0:  # pragma: no cover - asserted through child status
            os.close(result_read)
            rejected: list[bool] = []
            for operation in (
                lambda: configure_fork(shadow, 1),
                finish_fork,
            ):
                try:
                    operation()
                except RuntimeError:
                    rejected.append(True)
                except BaseException:
                    rejected.append(False)
                else:
                    rejected.append(False)
            os.write(result_write, bytes(rejected))
            os.close(result_write)
            os._exit(0 if rejected == [True, True] else 1)

        os.close(result_write)
        result_write = -1
        ready, _, _ = select.select([result_read], [], [], 5.0)
        assert ready == [result_read]
        assert os.read(result_read, 2) == b"\x01\x01"
        waited_pid, status = os.waitpid(child_pid, 0)
        reaped = True
        assert waited_pid == child_pid
        assert os.waitstatus_to_exitcode(status) == 0

        assert burn(shadow) is None
        _assert_native_issuer_foreign_fork_result(finish_fork(), 1)
        plan_finished = True
        assert close(shadow) is None
    finally:
        for descriptor in (result_read, result_write):
            if descriptor >= 0:
                with suppress(OSError):
                    os.close(descriptor)
        if child_pid > 0 and not reaped:
            with suppress(ProcessLookupError):
                os.kill(child_pid, 9)
            with suppress(ChildProcessError):
                os.waitpid(child_pid, 0)
        if not plan_finished:
            with suppress(RuntimeError):
                finish_fork()
        _close_native_issuer_projection_socket(projection, socket_owner)


