def test_native_issuer_active_operations_reject_a_foreign_thread(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_lifecycle_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    create = test_module._test_create_inert_topology_observation_issuer_shadow
    state = test_module._test_topology_observation_issuer_shadow_state
    activate, burn, close, validate, _configure = _native_issuer_lifecycle_hooks(test_module)
    projection, socket_owner = _new_native_issuer_activation_projection(tmp_path / "foreign-thread")
    try:
        active = create()
        assert activate(active, projection) is None
        active_snapshot = _native_issuer_active_snapshot(projection)
        failures: list[tuple[str, type[BaseException]]] = []

        def attempt(name: str, operation: Callable[[], object]) -> None:
            try:
                operation()
            except BaseException as error:
                failures.append((name, type(error)))
            else:
                failures.append((name, AssertionError))

        def run_foreign_operations() -> None:
            attempt("validate", lambda: validate(active))
            attempt("burn", lambda: burn(active))
            attempt("close", lambda: close(active))

        worker = threading.Thread(target=run_foreign_operations, daemon=True)
        worker.start()
        worker.join(timeout=5.0)
        assert worker.is_alive() is False
        assert failures == [
            ("validate", RuntimeError),
            ("burn", RuntimeError),
            ("close", RuntimeError),
        ]
        assert state(active) == active_snapshot
        assert validate(active) is None
        assert close(active) is None
        assert state(active) == _native_issuer_closed_snapshot(4)
    finally:
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_inert_allocation_thread_is_nonauthorizing(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    _require_coherent_native_issuer_lifecycle_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    create = test_module._test_create_inert_topology_observation_issuer_shadow
    state = test_module._test_topology_observation_issuer_shadow_state
    activate, burn, close, validate, _configure = _native_issuer_lifecycle_hooks(test_module)
    projection, socket_owner = _new_native_issuer_activation_projection(
        tmp_path / "thread-transfer"
    )
    activated = threading.Event()
    allow_close = threading.Event()
    observations: dict[str, object] = {}
    worker: threading.Thread | None = None
    inert_worker: threading.Thread | None = None
    try:
        shadow = create()

        def activate_on_worker() -> None:
            try:
                observations["activate"] = activate(shadow, projection)
                observations["validate"] = validate(shadow)
                observations["active_snapshot"] = state(shadow)
                activated.set()
                if not allow_close.wait(timeout=5.0):
                    raise AssertionError("activation owner was not released")
                observations["close"] = close(shadow)
                observations["closed_snapshot"] = state(shadow)
            except BaseException as error:
                observations["error"] = error
                activated.set()

        worker = threading.Thread(target=activate_on_worker, daemon=True)
        worker.start()
        assert activated.wait(timeout=5.0)
        assert "error" not in observations
        assert observations["activate"] is None
        assert observations["validate"] is None
        assert observations["active_snapshot"] == _native_issuer_active_snapshot(projection)
        main_thread_snapshot = state(shadow)
        assert main_thread_snapshot == _tuple_with_item(
            _native_issuer_active_snapshot(projection),
            10,
            False,
        )
        for operation in (
            lambda: validate(shadow),
            lambda: burn(shadow),
            lambda: close(shadow),
        ):
            with pytest.raises(RuntimeError):
                operation()
        allow_close.set()
        worker.join(timeout=5.0)
        assert worker.is_alive() is False
        assert "error" not in observations
        assert observations["close"] is None
        assert observations["closed_snapshot"] == _native_issuer_closed_snapshot(4)
        assert state(shadow) == _native_issuer_closed_snapshot(4)
        assert close(shadow) is None

        inert = create()
        inert_result: list[object] = []

        def close_inert_on_worker() -> None:
            try:
                inert_result.append(close(inert))
            except BaseException as error:
                inert_result.append(error)

        inert_worker = threading.Thread(target=close_inert_on_worker, daemon=True)
        inert_worker.start()
        inert_worker.join(timeout=5.0)
        assert inert_worker.is_alive() is False
        assert inert_result == [None]
        assert state(inert) == _native_issuer_closed_snapshot(2)
        assert close(inert) is None
    finally:
        allow_close.set()
        if worker is not None:
            worker.join(timeout=5.0)
        if inert_worker is not None:
            inert_worker.join(timeout=5.0)
        _close_native_issuer_projection_socket(projection, socket_owner)


def test_native_issuer_active_fork_child_rejects_and_releases_inherited_lock_copy(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
) -> None:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    _require_coherent_native_issuer_lifecycle_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    create = test_module._test_create_inert_topology_observation_issuer_shadow
    state = test_module._test_topology_observation_issuer_shadow_state
    activate, burn, close, validate, _configure = _native_issuer_lifecycle_hooks(test_module)
    projection, socket_owner = _new_native_issuer_activation_projection(tmp_path / "fork")
    result_read, result_write = os.pipe()
    resume_read, resume_write = os.pipe()
    child_pid = -1
    reaped = False
    try:
        active = create()
        assert activate(active, projection) is None
        child_pid = os.fork()
        if child_pid == 0:  # pragma: no cover - asserted through the pipes
            os.close(result_read)
            os.close(resume_write)
            rejected: list[bool] = []
            for operation in (
                lambda: state(active),
                lambda: validate(active),
                lambda: burn(active),
                lambda: close(active),
                lambda: activate(active, projection),
            ):
                try:
                    operation()
                except RuntimeError:
                    rejected.append(True)
                except BaseException:
                    rejected.append(False)
                else:
                    rejected.append(False)
            os.write(result_write, bytes(rejected))
            if os.read(resume_read, 1) != b"C":
                os._exit(2)
            descriptor = -1
            acquired = False
            try:
                descriptor = os.open(
                    _native_issuer_launch_lock_path(projection),
                    os.O_RDWR | os.O_CLOEXEC,
                )
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                acquired = True
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            except BaseException:
                acquired = False
            finally:
                if descriptor >= 0:
                    os.close(descriptor)
            os.write(result_write, b"\x01" if acquired else b"\x00")
            os.close(result_write)
            os.close(resume_read)
            os._exit(0 if rejected == [True] * 5 and acquired else 1)

        os.close(result_write)
        result_write = -1
        os.close(resume_read)
        resume_read = -1
        ready, _, _ = select.select([result_read], [], [], 5.0)
        assert ready == [result_read]
        assert os.read(result_read, 5) == b"\x01" * 5
        assert validate(active) is None
        assert state(active) == _native_issuer_active_snapshot(projection)
        assert close(active) is None
        os.write(resume_write, b"C")
        os.close(resume_write)
        resume_write = -1
        ready, _, _ = select.select([result_read], [], [], 5.0)
        assert ready == [result_read]
        assert os.read(result_read, 1) == b"\x01"
        waited_pid, status = os.waitpid(child_pid, 0)
        reaped = True
        assert waited_pid == child_pid
        assert os.waitstatus_to_exitcode(status) == 0
        assert state(active) == _native_issuer_closed_snapshot(4)
    finally:
        for descriptor in (result_read, result_write, resume_read, resume_write):
            if descriptor >= 0:
                with suppress(OSError):
                    os.close(descriptor)
        if child_pid > 0 and not reaped:
            with suppress(ProcessLookupError):
                os.kill(child_pid, 9)
            with suppress(ChildProcessError):
                os.waitpid(child_pid, 0)
        _close_native_issuer_projection_socket(projection, socket_owner)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", ["store", "return"])
def test_native_issuer_activation_lost_python_result_is_caller_closed(
    native_issuer_shadow_test_build: tuple[ModuleType, Path, Path],
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    _require_coherent_native_issuer_lifecycle_source()
    test_module, _test_extension, _production_extension = native_issuer_shadow_test_build
    create = test_module._test_create_inert_topology_observation_issuer_shadow
