    projection, socket_owner = _new_native_issuer_activation_projection(
        tmp_path / f"lost-{boundary}-{failure_type.__name__}"
    )
    active = create()

    def activate_at_boundary() -> object:
        result = activate(active, projection)
        return result

    offset = _instruction_offset(
        activate_at_boundary,
        opname="STORE_FAST" if boundary == "store" else "RETURN_VALUE",
        argval="result" if boundary == "store" else None,
    )
    failure: BaseException = SystemExit(197) if failure_type is SystemExit else KeyboardInterrupt()
    tool_id = _enable_instruction_interrupt(
        activate_at_boundary,
        offset,
        tool_name=f"native-issuer-activation-{boundary}-{failure_type.__name__}-test",
        interruption=failure,
    )
    try:
        with pytest.raises(failure_type) as retained:
            activate_at_boundary()
        assert retained.value is failure
        assert state(active) == _native_issuer_active_snapshot(projection)
    finally:
        _disable_instruction_interrupt(tool_id, activate_at_boundary)
        assert close(active) is None
        assert state(active) == _native_issuer_closed_snapshot(4)
        _close_native_issuer_projection_socket(projection, socket_owner)


