def _require_coherent_projection_seal_reader() -> None:
    reader_path = Path(cast(str, reader.__file__))
    reader_sha256 = hashlib.sha256(reader_path.read_bytes()).hexdigest()
    if reader_sha256 not in _COHERENT_PROJECTION_SEAL_READER_SHA256:
        pytest.skip("projection capability seal source is not coherent")


def _forget_projection_seal_modules_in_child() -> None:
    module_names = tuple(
        name
        for name in tuple(sys.modules)
        if name in _PROJECTION_SEAL_MODULES
        or name.startswith("scripts.trusted_time_post_enrollment_")
    )
    for module_name in module_names:
        module = sys.modules.pop(module_name, None)
        parent_name, _, child_name = module_name.rpartition(".")
        parent = sys.modules.get(parent_name)
        if parent is None:
            continue
        namespace = type(parent).__getattribute__(parent, "__dict__")
        if type(namespace) is dict and dict.get(namespace, child_name) is module:
            dict.pop(namespace, child_name, None)


def _projection_seal_escape_names(module: object) -> tuple[str, ...]:
    namespace = type(module).__getattribute__(module, "__dict__")
    assert type(namespace) is dict
    forbidden_prefixes = (
        "_finalize_",
        "_initialize_authenticated_receipt_projection",
        "_register_",
        "_retire_finalized_",
        "_stage_",
        "_take_finalized_",
    )
    return tuple(
        sorted(
            name
            for name in namespace
            if name.startswith(forbidden_prefixes)
            and ("projection" in name or "receipt" in name or "claim" in name or "locator" in name)
        )
    )


def _contains_private_projection_bootstrap_value(value: object) -> bool:
    if type(value) is MemberDescriptorType:
        return True
    if type(value) is str:
        return cast(str, value).startswith(
            (
                "trusted-time-staged-projection-",
                "trusted-time-projection-capability-",
                "trusted-time-start-projection-recipe-",
                "trusted-time-recovery-projection-recipe-",
                "trusted-time-controller-projection-recipe-",
                "trusted-time-locator-projection-recipe-",
            )
        )
    if type(value) is tuple:
        return any(
            _contains_private_projection_bootstrap_value(item)
            for item in cast(tuple[object, ...], value)
        )
    if type(value) is frozenset:
        return any(
            _contains_private_projection_bootstrap_value(item)
            for item in cast(frozenset[object], value)
        )
    if type(value) is dict:
        return any(
            _contains_private_projection_bootstrap_value(item)
            for pair in cast(dict[object, object], value).items()
            for item in pair
        )
    return False


def _projection_callable_capability_escape_names(module: object) -> tuple[str, ...]:
    namespace = type(module).__getattribute__(module, "__dict__")
    assert type(namespace) is dict
    module_name = cast(str, type(module).__getattribute__(module, "__name__"))
    source_modules = frozenset(
        {
            _PROJECTION_BOOTSTRAP_MODULE,
            _PROJECTION_CONTROLLER_OUTCOME_MODULE,
            _PROJECTION_RECOVERY_OUTCOME_MODULE,
            _PROJECTION_LOCATOR_MODULE,
            _PROJECTION_START_MODULE,
            _PROJECTION_DOMAIN_MODULE,
        }
    )
    forbidden_name_fragments = (
        "bootstrap",
        "capabilit",
        "finalize",
        "parse",
        "projection_recipe",
        "register",
        "retire",
        "revalidate",
        "stage",
        "validate",
    )
    escaped: set[str] = set()
    seen: set[int] = set()

    def inspect_value(value: object, path: str) -> None:
        identity = id(value)
        if identity in seen:
            return
        seen.add(identity)
        if _contains_private_projection_bootstrap_value(value):
            escaped.add(path)
            return
        if type(value) is tuple:
            for index, item in enumerate(cast(tuple[object, ...], value)):
                inspect_value(item, f"{path}[{index}]")
            return
        if type(value) is frozenset:
            for index, item in enumerate(cast(frozenset[object], value)):
                inspect_value(item, f"{path}{{{index}}}")
            return
        if type(value) is dict:
            for key, item in cast(dict[object, object], value).items():
                inspect_value(key, f"{path}.key")
                inspect_value(item, f"{path}[{key!r}]")
            return
        if type(value) is not FunctionType:
            return

        function = cast(FunctionType, value)
        function_module = type(function).__getattribute__(function, "__module__")
        function_name = type(function).__getattribute__(function, "__name__")
        if function_module == _PROJECTION_BOOTSTRAP_MODULE or (
            function_module in source_modules
            and function_module != module_name
            and any(fragment in function_name for fragment in forbidden_name_fragments)
        ):
            escaped.add(f"{path}->{function_module}.{function_name}")
            return

        defaults = type(function).__getattribute__(function, "__defaults__")
        if defaults is not None:
            inspect_value(defaults, f"{path}.__defaults__")
        keyword_defaults = type(function).__getattribute__(function, "__kwdefaults__")
        if keyword_defaults is not None:
            inspect_value(keyword_defaults, f"{path}.__kwdefaults__")
        closure = type(function).__getattribute__(function, "__closure__")
        if closure is not None:
            for index, cell in enumerate(closure):
                try:
                    cell_value = cell.cell_contents
                except ValueError:
                    continue
                inspect_value(cell_value, f"{path}.__closure__[{index}]")

    for name, value in namespace.items():
        if type(value) is FunctionType:
            inspect_value(value, name)
    return tuple(sorted(escaped))


def _run_fresh_projection_import_order(
    import_order: tuple[str, ...],
) -> dict[str, object]:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through the pipe
        os.close(read_descriptor)
        payload: dict[str, object]
        try:
            _forget_projection_seal_modules_in_child()
            imported = tuple(importlib.import_module(name) for name in import_order)
            fresh_reader = sys.modules.get(_PROJECTION_READER_MODULE)
            fresh_bootstrap = sys.modules.get(_PROJECTION_BOOTSTRAP_MODULE)
            if fresh_reader is None or fresh_bootstrap is None:
                raise AssertionError("projection seal activation did not import its graph")
            module_escape_names = {
                name: _projection_seal_escape_names(module)
                for name in _PROJECTION_SEAL_MODULES
                if (module := sys.modules.get(name)) is not None
            }
            module_private_value_names: dict[str, tuple[str, ...]] = {}
            for name in _PROJECTION_SEAL_MODULES:
                module = sys.modules.get(name)
                if module is None:
                    continue
                namespace = type(module).__getattribute__(module, "__dict__")
                module_private_value_names[name] = tuple(
                    sorted(
                        global_name
                        for global_name, value in namespace.items()
                        if _contains_private_projection_bootstrap_value(value)
                    )
                )
            bootstrap_namespace = type(fresh_bootstrap).__getattribute__(
                fresh_bootstrap,
                "__dict__",
            )
            reader_namespace = type(fresh_reader).__getattribute__(
                fresh_reader,
                "__dict__",
            )
            payload = {
                "status": "ok",
                "imported": tuple(module.__name__ for module in imported),
                "bootstrap_all": dict.get(bootstrap_namespace, "__all__"),
                "module_escape_names": module_escape_names,
                "module_private_value_names": module_private_value_names,
                "reader_recipe_globals": tuple(
                    sorted(
                        name
                        for name, value in reader_namespace.items()
                        if (
                            "recipe" in name
                            or "projection_capabilit" in name
                            or "projection_descriptor" in name
                        )
                        and value is not None
                    )
                ),
                "callable_capability_escapes": {
                    name: _projection_callable_capability_escape_names(module)
                    for name in _PROJECTION_SEAL_MODULES
                    if (module := sys.modules.get(name)) is not None
                },
            }
        except BaseException as error:
            payload = {
                "status": "error",
                "error_type": type(error).__name__,
                "error_message": str(error),
            }
        try:
            os.write(
                write_descriptor,
                json.dumps(payload, sort_keys=True).encode("utf-8"),
            )
        finally:
            os.close(write_descriptor)
        os._exit(0)

    os.close(write_descriptor)
    try:
        encoded = bytearray()
        while chunk := os.read(read_descriptor, 65_536):
            encoded.extend(chunk)
    finally:
        os.close(read_descriptor)
        _, wait_status = os.waitpid(child_pid, 0)
    assert os.waitstatus_to_exitcode(wait_status) == 0
    decoded = json.loads(bytes(encoded))
    assert type(decoded) is dict
    return cast(dict[str, object], decoded)


def _run_fresh_projection_bootstrap_wrong_frame_attempts() -> dict[str, object]:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through the pipe
        os.close(read_descriptor)
        payload: dict[str, object]
        try:
            _forget_projection_seal_modules_in_child()
            bootstrap = importlib.import_module(_PROJECTION_BOOTSTRAP_MODULE)
            namespace = type(bootstrap).__getattribute__(bootstrap, "__dict__")
            assert type(namespace) is dict
            attempted: dict[str, bool] = {}
            for name, candidate in tuple(namespace.items()):
                if not callable(candidate) or not name.startswith(
                    (
                        "_finalize_",
                        "_register_",
                        "_retire_",
                        "_stage_",
                        "_take_",
                    )
                ):
                    continue
                try:
                    if name.startswith(("_register_", "_stage_")):
                        candidate(object)
                    else:
                        candidate()
                except ImportError:
                    attempted[name] = True
                else:
                    attempted[name] = False
            fresh_reader = importlib.import_module(_PROJECTION_READER_MODULE)
            payload = {
                "status": "ok",
                "attempted": attempted,
                "reader_imported": fresh_reader.__name__ == _PROJECTION_READER_MODULE,
            }
        except BaseException as error:
            payload = {
                "status": "error",
                "error_type": type(error).__name__,
                "error_message": str(error),
            }
        try:
            os.write(
                write_descriptor,
                json.dumps(payload, sort_keys=True).encode("utf-8"),
            )
        finally:
            os.close(write_descriptor)
        os._exit(0)

    os.close(write_descriptor)
    try:
        encoded = bytearray()
        while chunk := os.read(read_descriptor, 65_536):
            encoded.extend(chunk)
    finally:
        os.close(read_descriptor)
        _, wait_status = os.waitpid(child_pid, 0)
    assert os.waitstatus_to_exitcode(wait_status) == 0
    decoded = json.loads(bytes(encoded))
    assert type(decoded) is dict
    return cast(dict[str, object], decoded)


def _fresh_import_module_code(module_name: str) -> CodeType:
    module = sys.modules.get(module_name)
    assert module is not None
    spec = type(module).__getattribute__(module, "__spec__")
    loader = None if spec is None else spec.loader
    assert loader is not None
    get_code = getattr(loader, "get_code", None)
    assert callable(get_code)
    code = get_code(module_name)
    assert type(code) is CodeType
    return code


def _module_call_return_offset(module_code: CodeType, callable_name: str) -> int:
    instructions = list(dis.get_instructions(module_code))
    load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname in {"LOAD_NAME", "LOAD_GLOBAL"}
        and instruction.argval == callable_name
    )
    call_index = next(
        index
        for index in range(load_index + 1, len(instructions))
        if instructions[index].opname == "CALL"
    )
    return instructions[call_index + 1].offset


def _run_fresh_projection_import_interruption(
    *,
    module_name: str,
    boundary: Literal["registrar_store", "root_store", "finalize_return"],
    target_name: str,
    failure_type: type[BaseException],
) -> dict[str, object]:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    module_code = _fresh_import_module_code(module_name)
    if boundary == "finalize_return":
        target_offset = _module_call_return_offset(module_code, target_name)
    else:
        target_offset = _instruction_offset(
            module_code,
            opname="STORE_NAME",
            argval=target_name,
        )
    target_filename = module_code.co_filename
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through the pipe
        os.close(read_descriptor)
        interruption: BaseException = (
            SystemExit(173) if failure_type is SystemExit else KeyboardInterrupt()
        )
        injected = False
        tool_id = next(
            candidate
            for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
            if sys.monitoring.get_tool(candidate) is None
        )
        payload: dict[str, object]
        try:
            _forget_projection_seal_modules_in_child()
            sys.monitoring.use_tool_id(
                tool_id,
                f"trusted-time-projection-{boundary}-test",
            )

            def interrupt_module_boundary(
                code: CodeType,
                instruction_offset: int,
            ) -> None:
                nonlocal injected
                if (
                    not injected
                    and code.co_name == "<module>"
                    and code.co_filename == target_filename
                    and instruction_offset == target_offset
                ):
                    injected = True
                    raise interruption

            sys.monitoring.register_callback(
                tool_id,
                sys.monitoring.events.INSTRUCTION,
                interrupt_module_boundary,
            )
            sys.monitoring.set_events(tool_id, sys.monitoring.events.INSTRUCTION)
            raised_exact = False
            try:
                importlib.import_module(module_name)
            except BaseException as error:
                raised_exact = error is interruption
            payload = {
                "status": "ok",
                "injected": injected,
                "raised_exact": raised_exact,
                "target_module_present": module_name in sys.modules,
                "reader_present": _PROJECTION_READER_MODULE in sys.modules,
            }
        except BaseException as error:
            payload = {
                "status": "error",
                "error_type": type(error).__name__,
                "error_message": str(error),
            }
        finally:
            if sys.monitoring.get_tool(tool_id) is not None:
                sys.monitoring.set_events(tool_id, 0)
                sys.monitoring.register_callback(
                    tool_id,
                    sys.monitoring.events.INSTRUCTION,
                    None,
                )
                sys.monitoring.free_tool_id(tool_id)
        try:
            os.write(
                write_descriptor,
                json.dumps(payload, sort_keys=True).encode("utf-8"),
            )
        finally:
            os.close(write_descriptor)
        os._exit(0)

    os.close(write_descriptor)
    try:
        encoded = bytearray()
        while chunk := os.read(read_descriptor, 65_536):
            encoded.extend(chunk)
    finally:
        os.close(read_descriptor)
        _, wait_status = os.waitpid(child_pid, 0)
    assert os.waitstatus_to_exitcode(wait_status) == 0
    decoded = json.loads(bytes(encoded))
    assert type(decoded) is dict
    return cast(dict[str, object], decoded)


def _run_fresh_projection_publication_fault(
    *,
    module_name: str,
    class_name: str,
    finalizer_name: str,
    fault: Literal["registrar_store", "finalizer_missing", "finalizer_decoy"],
    failure_type: type[BaseException] | None = None,
) -> dict[str, object]:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    module_code = _fresh_import_module_code(module_name)
    if fault == "registrar_store":
        target_offset = _instruction_offset(
            module_code,
            opname="STORE_NAME",
            argval=class_name,
        )
    else:
        target_offset = _instruction_offset(
            module_code,
            opname="LOAD_NAME",
            argval=finalizer_name,
            occurrence="last",
        )
    target_filename = module_code.co_filename
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through the pipe
        os.close(read_descriptor)
        interruption: BaseException | None = None
        if failure_type is SystemExit:
            interruption = SystemExit(177)
        elif failure_type is KeyboardInterrupt:
            interruption = KeyboardInterrupt()
        injected = False
        premature_finalizer_rejected = False
        tool_id = next(
            candidate
            for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
            if sys.monitoring.get_tool(candidate) is None
        )
        payload: dict[str, object]
        try:
            _forget_projection_seal_modules_in_child()
            sys.monitoring.use_tool_id(
                tool_id,
                f"trusted-time-projection-publication-{fault}-test",
            )

            def inject_publication_fault(
                code: CodeType,
                instruction_offset: int,
            ) -> None:
                nonlocal injected, premature_finalizer_rejected
                if (
                    injected
                    or code.co_name != "<module>"
                    or code.co_filename != target_filename
                    or instruction_offset != target_offset
                ):
                    return
                injected = True
                target_module = sys.modules.get(module_name)
                assert target_module is not None
                namespace = type(target_module).__getattribute__(
                    target_module,
                    "__dict__",
                )
                assert type(namespace) is dict
                if fault == "registrar_store":
                    finalizer = dict.get(namespace, finalizer_name)
                    assert callable(finalizer)
                    try:
                        finalizer()
                    except ImportError:
                        premature_finalizer_rejected = True
                    assert interruption is not None
                    raise interruption
                if fault == "finalizer_missing":
                    dict.pop(namespace, class_name, None)
                else:
                    assert fault == "finalizer_decoy"
                    namespace[class_name] = object

            sys.monitoring.register_callback(
                tool_id,
                sys.monitoring.events.INSTRUCTION,
                inject_publication_fault,
            )
            sys.monitoring.set_events(tool_id, sys.monitoring.events.INSTRUCTION)
            raised_exact = False
            import_rejected = False
            try:
                importlib.import_module(module_name)
            except BaseException as error:
                raised_exact = interruption is not None and error is interruption
                import_rejected = isinstance(error, ImportError)
            sys.monitoring.set_events(tool_id, 0)

            retry_rejected = False
            try:
                importlib.import_module(module_name)
            except ImportError:
                retry_rejected = True

            fresh_reader = sys.modules.get(_PROJECTION_READER_MODULE)
            gate_values: tuple[bool, ...] = ()
            if fresh_reader is not None:
                discovered: tuple[bool, ...] = ()
                reader_namespace = type(fresh_reader).__getattribute__(
                    fresh_reader,
                    "__dict__",
                )
                assert type(reader_namespace) is dict
                for value in reader_namespace.values():
                    if type(value) is not FunctionType:
                        continue
                    for nonlocal_name, nonlocal_value in inspect.getclosurevars(
                        value
                    ).nonlocals.items():
                        if (
                            type(nonlocal_value) is bool
                            and "projection" in nonlocal_name
                            and ("finalized" in nonlocal_name or "ready" in nonlocal_name)
                        ):
                            discovered += (nonlocal_value,)
                gate_values = discovered
            payload = {
                "status": "ok",
                "injected": injected,
                "raised_exact": raised_exact,
                "import_rejected": import_rejected,
                "premature_finalizer_rejected": premature_finalizer_rejected,
                "target_module_present": module_name in sys.modules,
                "retry_rejected": retry_rejected,
                "gate_values": gate_values,
            }
        except BaseException as error:
            payload = {
                "status": "error",
                "error_type": type(error).__name__,
                "error_message": str(error),
            }
        finally:
            if sys.monitoring.get_tool(tool_id) is not None:
                sys.monitoring.set_events(tool_id, 0)
                sys.monitoring.register_callback(
                    tool_id,
                    sys.monitoring.events.INSTRUCTION,
                    None,
                )
                sys.monitoring.free_tool_id(tool_id)
        try:
            os.write(
                write_descriptor,
                json.dumps(payload, sort_keys=True).encode("utf-8"),
            )
        finally:
            os.close(write_descriptor)
        os._exit(0)

    os.close(write_descriptor)
    try:
        encoded = bytearray()
        while chunk := os.read(read_descriptor, 65_536):
            encoded.extend(chunk)
    finally:
        os.close(read_descriptor)
        _, wait_status = os.waitpid(child_pid, 0)
    assert os.waitstatus_to_exitcode(wait_status) == 0
    decoded = json.loads(bytes(encoded))
    assert type(decoded) is dict
    return cast(dict[str, object], decoded)


def _projection_final_gate_code_and_offset(
    boundary: str,
) -> tuple[CodeType, int]:
    module_code = _fresh_import_module_code(_PROJECTION_READER_MODULE)
    disable_code = _nested_code(module_code, "disable_projection_staging_exports")
    finalizer_code = _nested_code(module_code, "finalize_controller_projection_types")
    if boundary == "export_pop":
        return disable_code, _call_return_offset(
            disable_code,
            callable_name="_dict_pop",
        )
    if boundary == "absence_check":
        absence_code = _nested_code(disable_code, "<genexpr>")
        return absence_code, _call_return_offset(
            absence_code,
            callable_name="_dict_get",
        )
    if boundary == "final_gate_store":
        gate_stores = [
            instruction.offset
            for instruction in dis.get_instructions(finalizer_code)
            if instruction.opname in {"STORE_DEREF", "STORE_FAST"}
            and type(instruction.argval) is str
            and "projection" in instruction.argval
            and ("finalized" in instruction.argval or "ready" in instruction.argval)
        ]
        assert len(gate_stores) == 1
        return finalizer_code, gate_stores[0]
    assert boundary == "finalizer_return"
    return finalizer_code, _instruction_offset(
        finalizer_code,
        opname="RETURN_VALUE",
        argval=None,
        occurrence="last",
    )


def _claimed_bridge_final_gate_code_and_offset(
    boundary: str,
) -> tuple[CodeType, int]:
    reader_module_code = _fresh_import_module_code(_PROJECTION_READER_MODULE)
    builder_code = _nested_code(reader_module_code, "_build_observation_sealer")
    finalizer_code = _nested_code(builder_code, "finalize_claimed_authorization_recipe")
    if boundary in {"caller_export_pop", "reader_export_pop"}:
        return finalizer_code, _call_return_offset(
            finalizer_code,
            callable_name="_dict_pop",
            occurrence=("first" if boundary == "caller_export_pop" else "last"),
        )
    if boundary in {"caller_absence_check", "reader_absence_check"}:
        absence_codes = [
            constant
            for constant in finalizer_code.co_consts
            if type(constant) is CodeType and constant.co_name == "<genexpr>"
        ]
        assert len(absence_codes) == 2
        absence_code = absence_codes[0 if boundary == "caller_absence_check" else 1]
        return absence_code, _call_return_offset(
            absence_code,
            callable_name="_dict_get",
        )
    if boundary == "final_gate_store":
        return finalizer_code, _instruction_offset(
            finalizer_code,
            opname="STORE_DEREF",
            argval="claimed_authorization_recipe_finalized",
        )
    if boundary == "finalizer_return":
        return finalizer_code, _instruction_offset(
            finalizer_code,
            opname="RETURN_VALUE",
            argval=None,
            occurrence="last",
        )

    claimed_module_code = _fresh_import_module_code(_PROJECTION_CLAIMED_FENCE_MODULE)
    claimed_instructions = list(dis.get_instructions(claimed_module_code))
    finalizer_load_index = max(
        index
        for index, instruction in enumerate(claimed_instructions)
        if instruction.argval == "_finalize_claimed_fence_recovery_binder_recipe"
    )
    finalizer_call_index = next(
        index
        for index in range(finalizer_load_index + 1, len(claimed_instructions))
        if claimed_instructions[index].opname == "CALL"
    )
    if boundary == "caller_finalizer_call":
        return claimed_module_code, claimed_instructions[finalizer_call_index].offset
    assert boundary == "caller_finalizer_return"
    return claimed_module_code, claimed_instructions[finalizer_call_index + 1].offset


def _run_fresh_claimed_bridge_final_gate_interruption(
    *,
    boundary: str,
    occurrence: int,
    failure_type: type[BaseException],
) -> dict[str, object]:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    target_code, target_offset = _claimed_bridge_final_gate_code_and_offset(boundary)
    target_filename = target_code.co_filename
    target_name = target_code.co_name
    target_first_line = target_code.co_firstlineno
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through the pipe
        os.close(read_descriptor)
        interruption: BaseException = (
            SystemExit(227) if failure_type is SystemExit else KeyboardInterrupt()
        )
        observed_occurrences = 0
        injected = False
        claimed_module_at_interruption: object | None = None
        tool_id = next(
            candidate
            for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
            if sys.monitoring.get_tool(candidate) is None
        )
        payload: dict[str, object]
        try:
            _forget_projection_seal_modules_in_child()
            sys.monitoring.use_tool_id(
                tool_id,
                f"trusted-time-claimed-bridge-{boundary}-test",
            )

            def interrupt_claimed_bridge(
                code: CodeType,
                instruction_offset: int,
            ) -> None:
                nonlocal claimed_module_at_interruption, injected
                nonlocal observed_occurrences
                if (
                    injected
                    or code.co_filename != target_filename
                    or code.co_name != target_name
                    or code.co_firstlineno != target_first_line
                    or instruction_offset != target_offset
                ):
                    return
                current_occurrence = observed_occurrences
                observed_occurrences += 1
                if current_occurrence != occurrence:
                    return
                claimed_module_at_interruption = sys.modules.get(_PROJECTION_CLAIMED_FENCE_MODULE)
                injected = True
                raise interruption

            sys.monitoring.register_callback(
                tool_id,
                sys.monitoring.events.INSTRUCTION,
                interrupt_claimed_bridge,
            )
            sys.monitoring.set_events(tool_id, sys.monitoring.events.INSTRUCTION)
            raised_exact = False
            try:
                importlib.import_module(_PROJECTION_CLAIMED_FENCE_MODULE)
            except BaseException as error:
                raised_exact = error is interruption
            sys.monitoring.set_events(tool_id, 0)

            fresh_reader = sys.modules.get(_PROJECTION_READER_MODULE)
            reader_namespace = (
                {}
                if fresh_reader is None
                else type(fresh_reader).__getattribute__(fresh_reader, "__dict__")
            )
            claimed_module = (
                claimed_module_at_interruption
                if claimed_module_at_interruption is not None
                else sys.modules.get(_PROJECTION_CLAIMED_FENCE_MODULE)
            )
            claimed_namespace = (
                {}
                if claimed_module is None
                else type(claimed_module).__getattribute__(claimed_module, "__dict__")
            )
            assert type(reader_namespace) is dict
            assert type(claimed_namespace) is dict
            live_reader_exports = tuple(
                name
                for name in _CLAIMED_BRIDGE_READER_STAGING_EXPORT_NAMES
                if name in reader_namespace
            )
            live_claimed_exports = tuple(
                name
                for name in _CLAIMED_BRIDGE_CALLER_STAGING_EXPORT_NAMES
                if name in claimed_namespace
            )

            pending_functions = [
                value for value in reader_namespace.values() if type(value) is FunctionType
            ]
            issuer_type = reader_namespace.get("TrustedTimePostEnrollmentTopologyObservationIssuer")
            if type(issuer_type) is type:
                issuer_namespace = type.__getattribute__(issuer_type, "__dict__")
                pending_functions.extend(
                    value for value in issuer_namespace.values() if type(value) is FunctionType
                )
            seen_functions: set[int] = set()
            gate_values: tuple[bool, ...] = ()
            while pending_functions:
                function = pending_functions.pop()
                if id(function) in seen_functions:
                    continue
                seen_functions.add(id(function))
                closure = type(function).__getattribute__(function, "__closure__")
                if closure is None:
                    continue
                freevars = (
                    type(function)
                    .__getattribute__(
                        function,
                        "__code__",
                    )
                    .co_freevars
                )
                for freevar, cell in zip(freevars, closure, strict=True):
                    try:
                        value = cell.cell_contents
                    except ValueError:
                        continue
                    if freevar == "claimed_authorization_recipe_finalized" and type(value) is bool:
                        gate_values += (value,)
                    elif type(value) is FunctionType:
                        pending_functions.append(value)

            payload = {
                "status": "ok",
                "injected": injected,
                "raised_exact": raised_exact,
                "observed_occurrences": observed_occurrences,
                "live_reader_exports": live_reader_exports,
                "live_claimed_exports": live_claimed_exports,
                "gate_values": gate_values,
            }
        except BaseException as error:
            payload = {
                "status": "error",
                "error_type": type(error).__name__,
                "error_message": str(error),
            }
        finally:
            if sys.monitoring.get_tool(tool_id) is not None:
                sys.monitoring.set_events(tool_id, 0)
                sys.monitoring.register_callback(
                    tool_id,
                    sys.monitoring.events.INSTRUCTION,
                    None,
                )
                sys.monitoring.free_tool_id(tool_id)
        try:
            os.write(
                write_descriptor,
                json.dumps(payload, sort_keys=True).encode("utf-8"),
            )
        finally:
            os.close(write_descriptor)
        os._exit(0)

    os.close(write_descriptor)
    try:
        encoded = bytearray()
        while chunk := os.read(read_descriptor, 65_536):
            encoded.extend(chunk)
    finally:
        os.close(read_descriptor)
        _, wait_status = os.waitpid(child_pid, 0)
    assert os.waitstatus_to_exitcode(wait_status) == 0
    decoded = json.loads(bytes(encoded))
    assert type(decoded) is dict
    return cast(dict[str, object], decoded)


def _run_fresh_claimed_producer_prefinalize_ab_attack(
    attack: str,
) -> dict[str, object]:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    target_code, target_offset = _claimed_bridge_final_gate_code_and_offset("caller_finalizer_call")
    target_filename = target_code.co_filename
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through the pipe
        os.close(read_descriptor)
        injected = False
        mutated_key: str | None = None
        tool_id = next(
            candidate
            for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
            if sys.monitoring.get_tool(candidate) is None
        )
        payload: dict[str, object]
        try:
            _forget_projection_seal_modules_in_child()
            sys.monitoring.use_tool_id(
                tool_id,
                f"trusted-time-claimed-producer-{attack}-test",
            )

            def mutate_before_finalizer(
                code: CodeType,
                instruction_offset: int,
            ) -> None:
                nonlocal injected, mutated_key
                if (
                    injected
                    or code.co_name != "<module>"
                    or code.co_filename != target_filename
                    or instruction_offset != target_offset
                ):
                    return
                injected = True
                claimed_module = sys.modules.get(_PROJECTION_CLAIMED_FENCE_MODULE)
                assert claimed_module is not None
                namespace = type(claimed_module).__getattribute__(
                    claimed_module,
                    "__dict__",
                )
                assert type(namespace) is dict
                if attack.startswith("module_"):
                    module_name = attack.removeprefix("module_")
                    if module_name == "classes":
                        for class_name in (
                            "TrustedTimePostEnrollmentTopologyObservationIssuer",
                            "_TrustedTimePostEnrollmentRecoveryClaimBinder",
                            "_ClaimedFenceRecoveryBinderAuthorization",
                        ):
                            namespace[class_name] = object
                        mutated_key = "classes"
                    elif module_name == "os":
                        namespace["os"] = SimpleNamespace(getpid=lambda: -1)
                        mutated_key = "os"
                    else:
                        assert module_name in {"any", "isinstance", "type"}
                        namespace[module_name] = lambda *_args, **_kwargs: True
                        mutated_key = module_name
                    return

                builder = namespace.get("_build_claimed_fence_preparer")
                assert type(builder) is FunctionType
                keyword_defaults = builder.__kwdefaults__
                assert type(keyword_defaults) is dict
                candidates = {
                    "kw_runner": (
                        "_run_under_exact_rlock",
                        "_rlock_acquire",
                        "_rlock_type",
                    ),
                    "kw_reducer": (
                        "_preferred_control_error",
                        "_preferred",
                        "_ordinary_exception_type",
                    ),
                    "kw_token": (
                        "_current_thread_token",
                        "_thread_local_type",
                        "_thread_local_getattribute",
                    ),
                    "kw_exception": (
                        "_base_exception_type",
                        "_seal_error_type",
                        "_rejected_error_type",
                    ),
                }[attack]
                mutated_key = next(name for name in candidates if name in keyword_defaults)
                replacement: object = (
                    Exception if attack == "kw_exception" else (lambda *_args, **_kwargs: object())
                )
                replacement_defaults = dict(keyword_defaults)
                replacement_defaults[mutated_key] = replacement
                builder.__kwdefaults__ = replacement_defaults

            sys.monitoring.register_callback(
                tool_id,
                sys.monitoring.events.INSTRUCTION,
                mutate_before_finalizer,
            )
            sys.monitoring.set_events(tool_id, sys.monitoring.events.INSTRUCTION)
            import_rejected = False
            try:
                importlib.import_module(_PROJECTION_CLAIMED_FENCE_MODULE)
            except BaseException:
                import_rejected = True
            sys.monitoring.set_events(tool_id, 0)

            fresh_reader = sys.modules.get(_PROJECTION_READER_MODULE)
            gate_values: tuple[bool, ...] = ()
            live_reader_exports: tuple[str, ...] = ()
            if fresh_reader is not None:
                reader_namespace = type(fresh_reader).__getattribute__(
                    fresh_reader,
                    "__dict__",
                )
                assert type(reader_namespace) is dict
                live_reader_exports = tuple(
                    name
                    for name in _CLAIMED_BRIDGE_READER_STAGING_EXPORT_NAMES
                    if name in reader_namespace
                )
                pending = [
                    value for value in reader_namespace.values() if type(value) is FunctionType
                ]
                seen: set[int] = set()
                while pending:
                    candidate = pending.pop()
                    if id(candidate) in seen:
                        continue
                    seen.add(id(candidate))
                    closure = candidate.__closure__
                    if closure is None:
                        continue
                    for name, cell in zip(
                        candidate.__code__.co_freevars,
                        closure,
                        strict=True,
                    ):
                        try:
                            value = cell.cell_contents
                        except ValueError:
                            continue
                        if name == "claimed_authorization_recipe_finalized" and type(value) is bool:
                            gate_values += (value,)
                        elif type(value) is FunctionType:
                            pending.append(value)
            payload = {
                "status": "ok",
                "injected": injected,
                "mutated_key": mutated_key,
                "import_rejected": import_rejected,
                "gate_values": gate_values,
                "live_reader_exports": live_reader_exports,
            }
        except BaseException as error:
            payload = {
                "status": "error",
                "error_type": type(error).__name__,
                "error_message": str(error),
            }
        finally:
            if sys.monitoring.get_tool(tool_id) is not None:
                sys.monitoring.set_events(tool_id, 0)
                sys.monitoring.register_callback(
                    tool_id,
                    sys.monitoring.events.INSTRUCTION,
                    None,
                )
                sys.monitoring.free_tool_id(tool_id)
        try:
            os.write(
                write_descriptor,
                json.dumps(payload, sort_keys=True).encode("utf-8"),
            )
        finally:
            os.close(write_descriptor)
        os._exit(0)

    os.close(write_descriptor)
    try:
        encoded = bytearray()
        while chunk := os.read(read_descriptor, 65_536):
            encoded.extend(chunk)
    finally:
        os.close(read_descriptor)
        _, wait_status = os.waitpid(child_pid, 0)
    assert os.waitstatus_to_exitcode(wait_status) == 0
    decoded = json.loads(bytes(encoded))
    assert type(decoded) is dict
    return cast(dict[str, object], decoded)


def _projection_proof_reachable_instruction_names(
    module_code: CodeType,
    entrypoint_name: str,
) -> frozenset[str]:
    pending = [module_code]
    code_by_name: dict[str, CodeType] = {}
    while pending:
        candidate = pending.pop()
        code_by_name.setdefault(candidate.co_name, candidate)
        pending.extend(constant for constant in candidate.co_consts if type(constant) is CodeType)
    assert entrypoint_name in code_by_name
    reachable = [code_by_name[entrypoint_name]]
    seen: set[int] = set()
    instruction_names: set[str] = set()
    while reachable:
        candidate = reachable.pop()
        if id(candidate) in seen:
            continue
        seen.add(id(candidate))
        for instruction in dis.get_instructions(candidate):
            if type(instruction.argval) is not str:
                continue
            instruction_names.add(instruction.argval)
            dependency = code_by_name.get(instruction.argval)
            if dependency is not None:
                reachable.append(dependency)
    return frozenset(instruction_names)


def _run_fresh_projection_final_gate_interruption(
    *,
    boundary: str,
    occurrence: int,
    failure_type: type[BaseException],
) -> dict[str, object]:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    target_code, target_offset = _projection_final_gate_code_and_offset(boundary)
    target_filename = target_code.co_filename
    target_name = target_code.co_name
    target_first_line = target_code.co_firstlineno
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through the pipe
        os.close(read_descriptor)
        interruption: BaseException = (
            SystemExit(179) if failure_type is SystemExit else KeyboardInterrupt()
        )
        observed_occurrences = 0
        injected = False
        tool_id = next(
            candidate
            for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
            if sys.monitoring.get_tool(candidate) is None
        )
        payload: dict[str, object]
        try:
            _forget_projection_seal_modules_in_child()
            sys.monitoring.use_tool_id(
                tool_id,
                f"trusted-time-projection-final-gate-{boundary}-test",
            )

            def interrupt_final_gate(
                code: CodeType,
                instruction_offset: int,
            ) -> None:
                nonlocal injected, observed_occurrences
                if (
                    injected
                    or code.co_filename != target_filename
                    or code.co_name != target_name
                    or code.co_firstlineno != target_first_line
                    or instruction_offset != target_offset
                ):
                    return
                current_occurrence = observed_occurrences
                observed_occurrences += 1
                if current_occurrence == occurrence:
                    injected = True
                    raise interruption

            sys.monitoring.register_callback(
                tool_id,
                sys.monitoring.events.INSTRUCTION,
                interrupt_final_gate,
            )
            sys.monitoring.set_events(tool_id, sys.monitoring.events.INSTRUCTION)
            raised_exact = False
            try:
                importlib.import_module(_PROJECTION_CONTROLLER_OUTCOME_MODULE)
            except BaseException as error:
                raised_exact = error is interruption

            fresh_reader = sys.modules.get(_PROJECTION_READER_MODULE)
            live_exports: tuple[str, ...] = ()
            gate_values: dict[str, bool] = {}
            if fresh_reader is not None:
                reader_namespace = type(fresh_reader).__getattribute__(
                    fresh_reader,
                    "__dict__",
                )
                assert type(reader_namespace) is dict
                live_exports = tuple(
                    name
                    for name in _PROJECTION_READER_STAGING_EXPORT_NAMES
                    if name in reader_namespace
                )
                for global_name, value in reader_namespace.items():
                    if type(value) is not FunctionType:
                        continue
                    for nonlocal_name, nonlocal_value in inspect.getclosurevars(
                        value
                    ).nonlocals.items():
                        if (
                            type(nonlocal_value) is bool
                            and "projection" in nonlocal_name
                            and ("finalized" in nonlocal_name or "ready" in nonlocal_name)
                        ):
                            gate_values[f"{global_name}:{nonlocal_name}"] = nonlocal_value
            payload = {
                "status": "ok",
                "injected": injected,
                "raised_exact": raised_exact,
                "observed_occurrences": observed_occurrences,
                "reader_present": fresh_reader is not None,
                "live_exports": live_exports,
                "gate_values": gate_values,
            }
        except BaseException as error:
            payload = {
                "status": "error",
                "error_type": type(error).__name__,
                "error_message": str(error),
            }
        finally:
            if sys.monitoring.get_tool(tool_id) is not None:
                sys.monitoring.set_events(tool_id, 0)
                sys.monitoring.register_callback(
                    tool_id,
                    sys.monitoring.events.INSTRUCTION,
                    None,
                )
                sys.monitoring.free_tool_id(tool_id)
        try:
            os.write(
                write_descriptor,
                json.dumps(payload, sort_keys=True).encode("utf-8"),
            )
        finally:
            os.close(write_descriptor)
        os._exit(0)

    os.close(write_descriptor)
    try:
        encoded = bytearray()
        while chunk := os.read(read_descriptor, 65_536):
            encoded.extend(chunk)
    finally:
        os.close(read_descriptor)
        _, wait_status = os.waitpid(child_pid, 0)
    assert os.waitstatus_to_exitcode(wait_status) == 0
    decoded = json.loads(bytes(encoded))
    assert type(decoded) is dict
    return cast(dict[str, object], decoded)


