def test_claimed_bridge_final_gate_follows_cross_module_export_retirement() -> None:
    _require_coherent_projection_seal_reader()
    reader_path = Path(cast(str, reader.__file__))
    reader_module_code = compile(
        reader_path.read_text(encoding="utf-8"),
        os.fspath(reader_path),
        "exec",
    )
    builder_code = _nested_code(reader_module_code, "_build_observation_sealer")
    finalizer_code = _nested_code(builder_code, "finalize_claimed_authorization_recipe")
    consumer_code = _nested_code(
        builder_code,
        "consume_claimed_recovery_binder_authorization",
    )
    assert _CLAIMED_BRIDGE_READER_STAGING_EXPORT_NAMES in builder_code.co_consts
    assert _CLAIMED_BRIDGE_CALLER_STAGING_EXPORT_NAMES in builder_code.co_consts

    finalizer_instructions = list(dis.get_instructions(finalizer_code))
    final_gate_stores = [
        instruction.offset
        for instruction in finalizer_instructions
        if instruction.opname in {"STORE_DEREF", "STORE_FAST"}
        and instruction.argval == "claimed_authorization_recipe_finalized"
    ]
    assert len(final_gate_stores) == 1
    final_gate_offset = final_gate_stores[0]
    retirement_offsets: list[int] = []
    for index, instruction in enumerate(finalizer_instructions):
        if instruction.argval not in {"_dict_pop", "_dict_get"}:
            continue
        call_index = next(
            candidate
            for candidate in range(index + 1, len(finalizer_instructions))
            if finalizer_instructions[candidate].opname == "CALL"
        )
        retirement_offsets.append(finalizer_instructions[call_index].offset)
    assert len(retirement_offsets) >= 4
    assert max(retirement_offsets) < final_gate_offset
    return_offsets = [
        instruction.offset
        for instruction in finalizer_instructions
        if instruction.opname == "RETURN_VALUE"
    ]
    assert return_offsets
    assert final_gate_offset < max(return_offsets)

    consumer_names = {
        cast(str, instruction.argval)
        for instruction in dis.get_instructions(consumer_code)
        if type(instruction.argval) is str
    }
    assert "claimed_authorization_recipe_finalized" in consumer_names
    assert "claimed_authorization_recipe_staged" not in consumer_names

    claimed_path = Path(cast(str, claimed_fence.__file__))
    claimed_module_code = compile(
        claimed_path.read_text(encoding="utf-8"),
        os.fspath(claimed_path),
        "exec",
    )
    claimed_instructions = list(dis.get_instructions(claimed_module_code))
    finalizer_load_index = max(
        index
        for index, instruction in enumerate(claimed_instructions)
        if instruction.argval == "_finalize_claimed_fence_recovery_binder_recipe"
    )
    finalizer_call_index = next(
        index
        for index in range(finalizer_load_index + 1, len(claimed_instructions))
        if claimed_instructions[index].opname == "CALL"
    )
    assert claimed_instructions[finalizer_call_index + 1].opname != "STORE_NAME"
    deleted_after_finalizer = {
        cast(str, instruction.argval)
        for instruction in claimed_instructions[finalizer_call_index + 1 :]
        if instruction.opname in {"DELETE_GLOBAL", "DELETE_NAME"}
        and type(instruction.argval) is str
    }
    assert set(_CLAIMED_BRIDGE_CALLER_STAGING_EXPORT_NAMES) <= (deleted_after_finalizer)


