def _sealed_claim_owner_registration_boundary(
    *,
    function_name: str,
    callable_name: str,
    boundary: str,
) -> tuple[Callable[..., object], int]:
    target = _sealed_claim_native_proof_functions()[function_name]
    instructions = list(dis.get_instructions(target))
    load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname
        in {
            "LOAD_DEREF",
            "LOAD_FAST",
            "LOAD_GLOBAL",
        }
        and instruction.argval == callable_name
    )
    call_index = next(
        index
        for index in range(load_index + 1, len(instructions))
        if instructions[index].opname == "CALL"
    )
    candidate_store_index = next(
        index
        for index in range(call_index + 1, len(instructions))
        if instructions[index].opname == "STORE_FAST"
        and type(instructions[index].argval) is str
        and ("candidate" in instructions[index].argval or "owner" in instructions[index].argval)
    )
    candidate_name = cast(str, instructions[candidate_store_index].argval)
    if boundary == "call_to_store":
        return target, instructions[candidate_store_index].offset
    candidate_clear_index = next(
        index
        for index in range(candidate_store_index + 1, len(instructions))
        if instructions[index].opname == "STORE_FAST"
        and instructions[index].argval == candidate_name
        and instructions[index - 1].opname == "LOAD_CONST"
        and instructions[index - 1].argval is None
    )
    append_end_index = next(
        (
            index
            for index in range(candidate_store_index + 1, candidate_clear_index)
            if instructions[index].opname == "BINARY_OP" and instructions[index].argrepr == "+="
        ),
        None,
    )
    if append_end_index is None:
        append_load_index = next(
            index
            for index in range(candidate_store_index + 1, candidate_clear_index)
            if instructions[index].argval == "append"
        )
        append_end_index = next(
            index
            for index in range(append_load_index + 1, candidate_clear_index)
            if instructions[index].opname == "CALL"
        )
    if boundary == "store_to_append":
        return target, instructions[candidate_store_index + 1].offset
    assert boundary == "append_to_clear"
    return target, instructions[append_end_index + 1].offset


def _sealed_claim_body_exception_boundary(
    *,
    function_name: str,
    boundary: str,
) -> tuple[Callable[..., object], int]:
    target = _sealed_claim_native_proof_functions()[function_name]
    instructions = list(dis.get_instructions(target))
    primary_store_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname == "STORE_DEREF"
        and instruction.argval == "primary_error"
        and index > 0
        and instructions[index - 1].opname == "LOAD_FAST"
        and instructions[index - 1].argval == "error"
    )
    error_store_index = next(
        index
        for index in range(primary_store_index - 1, -1, -1)
        if instructions[index].opname == "STORE_FAST" and instructions[index].argval == "error"
    )
    pop_except_index = next(
        index
        for index in range(primary_store_index + 1, len(instructions))
        if instructions[index].opname == "POP_EXCEPT"
    )
    cleanup_handoff_index = next(
        index
        for index in range(pop_except_index + 1, len(instructions))
        if instructions[index].opname == "JUMP_BACKWARD"
    )
    offsets = {
        "error_store": instructions[error_store_index].offset,
        "primary_store": instructions[primary_store_index].offset,
        "pop_except": instructions[pop_except_index].offset,
        "cleanup_handoff": instructions[cleanup_handoff_index].offset,
    }
    return target, offsets[boundary]


def _rewrite_claim_artifact_in_place_same_size(
    artifact_path: Path,
    original: bytes,
) -> None:
    assert original
    replacement = bytes((original[0] ^ 1,)) + original[1:]
    assert replacement != original
    assert len(replacement) == len(original)
    descriptor = os.open(artifact_path, os.O_WRONLY)
    try:
        assert os.write(descriptor, replacement) == len(replacement)
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    assert artifact_path.stat().st_size == len(original)


def _path_has_no_cached_string(candidate: Path) -> bool:
    try:
        object.__getattribute__(candidate, "_str")
    except AttributeError:
        return True
    return False


def _nested_json_mappings(
    value: object,
    path: tuple[str | int, ...] = (),
) -> tuple[tuple[tuple[str | int, ...], dict[str, object]], ...]:
    mappings: tuple[tuple[tuple[str | int, ...], dict[str, object]], ...] = ()
    if type(value) is dict:
        exact = cast(dict[str, object], value)
        mappings += ((path, exact),)
        for key, item in exact.items():
            mappings += _nested_json_mappings(item, (*path, key))
    elif type(value) is list:
        for index, item in enumerate(cast(list[object], value)):
            mappings += _nested_json_mappings(item, (*path, index))
    return mappings


def _json_path_parent(
    root: dict[str, object],
    path: tuple[str | int, ...],
) -> tuple[dict[str, object] | list[object], str | int]:
    assert path
    current: object = root
    for component in path[:-1]:
        if type(component) is str:
            assert type(current) is dict
            current = cast(dict[str, object], current)[component]
        else:
            assert type(current) is list
            current = cast(list[object], current)[component]
    assert type(current) in {dict, list}
    return cast(dict[str, object] | list[object], current), path[-1]


def _rebalance_claim_payload_hashes(
    payload: dict[str, object],
    *,
    protected_path: tuple[str | int, ...],
) -> None:
    claim = payload.get("claim")
    if type(claim) is not dict:
        return
    exact_claim = cast(dict[str, object], claim)
    for child_name, hash_name in (
        ("approval", "approval_sha256"),
        ("reauthentication", "reauthentication_sha256"),
    ):
        child = exact_claim.get(child_name)
        hash_path = ("claim", hash_name)
        if type(child) is dict and protected_path != hash_path:
            exact_claim[hash_name] = hashlib.sha256(
                claim_persistence.canonical_first_enrollment_json_bytes(child)
            ).hexdigest()
    if protected_path != ("claim_projection_sha256",):
        payload["claim_projection_sha256"] = hashlib.sha256(
            claim_persistence.canonical_first_enrollment_json_bytes(exact_claim)
        ).hexdigest()


def _recursive_claim_payload_mutations(
    original: dict[str, object],
) -> tuple[tuple[str, dict[str, object]], ...]:
    mutations: tuple[tuple[str, dict[str, object]], ...] = ()
    for mapping_path, mapping in _nested_json_mappings(original):
        if not mapping:
            continue
        mapping_label = ".".join(map(str, mapping_path)) or "root"
        first_key = sorted(mapping)[0]
        for mutation_kind in ("missing", "extra", "wrong_type", "value"):
            candidate = deepcopy(original)
            candidate_parent, candidate_key = _json_path_parent(
                candidate,
                (*mapping_path, first_key),
            )
            assert type(candidate_parent) is dict
            exact_parent = cast(dict[str, object], candidate_parent)
            protected_path = (*mapping_path, first_key)
            if mutation_kind == "missing":
                del exact_parent[cast(str, candidate_key)]
            elif mutation_kind == "extra":
                exact_mapping_parent, _ = _json_path_parent(
                    candidate,
                    (*mapping_path, first_key),
                )
                assert type(exact_mapping_parent) is dict
                cast(dict[str, object], exact_mapping_parent)["unexpected_projection_field"] = False
                protected_path = (*mapping_path, "unexpected_projection_field")
            elif mutation_kind == "wrong_type":
                exact_parent[cast(str, candidate_key)] = []
            else:
                current = exact_parent[cast(str, candidate_key)]
                if type(current) is bool:
                    replacement: object = not current
                elif type(current) is int:
                    replacement = current + 1
                elif type(current) is str:
                    replacement = "invalid-projection-value"
                elif current is None:
                    replacement = "unexpected-non-null"
                else:
                    replacement = False
                exact_parent[cast(str, candidate_key)] = replacement
            _rebalance_claim_payload_hashes(
                candidate,
                protected_path=protected_path,
            )
            mutations += ((f"{mapping_label}:{mutation_kind}", candidate),)

        crosslink_key = next(
            (key for key in sorted(mapping) if key == "operation_id" or key.endswith("_sha256")),
            None,
        )
        if crosslink_key is not None:
            candidate = deepcopy(original)
            candidate_parent, candidate_key = _json_path_parent(
                candidate,
                (*mapping_path, crosslink_key),
            )
            assert type(candidate_parent) is dict
            cast(dict[str, object], candidate_parent)[cast(str, candidate_key)] = (
                "00000000-0000-4000-8000-000000000001"
                if crosslink_key == "operation_id"
                else "e" * 64
            )
            protected_path = (*mapping_path, crosslink_key)
            _rebalance_claim_payload_hashes(
                candidate,
                protected_path=protected_path,
            )
            mutations += ((f"{mapping_label}:crosslink", candidate),)
    return mutations


def _retained_claim_with_payload(
    retained: RetainedTrustedTimePostEnrollmentStartClaim,
    payload: dict[str, object],
) -> RetainedTrustedTimePostEnrollmentStartClaim:
    encoded = claim_persistence.canonical_first_enrollment_json_bytes(payload)
    retained.artifact_path.write_bytes(encoded)
    retained.artifact_path.chmod(0o600)
    file_descriptor = os.open(retained.artifact_path, os.O_RDONLY)
    try:
        os.fsync(file_descriptor)
    finally:
        os.close(file_descriptor)
    directory_descriptor = os.open(retained.artifact_path.parent, os.O_RDONLY)
    try:
        os.fsync(directory_descriptor)
    finally:
        os.close(directory_descriptor)
    candidate = object.__new__(RetainedTrustedTimePostEnrollmentStartClaim)
    object.__setattr__(candidate, "claim", retained.claim)
    object.__setattr__(
        candidate,
        "operation_id",
        payload.get("operation_id", retained.operation_id),
    )
    object.__setattr__(
        candidate,
        "claim_projection_sha256",
        payload.get(
            "claim_projection_sha256",
            retained.claim_projection_sha256,
        ),
    )
    object.__setattr__(candidate, "artifact_sha256", hashlib.sha256(encoded).hexdigest())
    object.__setattr__(candidate, "artifact_path", retained.artifact_path)
    object.__setattr__(candidate, "encoded", encoded)
    object.__setattr__(
        candidate,
        "file_identity",
        claim_persistence._stable_file_identity(retained.artifact_path.stat()),
    )
    return candidate


def test_sealed_path_snapshot_accepts_exact_root_and_trusted_time_crossbinding() -> None:
    _require_coherent_projection_seal_reader()
    functions = _sealed_claim_native_proof_functions()
    path_snapshot = functions["sealed_path_snapshot"]
    public_roots = functions["sealed_public_roots"]
    root = Path("/")
    artifact_directory = Path("/trusted-time")
    assert _path_has_no_cached_string(root)
    assert _path_has_no_cached_string(artifact_directory)

    assert path_snapshot(root) == ("/", ("/",), ())
    assert path_snapshot(artifact_directory) == (
        "/trusted-time",
        ("/trusted-time",),
        ("trusted-time",),
    )
    assert public_roots(artifact_directory, root) == (
        "/trusted-time",
        "/",
        ("trusted-time",),
    )


