def test_sealed_claim_native_proof_accepts_permissive_ancestors_and_uncached_paths(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _require_coherent_projection_seal_reader()
    permissive_parent = tmp_path / "permissive-ancestor"
    permissive_parent.mkdir(mode=0o755)
    permissive_parent.chmod(0o755)
    issuer, _ = _open_issuer(monkeypatch, permissive_parent)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    fresh_artifact_directory = Path(os.fspath(artifact_directory))
    fresh_ignored_root = Path(os.fspath(ignored_root))
    assert stat.S_IMODE(permissive_parent.stat().st_mode) == 0o755
    assert stat.S_IMODE(ignored_root.stat().st_mode) == 0o700
    assert stat.S_IMODE(artifact_directory.stat().st_mode) == 0o700
    assert _path_has_no_cached_string(fresh_artifact_directory)
    assert _path_has_no_cached_string(fresh_ignored_root)

    projection = _sealed_claim_durable_projection_test_seam()(
        retained,
        fresh_artifact_directory,
        fresh_ignored_root,
    )

    assert type(projection) is tuple
    assert len(cast(tuple[object, ...], projection)) == 11
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def test_sealed_claim_semantics_reject_every_recursive_schema_mutation(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    decoded = json.loads(retained.encoded)
    assert type(decoded) is dict
    original_payload = cast(dict[str, object], decoded)
    mutations = _recursive_claim_payload_mutations(original_payload)
    assert mutations
    durable_projection = _sealed_claim_durable_projection_test_seam()
    try:
        for label, payload in mutations:
            candidate = _retained_claim_with_payload(retained, payload)
            assert (
                durable_projection(
                    candidate,
                    artifact_directory,
                    ignored_root,
                )
                is None
            ), label
    finally:
        _retained_claim_with_payload(retained, original_payload)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


