def test_sealed_claim_native_proof_rejects_same_size_in_place_rewrite_at_stop_gate(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    seam: str,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
