@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize(
    ("owner_scope", "parent_name", "cleanup_name"),
    [
        ("file", "sealed_read_regular", "finish_read_cleanup_once"),
        (
            "directories",
            "sealed_claim_artifact_material",
            "finish_claim_material_cleanup_once",
        ),
    ],
)
def test_sealed_claim_cleanup_py_return_to_store_preserves_exact_async_and_closes(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
    owner_scope: str,
    parent_name: str,
    cleanup_name: str,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    cleanup_parent = _sealed_claim_native_proof_functions()[parent_name]
    cleanup_code = _nested_code(cleanup_parent, cleanup_name)
    failure: BaseException = SystemExit(189) if failure_type is SystemExit else KeyboardInterrupt()
    injected = False

    def interrupt_cleanup_return(*_: object) -> None:
        nonlocal injected
        if not injected:
            injected = True
            raise failure

    descriptors_before = _open_descriptor_count()
    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(
        tool_id,
        f"trusted-time-sealed-claim-{owner_scope}-cleanup-return-test",
    )
    try:
        sys.monitoring.register_callback(
            tool_id,
            sys.monitoring.events.PY_RETURN,
            interrupt_cleanup_return,
        )
        sys.monitoring.set_local_events(
            tool_id,
            cleanup_code,
            sys.monitoring.events.PY_RETURN,
        )
        with pytest.raises(failure_type) as retained_interruption:
            _sealed_claim_durable_projection_test_seam()(
                retained,
                artifact_directory,
                ignored_root,
            )
        assert retained_interruption.value is failure
    finally:
        sys.monitoring.set_local_events(tool_id, cleanup_code, 0)
        sys.monitoring.register_callback(
            tool_id,
            sys.monitoring.events.PY_RETURN,
            None,
        )
        sys.monitoring.free_tool_id(tool_id)
    assert injected is True
    gc.collect()
    assert _open_descriptor_count() == descriptors_before
    _close_and_assert_launch_lock_is_reacquirable(issuer)


