def test_sealed_claim_native_proof_orders_file_and_directory_durability_checks() -> None:
    _require_coherent_projection_seal_reader()
    functions = _sealed_claim_native_proof_functions()
    read_regular = functions["sealed_read_regular"]
    claim_material = functions["sealed_claim_artifact_material"]
    read_names = [
        instruction.argval
        for instruction in dis.get_instructions(read_regular)
        if instruction.opname
        in {
            "LOAD_DEREF",
            "LOAD_FAST",
            "LOAD_GLOBAL",
        }
    ]
    assert read_names.index("_native_owner_fsync") < read_names.index("_native_owner_read")
    durable_instructions = list(dis.get_instructions(claim_material))
    read_index = next(
        index
        for index, instruction in enumerate(durable_instructions)
        if instruction.argval == "sealed_read_regular"
    )
    post_read_statat_indices = [
        index
        for index in range(read_index + 1, len(durable_instructions))
        if durable_instructions[index].argval == "_native_owner_statat"
    ]
    directory_fsync_index = next(
        index
        for index in range(read_index + 1, len(durable_instructions))
        if durable_instructions[index].argval == "_native_owner_fsync"
    )
    final_inventory_index = max(
        index
        for index in range(read_index + 1, len(durable_instructions))
        if durable_instructions[index].argval == "sealed_inventory_snapshot"
    )
    assert len(post_read_statat_indices) >= 2
    assert read_index < post_read_statat_indices[0] < directory_fsync_index
    assert directory_fsync_index < final_inventory_index < post_read_statat_indices[-1]


