def test_sealed_claim_native_helpers_never_return_owner_or_error_objects() -> None:
    _require_coherent_projection_seal_reader()
    reader_path = Path(cast(str, reader.__file__))
    tree = ast.parse(reader_path.read_text(encoding="utf-8"), filename=os.fspath(reader_path))
    helper_names = {
        "close_sealed_native_owner_once",
        "close_sealed_native_owners_once",
        "finish_claim_material_cleanup_once",
        "finish_read_cleanup_once",
        "sealed_inventory_snapshot",
        "sealed_native_owners_are_closed",
        "sealed_claim_artifact_material",
        "sealed_read_regular",
        "sealed_retained_claim_durable_projection",
    }
    helpers = {
        node.name: node
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name in helper_names
    }
    assert helpers.keys() == helper_names
    forbidden_error_return_helpers = {
        node.name
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name in {"cleanup_sealed_owners", "reduce_sealed_errors"}
    }
    assert not forbidden_error_return_helpers
    forbidden_fragments = ("candidate", "error", "exception", "owner")
    for helper_name, helper in helpers.items():
        if helper.returns is not None:
            assert "BaseException" not in ast.unparse(helper.returns), helper_name
            assert "OwnedFileDescriptor" not in ast.unparse(helper.returns), helper_name
        for node in ast.walk(helper):
            if not isinstance(node, (ast.Return, ast.Yield, ast.YieldFrom)):
                continue
            if node.value is None:
                continue
            returned_names = {
                candidate.id
                for candidate in ast.walk(node.value)
                if isinstance(candidate, ast.Name)
            }
            assert not any(
                fragment in name for name in returned_names for fragment in forbidden_fragments
            ), (helper_name, returned_names)


def test_sealed_claim_native_closure_has_no_bare_global_dependencies() -> None:
    _require_coherent_projection_seal_reader()
    bare_globals: list[tuple[str, str]] = []
    seen: set[int] = set()
    pending = [function.__code__ for function in _sealed_claim_native_proof_functions().values()]
    pending.append(
        _nested_code(
            reader._build_observation_sealer,
            "sealed_json_object_items",
        )
    )
    pending.append(
        cast(
            FunctionType,
            _sealed_projection_function_test_seam("sealed_retained_claim_references_claim"),
        ).__code__
    )
    while pending:
        code = pending.pop()
        if id(code) in seen:
            continue
        seen.add(id(code))
        bare_globals.extend(
            (code.co_name, cast(str, instruction.argval))
            for instruction in dis.get_instructions(code)
            if instruction.opname == "LOAD_GLOBAL" and type(instruction.argval) is str
        )
        pending.extend(constant for constant in code.co_consts if type(constant) is CodeType)
    assert not bare_globals


