def test_all_exported_sealer_roots_have_zero_global_or_import_surface() -> None:
    _require_coherent_projection_seal_reader()
    assert len(_SEALER_EXPORTED_ROOT_NAMES) == 59
    assert len(set(_SEALER_EXPORTED_ROOT_NAMES)) == 59
    reader_path = Path(cast(str, reader.__file__))
    module_code = compile(
        reader_path.read_text(encoding="utf-8"),
        os.fspath(reader_path),
        "exec",
    )
    builder_code = _nested_code(module_code, "_build_observation_sealer")
    direct_codes = {
        constant.co_name: constant
        for constant in builder_code.co_consts
        if type(constant) is CodeType and constant.co_name in _SEALER_EXPORTED_ROOT_NAMES
    }
    assert direct_codes.keys() == set(_SEALER_EXPORTED_ROOT_NAMES)

    all_codes: list[CodeType] = [builder_code]
    codes_by_name: dict[str, list[CodeType]] = {}
    seen_all: set[int] = set()
    while all_codes:
        code = all_codes.pop()
        if id(code) in seen_all:
            continue
        seen_all.add(id(code))
        codes_by_name.setdefault(code.co_name, []).append(code)
        all_codes.extend(constant for constant in code.co_consts if type(constant) is CodeType)

    reached_code_ids: set[int] = set()
    failures: dict[str, object] = {}
    for root_name, root_code in direct_codes.items():
        pending = [root_code]
        seen: set[int] = set()
        globals_found: list[tuple[str, str]] = []
        imports_found: list[tuple[str, str]] = []
        while pending:
            code = pending.pop()
            if id(code) in seen:
                continue
            seen.add(id(code))
            reached_code_ids.add(id(code))
            instructions = list(dis.get_instructions(code))
            globals_found.extend(
                (code.co_name, cast(str, instruction.argval))
                for instruction in instructions
                if instruction.opname == "LOAD_GLOBAL" and type(instruction.argval) is str
            )
            imports_found.extend(
                (code.co_name, cast(str, instruction.argval))
                for instruction in instructions
                if instruction.opname in {"IMPORT_FROM", "IMPORT_NAME"}
                and type(instruction.argval) is str
            )
            pending.extend(constant for constant in code.co_consts if type(constant) is CodeType)
            referenced_names = {
                cast(str, instruction.argval)
                for instruction in instructions
                if instruction.opname in {"LOAD_CLOSURE", "LOAD_DEREF"}
                and type(instruction.argval) is str
            }
            for referenced_name in referenced_names:
                pending.extend(codes_by_name.get(referenced_name, ()))
        if globals_found or imports_found:
            failures[root_name] = {
                "globals": globals_found,
                "imports": imports_found,
            }
    assert len(reached_code_ids) >= 260
    assert not failures


def test_choreography_authority_roots_have_zero_runtime_global_or_import_surface() -> None:
    _require_coherent_projection_seal_reader()
    roots = _runtime_sealer_authority_roots()
    allowed_globals: frozenset[str] = frozenset()
    failures: dict[str, object] = {}
    for root_name, root in roots.items():
        global_loads, imports = _recursive_function_graph_instruction_manifest(root)
        unexpected_globals = [
            (location, name) for location, name in global_loads if name not in allowed_globals
        ]
        if unexpected_globals or imports:
            failures[root_name] = {
                "globals": unexpected_globals,
                "imports": imports,
            }
    assert not failures


def test_choreography_authority_closure_does_not_capture_mutable_callable_aliases() -> None:
    _require_coherent_projection_seal_reader()
    mutable_aliases = {
        "normpath": os.path.normpath,
        "token_bytes": secrets.token_bytes,
        "canonical_json": claim_persistence.canonical_first_enrollment_json_bytes,
        "environment_sha256": reader._environment_identity_sha256,
        "daemon_registration_validator": (reader._require_daemon_identity_registration),
        "typing_cast": cast,
        "preferred_control_error": reader._preferred_control_error,
        "salvage_loader": (claim_persistence._salvage_retained_post_enrollment_start_claim),
        "current_thread": threading.current_thread,
    }
    assert all(type(alias) is FunctionType for alias in mutable_aliases.values())
    observed_function_ids: set[int] = set()
    for root in _runtime_sealer_authority_roots().values():
        _recursive_function_graph_instruction_manifest(
            root,
            observed_function_ids=observed_function_ids,
        )
    escaped = {
        name: alias for name, alias in mutable_aliases.items() if id(alias) in observed_function_ids
    }
    assert not escaped


def test_choreography_class_authority_surface_is_native_and_has_no_python_escape() -> None:
    _require_coherent_projection_seal_reader()
    assert len(_CHOREOGRAPHY_DYNAMIC_SELF_HELPER_TARGETS) == 23
    assert len(_CHOREOGRAPHY_CLASS_AUTHORITY_METHOD_NAMES) == 49
    assert len(set(_CHOREOGRAPHY_CLASS_AUTHORITY_METHOD_NAMES)) == 49
    issuer_type = reader.TrustedTimePostEnrollmentTopologyObservationIssuer
    namespace = type.__getattribute__(issuer_type, "__dict__")
    reader_namespace = type(reader).__getattribute__(reader, "__dict__")
    assert not (set(_CHOREOGRAPHY_CLASS_MUTABLE_DEFAULT_ALIAS_NAMES) & set(reader_namespace))
    descriptors = {name: namespace[name] for name in _CHOREOGRAPHY_CLASS_AUTHORITY_METHOD_NAMES}
    assert descriptors.keys() == set(_CHOREOGRAPHY_CLASS_AUTHORITY_METHOD_NAMES)
    for name, descriptor in descriptors.items():
        assert type(descriptor) is not FunctionType
        assert descriptor.__objclass__ is issuer_type
        assert descriptor.__name__ == name
        for attribute in (
            "__closure__",
            "__code__",
            "__defaults__",
            "__dict__",
            "__globals__",
            "__kwdefaults__",
            "__reduce__",
            "__reduce_ex__",
            "__wrapped__",
        ):
            with pytest.raises(AttributeError):
                object.__getattribute__(descriptor, attribute)
        referents = gc.get_referents(descriptor)
        assert all(
            type(referent) not in {CellType, CodeType, FunctionType, dict} for referent in referents
        )
        with pytest.raises((AttributeError, pickle.PicklingError, TypeError)):
            pickle.dumps(descriptor)
        with pytest.raises((AttributeError, TypeError)):
            copy(descriptor)
        with pytest.raises((AttributeError, TypeError)):
            deepcopy(descriptor)


def test_native_issuer_protocol_and_failclosed_tail_have_no_python_fallthrough() -> None:
    _require_coherent_projection_seal_reader()
    assert len(_NATIVE_ISSUER_FULL_CALLABLE_NAMES) == 84
    assert len(set(_NATIVE_ISSUER_FULL_CALLABLE_NAMES)) == 84
    assert len(_NATIVE_ISSUER_PROTOCOL_METHOD_NAMES) == 13
    assert len(_NATIVE_ISSUER_FAILCLOSED_TAIL_METHOD_NAMES) == 21
    assert _NATIVE_ISSUER_FULL_CALLABLE_NAMES[:13] == (_NATIVE_ISSUER_PROTOCOL_METHOD_NAMES)
    assert _NATIVE_ISSUER_FULL_CALLABLE_NAMES[62:83] == (
        _NATIVE_ISSUER_FAILCLOSED_TAIL_METHOD_NAMES
    )
    assert _NATIVE_ISSUER_FULL_CALLABLE_NAMES[41] == ("_reviewed_compose_create_payload")
    assert _NATIVE_ISSUER_FULL_CALLABLE_NAMES[83] == "close"
    assert set(_CHOREOGRAPHY_CLASS_AUTHORITY_METHOD_NAMES) < set(_NATIVE_ISSUER_FULL_CALLABLE_NAMES)
    assert (
        set(_NATIVE_ISSUER_PROTOCOL_METHOD_NAMES) & set(_NATIVE_ISSUER_FAILCLOSED_TAIL_METHOD_NAMES)
    ) == set()
    issuer_type = reader.TrustedTimePostEnrollmentTopologyObservationIssuer
    namespace = type.__getattribute__(issuer_type, "__dict__")
    assert set(_NATIVE_ISSUER_FULL_CALLABLE_NAMES) <= set(namespace)
    assert type(namespace["allocate_inert"]) is ClassMethodDescriptorType
    assert type(namespace["_reviewed_mutation_created_observation"]) is (GetSetDescriptorType)
    assert type(namespace["_reviewed_mutation_created_observation_sha256"]) is (
        GetSetDescriptorType
    )
    for index, name in enumerate(_NATIVE_ISSUER_FULL_CALLABLE_NAMES):
        descriptor = namespace[name]
        assert type(descriptor) is not FunctionType
        assert descriptor.__objclass__ is issuer_type
        assert descriptor.__name__ == name
        assert all(
            type(referent) not in {CellType, CodeType, FunctionType, dict}
            for referent in gc.get_referents(descriptor)
        )
        if index not in {2, 3}:
            assert callable(descriptor)

    reader_path = Path(cast(str, reader.__file__))
    tree = ast.parse(
        reader_path.read_text(encoding="utf-8"),
        filename=os.fspath(reader_path),
    )
    prototype = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef)
        and node.name == "TrustedTimePostEnrollmentTopologyObservationIssuer"
    )
    prototype_method_order = tuple(
        node.name
        for node in prototype.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    )
    assert prototype_method_order == _NATIVE_ISSUER_FULL_CALLABLE_NAMES
    assert (
        tuple(
            name for name in prototype_method_order if name in _NATIVE_ISSUER_PROTOCOL_METHOD_NAMES
        )
        == _NATIVE_ISSUER_PROTOCOL_METHOD_NAMES
    )
    assert (
        tuple(
            name
            for name in prototype_method_order
            if name in _NATIVE_ISSUER_FAILCLOSED_TAIL_METHOD_NAMES
        )
        == _NATIVE_ISSUER_FAILCLOSED_TAIL_METHOD_NAMES
    )


def test_native_issuer_weakref_callback_observes_inert_authority_after_dealloc(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer_type = reader.TrustedTimePostEnrollmentTopologyObservationIssuer
    callback_observations: list[tuple[object | None, bool, bool]] = []
    reference_holder: list[weakref.ReferenceType[object]] = []
    retained_tokens: list[object] = []

    def abandon_native_issuer() -> tuple[weakref.ReferenceType[object], str]:
        issuer, _ = _open_issuer(monkeypatch, tmp_path)
        ignored_root = os.fspath(issuer._ignored_root)

        def retain_scope_token(lease: object) -> None:
            retained_tokens.append(lease)

        issuer._run_exclusive_choreography(retain_scope_token)
        assert len(retained_tokens) == 1

        def owner_collected(reference: weakref.ReferenceType[object]) -> None:
            assert reference is reference_holder[0]
            assert reference() is None
            token_referents = gc.get_referents(retained_tokens[0])
            token_has_owner = any(type(referent) is issuer_type for referent in token_referents)
            replacement = _acquire_trusted_time_launch_lock(ignored_root)
            try:
                _validate_trusted_time_launch_lock(replacement)
                callback_observations.append((reference(), replacement.closed, token_has_owner))
            finally:
                replacement.close()

        issuer_reference = weakref.ref(issuer, owner_collected)
        reference_holder.append(issuer_reference)
        assert issuer_reference() is issuer
        return issuer_reference, ignored_root

    issuer_reference, ignored_root = abandon_native_issuer()
    for _ in range(4):
        gc.collect()
        if issuer_reference() is None:
            break

    assert issuer_reference() is None
    assert callback_observations == [(None, False, False)]
    assert len(retained_tokens) == 1
    token = retained_tokens[0]
    assert not hasattr(token, "__dict__")
    for attribute in ("binding", "generation", "owner", "snapshot", "state"):
        with pytest.raises(AttributeError):
            object.__getattribute__(token, attribute)
    replacement = _acquire_trusted_time_launch_lock(ignored_root)
    _validate_trusted_time_launch_lock(replacement)
    replacement.close()


def _authority_code_behavior_fingerprint(code: CodeType) -> tuple[object, ...]:
    def normalize(value: object) -> object:
        if type(value) is CodeType:
            return _authority_code_behavior_fingerprint(cast(CodeType, value))
        if type(value) is tuple:
            return tuple(normalize(item) for item in cast(tuple[object, ...], value))
        if type(value) is frozenset:
            return frozenset(normalize(item) for item in cast(frozenset[object], value))
        if value is None or type(value) in {bool, bytes, complex, float, int, str}:
            return value
        return (type(value).__name__, repr(value))

    return (
        code.co_argcount,
        code.co_posonlyargcount,
        code.co_kwonlyargcount,
        code.co_nlocals,
        code.co_stacksize,
        code.co_flags,
        code.co_code,
        tuple(normalize(value) for value in code.co_consts),
        code.co_names,
        code.co_varnames,
        code.co_freevars,
        code.co_cellvars,
    )


def test_original_python_authority_method_bodies_are_not_retained_or_cloned() -> None:
    _require_coherent_projection_seal_reader()
    reader_path = Path(cast(str, reader.__file__))
    module_code = compile(
        reader_path.read_text(encoding="utf-8"),
        os.fspath(reader_path),
        "exec",
    )
    class_code = _nested_code(
        module_code,
        "TrustedTimePostEnrollmentTopologyObservationIssuer",
    )
    original_codes = {
        candidate.co_name: candidate
        for candidate in class_code.co_consts
        if type(candidate) is CodeType
        and candidate.co_name in _CHOREOGRAPHY_CLASS_AUTHORITY_METHOD_NAMES
    }
    assert original_codes
    assert original_codes.keys() <= set(_CHOREOGRAPHY_CLASS_AUTHORITY_METHOD_NAMES)
    forbidden_fingerprints = {
        name: _authority_code_behavior_fingerprint(code) for name, code in original_codes.items()
    }
    forbidden_fingerprint_values = frozenset(forbidden_fingerprints.values())

    issuer_type = reader.TrustedTimePostEnrollmentTopologyObservationIssuer
    issuer_namespace = type.__getattribute__(issuer_type, "__dict__")
    reader_namespace = type(reader).__getattribute__(reader, "__dict__")
    descriptors = tuple(
        issuer_namespace[name] for name in _CHOREOGRAPHY_CLASS_AUTHORITY_METHOD_NAMES
    )
    directly_exposed = [
        (path, candidate)
        for path, values in (
            ("module", tuple(reader_namespace.values())),
            ("class", tuple(issuer_namespace.values())),
            (
                "descriptor",
                tuple(
                    referent
                    for descriptor in descriptors
                    for referent in gc.get_referents(descriptor)
                ),
            ),
        )
        for candidate in values
        if type(candidate) is FunctionType
        and _authority_code_behavior_fingerprint(
            type(candidate).__getattribute__(candidate, "__code__")
        )
        in forbidden_fingerprint_values
    ]
    assert not directly_exposed

    gc.collect()
    escaped_through_gc = [
        candidate
        for candidate in gc.get_objects()
        if type(candidate) is FunctionType
        and _authority_code_behavior_fingerprint(
            type(candidate).__getattribute__(candidate, "__code__")
        )
        in forbidden_fingerprint_values
    ]
    assert not escaped_through_gc
    escaped_cells: list[object] = []
    for candidate in gc.get_objects():
        if type(candidate) is not CellType:
            continue
        try:
            cell_value = candidate.cell_contents
        except ValueError:
            continue
        if (
            type(cell_value) is FunctionType
            and _authority_code_behavior_fingerprint(
                type(cell_value).__getattribute__(cell_value, "__code__")
            )
            in forbidden_fingerprint_values
        ) or (
            type(cell_value) is dict
            and any(
                type(value) is FunctionType
                and _authority_code_behavior_fingerprint(
                    type(value).__getattribute__(value, "__code__")
                )
                in forbidden_fingerprint_values
                for value in cell_value.values()
            )
        ):
            escaped_cells.append(candidate)
    assert not escaped_cells


@pytest.mark.parametrize("operation", ["set", "delete"])
def test_native_sealed_issuer_type_rejects_authority_method_mutation(
    operation: Literal["set", "delete"],
) -> None:
    _require_coherent_projection_seal_reader()
    issuer_type = reader.TrustedTimePostEnrollmentTopologyObservationIssuer
    namespace = type.__getattribute__(issuer_type, "__dict__")
    method_name = "_require_usable"
    original = namespace[method_name]
    mutation_succeeded = False
    try:
        with pytest.raises((AttributeError, TypeError)):
            if operation == "set":
                type.__setattr__(issuer_type, method_name, object())
            else:
                type.__delattr__(issuer_type, method_name)
        mutation_succeeded = namespace.get(method_name) is not original
    finally:
        if namespace.get(method_name) is not original:
            type.__setattr__(issuer_type, method_name, original)
    assert mutation_succeeded is False
    assert namespace[method_name] is original


