def test_native_issuer_publication_is_one_exact_static_type_with_no_prototype_escape() -> None:
    _require_coherent_projection_seal_reader()
    reader_namespace = type(reader).__getattribute__(reader, "__dict__")
    public_name = "TrustedTimePostEnrollmentTopologyObservationIssuer"
    issuer_type = reader_namespace[public_name]
    assert type(issuer_type) is type
    assert type.__getattribute__(issuer_type, "__module__") == reader.__name__
    assert type.__getattribute__(issuer_type, "__name__") == public_name
    assert type.__getattribute__(issuer_type, "__qualname__") == public_name
    flags = type.__getattribute__(issuer_type, "__flags__")
    assert type(flags) is int
    assert flags & (1 << 8)  # Py_TPFLAGS_IMMUTABLETYPE
    assert not flags & (1 << 9)  # Py_TPFLAGS_HEAPTYPE
    assert not flags & (1 << 10)  # Py_TPFLAGS_BASETYPE

    forbidden_fragments = (
        "issuer_manifest",
        "issuer_method",
        "issuer_prototype",
        "issuer_type_seal",
        "topology_issuer_install",
        "topology_issuer_stage",
    )
    escaped_names = {
        name
        for name in reader_namespace
        if any(fragment in name.lower() for fragment in forbidden_fragments)
    }
    assert not escaped_names

    duplicate_types = []
    for candidate in gc.get_objects():
        if type(candidate) is not type or candidate is issuer_type:
            continue
        try:
            candidate_module = type.__getattribute__(candidate, "__module__")
            candidate_name = type.__getattribute__(candidate, "__name__")
        except (AttributeError, TypeError):
            continue
        if candidate_module == reader.__name__ and candidate_name == public_name:
            duplicate_types.append(candidate)
    assert not duplicate_types


def test_native_issuer_stub_store_and_bottom_finalizer_form_one_publication_transaction() -> None:
    _require_coherent_projection_seal_reader()
    reader_path = Path(cast(str, reader.__file__))
    source = reader_path.read_text(encoding="utf-8")
    tree = ast.parse(source, filename=os.fspath(reader_path))
    public_name = "TrustedTimePostEnrollmentTopologyObservationIssuer"
    prototype = next(
        node for node in tree.body if isinstance(node, ast.ClassDef) and node.name == public_name
    )
    assert len(prototype.decorator_list) == 1
    assert not any(
        isinstance(node, ast.Attribute)
        and isinstance(node.value, ast.Name)
        and node.value.id == "self"
        for node in ast.walk(prototype)
    )

    module_code = compile(source, os.fspath(reader_path), "exec")
    instructions = list(dis.get_instructions(module_code))
    store_indices = [
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname == "STORE_NAME" and instruction.argval == public_name
    ]
    assert len(store_indices) == 1
    store_index = store_indices[0]
    decorator_call_index = max(
        index for index in range(store_index) if instructions[index].opname == "CALL"
    )
    assert all(
        instruction.opname in {"CACHE", "EXTENDED_ARG", "NOP", "STORE_NAME"}
        for instruction in instructions[decorator_call_index + 1 : store_index + 1]
    )

    call_indices = [
        index for index, instruction in enumerate(instructions) if instruction.opname == "CALL"
    ]
    assert call_indices[-1] > store_index
    finalizer_call_index = call_indices[-1]
    assert all(
        instruction.opname
        in {
            "CACHE",
            "EXTENDED_ARG",
            "LOAD_CONST",
            "NOP",
            "POP_TOP",
            "RETURN_VALUE",
        }
        for instruction in instructions[finalizer_call_index + 1 :]
    )


def test_native_authority_rejection_traceback_exposes_no_python_semantic_frame() -> None:
    _require_coherent_projection_seal_reader()
    issuer = reader.TrustedTimePostEnrollmentTopologyObservationIssuer.allocate_inert()
    with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError) as rejected:
        issuer._require_usable()
    traceback = rejected.value.__traceback__
    reader_filename = os.fspath(Path(cast(str, reader.__file__)).resolve())
    observed_frames = 0
    while traceback is not None:
        frame = traceback.tb_frame
        code = frame.f_code
        observed_frames += 1
        assert os.fspath(Path(code.co_filename).resolve()) != reader_filename
        assert all(type(value) not in {CellType, FunctionType} for value in frame.f_locals.values())
        traceback = traceback.tb_next
    assert observed_frames == 1


