@pytest.mark.parametrize(
    "value",
    [
        'quote:"',
        "backslash:\\",
        "short-controls:\b\f\n\r\t",
        "raw-controls:\x00\x01\x1f\x7f",
        "bmp:\u00e9\u2028\u6f22",
        "astral:\U0001f600\U0001f680",
    ],
    ids=("quote", "backslash", "short-controls", "raw-controls", "bmp", "astral"),
)
def test_sealed_environment_digest_matches_exact_legacy_json_bytes(
    value: str,
) -> None:
    _require_coherent_projection_seal_reader()
    payload = (
        ("DOCKER_HOST", "unix:///tmp/trusted-time-docker.sock"),
        ("LANG", value),
        ("PATH", "/usr/bin:/bin"),
    )
    exact_bytes = reader._EXACT_IMMUTABLE_JSON_SERIALIZER((0, payload))
    assert type(exact_bytes) is bytes
    assert not exact_bytes.endswith(b"\n")
    if value.startswith("raw-controls:"):
        assert b"\x7f" in exact_bytes
        assert b"\\u007f" not in exact_bytes
    elif value.startswith("bmp:"):
        assert b"\\u00e9\\u2028\\u6f22" in exact_bytes
    elif value.startswith("astral:"):
        assert b"\\ud83d\\ude00\\ud83d\\ude80" in exact_bytes
    expected = hashlib.sha256(exact_bytes).hexdigest()
    assert expected != hashlib.sha256(exact_bytes + b"\n").hexdigest()
    assert reader._environment_identity_sha256(payload) == expected
    sealed_digest = _sealed_projection_function_test_seam("sealed_environment_identity_sha256")(
        payload
    )
    assert sealed_digest == expected
    assert type(sealed_digest) is str
    assert len(cast(str, sealed_digest)) == 64


