def test_sealed_daemon_registration_matches_exact_ascii_regex_contract() -> None:
    _require_coherent_projection_seal_reader()
    sealed_validator = _sealed_projection_function_test_seam("sealed_require_daemon_registration")
    endpoint = "unix:///tmp/trusted-time-docker.sock"
    ascii_alphanumeric = frozenset("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz")
    for field_name, punctuation in (
        ("context", "_.-"),
        ("daemon", ":._-"),
    ):
        allowed_tail = ascii_alphanumeric | frozenset(punctuation)
        for codepoint in range(128):
            character = chr(codepoint)
            context_name = "A" + character if field_name == "context" else "ctx"
            daemon_id = "A" + character if field_name == "daemon" else "daemon"
            candidate = (
                "trusted-time-daemon-identity-registration-v1",
                context_name,
                endpoint,
                daemon_id,
            )
            if character in allowed_tail:
                assert reader._require_daemon_identity_registration(candidate) is candidate
                assert sealed_validator(candidate) is candidate
            else:
                with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
                    reader._require_daemon_identity_registration(candidate)
                with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
                    sealed_validator(candidate)

        for first_character in map(chr, range(128)):
            context_name = first_character + "A" if field_name == "context" else "ctx"
            daemon_id = first_character + "A" if field_name == "daemon" else "daemon"
            candidate = (
                "trusted-time-daemon-identity-registration-v1",
                context_name,
                endpoint,
                daemon_id,
            )
            if first_character in ascii_alphanumeric:
                assert reader._require_daemon_identity_registration(candidate) is candidate
                assert sealed_validator(candidate) is candidate
            else:
                with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
                    reader._require_daemon_identity_registration(candidate)
                with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
                    sealed_validator(candidate)


