@pytest.mark.parametrize("attack", ["module_relabel", "code_relabel"])
def test_choreography_salvage_ignores_mutable_loader_alias_ab(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    attack: Literal["module_relabel", "code_relabel"],
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    exact_loader = claim_persistence._salvage_retained_post_enrollment_start_claim
    assert type(exact_loader) is FunctionType
    assert (
        exact_loader.__code__.co_freevars
        == (_hostile_choreography_salvage_loader.__code__.co_freevars)
        == ()
    )

    def salvage_under_attack(lease: object, recovery_capability: object) -> Never:
        binder = _issue_registered_recovery_claim_binder(
            issuer,
            lease,
            recovery_capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        binder._checkpoint(
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        installed: RetainedTrustedTimePostEnrollmentStartClaim | None = None

        def retain_on_stack(
            candidate: object,
        ) -> RetainedTrustedTimePostEnrollmentStartClaim:
            nonlocal installed
            assert type(candidate) is RetainedTrustedTimePostEnrollmentStartClaim
            if installed is None:
                installed = candidate
            else:
                assert installed is candidate
            return installed

        with monkeypatch.context() as scoped:
            if attack == "module_relabel":
                scoped.setattr(
                    claim_persistence,
                    "_salvage_retained_post_enrollment_start_claim",
                    _hostile_choreography_salvage_loader,
                )
            else:
                scoped.setattr(
                    exact_loader,
                    "__code__",
                    _hostile_choreography_salvage_loader.__code__,
                )
            assert issuer._salvage_recovery_retention_claim_binder(
                binder,
                retained.claim,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
                retain_salvaged_claim=retain_on_stack,
            )

        state = _active_choreography_state(issuer)
        assert _choreography_state_value(state, "phase") == "armed"
        assert installed is not None
        assert _choreography_state_value(state, "retained_claim") is installed
        raise _RecoveryRetentionTerminal

    with pytest.raises(_RecoveryRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(salvage_under_attack)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize(
    "attack",
    ["module_relabel", "new_relabel", "init_relabel"],
)
@pytest.mark.parametrize(
    "authority_kind",
    ["lease", "recovery_capability", "binder", "post_effect_capability"],
)
def test_opaque_authority_allocation_ignores_mutable_class_methods(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    authority_kind: Literal[
        "lease",
        "recovery_capability",
        "binder",
        "post_effect_capability",
    ],
    attack: Literal["module_relabel", "new_relabel", "init_relabel"],
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    module_attribute = {
        "lease": "_TrustedTimePostEnrollmentTopologyChoreographyLease",
        "recovery_capability": ("_TrustedTimePostEnrollmentRecoveryRetentionCapability"),
        "binder": "_TrustedTimePostEnrollmentRecoveryClaimBinder",
        "post_effect_capability": ("_TrustedTimePostEnrollmentPostEffectOutcomeCapability"),
    }[authority_kind]
    exact_type = cast(type[object], getattr(reader, module_attribute))
    binder = object.__new__(exact_type) if authority_kind == "binder" else None

    def allocate_authority(lease: object, recovery_capability: object) -> object:
        if authority_kind == "lease":
            assert type(lease) is exact_type
            return "accepted"
        if authority_kind == "recovery_capability":
            assert type(recovery_capability) is exact_type
            return "accepted"
        if authority_kind == "binder":
            assert type(binder) is exact_type
            _register_recovery_claim_binder(
                issuer,
                lease,
                recovery_capability,
                cast(reader._TrustedTimePostEnrollmentRecoveryClaimBinder, binder),
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            state = _active_choreography_state(issuer)
            assert _choreography_state_value(state, "recovery_claim_binder") is binder
            raise _RecoveryRetentionTerminal

        _bind_registered_recovery_claim(
            issuer,
            lease,
            recovery_capability,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        post_effect_capability = _transition_registered_post_effect_retention(
            issuer,
            lease,
            recovery_capability,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        assert type(post_effect_capability) is exact_type
        raise _PostEffectRetentionTerminal

    with monkeypatch.context() as scoped:
        _install_mutable_authority_class_attack(
            scoped,
            module_attribute=module_attribute,
            exact_type=exact_type,
            attack=attack,
        )
        if authority_kind in {"lease", "recovery_capability"}:
            assert (
                issuer._run_exclusive_choreography_with_recovery_retention(allocate_authority)
                == "accepted"
            )
        else:
            terminal_type = (
                _RecoveryRetentionTerminal
                if authority_kind == "binder"
                else _PostEffectRetentionTerminal
            )
            with pytest.raises(terminal_type):
                issuer._run_exclusive_choreography_with_recovery_retention(allocate_authority)

    _close_and_assert_launch_lock_is_reacquirable(issuer)


