def test_sealed_reader_error_uses_captured_runtime_error_factory_not_class_call() -> None:
    _require_coherent_projection_seal_reader()
    sealed_reader_error = _sealed_projection_function_test_seam("sealed_reader_error")
    closure = inspect.getclosurevars(sealed_reader_error).nonlocals
    assert closure["_runtime_error_new"] is RuntimeError.__new__
    assert closure["_seal_error_type"] is (reader.TrustedTimePostEnrollmentTopologyReaderError)
    instructions = list(dis.get_instructions(sealed_reader_error))
    factory_load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname == "LOAD_DEREF" and instruction.argval == "_runtime_error_new"
    )
    class_load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname == "LOAD_DEREF" and instruction.argval == "_seal_error_type"
    )
    first_call_index = next(
        index for index, instruction in enumerate(instructions) if instruction.opname == "CALL"
    )
    assert factory_load_index < class_load_index < first_call_index
    assert all(instruction.opname != "LOAD_GLOBAL" for instruction in instructions)


@pytest.mark.parametrize("attack", ["new_relabel", "init_relabel"])
@pytest.mark.parametrize("primary_type", [KeyboardInterrupt, SystemExit])
def test_sealed_reader_error_constructor_attack_cannot_replace_pending_control(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    attack: Literal["new_relabel", "init_relabel"],
    primary_type: type[BaseException],
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    read_regular = _sealed_claim_native_proof_functions()["sealed_read_regular"]
    target_offset = _call_return_offset(
        read_regular,
        callable_name="_native_owner_fsync",
    )
    primary: BaseException = SystemExit(211) if primary_type is SystemExit else KeyboardInterrupt()
    secondary: BaseException = (
        KeyboardInterrupt() if primary_type is SystemExit else SystemExit(213)
    )
    constructor_calls: list[object] = []

    def hostile_new(
        _cls: type[object],
        *_args: object,
        **_kwargs: object,
    ) -> Never:
        constructor_calls.append(_cls)
        raise secondary

    def hostile_init(
        self: object,
        *_args: object,
        **_kwargs: object,
    ) -> Never:
        constructor_calls.append(self)
        raise secondary

    descriptors_before = _open_descriptor_count()
    tool_id = _enable_instruction_interrupt(
        read_regular,
        target_offset,
        tool_name=(f"trusted-time-sealed-error-{attack}-{primary_type.__name__}-test"),
        interruption=primary,
    )
    try:
        with monkeypatch.context() as scoped:
            if attack == "new_relabel":
                scoped.setattr(
                    reader.TrustedTimePostEnrollmentTopologyReaderError,
                    "__new__",
                    staticmethod(hostile_new),
                    raising=False,
                )
            else:
                scoped.setattr(
                    reader.TrustedTimePostEnrollmentTopologyReaderError,
                    "__init__",
                    hostile_init,
                    raising=False,
                )
            with pytest.raises(primary_type) as retained_interruption:
                _sealed_claim_durable_projection_test_seam()(
                    retained,
                    artifact_directory,
                    ignored_root,
                )
            assert retained_interruption.value is primary
    finally:
        _disable_instruction_interrupt(tool_id, read_regular)
    assert constructor_calls == []
    gc.collect()
    assert _open_descriptor_count() == descriptors_before
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize(
    "operation",
    [
        "validated_binding",
        "active",
        "runtime_provenance",
        "abort",
        "owner_gc",
    ],
)
def test_launch_lock_authority_paths_ignore_runtime_cast_closed_decoy(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    operation: Literal[
        "validated_binding",
        "active",
        "runtime_provenance",
        "abort",
        "owner_gc",
    ],
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    exact_lease = issuer._launch_lock_lease
    ignored_root = os.fspath(issuer._ignored_root)
    exact_capability = issuer._authentication_capability
    assert type(exact_lease) is _TrustedTimeLaunchLockLease
    assert exact_lease.closed is False
    decoy_closed_lease = SimpleNamespace(closed=True)
    decoy_calls: list[object] = []

    def fake_closed_cast(_hint: object, candidate: object) -> object:
        decoy_calls.append(candidate)
        return decoy_closed_lease

    owner_reference: weakref.ReferenceType[object] | None = None
    with monkeypatch.context() as scoped:
        scoped.setattr(reader, "cast", fake_closed_cast, raising=False)
        if operation == "validated_binding":
            binding = reader._validated_authenticated_issuer_launch_lock_binding(issuer)
            assert type(binding) is tuple
            assert tuple.__getitem__(binding, 1) is exact_lease
        elif operation == "active":
            assert reader._authenticated_issuer_capability_is_active(
                issuer,
                exact_capability,
            )
        elif operation == "runtime_provenance":
            provenance = reader._authenticated_issuer_runtime_provenance(
                issuer,
                exact_capability,
            )
            assert type(provenance) is tuple
            assert len(provenance) == 8
        elif operation == "abort":
            reader._abort_authenticated_issuer_activation(issuer)
        else:
            assert operation == "owner_gc"
            owner_reference = weakref.ref(issuer)
            del issuer
            for _attempt in range(8):
                gc.collect()
                if owner_reference() is None:
                    break

    assert decoy_calls == []
    if operation == "owner_gc":
        assert owner_reference is not None
        assert owner_reference() is None
    if operation in {"abort", "owner_gc"}:
        assert exact_lease.closed is True
        replacement = _acquire_trusted_time_launch_lock(ignored_root)
        _validate_trusted_time_launch_lock(replacement)
        replacement.close()
        assert replacement.closed is True
    else:
        assert exact_lease.closed is False
        _validate_trusted_time_launch_lock(exact_lease)
        _close_and_assert_launch_lock_is_reacquirable(issuer)


