def test_controller_writer_orders_prepared_cas_commit_and_durable_selection(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    receipt_projection = _sealed_projection_function_test_seam(
        "sealed_controller_receipt_object_projection"
    )

    def write_controller_outcome(
        lease: object,
        recovery_capability: object,
    ) -> Never:
        post_effect_capability = _transition_registered_post_effect_retention(
            issuer,
            lease,
            recovery_capability,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        checkpoint = issuer._begin_post_effect_controller_outcome_retention(
            post_effect_capability,
            lease,
            retained,
            outcome_kind="failure",
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        receipt = _real_prepared_controller_failure_receipt(
            retained,
            artifact_directory=artifact_directory,
        )
        prepared_projection = receipt_projection(receipt, "prepared")
        assert type(prepared_projection) is tuple
        assert receipt_projection(receipt, "durable") is None

        issuer._complete_post_effect_controller_outcome_retention(
            post_effect_capability,
            checkpoint,
            receipt,
        )
        state = _active_choreography_state(issuer)
        assert _choreography_state_value(state, "phase") == "post_effect_confirmed"
        binding = cast(
            tuple[object, ...],
            _choreography_state_raw_value(state, "controller_outcome_receipt"),
        )
        assert tuple.__getitem__(binding, 3) == prepared_projection
        assert receipt.commit_file_identity is None
        assert receipt._prepared_marker is (controller_outcome._PREPARED_OUTCOME_RECEIPT_MARKER)
        registered_validator = _sealed_projection_function_test_seam(
            "registered_controller_outcome_binding_is_exact"
        )
        assert registered_validator(state, receipt, mode="prepared") is binding
        assert registered_validator(state, receipt, mode="durable") is None

        controller_outcome._commit_prepared_controller_outcome(
            receipt,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        assert receipt_projection(receipt, "prepared") is None
        assert receipt_projection(receipt, "durable") == prepared_projection
        assert registered_validator(state, receipt, mode="prepared") is None
        assert registered_validator(state, receipt, mode="durable") is binding
        scope_nonce = issuer._choreography_scope_nonce
        assert scope_nonce is not None
        assert (
            reader._authenticated_registered_confirmed_terminal_outcome(
                issuer,
                lease,
                recovery_capability,
                scope_nonce,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            is receipt
        )
        raise _PostEffectRetentionTerminal

    with pytest.raises(_PostEffectRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(write_controller_outcome)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


