def test_success_finalization_revokes_scope_atomically_before_close_can_run(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, queued = _open_issuer(monkeypatch, tmp_path)
    original_consume = cast(
        Callable[[object, object, object], bool],
        _patch_authenticated_scope_default(
            monkeypatch,
            "_consume_active_scope",
            lambda _owner, _lease, _scope_nonce: False,
        ),
    )
    final_validation_entered = threading.Event()
    close_started = threading.Event()
    close_finished = threading.Event()
    consume_calls = 0

    def gated_consume(owner: object, lease: object, scope_nonce: object) -> bool:
        nonlocal consume_calls
        consume_calls += 1
        consumed = original_consume(owner, lease, scope_nonce)
        assert consumed is True
        assert id(issuer) not in _active_choreography_registry()
        final_validation_entered.set()
        assert close_started.wait(timeout=2.0)
        assert close_finished.is_set() is False
        return consumed

    scope_defaults = _authenticated_choreography_scope_kwdefaults()
    assert scope_defaults is not None
    monkeypatch.setitem(scope_defaults, "_consume_active_scope", gated_consume)
    close_errors: list[BaseException] = []

    def close_when_finalizing() -> None:
        assert final_validation_entered.wait(timeout=2.0)
        close_started.set()
        try:
            issuer.close()
        except BaseException as error:
            close_errors.append(error)
        finally:
            close_finished.set()

    worker = threading.Thread(target=close_when_finalizing)
    worker.start()
    try:
        result = issuer._run_exclusive_choreography(lambda _lease: "accepted")
    finally:
        final_validation_entered.set()
        close_started.set()
        worker.join(timeout=2.0)

    assert result == "accepted"
    assert consume_calls == 1
    assert not worker.is_alive()
    assert close_errors == []
    assert close_finished.is_set() is True
    assert issuer._closed is True
    assert issuer._choreography_inflight is False
    assert issuer._launch_lock_lease is None
    assert len(queued.calls) == 1
    assert queued.outputs == []
    replacement = _acquire_trusted_time_launch_lock(os.fspath(issuer._ignored_root))
    _validate_trusted_time_launch_lock(replacement)
    replacement.close()


