@pytest.mark.parametrize("boundary", ["primary_dispatch", "catch_cleanup_handoff"])
def test_adoption_reducer_handoff_async_runs_quiescent_burn_cleanup(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    receipt = _real_prepared_controller_success_receipt(
        retained,
        artifact_directory=artifact_directory,
    )
    scope_method = _authenticated_choreography_scope_method()
    classification_code = _nested_code(scope_method, "adopt_terminal_after_body")
    instructions = list(dis.get_instructions(scope_method))
    cleanup_call_indices = _outer_cleanup_attempt_call_indices(scope_method.__code__)
    primary_dispatch_index = next(
        index
        for index, instruction in enumerate(instructions[:-1])
        if instruction.opname in {"LOAD_FAST", "LOAD_DEREF"}
        and instruction.argval == "primary_error"
        and instructions[index + 1].opname == "POP_JUMP_IF_NONE"
    )
    exact_offset = (
        instructions[primary_dispatch_index].offset
        if boundary == "primary_dispatch"
        else instructions[cleanup_call_indices[0] - 1].offset
    )
    failure: BaseException = SystemExit(191) if failure_type is SystemExit else KeyboardInterrupt()
    exact_tool_id = _enable_instruction_interrupt(
        scope_method,
        exact_offset,
        tool_name=(f"trusted-time-adoption-{boundary}-{failure_type.__name__}-test"),
        interruption=failure,
    )
    ordinary_tool_id: int | None = None
    if boundary == "catch_cleanup_handoff":
        ordinary_tool_id = _enable_instruction_interrupt(
            classification_code,
            _instruction_offset(
                classification_code,
                opname="LOAD_DEREF",
                argval="adopted_terminal_disposition",
                occurrence="first",
            ),
            tool_name="trusted-time-adoption-catch-handoff-ordinary-test",
            interruption=RuntimeError("ordinary adopted classification failure"),
        )

    def complete_then_adopt(lease: object, recovery_capability: object) -> Never:
        _complete_and_commit_controller_receipt(
            issuer,
            lease,
            recovery_capability,
            retained,
            receipt,
            outcome_kind="success",
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        raise RuntimeError("trigger registered terminal adoption")

    try:
        with pytest.raises(failure_type) as retained_interruption:
            issuer._run_exclusive_choreography_with_recovery_retention(complete_then_adopt)
    finally:
        _disable_instruction_interrupt(exact_tool_id, scope_method)
        if ordinary_tool_id is not None:
            _disable_instruction_interrupt(ordinary_tool_id, classification_code)

    assert retained_interruption.value is failure
    _assert_choreography_authority_is_burned(issuer)
    _assert_launch_lock_is_held(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


