def test_close_between_choreography_calls_poisons_without_releasing_flock(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, queued = _open_issuer(monkeypatch, tmp_path)
    launch_lock_lease = issuer._launch_lock_lease
    assert type(launch_lock_lease) is _TrustedTimeLaunchLockLease
    close_errors: list[BaseException] = []
    lock_was_held_inside_callback = False

    monkeypatch.setattr(
        reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
        "_poison_locked",
        lambda _issuer: None,
    )

    def action(_: object) -> None:
        nonlocal lock_was_held_inside_callback
        issuer._busy = False
        issuer._choreography_inflight = False
        try:
            issuer.close()
        except BaseException as error:
            close_errors.append(error)
        assert launch_lock_lease.closed is False
        assert issuer._authentication_capability is None
        _assert_launch_lock_is_held(issuer)
        lock_was_held_inside_callback = True

    with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
        issuer._run_exclusive_choreography(action)

    assert len(close_errors) == 1
    assert isinstance(close_errors[0], reader.TrustedTimePostEnrollmentTopologyReaderError)
    assert lock_was_held_inside_callback is True
    assert launch_lock_lease.closed is False
    _assert_launch_lock_is_held(issuer)
    assert len(queued.calls) == 1
    assert queued.outputs == []
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize(
    "hostile_slot",
    ["_busy", "_choreography_inflight", "_closed", "_lifecycle_lock", "_owner_pid"],
)
def test_live_scope_close_burns_before_hostile_heap_descriptor_read(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    hostile_slot: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    issuer_type = reader.TrustedTimePostEnrollmentTopologyObservationIssuer
    launch_lock_lease = issuer._launch_lock_lease
    lifecycle_lock = issuer._lifecycle_lock
    assert type(launch_lock_lease) is _TrustedTimeLaunchLockLease
    original_descriptor = vars(issuer_type)[hostile_slot]
    close_errors: list[BaseException] = []

    def reject_heap_read(_issuer: object) -> Never:
        raise RuntimeError("hostile heap descriptor read")

    def reject_heap_write(_issuer: object, _value: object) -> Never:
        raise RuntimeError("hostile heap descriptor write")

    def action(_: object) -> None:
        monkeypatch.setattr(
            issuer_type,
            hostile_slot,
            property(reject_heap_read, reject_heap_write),
        )
        try:
            try:
                issuer.close()
            except BaseException as error:
                close_errors.append(error)
        finally:
            monkeypatch.setattr(issuer_type, hostile_slot, original_descriptor)
        assert launch_lock_lease.closed is False
        assert issuer._authentication_capability is None

    with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
        issuer._run_exclusive_choreography(action)

    assert len(close_errors) == 1
    assert isinstance(close_errors[0], reader.TrustedTimePostEnrollmentTopologyReaderError)
    assert launch_lock_lease.closed is False
    assert issuer._authentication_capability is None
    assert issuer._lifecycle_lock is lifecycle_lock
    issuer._busy = False
    issuer._choreography_inflight = False
    _close_and_assert_launch_lock_is_reacquirable(issuer)


