@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_scope_revocation_baseexception_preserves_identity_and_cannot_wedge(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    original_revoke = cast(
        Callable[[object, object | None], None],
        _patch_authenticated_scope_default(
            monkeypatch,
            "_revoke_scope",
            lambda _owner, _scope_nonce: None,
        ),
    )
    failure: BaseException = SystemExit(79) if failure_type is SystemExit else KeyboardInterrupt()
    revoke_calls = 0

    def revoke_then_interrupt(owner: object, scope_nonce: object | None) -> None:
        nonlocal revoke_calls
        revoke_calls += 1
        original_revoke(owner, scope_nonce)
        if revoke_calls == 1:
            raise failure

    _patch_authenticated_scope_default(
        monkeypatch,
        "_revoke_scope",
        revoke_then_interrupt,
    )

    def fail_body(_lease: object) -> Never:
        raise RuntimeError("ordinary choreography body failure")

    with pytest.raises(failure_type) as retained_interruption:
        issuer._run_exclusive_choreography(fail_body)

    assert retained_interruption.value is failure
    assert revoke_calls >= 2
    assert id(issuer) not in _active_choreography_registry()
    assert issuer._choreography_inflight is False
    assert issuer._choreography_scope_nonce is None
    assert issuer._poisoned is True
    _assert_launch_lock_is_held(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", ["before", "after"])
def test_scope_registry_pop_interruption_retries_cleanup_and_preserves_identity(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    revoke_scope = reader._revoke_authenticated_choreography_scope
    revoke_scope_locked = cast(
        Callable[..., object],
        inspect.getclosurevars(revoke_scope).nonlocals["revoke_choreography_scope_locked"],
    )
    clear_anchor_and_state = cast(
        Callable[..., object],
        inspect.getclosurevars(revoke_scope_locked).nonlocals[
            "clear_choreography_anchor_and_state_locked"
        ],
    )
    clear_code = clear_anchor_and_state.__code__
    instructions = list(dis.get_instructions(clear_code))
    load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname in {"LOAD_ATTR", "LOAD_METHOD"} and instruction.argval == "pop"
    )
    call_index = next(
        index
        for index in range(load_index + 1, len(instructions))
        if instructions[index].opname == "CALL"
    )
    offset = (
        instructions[call_index].offset
        if boundary == "before"
        else instructions[call_index + 1].offset
    )
    failure: BaseException = SystemExit(101) if failure_type is SystemExit else KeyboardInterrupt()
    tool_id = _enable_instruction_interrupt(
        clear_code,
        offset,
        tool_name=f"trusted-time-scope-pop-{boundary}-{failure_type.__name__}-test",
        interruption=failure,
    )
    try:
        with pytest.raises(failure_type) as retained_interruption:
            issuer._run_exclusive_choreography(lambda _lease: None)
    finally:
        _disable_instruction_interrupt(tool_id, clear_code)

    assert retained_interruption.value is failure
    assert id(issuer) not in _active_choreography_registry()
    lifecycle_registry, run_under_registry_lock = _choreography_lifecycle_test_seams()
    lifecycle = run_under_registry_lock(lambda: lifecycle_registry[id(issuer)])
    assert type(lifecycle) is tuple
    assert tuple.__getitem__(lifecycle, 4) == "burned"
    assert tuple.__getitem__(lifecycle, 7) == ()
    assert tuple.__getitem__(lifecycle, 8) is None
    assert issuer._choreography_inflight is False
    assert issuer._choreography_scope_nonce is None
    assert issuer._poisoned is True
    _assert_launch_lock_is_held(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


