@pytest.mark.parametrize("primary_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("cleanup_point", ["burn", "scope_revoke"])
@pytest.mark.parametrize("cleanup_kind", ["ordinary", "keyboard", "system_exit"])
def test_choreography_primary_async_identity_has_priority_over_cleanup_failures(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    primary_type: type[BaseException],
    cleanup_point: str,
    cleanup_kind: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    primary: BaseException = SystemExit(89) if primary_type is SystemExit else KeyboardInterrupt()
    cleanup_failure: BaseException
    if cleanup_kind == "ordinary":
        cleanup_failure = RuntimeError("injected ordinary choreography cleanup failure")
    elif cleanup_kind == "keyboard":
        cleanup_failure = KeyboardInterrupt()
    else:
        cleanup_failure = SystemExit(97)
    cleanup_calls = 0
    scope_defaults = type(issuer)._run_authenticated_choreography_scope.__kwdefaults__
    assert scope_defaults is not None

    if cleanup_point == "burn":
        original_cleanup = cast(Callable[[object], bool], scope_defaults["_burn_owner"])

        def fail_cleanup_once(owner: object) -> bool:
            nonlocal cleanup_calls
            cleanup_calls += 1
            result = original_cleanup(owner)
            if cleanup_calls == 1:
                raise cleanup_failure
            return result

        monkeypatch.setitem(scope_defaults, "_burn_owner", fail_cleanup_once)
    else:
        original_revoke = cast(
            Callable[[object, object | None], None],
            scope_defaults["_revoke_scope"],
        )

        def fail_cleanup_once(owner: object, scope_nonce: object | None) -> None:
            nonlocal cleanup_calls
            cleanup_calls += 1
            original_revoke(owner, scope_nonce)
            if cleanup_calls == 1:
                raise cleanup_failure

        monkeypatch.setitem(
            scope_defaults,
            "_revoke_scope",
            fail_cleanup_once,
        )

    def raise_primary(_lease: object) -> Never:
        raise primary

    with pytest.raises(primary_type) as retained_interruption:
        issuer._run_exclusive_choreography(raise_primary)

    assert retained_interruption.value is primary
    assert cleanup_calls >= 1
    assert id(issuer) not in _active_choreography_registry()
    lifecycle_registry, run_under_registry_lock = _choreography_lifecycle_test_seams()
    lifecycle = run_under_registry_lock(lambda: lifecycle_registry[id(issuer)])
    assert type(lifecycle) is tuple
    assert tuple.__getitem__(lifecycle, 7) == ()
    assert tuple.__getitem__(lifecycle, 8) is None
    assert issuer._choreography_inflight is False
    assert issuer._choreography_scope_nonce is None
    assert issuer._poisoned is True
    _assert_launch_lock_is_held(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


