def test_forked_child_native_atfork_closes_lease_and_python_scrubs_authority(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    issuer, queued = _open_issuer(monkeypatch, tmp_path)
    inherited_launch_lock_lease = issuer._launch_lock_lease
    assert type(inherited_launch_lock_lease) is _TrustedTimeLaunchLockLease

    def inspect_child(lease: object) -> bytes:
        parent_state = _active_choreography_state(issuer)
        read_descriptor, write_descriptor = os.pipe()
        child_pid = os.fork()
        if child_pid == 0:  # pragma: no cover - asserted through the pipe
            os.close(read_descriptor)
            try:
                lease_rejected = not reader._authenticated_choreography_is_active(issuer, lease)
                state_closed = (
                    inherited_launch_lock_lease.closed is True
                    and issuer._launch_lock_lease is None
                    and issuer._closed is True
                    and issuer._poisoned is True
                    and issuer._choreography_inflight is False
                    and issuer._authentication_capability is None
                )
                registry_scrubbed = id(issuer) not in _active_choreography_registry()
                payload = (
                    b"safe" if lease_rejected and state_closed and registry_scrubbed else b"unsafe"
                )
                os.write(write_descriptor, payload)
            finally:
                os.close(write_descriptor)
            os._exit(0)

        os.close(write_descriptor)
        try:
            payload = os.read(read_descriptor, 16)
            assert _active_choreography_state(issuer) is parent_state
            return payload
        finally:
            os.close(read_descriptor)
            os.waitpid(child_pid, 0)

    assert issuer._run_exclusive_choreography(inspect_child) == b"safe"
    assert issuer._poisoned is False
    assert issuer._choreography_inflight is False
    assert len(queued.calls) == 1
    assert queued.outputs == []
    _close_and_assert_launch_lock_is_reacquirable(issuer)


