def test_choreography_registry_uses_exact_private_binding_and_state_tuples(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    observed: list[tuple[object, ...]] = []
    private_values: list[tuple[object, object]] = []

    def inspect_binding(lease: object, recovery_capability: object) -> object:
        state = _active_choreography_state(issuer)
        observed.append(state)
        assert type(state) is tuple
        assert len(state) == 15
        assert _choreography_state_value(state, "tag") == ("trusted-time-choreography-state-v1")

        binding = _choreography_state_value(state, "binding")
        assert type(binding) is tuple
        assert len(binding) == 15
        assert _choreography_binding_value(state, "tag") == ("trusted-time-choreography-binding-v2")
        owner_reference = _choreography_binding_value(state, "owner_reference")
        assert type(owner_reference) is weakref.ReferenceType
        assert owner_reference() is issuer
        assert _choreography_binding_value(state, "lifecycle_lock") is issuer._lifecycle_lock
        launch_lock_binding = _choreography_binding_value(state, "launch_lock_binding")
        assert type(launch_lock_binding) is tuple
        assert len(launch_lock_binding) == 5
        assert tuple.__getitem__(launch_lock_binding, 0) == ("trusted-time-launch-lock-binding-v1")
        assert tuple.__getitem__(launch_lock_binding, 4) is issuer._lifecycle_lock
        assert _choreography_binding_value(state, "lease") is lease
        assert (
            _choreography_binding_value(state, "recovery_retention_capability")
            is recovery_capability
        )
        assert (
            _choreography_binding_value(state, "authentication_capability")
            is issuer._authentication_capability
        )
        scope_binding = _choreography_binding_value(state, "scope_binding")
        assert type(scope_binding) is tuple
        assert len(scope_binding) == 3
        assert tuple.__getitem__(scope_binding, 0) == ("trusted-time-choreography-scope-v1")
        assert tuple.__getitem__(scope_binding, 1) is issuer._choreography_scope_nonce
        live_token = tuple.__getitem__(scope_binding, 2)
        assert type(live_token) is object
        assert live_token is not issuer._choreography_scope_nonce
        assert lease is not live_token
        assert recovery_capability is not live_token
        assert all(value is not inspect_binding for value in binding)
        assert all(value is not inspect_binding for value in launch_lock_binding)
        assert all(value is not inspect_binding for value in scope_binding)
        pending_private_values: list[object] = [state]
        while pending_private_values:
            private_value = pending_private_values.pop()
            assert private_value is not inspect_binding
            if type(private_value) is tuple:
                pending_private_values.extend(tuple.__iter__(private_value))
        lifecycle_registry, run_under_registry_lock = _choreography_lifecycle_test_seams()
        lifecycle = run_under_registry_lock(lambda: lifecycle_registry[id(issuer)])
        assert type(lifecycle) is tuple
        assert len(lifecycle) == 9
        assert tuple.__getitem__(lifecycle, 0) == "trusted-time-issuer-lifecycle-v3"
        thread_token = _choreography_binding_value(state, "owner_thread_token")
        assert type(thread_token) is object
        assert tuple.__getitem__(lifecycle, 3) is thread_token
        choreography_tokens = tuple.__getitem__(lifecycle, 7)
        assert type(choreography_tokens) is tuple
        assert len(choreography_tokens) == 1
        assert tuple.__getitem__(choreography_tokens, 0) is live_token
        assert tuple.__getitem__(lifecycle, 8) is binding
        private_values.append((scope_binding, live_token))

        heap_values = [object.__getattribute__(issuer, slot) for slot in type(issuer).__slots__]
        assert all(value is not scope_binding for value in heap_values)
        assert all(value is not live_token for value in heap_values)
        assert all(value is not scope_binding for value in (lease, recovery_capability))
        assert all(value is not live_token for value in (lease, recovery_capability))
        assert _choreography_binding_value(state, "session_sha256") == issuer._session_sha256
        assert _choreography_binding_value(state, "owner_pid") == os.getpid()
        started = cast(int, _choreography_binding_value(state, "started_monotonic_ns"))
        deadline = cast(int, _choreography_binding_value(state, "deadline_monotonic_ns"))
        retention_deadline = cast(
            int,
            _choreography_binding_value(state, "retention_deadline_monotonic_ns"),
        )
        assert deadline - started == (
            reader._POST_ENROLLMENT_START_CHOREOGRAPHY_DEADLINE_NANOSECONDS
        )
        assert retention_deadline - started == (
            reader._POST_ENROLLMENT_START_RECOVERY_RETENTION_DEADLINE_NANOSECONDS
        )
        lease_sha256 = _choreography_binding_value(state, "lease_sha256")
        assert type(lease_sha256) is str and len(lease_sha256) == 64

        last_observed = cast(
            int,
            _choreography_state_value(state, "last_monotonic_ns"),
        )
        assert started <= last_observed < deadline
        assert _choreography_state_value(state, "action_active") is True
        assert _choreography_state_value(state, "phase") == "unbound"
        assert all(tuple.__getitem__(state, index) is None for index in range(5, 15))
        checkpoint = issuer._require_unbound_recovery_retention_preparation(
            lease,
            recovery_capability,
        )
        checkpoint_values = tuple(
            object.__getattribute__(checkpoint, field) for field in checkpoint.__dataclass_fields__
        )
        assert all(value is not scope_binding for value in checkpoint_values)
        assert all(value is not live_token for value in checkpoint_values)
        return checkpoint

    result = issuer._run_exclusive_choreography_with_recovery_retention(inspect_binding)

    assert len(observed) == 1
    assert len(private_values) == 1
    assert all(result is not private_value for private_value in private_values[0])
    assert id(issuer) not in _active_choreography_registry()
    assert not hasattr(reader, "_ChoreographyBindingV1")
    assert not hasattr(reader, "_ChoreographyStateV1")
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def test_choreography_thread_token_is_stable_and_rejects_reused_thread_ident(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    current_thread_token = _sealed_projection_function_test_seam("current_thread_token")
    assert type(current_thread_token) is FunctionType
    main_thread = threading.current_thread()
    main_ident = main_thread.ident
    assert type(main_ident) is int

    def inspect_thread_tokens(lease: object, _recovery_capability: object) -> str:
        state = _active_choreography_state(issuer)
        binding_token = _choreography_binding_value(state, "owner_thread_token")
        lifecycle_registry, run_under_registry_lock = _choreography_lifecycle_test_seams()
        lifecycle = run_under_registry_lock(lambda: lifecycle_registry[id(issuer)])
        assert type(binding_token) is object
        assert tuple.__getitem__(lifecycle, 3) is binding_token
        assert current_thread_token() is binding_token
        assert current_thread_token() is binding_token

        observations: list[tuple[object, object, bool]] = []
        errors: list[BaseException] = []

        def sample_reused_ident() -> None:
            worker = threading.current_thread()
            original_ident = object.__getattribute__(worker, "_ident")
            try:
                object.__setattr__(worker, "_ident", main_ident)
                first = current_thread_token()
                second = current_thread_token()
                active = reader._authenticated_choreography_is_active(
                    issuer,
                    lease,
                )
                observations.append((first, second, active))
            except BaseException as error:
                errors.append(error)
            finally:
                object.__setattr__(worker, "_ident", original_ident)

        for _ in range(2):
            worker = threading.Thread(target=sample_reused_ident)
            worker.start()
            worker.join(timeout=2.0)
            assert not worker.is_alive()

        assert errors == []
        assert len(observations) == 2
        first_token, first_repeat, first_active = observations[0]
        second_token, second_repeat, second_active = observations[1]
        assert type(first_token) is object
        assert type(second_token) is object
        assert first_repeat is first_token
        assert second_repeat is second_token
        assert first_token is not binding_token
        assert second_token is not binding_token
        assert second_token is not first_token
        assert first_active is False
        assert second_active is False
        assert _active_choreography_state(issuer) is state
        return "accepted"

    assert (
        issuer._run_exclusive_choreography_with_recovery_retention(inspect_thread_tokens)
        == "accepted"
    )
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize(
    "boundary",
    ["candidate_call_return", "install_before", "install_after", "return"],
)
def test_current_thread_token_install_interruption_is_idempotent_and_nonauthorizing(
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    _require_coherent_projection_seal_reader()
    current_thread_token = _sealed_projection_function_test_seam("current_thread_token")
    assert type(current_thread_token) is FunctionType
    instructions = list(dis.get_instructions(current_thread_token))
    assert all(instruction.opname != "STORE_ATTR" for instruction in instructions)
    candidate_load_index = next(
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname == "LOAD_DEREF" and instruction.argval == "_exact_object_type"
    )
    candidate_call_index = next(
        index
        for index in range(candidate_load_index + 1, len(instructions))
        if instructions[index].opname == "CALL"
    )
    install_load_indices = [
        index
        for index, instruction in enumerate(instructions)
        if instruction.opname == "LOAD_DEREF" and instruction.argval == "_thread_local_setattr"
    ]
    assert len(install_load_indices) == 1
    install_call_index = next(
        index
        for index in range(install_load_indices[0] + 1, len(instructions))
        if instructions[index].opname == "CALL"
    )
    return_index = next(
        index
        for index in range(install_call_index + 1, len(instructions))
        if instructions[index].opname == "RETURN_VALUE"
    )
    target_offset = {
        "candidate_call_return": instructions[candidate_call_index + 1].offset,
        "install_before": instructions[install_call_index].offset,
        "install_after": instructions[install_call_index + 1].offset,
        "return": instructions[return_index].offset,
    }[boundary]
    failure: BaseException = SystemExit(229) if failure_type is SystemExit else KeyboardInterrupt()
    tool_id = _enable_instruction_interrupt(
        current_thread_token,
        target_offset,
        tool_name=(f"trusted-time-thread-token-{boundary}-{failure_type.__name__}-test"),
        interruption=failure,
    )
    errors: list[BaseException] = []
    retry_tokens: list[tuple[object, object]] = []
    registry_before = dict(_active_choreography_registry())

    def interrupt_then_retry() -> None:
        try:
            current_thread_token()
        except BaseException as error:
            errors.append(error)
        retry_tokens.append((current_thread_token(), current_thread_token()))

    worker = threading.Thread(target=interrupt_then_retry)
    try:
        worker.start()
        worker.join(timeout=2.0)
    finally:
        _disable_instruction_interrupt(tool_id, current_thread_token)
    assert not worker.is_alive()
    assert errors == [failure]
    assert len(retry_tokens) == 1
    first_retry, second_retry = retry_tokens[0]
    assert type(first_retry) is object
    assert second_retry is first_retry
    assert _active_choreography_registry() == registry_before
    assert not reader._authenticated_choreography_is_active(object(), object())


def test_forked_child_cannot_authorize_with_inherited_thread_token(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _require_coherent_projection_seal_reader()
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    current_thread_token = _sealed_projection_function_test_seam("current_thread_token")

    def inspect_child(lease: object, _recovery_capability: object) -> bytes:
        state = _active_choreography_state(issuer)
        inherited_token = _choreography_binding_value(state, "owner_thread_token")
        assert current_thread_token() is inherited_token
        read_descriptor, write_descriptor = os.pipe()
        child_pid = os.fork()
        if child_pid == 0:  # pragma: no cover - asserted through the pipe
            os.close(read_descriptor)
            try:
                child_token = current_thread_token()
                payload = (
                    b"safe"
                    if child_token is not inherited_token
                    and not reader._authenticated_choreography_is_active(
                        issuer,
                        lease,
                    )
                    and id(issuer) not in _active_choreography_registry()
                    else b"unsafe"
                )
                os.write(write_descriptor, payload)
            finally:
                os.close(write_descriptor)
            os._exit(0)

        os.close(write_descriptor)
        try:
            payload = os.read(read_descriptor, 16)
            assert _active_choreography_state(issuer) is state
            return payload
        finally:
            os.close(read_descriptor)
            os.waitpid(child_pid, 0)

    assert issuer._run_exclusive_choreography_with_recovery_retention(inspect_child) == b"safe"
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize(
    "terminal_kind",
    ["recovery", "controller_success", "controller_failure"],
)
def test_choreography_registry_uses_exact_weak_identity_and_receipt_bindings(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    terminal_kind: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    if terminal_kind == "recovery":
        receipt: object = _persist_recovery_outcome(
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
    else:
        receipt = (
            _real_prepared_controller_success_receipt(
                retained,
                artifact_directory=artifact_directory,
            )
            if terminal_kind == "controller_success"
            else _real_prepared_controller_failure_receipt(
                retained,
                artifact_directory=artifact_directory,
                reason=(
                    controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.SEQUENCE_TWO_UNCONFIRMED
                ),
            )
        )

    def inspect_bindings(lease: object, recovery_capability: object) -> Never:
        if terminal_kind == "recovery":
            _bind_registered_recovery_claim(
                issuer,
                lease,
                recovery_capability,
                retained,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
        else:
            post_effect_capability = _transition_registered_post_effect_retention(
                issuer,
                lease,
                recovery_capability,
                retained,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )

        claim_state = _active_choreography_state(issuer)
        claim_identity = _assert_choreography_identity_slot(
            claim_state,
            "retained_claim",
            retained,
        )
        if terminal_kind == "recovery":
            checkpoint = issuer._begin_recovery_outcome_retention(
                recovery_capability,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            checkpoint_name = "retention_checkpoint"
            checkpoint_tag = "trusted-time-recovery-retention-checkpoint-identity-v1"
            receipt_name = "recovery_outcome_receipt"
            receipt_projection_length = 11
            checkpoint_projection_length = 6
            issuer._complete_recovery_outcome_retention(
                recovery_capability,
                checkpoint,
                receipt,
            )
        else:
            checkpoint = issuer._begin_post_effect_controller_outcome_retention(
                post_effect_capability,
                lease,
                retained,
                outcome_kind=("success" if terminal_kind == "controller_success" else "failure"),
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            checkpoint_name = "controller_outcome_checkpoint"
            checkpoint_tag = "trusted-time-controller-outcome-checkpoint-identity-v1"
            receipt_name = "controller_outcome_receipt"
            receipt_projection_length = 15
            checkpoint_projection_length = 8
            issuer._complete_post_effect_controller_outcome_retention(
                post_effect_capability,
                checkpoint,
                receipt,
            )

        confirmed_state = _active_choreography_state(issuer)
        assert (
            _choreography_state_raw_value(
                confirmed_state,
                "retained_claim",
            )
            is claim_identity
        )
        checkpoint_identity = _assert_choreography_identity_slot(
            confirmed_state,
            checkpoint_name,
            checkpoint,
        )
        assert tuple.__getitem__(checkpoint_identity, 0) == checkpoint_tag
        _assert_choreography_receipt_binding_slot(
            confirmed_state,
            receipt_name,
            receipt,
            receipt_projection_length=receipt_projection_length,
            checkpoint_identity=checkpoint_identity,
            checkpoint_projection_length=checkpoint_projection_length,
            claim_identity=claim_identity,
        )
        assert _choreography_state_value(confirmed_state, receipt_name) is receipt
        assert not _tuple_tree_contains_identity(confirmed_state, retained)
        assert not _tuple_tree_contains_identity(confirmed_state, checkpoint)
        assert not _tuple_tree_contains_identity(confirmed_state, receipt)
        raise _PostEffectRetentionTerminal

    with pytest.raises(_PostEffectRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(inspect_bindings)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize(
    "terminal_kind",
    ["recovery", "controller_success", "controller_failure"],
)
@pytest.mark.parametrize("dependency_state", ["dead", "mutated_live"])
def test_registered_terminal_uses_tombstones_after_one_time_installation_barrier(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    terminal_kind: str,
    dependency_state: Literal["dead", "mutated_live"],
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    if terminal_kind == "recovery":
        receipt: object = _persist_recovery_outcome(
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
    else:
        receipt = (
            _real_prepared_controller_success_receipt(
                retained,
                artifact_directory=artifact_directory,
            )
            if terminal_kind == "controller_success"
            else _real_prepared_controller_failure_receipt(
                retained,
                artifact_directory=artifact_directory,
                reason=(
                    controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.SEQUENCE_TWO_UNCONFIRMED
                ),
            )
        )

    def select_after_dependencies_die(
        lease: object,
        recovery_capability: object,
    ) -> Never:
        nonlocal retained
        if terminal_kind == "recovery":
            _bind_registered_recovery_claim(
                issuer,
                lease,
                recovery_capability,
                retained,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            checkpoint = issuer._begin_recovery_outcome_retention(
                recovery_capability,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            issuer._complete_recovery_outcome_retention(
                recovery_capability,
                checkpoint,
                receipt,
            )
            checkpoint_name = "retention_checkpoint"
            receipt_name = "recovery_outcome_receipt"
        else:
            post_effect_capability = _transition_registered_post_effect_retention(
                issuer,
                lease,
                recovery_capability,
                retained,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            checkpoint = issuer._begin_post_effect_controller_outcome_retention(
                post_effect_capability,
                lease,
                retained,
                outcome_kind=("success" if terminal_kind == "controller_success" else "failure"),
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            issuer._complete_post_effect_controller_outcome_retention(
                post_effect_capability,
                checkpoint,
                receipt,
            )
            controller_outcome._commit_prepared_controller_outcome(
                cast(
                    controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome,
                    receipt,
                ),
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            checkpoint_name = "controller_outcome_checkpoint"
            receipt_name = "controller_outcome_receipt"

        confirmed_state = _active_choreography_state(issuer)
        claim_identity = cast(
            tuple[object, ...],
            _choreography_state_raw_value(confirmed_state, "retained_claim"),
        )
        checkpoint_identity = cast(
            tuple[object, ...],
            _choreography_state_raw_value(confirmed_state, checkpoint_name),
        )
        receipt_binding = cast(
            tuple[object, ...],
            _choreography_state_raw_value(confirmed_state, receipt_name),
        )
        claim_reference = cast(
            weakref.ReferenceType[object],
            tuple.__getitem__(claim_identity, 1),
        )
        checkpoint_reference = cast(
            weakref.ReferenceType[object],
            tuple.__getitem__(checkpoint_identity, 1),
        )
        if dependency_state == "dead":
            del checkpoint
            del retained
            for _ in range(3):
                gc.collect()
                if claim_reference() is None and checkpoint_reference() is None:
                    break
            assert claim_reference() is None
            assert checkpoint_reference() is None
        else:
            assert dependency_state == "mutated_live"
            _mutate_nested_live_claim_field(
                retained.claim,
                "launch",
                "git_revision",
            )
            _mutate_live_checkpoint_field(
                checkpoint,
                "observed_monotonic_ns",
                retained,
            )
            assert claim_reference() is retained
            assert checkpoint_reference() is checkpoint
        assert (
            _choreography_state_raw_value(
                confirmed_state,
                "retained_claim",
            )
            is claim_identity
        )
        assert (
            _choreography_state_raw_value(
                confirmed_state,
                checkpoint_name,
            )
            is checkpoint_identity
        )
        assert (
            _choreography_state_raw_value(
                confirmed_state,
                receipt_name,
            )
            is receipt_binding
        )
        assert tuple.__getitem__(receipt_binding, 4) is checkpoint_identity
        assert tuple.__getitem__(receipt_binding, 6) is claim_identity

        selected = issuer._adopt_registered_confirmed_terminal_outcome(
            lease,
            recovery_capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        assert selected is receipt
        raise _PostEffectRetentionTerminal

    with pytest.raises(_PostEffectRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(select_after_dependencies_die)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize(
    "terminal_kind",
    ["recovery", "controller_success", "controller_failure"],
)
@pytest.mark.parametrize("binding_attack", ["dead", "foreign"])
def test_dead_or_crossbound_receipt_reference_cannot_revive_terminal_authority(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    terminal_kind: str,
    binding_attack: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    if terminal_kind == "recovery":
        receipt: object = _persist_recovery_outcome(
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
    else:
        receipt = (
            _real_prepared_controller_success_receipt(
                retained,
                artifact_directory=artifact_directory,
            )
            if terminal_kind == "controller_success"
            else _real_prepared_controller_failure_receipt(
                retained,
                artifact_directory=artifact_directory,
                reason=(
                    controller_outcome.TrustedTimePostEnrollmentStartControllerOutcomeReason.SEQUENCE_TWO_UNCONFIRMED
                ),
            )
        )

    def reject_dead_or_crossbound_receipt(
        lease: object,
        recovery_capability: object,
    ) -> Never:
        nonlocal receipt
        if terminal_kind == "recovery":
            _bind_registered_recovery_claim(
                issuer,
                lease,
                recovery_capability,
                retained,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            checkpoint = issuer._begin_recovery_outcome_retention(
                recovery_capability,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            issuer._complete_recovery_outcome_retention(
                recovery_capability,
                checkpoint,
                receipt,
            )
            receipt_name = "recovery_outcome_receipt"
        else:
            post_effect_capability = _transition_registered_post_effect_retention(
                issuer,
                lease,
                recovery_capability,
                retained,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            checkpoint = issuer._begin_post_effect_controller_outcome_retention(
                post_effect_capability,
                lease,
                retained,
                outcome_kind=("success" if terminal_kind == "controller_success" else "failure"),
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            issuer._complete_post_effect_controller_outcome_retention(
                post_effect_capability,
                checkpoint,
                receipt,
            )
            controller_outcome._commit_prepared_controller_outcome(
                cast(
                    controller_outcome.RetainedTrustedTimePostEnrollmentStartControllerOutcome,
                    receipt,
                ),
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            receipt_name = "controller_outcome_receipt"

        registered_state = _active_choreography_state(issuer)
        receipt_binding = cast(
            tuple[object, ...],
            _choreography_state_raw_value(registered_state, receipt_name),
        )
        receipt_reference = cast(
            weakref.ReferenceType[object],
            tuple.__getitem__(receipt_binding, 1),
        )
        registered_receipt_id = tuple.__getitem__(receipt_binding, 2)
        assert receipt_reference() is receipt
        assert registered_receipt_id == id(receipt)
        if binding_attack == "dead":
            del receipt
            for _ in range(3):
                gc.collect()
                if receipt_reference() is None:
                    break
            assert receipt_reference() is None
        else:
            foreign_receipt = object.__new__(cast(type[object], type(receipt)))
            foreign_reference = weakref.ref(foreign_receipt)
            assert id(foreign_receipt) != registered_receipt_id
            forged_binding = _tuple_with_item(
                receipt_binding,
                1,
                foreign_reference,
            )
            forged_state = _choreography_state_with_item(
                registered_state,
                receipt_name,
                forged_binding,
            )
            _, _, run_under_registry_lock, state_validator = _choreography_cas_test_seams()
            assert run_under_registry_lock(lambda: state_validator(issuer, forged_state))
            _active_choreography_registry()[id(issuer)] = forged_state

        with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
            issuer._adopt_registered_confirmed_terminal_outcome(
                lease,
                recovery_capability,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
        demoted_state = _active_choreography_state(issuer)
        assert _choreography_state_value(demoted_state, "phase") in {
            "recovery_unconfirmed",
            "post_effect_unconfirmed",
        }
        assert _choreography_state_raw_value(demoted_state, receipt_name) is None
        raise _PostEffectRetentionTerminal

    with pytest.raises(_PostEffectRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(
            reject_dead_or_crossbound_receipt
        )
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("hash_attack", ["method", "descriptor"])
def test_int_keyed_choreography_registry_never_invokes_issuer_hash(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    hash_attack: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root
    issuer_type = type(issuer)

    def reject_hash(_owner: object) -> Never:
        raise AssertionError("issuer __hash__ executed under choreography registry")

    class ExplodingHashDescriptor:
        def __get__(self, _instance: object, _owner: object) -> Never:
            raise AssertionError("issuer __hash__ descriptor executed")

    replacement: object = reject_hash if hash_attack == "method" else ExplodingHashDescriptor()

    def inspect_hash_independence(lease: object, capability: object) -> None:
        compare_and_swap, build_candidate, run_under_registry_lock, _ = (
            _choreography_cas_test_seams()
        )
        state = _active_choreography_state(issuer)
        candidate = build_candidate(state)
        run_under_registry_lock(lambda: compare_and_swap(issuer, state, candidate))
        binder = _issue_registered_recovery_claim_binder(
            issuer,
            lease,
            capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        assert reader._authenticated_recovery_claim_binder_is_available(
            binder,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )

    with monkeypatch.context() as scoped:
        scoped.setattr(issuer_type, "__hash__", replacement)
        issuer._run_exclusive_choreography_with_recovery_retention(inspect_hash_independence)

    assert id(issuer) not in _active_choreography_registry()
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def test_choreography_registry_key_and_owner_weakref_crossbinding_fail_closed(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    first_root = tmp_path / "first-crossbind"
    second_root = tmp_path / "second-crossbind"
    first_root.mkdir()
    second_root.mkdir()
    first, _ = _open_issuer(monkeypatch, first_root)
    second, _ = _open_issuer(monkeypatch, second_root)

    def inspect_first(_first_lease: object, _first_capability: object) -> None:
        first_state = _active_choreography_state(first)
        first_owner_reference = _choreography_binding_value(
            first_state,
            "owner_reference",
        )

        def inspect_second(second_lease: object, _second_capability: object) -> None:
            compare_and_swap, build_candidate, run_under_registry_lock, state_validator = (
                _choreography_cas_test_seams()
            )
            available = reader._authenticated_recovery_claim_binder_is_available
            scan_owner = cast(
                Callable[[object], object | None],
                inspect.getclosurevars(available).nonlocals["recovery_claim_binder_owner_locked"],
            )
            registry = _active_choreography_registry()
            second_state = _active_choreography_state(second)
            second_binding = _choreography_state_value(second_state, "binding")
            assert type(second_binding) is tuple
            forged_binding = _tuple_with_item(
                second_binding,
                _CHOREOGRAPHY_BINDING_INDEX["owner_reference"],
                first_owner_reference,
            )
            forged_weakref_state = _choreography_state_with_item(
                second_state,
                "binding",
                forged_binding,
            )
            assert not state_validator(second, first_state)
            assert not state_validator(second, forged_weakref_state)

            for malformed in (first_state, forged_weakref_state):
                registry[id(second)] = malformed
                try:
                    with pytest.raises(
                        reader.TrustedTimePostEnrollmentTopologyReaderError,
                        match="recovery claim binder is unavailable",
                    ):
                        run_under_registry_lock(lambda: scan_owner(object()))
                    assert not reader._authenticated_choreography_is_active(
                        second,
                        second_lease,
                    )
                    with pytest.raises(
                        reader.TrustedTimePostEnrollmentTopologyReaderError,
                        match="compare-and-swap is unavailable",
                    ):
                        candidate = build_candidate(second_state)
                        run_under_registry_lock(
                            lambda candidate=candidate: compare_and_swap(
                                second,
                                second_state,
                                candidate,
                            )
                        )
                finally:
                    registry[id(second)] = second_state

            assert _active_choreography_state(first) is first_state
            assert _active_choreography_state(second) is second_state

        second._run_exclusive_choreography_with_recovery_retention(inspect_second)

    first._run_exclusive_choreography_with_recovery_retention(inspect_first)
    _close_and_assert_launch_lock_is_reacquirable(second)
    _close_and_assert_launch_lock_is_reacquirable(first)


def test_lost_owner_gc_retires_int_keyed_choreography_and_capturing_action(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    def abandon_registered_owner() -> tuple[
        weakref.ReferenceType[object],
        int,
        _TrustedTimeLaunchLockLease,
        str,
    ]:
        issuer, _ = _open_issuer(monkeypatch, tmp_path)
        owner_key = id(issuer)
        owner_reference = weakref.ref(issuer)
        launch_lock_lease = issuer._launch_lock_lease
        ignored_root = os.fspath(issuer._ignored_root)
        assert type(launch_lock_lease) is _TrustedTimeLaunchLockLease

        def capturing_action(_lease: object) -> None:
            assert issuer._choreography_inflight is True

        issuer._run_exclusive_choreography(capturing_action)
        state = _active_choreography_registry()[owner_key]
        binding = _choreography_state_value(state, "binding")
        assert type(binding) is tuple
        assert all(value is not capturing_action for value in binding)
        return owner_reference, owner_key, launch_lock_lease, ignored_root

    with monkeypatch.context() as scoped:
        scope_defaults = _authenticated_choreography_scope_kwdefaults()
        assert scope_defaults is not None
        scoped.setitem(
            scope_defaults,
            "_consume_active_scope",
            lambda _owner, _lease, _scope_nonce: True,
        )
        owner_reference, owner_key, launch_lock_lease, ignored_root = abandon_registered_owner()

    for _ in range(3):
        gc.collect()
        if owner_reference() is None:
            break

    assert owner_reference() is None
    assert owner_key not in _active_choreography_registry()
    launch_lock_lease.close()
    assert launch_lock_lease.closed is True
    replacement = _acquire_trusted_time_launch_lock(ignored_root)
    _validate_trusted_time_launch_lock(replacement)
    replacement.close()


