def test_registration_snapshot_returns_builtin_only_before_final_commit_publication(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    registrar = cast(
        Callable[..., object],
        inspect.getclosurevars(type(issuer)._run_exclusive_choreography).nonlocals[
            "register_choreography"
        ],
    )
    snapshot_code = _nested_code(registrar, "snapshot_choreography_session_locked")
    commit_code = _choreography_registration_commit_code(registrar)
    state_registry = _active_choreography_registry()
    lifecycle_registry, _run_under_registry_lock = _choreography_lifecycle_test_seams()
    owner_key = id(issuer)
    snapshot_returns: list[tuple[object, object | None, object | None]] = []
    commit_events: list[tuple[str, object, object | None, object | None]] = []

    def profile_registration_split(frame: object, event: str, result: object) -> None:
        code = getattr(frame, "f_code", None)
        if code is snapshot_code and event == "return":
            lifecycle = lifecycle_registry[owner_key]
            snapshot_returns.append(
                (
                    result,
                    state_registry.get(owner_key),
                    tuple.__getitem__(lifecycle, 8),
                )
            )
        elif code is commit_code and event in {"call", "return"}:
            lifecycle = lifecycle_registry[owner_key]
            commit_events.append(
                (
                    event,
                    result,
                    state_registry.get(owner_key),
                    tuple.__getitem__(lifecycle, 8),
                )
            )

    previous_profile = sys.getprofile()
    sys.setprofile(profile_registration_split)
    try:
        returned = issuer._run_exclusive_choreography(lambda _lease: "accepted")
    finally:
        sys.setprofile(previous_profile)

    assert returned == "accepted"
    assert len(snapshot_returns) == 1
    snapshot_result, snapshot_state, snapshot_anchor = snapshot_returns[0]
    assert type(snapshot_result) is str
    assert snapshot_result == issuer._session_sha256
    assert snapshot_state is None
    assert snapshot_anchor is None
    assert len(commit_events) == 2
    call_event, return_event = commit_events
    assert call_event == ("call", None, None, None)
    assert return_event[0] == "return"
    assert return_event[1] is None
    committed_state = return_event[2]
    committed_anchor = return_event[3]
    assert type(committed_state) is tuple
    assert type(committed_anchor) is tuple
    assert tuple.__getitem__(committed_state, 1) is committed_anchor
    assert id(issuer) not in state_registry
    _close_and_assert_launch_lock_is_reacquirable(issuer)


