@pytest.mark.parametrize(
    "boundary",
    [
        "token_bytes",
        "inner_sha256",
        "inner_hexdigest",
        "canonical_bytes",
        "outer_sha256",
        "outer_hexdigest",
    ],
)
def test_registration_material_reentrant_close_cannot_resurrect_state_or_capability(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    boundary: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    launch_lock_lease = issuer._launch_lock_lease
    saved_capability = issuer._authentication_capability
    ignored_root = os.fspath(issuer._ignored_root)
    assert type(launch_lock_lease) is _TrustedTimeLaunchLockLease
    registrar = cast(
        Callable[..., object],
        inspect.getclosurevars(type(issuer)._run_exclusive_choreography).nonlocals[
            "register_choreography"
        ],
    )
    material_target = _choreography_material_builder_code(registrar)
    entropy_name = _choreography_material_callable_name(
        material_target,
        "_choreography_entropy",
        "token_bytes",
    )
    sha256_name = _choreography_material_callable_name(
        material_target,
        "_choreography_sha256",
        "sha256",
    )
    hexdigest_name = _choreography_material_callable_name(
        material_target,
        "_choreography_hexdigest",
        "hexdigest",
    )
    if boundary == "canonical_bytes":
        offset = _instruction_offset(
            material_target,
            opname="STORE_FAST",
            argval="canonical",
        )
    else:
        callable_name, occurrence = {
            "token_bytes": (entropy_name, "first"),
            "inner_sha256": (sha256_name, "first"),
            "inner_hexdigest": (hexdigest_name, "first"),
            "outer_sha256": (sha256_name, "last"),
            "outer_hexdigest": (hexdigest_name, "last"),
        }[boundary]
        offset = _call_return_offset(
            material_target,
            callable_name=callable_name,
            occurrence=cast(Literal["first", "last"], occurrence),
        )
    interposed = False
    close_errors: list[BaseException] = []

    def close_after_valid_material_return(
        _frame: object,
        instruction_offset: int,
    ) -> None:
        nonlocal interposed
        if not interposed and instruction_offset == offset:
            interposed = True
            try:
                issuer.close()
            except BaseException as error:
                close_errors.append(error)

    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(
        tool_id,
        f"trusted-time-register-material-close-{boundary}-test",
    )
    sys.monitoring.register_callback(
        tool_id,
        sys.monitoring.events.INSTRUCTION,
        close_after_valid_material_return,
    )
    sys.monitoring.set_local_events(
        tool_id,
        material_target,
        sys.monitoring.events.INSTRUCTION,
    )
    action_called = False

    def unreachable(_lease: object) -> None:
        nonlocal action_called
        action_called = True

    try:
        with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
            issuer._run_exclusive_choreography(unreachable)
    finally:
        sys.monitoring.set_local_events(tool_id, material_target, 0)
        sys.monitoring.register_callback(
            tool_id,
            sys.monitoring.events.INSTRUCTION,
            None,
        )
        sys.monitoring.free_tool_id(tool_id)

    assert interposed is True
    assert action_called is False
    assert id(issuer) not in _active_choreography_registry()
    lifecycle_registry, run_under_registry_lock = _choreography_lifecycle_test_seams()
    lifecycle = run_under_registry_lock(lambda: lifecycle_registry.get(id(issuer)))
    if lifecycle is not None:
        assert type(lifecycle) is tuple
        assert tuple.__getitem__(lifecycle, 4) != "active"
        assert tuple.__getitem__(lifecycle, 7) == ()
        assert tuple.__getitem__(lifecycle, 8) is None
    assert issuer._authentication_capability is None
    assert not reader._authenticated_issuer_capability_is_active(
        issuer,
        saved_capability,
    )
    assert issuer._choreography_inflight is False
    assert issuer._choreography_scope_nonce is None
    assert issuer._poisoned is True
    if issuer._launch_lock_lease is launch_lock_lease:
        assert launch_lock_lease.closed is False
        _assert_launch_lock_is_held(issuer)
        _close_and_assert_launch_lock_is_reacquirable(issuer)
    else:
        assert issuer._launch_lock_lease is None
        assert launch_lock_lease.closed is True
        replacement = _acquire_trusted_time_launch_lock(ignored_root)
        _validate_trusted_time_launch_lock(replacement)
        replacement.close()
    assert all(
        isinstance(error, reader.TrustedTimePostEnrollmentTopologyReaderError)
        for error in close_errors
    )


def test_removed_lifecycle_scope_token_cannot_reactivate_stale_or_forged_state(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)

    def remove_and_forge(lease: object, _capability: object) -> None:
        state_registry = _active_choreography_registry()
        lifecycle_registry, run_under_registry_lock = _choreography_lifecycle_test_seams()
        state = _active_choreography_state(issuer)
        lifecycle = run_under_registry_lock(lambda: lifecycle_registry[id(issuer)])
        assert type(lifecycle) is tuple
        scope_binding = _choreography_binding_value(state, "scope_binding")
        assert type(scope_binding) is tuple
        scope_nonce = tuple.__getitem__(scope_binding, 1)
        live_token = tuple.__getitem__(scope_binding, 2)
        choreography_tokens = tuple.__getitem__(lifecycle, 7)
        assert type(choreography_tokens) is tuple
        assert len(choreography_tokens) == 1
        assert tuple.__getitem__(choreography_tokens, 0) is live_token

        original_heap = (
            issuer._choreography_scope_nonce,
            issuer._choreography_inflight,
            issuer._closed,
            issuer._busy,
            issuer._poisoned,
        )

        def install(
            candidate_lifecycle: tuple[object, ...],
            candidate_state: tuple[object, ...],
        ) -> None:
            lifecycle_registry[id(issuer)] = candidate_lifecycle
            state_registry[id(issuer)] = candidate_state

        try:
            stripped_lifecycle = _tuple_with_item(lifecycle, 7, ())
            run_under_registry_lock(lambda: install(stripped_lifecycle, state))
            object.__setattr__(issuer, "_choreography_scope_nonce", scope_nonce)
            object.__setattr__(issuer, "_choreography_inflight", True)
            object.__setattr__(issuer, "_closed", False)
            object.__setattr__(issuer, "_busy", False)
            object.__setattr__(issuer, "_poisoned", False)
            assert not reader._authenticated_choreography_is_active(issuer, lease)

            fresh_nonce = object()
            fresh_token = object()
            fresh_lifecycle = _tuple_with_item(lifecycle, 7, (fresh_token,))
            run_under_registry_lock(lambda: install(fresh_lifecycle, state))
            object.__setattr__(issuer, "_choreography_scope_nonce", fresh_nonce)
            assert not reader._authenticated_choreography_is_active(issuer, lease)

            binding = _choreography_state_value(state, "binding")
            assert type(binding) is tuple
            forged_scope_binding = (
                "trusted-time-choreography-scope-v1",
                fresh_nonce,
                fresh_token,
            )
            forged_binding = _tuple_with_item(
                binding,
                _CHOREOGRAPHY_BINDING_INDEX["scope_binding"],
                forged_scope_binding,
            )
            forged_state = _choreography_state_with_item(
                state,
                "binding",
                forged_binding,
            )
            run_under_registry_lock(lambda: install(fresh_lifecycle, forged_state))
            assert not reader._authenticated_choreography_is_active(issuer, lease)
        finally:
            run_under_registry_lock(lambda: install(lifecycle, state))
            (
                original_nonce,
                original_inflight,
                original_closed,
                original_busy,
                original_poisoned,
            ) = original_heap
            object.__setattr__(issuer, "_choreography_scope_nonce", original_nonce)
            object.__setattr__(issuer, "_choreography_inflight", original_inflight)
            object.__setattr__(issuer, "_closed", original_closed)
            object.__setattr__(issuer, "_busy", original_busy)
            object.__setattr__(issuer, "_poisoned", original_poisoned)

        assert reader._authenticated_choreography_is_active(issuer, lease)

    issuer._run_exclusive_choreography_with_recovery_retention(remove_and_forge)
    assert id(issuer) not in _active_choreography_registry()
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("boundary", ["before", "after"])
@pytest.mark.parametrize("interruption_type", [KeyboardInterrupt, SystemExit])
def test_choreography_cas_single_store_is_atomic_and_preserves_async_identity(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    boundary: str,
    interruption_type: type[BaseException],
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)

    def inspect_cas(_lease: object, _capability: object) -> None:
        compare_and_swap, build_candidate, run_under_registry_lock, state_validator = (
            _choreography_cas_test_seams()
        )
        instructions = list(dis.get_instructions(compare_and_swap))
        stores = [
            (index, instruction)
            for index, instruction in enumerate(instructions)
            if instruction.opname == "STORE_SUBSCR"
        ]
        assert len(stores) == 1
        store_index, store_instruction = stores[0]
        assert not any(instruction.opname == "STORE_ATTR" for instruction in instructions)
        target_offset = (
            store_instruction.offset
            if boundary == "before"
            else instructions[store_index + 1].offset
        )
        failure: BaseException = (
            SystemExit(93) if interruption_type is SystemExit else KeyboardInterrupt()
        )
        old_state = _active_choreography_state(issuer)
        old_last = _choreography_state_value(old_state, "last_monotonic_ns")
        assert state_validator(issuer, old_state)
        candidate_state = build_candidate(
            old_state,
            last_monotonic_ns=old_last,
        )
        tool_id = _enable_instruction_interrupt(
            compare_and_swap,
            target_offset,
            tool_name=(f"trusted-time-cas-{boundary}-{interruption_type.__name__}-test"),
            interruption=failure,
        )
        try:
            with pytest.raises(interruption_type) as retained_interruption:
                run_under_registry_lock(
                    lambda: compare_and_swap(
                        issuer,
                        old_state,
                        candidate_state,
                    )
                )
        finally:
            _disable_instruction_interrupt(tool_id, compare_and_swap)

        assert retained_interruption.value is failure
        current_state = _active_choreography_state(issuer)
        if boundary == "before":
            assert current_state is old_state
        else:
            assert current_state is not old_state
            assert current_state == old_state
            assert _choreography_state_value(current_state, "binding") is (
                _choreography_state_value(old_state, "binding")
            )
        assert state_validator(issuer, current_state)

    issuer._run_exclusive_choreography_with_recovery_retention(inspect_cas)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def test_choreography_cas_rejects_stale_and_cross_owner_expected_identity(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    first_root = tmp_path / "first"
    second_root = tmp_path / "second"
    first_root.mkdir()
    second_root.mkdir()
    first, _ = _open_issuer(monkeypatch, first_root)
    second, _ = _open_issuer(monkeypatch, second_root)

    def inspect_first(_first_lease: object, _first_capability: object) -> None:
        first_state = _active_choreography_state(first)

        def inspect_second(_second_lease: object, _second_capability: object) -> None:
            compare_and_swap, build_candidate, run_under_registry_lock, state_validator = (
                _choreography_cas_test_seams()
            )
            second_state = _active_choreography_state(second)
            assert state_validator(first, first_state)
            assert state_validator(second, second_state)
            for owner, foreign_state in (
                (first, second_state),
                (second, first_state),
            ):
                foreign_candidate = build_candidate(foreign_state)
                with pytest.raises(
                    reader.TrustedTimePostEnrollmentTopologyReaderError,
                    match="compare-and-swap is unavailable",
                ):

                    def attempt_foreign_compare_and_swap(
                        owner: object = owner,
                        foreign_state: tuple[object, ...] = foreign_state,
                        foreign_candidate: tuple[object, ...] = foreign_candidate,
                    ) -> object:
                        return compare_and_swap(
                            owner,
                            foreign_state,
                            foreign_candidate,
                        )

                    run_under_registry_lock(attempt_foreign_compare_and_swap)

            first_candidate = build_candidate(
                first_state,
                last_monotonic_ns=_choreography_state_value(
                    first_state,
                    "last_monotonic_ns",
                ),
            )
            run_under_registry_lock(
                lambda: compare_and_swap(
                    first,
                    first_state,
                    first_candidate,
                )
            )
            replacement = _active_choreography_state(first)
            assert replacement is not first_state
            assert replacement == first_state
            assert state_validator(first, replacement)
            with pytest.raises(
                reader.TrustedTimePostEnrollmentTopologyReaderError,
                match="compare-and-swap is unavailable",
            ):
                stale_candidate = build_candidate(first_state)
                run_under_registry_lock(
                    lambda: compare_and_swap(
                        first,
                        first_state,
                        stale_candidate,
                    )
                )
            assert _active_choreography_state(first) is replacement
            assert _active_choreography_state(second) is second_state

        second._run_exclusive_choreography_with_recovery_retention(inspect_second)

    first._run_exclusive_choreography_with_recovery_retention(inspect_first)
    _close_and_assert_launch_lock_is_reacquirable(second)
    _close_and_assert_launch_lock_is_reacquirable(first)


def test_recovery_binder_allocation_is_inert_until_none_returning_registration(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root

    def allocate_then_register(lease: object, capability: object) -> None:
        initial_state = _active_choreography_state(issuer)
        binder = object.__new__(reader._TrustedTimePostEnrollmentRecoveryClaimBinder)
        assert _active_choreography_state(issuer) is initial_state
        assert _choreography_state_value(initial_state, "phase") == "unbound"
        assert _choreography_state_value(initial_state, "recovery_claim_binder") is None
        assert not reader._authenticated_recovery_claim_binder_is_available(
            binder,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )

        registered = _register_recovery_claim_binder(
            issuer,
            lease,
            capability,
            binder,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        assert registered is None
        registered_state = _active_choreography_state(issuer)
        assert registered_state is not initial_state
        assert _choreography_state_value(registered_state, "phase") == "binder_issued"
        assert (
            _choreography_state_value(
                registered_state,
                "recovery_claim_binder",
            )
            is binder
        )
        assert reader._authenticated_recovery_claim_binder_is_available(
            binder,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        authorization_registry, run_under_authorization_lock = (
            _claimed_fence_binder_authorization_test_seams()
        )
        assert run_under_authorization_lock(lambda: not authorization_registry) is True

    issuer._run_exclusive_choreography_with_recovery_retention(allocate_then_register)
    assert id(issuer) not in _active_choreography_registry()
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def test_recovery_binder_cleanup_force_demote_keyword_is_explicit_and_protected() -> None:
    _require_coherent_projection_seal_reader()
    source_path = Path("scripts/trusted_time_post_enrollment_topology_reader.py")
    tree = ast.parse(
        source_path.read_text(encoding="utf-8"),
        filename=os.fspath(source_path),
    )
    issuer_class = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef)
        and node.name == "TrustedTimePostEnrollmentTopologyObservationIssuer"
    )
    issuer_methods = {
        node.name: node
        for node in issuer_class.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    def exact_calls(
        root: ast.AST,
        callable_name: str,
    ) -> list[ast.Call]:
        return [
            node
            for node in ast.walk(root)
            if isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == callable_name
        ]

    for method_name in (
        "_issue_recovery_retention_claim_binder",
        "_fail_recovery_retention_claim_binder",
    ):
        calls = exact_calls(issuer_methods[method_name], "_fail_binder")
        assert len(calls) == 1
        keyword_values = {
            keyword.arg: keyword.value for keyword in calls[0].keywords if keyword.arg is not None
        }
        assert isinstance(keyword_values["binding_may_have_begun"], ast.AST)
        force_demote = keyword_values["force_demote_armed"]
        assert isinstance(force_demote, ast.Constant)
        assert force_demote.value is False

    checkpoint = next(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.FunctionDef) and node.name == "checkpoint_recovery_claim_binder"
    )
    consume = next(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.FunctionDef) and node.name == "consume_recovery_claim_binder"
    )
    checkpoint_calls = exact_calls(checkpoint, "fail_recovery_claim_binder")
    consume_calls = exact_calls(consume, "fail_recovery_claim_binder")
    assert len(checkpoint_calls) == 1
    assert len(consume_calls) == 1
    checkpoint_force = next(
        keyword.value
        for keyword in checkpoint_calls[0].keywords
        if keyword.arg == "force_demote_armed"
    )
    consume_force = next(
        keyword.value
        for keyword in consume_calls[0].keywords
        if keyword.arg == "force_demote_armed"
    )
    assert isinstance(checkpoint_force, ast.Constant)
    assert checkpoint_force.value is False
    assert isinstance(consume_force, ast.Name)
    assert consume_force.id == "force_demote_armed"
    true_assignments = [
        node
        for node in ast.walk(consume)
        if isinstance(node, (ast.Assign, ast.AnnAssign))
        and isinstance(node.value, ast.Constant)
        and node.value.value is True
        and any(
            isinstance(target, ast.Name) and target.id == "force_demote_armed"
            for target in (node.targets if isinstance(node, ast.Assign) else [node.target])
        )
    ]
    assert len(true_assignments) == 1


def test_direct_recovery_binder_issue_failure_uses_nondemoting_cleanup_keyword(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root
    issue_method = type(issuer)._issue_recovery_retention_claim_binder
    defaults = issue_method.__kwdefaults__
    assert defaults is not None
    exact_fail = cast(Callable[..., bool], defaults["_fail_binder"])
    observed_calls: list[tuple[object, object, bool, bool]] = []

    def require_protected_keyword(
        candidate: object,
        owner_hint: object,
        *,
        binding_may_have_begun: bool,
        force_demote_armed: bool,
    ) -> bool:
        observed_calls.append(
            (
                candidate,
                owner_hint,
                binding_may_have_begun,
                force_demote_armed,
            )
        )
        return exact_fail(
            candidate,
            owner_hint,
            binding_may_have_begun=binding_may_have_begun,
            force_demote_armed=force_demote_armed,
        )

    monkeypatch.setitem(defaults, "_fail_binder", require_protected_keyword)
    binder = object.__new__(reader._TrustedTimePostEnrollmentRecoveryClaimBinder)

    def reject_forged_issue(lease: object, capability: object) -> Never:
        authorization_type = _claimed_fence_recovery_binder_authorization_type_test_seam()
        forged = object.__new__(authorization_type)
        with pytest.raises(
            reader.TrustedTimePostEnrollmentTopologyReaderError,
            match="recovery claim binder is unavailable",
        ):
            issuer._issue_recovery_retention_claim_binder(
                lease,
                capability,
                binder,
                claimed_fence_authorization=forged,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
        state = _active_choreography_state(issuer)
        assert _choreography_state_value(state, "phase") == "revoked"
        assert _choreography_state_value(state, "action_active") is False
        assert _choreography_state_value(state, "recovery_claim_binder") is None
        assert all(value is not binder for value in state)
        raise _RecoveryRetentionTerminal

    with pytest.raises(_RecoveryRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(reject_forged_issue)

    assert observed_calls == [(binder, issuer, False, False)]
    _assert_choreography_authority_is_burned(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("phase", ["binder_issued", "armed"])
def test_public_recovery_binder_failure_retry_uses_nondemoting_cleanup_keyword(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    phase: Literal["binder_issued", "armed"],
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    fail_method = type(issuer)._fail_recovery_retention_claim_binder
    defaults = fail_method.__kwdefaults__
    assert defaults is not None
    exact_fail = cast(Callable[..., bool], defaults["_fail_binder"])
    observed_calls: list[tuple[object, object, bool, bool]] = []

    def require_protected_keyword(
        candidate: object,
        owner_hint: object,
        *,
        binding_may_have_begun: bool,
        force_demote_armed: bool,
    ) -> bool:
        observed_calls.append(
            (
                candidate,
                owner_hint,
                binding_may_have_begun,
                force_demote_armed,
            )
        )
        return exact_fail(
            candidate,
            owner_hint,
            binding_may_have_begun=binding_may_have_begun,
            force_demote_armed=force_demote_armed,
        )

    monkeypatch.setitem(defaults, "_fail_binder", require_protected_keyword)
    binder: reader._TrustedTimePostEnrollmentRecoveryClaimBinder | None = None

    def retire_and_retry(lease: object, capability: object) -> Never:
        nonlocal binder
        binder = _issue_registered_recovery_claim_binder(
            issuer,
            lease,
            capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        if phase == "armed":
            binder._checkpoint(
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            binder(retained)
        issuer._fail_recovery_retention_claim_binder(
            binder,
            binding_may_have_begun=phase == "armed",
        )
        first_state = _active_choreography_state(issuer)
        assert _choreography_state_value(first_state, "phase") == (
            "armed" if phase == "armed" else "revoked"
        )
        assert _choreography_state_value(first_state, "action_active") is False
        assert _choreography_state_value(first_state, "recovery_claim_binder") is None
        assert all(value is not binder for value in first_state)

        issuer._fail_recovery_retention_claim_binder(
            binder,
            binding_may_have_begun=phase == "armed",
        )
        retried_state = _active_choreography_state(issuer)
        assert _choreography_state_value(retried_state, "phase") == (
            "armed" if phase == "armed" else "revoked"
        )
        assert _choreography_state_value(retried_state, "action_active") is False
        assert _choreography_state_value(retried_state, "recovery_claim_binder") is None
        assert all(value is not binder for value in retried_state)
        raise _RecoveryRetentionTerminal

    with pytest.raises(_RecoveryRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(retire_and_retry)

    assert binder is not None
    assert observed_calls == [
        (binder, issuer, phase == "armed", False),
        (binder, issuer, phase == "armed", False),
    ]
    _assert_choreography_authority_is_burned(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize(
    "boundary",
    [
        "authorization_store_before",
        "authorization_store_after",
        "topology_call_return",
        "consumer_pop_store",
        "consumer_return",
        "cleanup_acquire",
        "cleanup_body",
        "cleanup_exit",
    ],
)
def test_recovery_binder_authorization_boundaries_retire_map_and_candidate(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root
    issue = _claimed_fence_recovery_binder_issue_test_seam()
    consume_authorization = _claimed_fence_recovery_binder_consumer_test_seam()
    if boundary.startswith("authorization_store_"):
        target: Callable[..., object] | CodeType = _nested_code(
            issue,
            "register_authorization_locked",
        )
        instructions = list(dis.get_instructions(target))
        store_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.opname == "STORE_SUBSCR"
        )
        offset = instructions[store_index + (1 if boundary.endswith("_after") else 0)].offset
    elif boundary == "topology_call_return":
        target = issue
        offset = _call_return_offset(
            issue,
            callable_name="_issue_recovery_binder",
        )
    elif boundary == "consumer_pop_store":
        target = _nested_code(
            consume_authorization,
            "consume_claimed_authorization_locked",
        )
        offset = _instruction_offset(
            target,
            opname="STORE_FAST",
            argval="registration",
        )
    elif boundary == "consumer_return":
        target = consume_authorization
        offset = _call_return_offset(
            consume_authorization,
            callable_name="sealed_run_under_rlock",
        )
    elif boundary == "cleanup_body":
        target = _nested_code(issue, "retire_authorization_locked")
        offset = next(
            instruction.offset
            for instruction in dis.get_instructions(target)
            if instruction.opname not in {"COPY_FREE_VARS", "RESUME"}
        )
    else:
        target = issue
        instructions = list(dis.get_instructions(issue))
        cleanup_load_index = max(
            index
            for index, instruction in enumerate(instructions)
            if instruction.argval == "run_under_recovery_binder_registry_lock"
        )
        cleanup_call_index = next(
            index
            for index in range(cleanup_load_index + 1, len(instructions))
            if instructions[index].opname == "CALL"
        )
        offset = instructions[cleanup_call_index + (1 if boundary == "cleanup_exit" else 0)].offset

    failure: BaseException = SystemExit(181) if failure_type is SystemExit else KeyboardInterrupt()
    observed_states: list[tuple[object, ...]] = []

    def interrupt_authorization_boundary(
        lease: object,
        capability: object,
    ) -> Never:
        binder = object.__new__(reader._TrustedTimePostEnrollmentRecoveryClaimBinder)
        tool_id = _enable_instruction_interrupt(
            target,
            offset,
            tool_name=(f"trusted-time-binder-auth-{boundary}-{failure_type.__name__}-test"),
            interruption=failure,
        )
        try:
            try:
                issue(
                    topology_issuer=issuer,
                    choreography_lease=lease,
                    recovery_retention_capability=capability,
                    recovery_claim_binder=binder,
                    artifact_directory=artifact_directory,
                    ignored_root=ignored_root,
                )
            except failure_type as retained_interruption:
                assert retained_interruption is failure
                issuer._fail_recovery_retention_claim_binder(
                    binder,
                    binding_may_have_begun=False,
                )
                state = _active_choreography_state(issuer)
                observed_states.append(state)
                assert _choreography_state_value(state, "phase") == "revoked"
                assert _choreography_state_value(state, "recovery_claim_binder") is None
                assert all(value is not binder for value in state)
                authorization_registry, run_under_authorization_lock = (
                    _claimed_fence_binder_authorization_test_seams()
                )
                assert run_under_authorization_lock(lambda: not authorization_registry) is True
                raise
        finally:
            _disable_instruction_interrupt(tool_id, target)
        raise AssertionError("binder authorization interruption was not injected")

    with pytest.raises(failure_type) as retained_interruption:
        issuer._run_exclusive_choreography_with_recovery_retention(interrupt_authorization_boundary)

    assert retained_interruption.value is failure
    assert len(observed_states) == 1
    assert id(issuer) not in _active_choreography_registry()
    assert issuer._poisoned is True
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", _CLAIMED_ISSUE_CLEANUP_BOUNDARIES)
def test_claimed_issue_handler_and_cleanup_boundaries_preserve_async_and_retire_auth(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    owner_reference = weakref.ref(issuer)
    launch_lock_lease = issuer._launch_lock_lease
    assert type(launch_lock_lease) is _TrustedTimeLaunchLockLease
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root
    issue = _claimed_fence_recovery_binder_issue_test_seam()
    issue_target_offset = _claimed_issue_cleanup_boundary_offset(issue, boundary)
    reader_issue = type(issuer)._issue_recovery_retention_claim_binder
    reader_issue_entry = next(
        instruction.offset
        for instruction in dis.get_instructions(reader_issue)
        if instruction.opname not in {"COPY_FREE_VARS", "RESUME"}
    )
    failure: BaseException = SystemExit(233) if failure_type is SystemExit else KeyboardInterrupt()
    reader_failure = RuntimeError("reader failed before consuming authorization")
    reader_failed = False
    boundary_injected = False
    binder_holder: list[object] = []
    tool_id = next(
        candidate
        for candidate in range(sys.monitoring.OPTIMIZER_ID + 1)
        if sys.monitoring.get_tool(candidate) is None
    )
    sys.monitoring.use_tool_id(
        tool_id,
        f"trusted-time-claimed-issue-{boundary}-{failure_type.__name__}-test",
    )

    def interrupt_issue_cleanup(code: CodeType, instruction_offset: int) -> None:
        nonlocal boundary_injected, reader_failed
        if (
            code is reader_issue.__code__
            and instruction_offset == reader_issue_entry
            and not reader_failed
        ):
            reader_failed = True
            raise reader_failure
        if (
            code is issue.__code__
            and instruction_offset == issue_target_offset
            and not boundary_injected
        ):
            boundary_injected = True
            raise failure

    sys.monitoring.register_callback(
        tool_id,
        sys.monitoring.events.INSTRUCTION,
        interrupt_issue_cleanup,
    )
    sys.monitoring.set_local_events(
        tool_id,
        reader_issue.__code__,
        sys.monitoring.events.INSTRUCTION,
    )
    sys.monitoring.set_local_events(
        tool_id,
        issue.__code__,
        sys.monitoring.events.INSTRUCTION,
    )

    def interrupt_after_authorization_store(
        lease: object,
        capability: object,
    ) -> Never:
        binder = object.__new__(reader._TrustedTimePostEnrollmentRecoveryClaimBinder)
        binder_holder.append(binder)
        issue(
            topology_issuer=issuer,
            choreography_lease=lease,
            recovery_retention_capability=capability,
            recovery_claim_binder=binder,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        raise AssertionError("claimed issue cleanup interruption was not injected")

    try:
        with pytest.raises(failure_type) as retained_interruption:
            issuer._run_exclusive_choreography_with_recovery_retention(
                interrupt_after_authorization_store
            )
    finally:
        sys.monitoring.set_local_events(tool_id, reader_issue.__code__, 0)
        sys.monitoring.set_local_events(tool_id, issue.__code__, 0)
        sys.monitoring.register_callback(
            tool_id,
            sys.monitoring.events.INSTRUCTION,
            None,
        )
        sys.monitoring.free_tool_id(tool_id)

    assert retained_interruption.value is failure
    assert reader_failed is True
    assert boundary_injected is True
    assert len(binder_holder) == 1
    binder = binder_holder[0]
    authorization_registry, run_under_authorization_lock = (
        _claimed_fence_binder_authorization_test_seams()
    )
    assert run_under_authorization_lock(lambda: not authorization_registry) is True
    assert id(issuer) not in _active_choreography_registry()
    assert not reader._authenticated_recovery_claim_binder_is_available(
        binder,
        artifact_directory=artifact_directory,
        ignored_root=ignored_root,
    )
    _assert_choreography_authority_is_burned(issuer)

    failure.__traceback__ = None
    reader_failure.__traceback__ = None
    del retained_interruption
    binder_holder.clear()
    _close_and_assert_launch_lock_is_reacquirable(issuer)
    issuer = cast(Any, None)
    for _ in range(4):
        gc.collect()
        if owner_reference() is None:
            break
    assert owner_reference() is None
    assert launch_lock_lease.closed is True


