@pytest.mark.parametrize("attack", _CLAIMED_AUTHORIZATION_SPECIAL_METHOD_ATTACKS)
@pytest.mark.parametrize("phase", ["registration", "consume", "cleanup"])
def test_claimed_authorization_special_methods_are_never_invoked_across_bridge_phases(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    phase: Literal["registration", "consume", "cleanup"],
    attack: str,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root
    issue = _claimed_fence_recovery_binder_issue_test_seam()
    authorization_type = _claimed_fence_recovery_binder_authorization_type_test_seam()
    reader_issue = type(issuer)._issue_recovery_retention_claim_binder
    reader_issue_entry = next(
        instruction.offset
        for instruction in dis.get_instructions(reader_issue)
        if instruction.opname not in {"COPY_FREE_VARS", "RESUME"}
    )
    if phase == "registration":
        mutation_target = _nested_code(issue, "register_authorization_locked")
        mutation_offset = next(
            instruction.offset
            for instruction in dis.get_instructions(mutation_target)
            if instruction.opname not in {"COPY_FREE_VARS", "RESUME"}
        )
    elif phase == "consume":
        mutation_target = reader_issue.__code__
        mutation_offset = reader_issue_entry
    else:
        mutation_target = _nested_code(issue, "retire_authorization_locked")
        mutation_offset = next(
            instruction.offset
            for instruction in dis.get_instructions(mutation_target)
            if instruction.opname not in {"COPY_FREE_VARS", "RESUME"}
        )

    mutation_installed = False
    method_invocations: list[tuple[str, object, object | None]] = []
    restore_special_methods: Callable[[], None] | None = None

    def install_mutation() -> None:
        nonlocal method_invocations, mutation_installed, restore_special_methods
        method_invocations, restore_special_methods = (
            _install_claimed_authorization_special_method_attack(
                authorization_type,
                attack,
            )
        )
        mutation_installed = True

    mutation_tool = _enable_instruction_callback(
        mutation_target,
        mutation_offset,
        tool_name=f"trusted-time-claimed-auth-{phase}-{attack}-test",
        callback=install_mutation,
    )
    reader_failure_tool: int | None = None
    if phase == "cleanup":
        reader_failure_tool = _enable_instruction_interrupt(
            reader_issue,
            reader_issue_entry,
            tool_name=f"trusted-time-claimed-auth-cleanup-reader-{attack}-test",
            interruption=RuntimeError("reader issue deliberately unavailable"),
        )
    outcomes: list[str] = []

    def issue_under_special_method_attack(
        lease: object,
        capability: object,
    ) -> None:
        binder = object.__new__(reader._TrustedTimePostEnrollmentRecoveryClaimBinder)
        try:
            issue(
                topology_issuer=issuer,
                choreography_lease=lease,
                recovery_retention_capability=capability,
                recovery_claim_binder=binder,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
        except Exception:
            outcomes.append("rejected")
        else:
            outcomes.append("registered")
            issuer._fail_recovery_retention_claim_binder(
                binder,
                binding_may_have_begun=False,
            )
        registry, run_under_registry_lock = _claimed_fence_binder_authorization_test_seams()
        assert run_under_registry_lock(lambda: not registry) is True

    try:
        issuer._run_exclusive_choreography_with_recovery_retention(
            issue_under_special_method_attack
        )
    finally:
        _disable_instruction_interrupt(mutation_tool, mutation_target)
        if reader_failure_tool is not None:
            _disable_instruction_interrupt(reader_failure_tool, reader_issue)
        if restore_special_methods is not None:
            restore_special_methods()

    assert mutation_installed is True
    assert method_invocations == []
    assert outcomes == (["rejected"] if phase == "cleanup" else ["registered"])
    registry, run_under_registry_lock = _claimed_fence_binder_authorization_test_seams()
    assert run_under_registry_lock(lambda: not registry) is True
    assert id(issuer) not in _active_choreography_registry()
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("attack", _CLAIMED_AUTHORIZATION_SPECIAL_METHOD_ATTACKS)
def test_claimed_authorization_foreign_identity_never_cross_consumes_exact_registration(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    attack: str,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root
    authorization_type = _claimed_fence_recovery_binder_authorization_type_test_seam()
    registered_authorization = object.__new__(authorization_type)
    foreign_authorization = object.__new__(authorization_type)
    assert foreign_authorization is not registered_authorization
    registry, run_under_registry_lock, thread_token = _claimed_fence_binder_recipe_test_seams()
    callback = _claimed_fence_recovery_binder_retirement_callback_test_seam()
    method_invocations, restore_special_methods = (
        _install_claimed_authorization_special_method_attack(
            authorization_type,
            attack,
        )
    )
    registry_was_empty = False
    state_was_retired = False

    def reject_foreign_authorization(
        lease: object,
        capability: object,
    ) -> None:
        binder = object.__new__(reader._TrustedTimePostEnrollmentRecoveryClaimBinder)
        registration = (
            weakref.ref(issuer, callback),
            lease,
            capability,
            binder,
            os.fspath(artifact_directory),
            os.fspath(ignored_root),
            os.getpid(),
            thread_token(),
            registered_authorization,
        )
        run_under_registry_lock(
            lambda: registry.__setitem__(
                id(registered_authorization),
                registration,
            )
        )
        issuer._issue_recovery_retention_claim_binder(
            lease,
            capability,
            binder,
            claimed_fence_authorization=foreign_authorization,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )

    try:
        with pytest.raises(
            reader.TrustedTimePostEnrollmentTopologyReaderError,
            match="recovery claim binder is unavailable",
        ):
            issuer._run_exclusive_choreography_with_recovery_retention(reject_foreign_authorization)
        registry_was_empty = run_under_registry_lock(lambda: not registry) is True
        state_was_retired = id(issuer) not in _active_choreography_registry()
    finally:
        if not registry_was_empty:
            run_under_registry_lock(registry.clear)
        restore_special_methods()
        _close_and_assert_launch_lock_is_reacquirable(issuer)

    assert method_invocations == []
    assert registry_was_empty is True
    assert state_was_retired is True


@pytest.mark.parametrize("corruption", ["malformed_registration", "duplicate_binder"])
def test_recovery_binder_authorization_corruption_fails_closed_and_clears_map(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    corruption: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root
    consume_authorization = _claimed_fence_recovery_binder_consumer_test_seam()

    def reject_corrupt_authorization(lease: object, capability: object) -> Never:
        binder = _issue_registered_recovery_claim_binder(
            issuer,
            lease,
            capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        authorization_registry, run_under_authorization_lock, thread_token = (
            _claimed_fence_binder_recipe_test_seams()
        )
        authorization_type = _claimed_fence_recovery_binder_authorization_type_test_seam()
        first_authorization = object.__new__(authorization_type)
        retirement_callback = _claimed_fence_recovery_binder_retirement_callback_test_seam()

        def exact_registration(authorization: object) -> tuple[object, ...]:
            return (
                weakref.ref(issuer, retirement_callback),
                lease,
                capability,
                binder,
                os.fspath(artifact_directory),
                os.fspath(ignored_root),
                os.getpid(),
                thread_token(),
                authorization,
            )

        def inject_corruption() -> None:
            assert not authorization_registry
            if corruption == "malformed_registration":
                authorization_registry[id(first_authorization)] = (object(),)
            else:
                second_authorization = object.__new__(authorization_type)
                authorization_registry[id(first_authorization)] = exact_registration(
                    first_authorization
                )
                authorization_registry[id(second_authorization)] = exact_registration(
                    second_authorization
                )

        run_under_authorization_lock(inject_corruption)
        accepted = consume_authorization(
            first_authorization,
            topology_issuer=issuer,
            choreography_lease=lease,
            recovery_retention_capability=capability,
            recovery_claim_binder=binder,
            artifact_directory_value=os.fspath(artifact_directory),
            ignored_root_value=os.fspath(ignored_root),
        )
        assert accepted is False
        assert run_under_authorization_lock(lambda: not authorization_registry) is True

        issuer._fail_recovery_retention_claim_binder(
            binder,
            binding_may_have_begun=False,
        )
        state = _active_choreography_state(issuer)
        assert _choreography_state_value(state, "phase") == "revoked"
        assert _choreography_state_value(state, "recovery_claim_binder") is None
        assert all(value is not binder for value in state)
        raise _PostEffectRetentionTerminal

    with pytest.raises(_PostEffectRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(reject_corrupt_authorization)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


