def test_claimed_bridge_retirement_callback_pid_guard_precedes_lock_and_map() -> None:
    _require_coherent_projection_seal_reader()
    callback = _claimed_fence_recovery_binder_retirement_callback_test_seam()
    instructions = list(dis.get_instructions(callback))
    pid_load_index = next(
        index for index, instruction in enumerate(instructions) if instruction.argval == "_getpid"
    )
    origin_load_index = next(
        index
        for index, instruction in enumerate(
            instructions[pid_load_index + 1 :],
            start=pid_load_index + 1,
        )
        if instruction.argval == "origin_pid"
    )
    first_authority_access = min(
        index
        for index, instruction in enumerate(instructions)
        if instruction.argval
        in {
            "recovery_binder_authorizations",
            "run_under_recovery_binder_registry_lock",
        }
    )
    assert pid_load_index < origin_load_index < first_authority_access
    assert any(
        instruction.opname == "RETURN_VALUE"
        for instruction in instructions[origin_load_index:first_authority_access]
    )


def test_claimed_bridge_forked_callback_never_enters_inherited_auth_lock(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _require_coherent_projection_seal_reader()
    if not hasattr(os, "fork"):
        pytest.skip("fork is unavailable")
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    owner_reference = weakref.ref(issuer)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root
    registry, run_under_registry_lock, thread_token = _claimed_fence_binder_recipe_test_seams()
    callback = _claimed_fence_recovery_binder_retirement_callback_test_seam()
    authorization_type = _claimed_fence_recovery_binder_authorization_type_test_seam()
    authorization = object.__new__(authorization_type)
    choreography_lease = object.__new__(reader._TrustedTimePostEnrollmentTopologyChoreographyLease)
    recovery_capability = object.__new__(
        reader._TrustedTimePostEnrollmentRecoveryRetentionCapability
    )
    binder = object.__new__(reader._TrustedTimePostEnrollmentRecoveryClaimBinder)
    issuer_reference = weakref.ref(issuer, callback)
    registration = (
        issuer_reference,
        choreography_lease,
        recovery_capability,
        binder,
        os.fspath(artifact_directory),
        os.fspath(ignored_root),
        os.getpid(),
        thread_token(),
        authorization,
    )
    run_under_registry_lock(lambda: registry.__setitem__(id(authorization), registration))
    lock_entered = threading.Event()
    release_lock = threading.Event()

    def hold_authorization_lock() -> None:
        def hold_locked() -> None:
            lock_entered.set()
            assert release_lock.wait(timeout=5.0)

        run_under_registry_lock(hold_locked)

    worker = threading.Thread(target=hold_authorization_lock)
    worker.start()
    assert lock_entered.wait(timeout=2.0)
    read_descriptor, write_descriptor = os.pipe()
    child_pid = os.fork()
    if child_pid == 0:  # pragma: no cover - asserted through the pipe
        os.close(read_descriptor)
        payload: dict[str, object]
        try:
            issue = _claimed_fence_recovery_binder_issue_test_seam()
            consume = _claimed_fence_recovery_binder_consumer_test_seam()
            issue_rejected = False
            consume_rejected = False
            try:
                issue(
                    topology_issuer=issuer,
                    choreography_lease=choreography_lease,
                    recovery_retention_capability=recovery_capability,
                    recovery_claim_binder=binder,
                    artifact_directory=artifact_directory,
                    ignored_root=ignored_root,
                )
            except BaseException:
                issue_rejected = True
            try:
                consume(
                    authorization,
                    topology_issuer=issuer,
                    choreography_lease=choreography_lease,
                    recovery_retention_capability=recovery_capability,
                    recovery_claim_binder=binder,
                    artifact_directory_value=os.fspath(artifact_directory),
                    ignored_root_value=os.fspath(ignored_root),
                )
            except BaseException:
                consume_rejected = True
            issuer = cast(Any, None)
            gc.collect()
            payload = {
                "status": "ok",
                "issue_rejected": issue_rejected,
                "consume_rejected": consume_rejected,
                "owner_collected": owner_reference() is None,
            }
        except BaseException as error:
            payload = {
                "status": "error",
                "error_type": type(error).__name__,
                "error_message": str(error),
            }
        try:
            os.write(
                write_descriptor,
                json.dumps(payload, sort_keys=True).encode("utf-8"),
            )
        finally:
            os.close(write_descriptor)
        os._exit(0)

    os.close(write_descriptor)
    child_payload: dict[str, object] | None = None
    try:
        readable, _, _ = select.select([read_descriptor], [], [], 2.0)
        if readable:
            encoded = bytearray()
            while chunk := os.read(read_descriptor, 65_536):
                encoded.extend(chunk)
            decoded = json.loads(bytes(encoded))
            assert type(decoded) is dict
            child_payload = cast(dict[str, object], decoded)
        else:
            os.kill(child_pid, 9)
    finally:
        os.close(read_descriptor)
        _, wait_status = os.waitpid(child_pid, 0)
        release_lock.set()
        worker.join(timeout=2.0)
    assert child_payload is not None
    assert os.waitstatus_to_exitcode(wait_status) == 0
    assert child_payload == {
        "status": "ok",
        "issue_rejected": True,
        "consume_rejected": True,
        "owner_collected": True,
    }
    assert not worker.is_alive()
    assert run_under_registry_lock(lambda: len(registry)) == 1
    run_under_registry_lock(registry.clear)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


