def test_recovery_armed_query_rejects_forged_or_inconsistent_tuple_without_poison(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root

    def inspect(lease: object, capability: object) -> None:
        def rejected(candidate_lease: object, candidate_capability: object) -> None:
            before = _active_choreography_state(issuer)
            with pytest.raises(
                reader.TrustedTimePostEnrollmentTopologyReaderError,
                match="recovery retention state is unavailable",
            ):
                issuer._recovery_outcome_retention_is_armed(
                    candidate_lease,
                    candidate_capability,
                    artifact_directory=artifact_directory,
                    ignored_root=ignored_root,
                )
            assert _active_choreography_state(issuer) is before
            assert issuer._poisoned is False

        rejected(object(), capability)
        rejected(lease, object())
        with pytest.raises(
            reader.TrustedTimePostEnrollmentTopologyReaderError,
            match="recovery retention state is unavailable",
        ):
            issuer._recovery_outcome_retention_is_armed(
                lease,
                capability,
                artifact_directory=tmp_path / "forged-root" / "trusted-time",
                ignored_root=tmp_path / "forged-root",
            )
        assert issuer._poisoned is False

        original_scope_nonce = issuer._choreography_scope_nonce
        forged_scope_nonce = object()
        issuer._choreography_scope_nonce = forged_scope_nonce
        try:
            with pytest.raises(
                reader.TrustedTimePostEnrollmentTopologyReaderError,
                match="recovery retention state is unavailable",
            ):
                issuer._recovery_outcome_retention_is_armed(
                    lease,
                    capability,
                    artifact_directory=artifact_directory,
                    ignored_root=ignored_root,
                )
            assert issuer._choreography_scope_nonce is forged_scope_nonce
            assert issuer._poisoned is False
        finally:
            issuer._choreography_scope_nonce = original_scope_nonce

        registry = _active_choreography_registry()
        original_state = _active_choreography_state(issuer)
        corruptions = (
            _choreography_state_with_binding_item(original_state, "owner_pid", 0),
            _choreography_state_with_item(original_state, "phase", "impossible"),
            _choreography_state_with_item(
                original_state,
                "artifact_directory",
                artifact_directory,
            ),
        )
        for forged in corruptions:
            registry[id(issuer)] = forged
            try:
                with pytest.raises(
                    reader.TrustedTimePostEnrollmentTopologyReaderError,
                    match="recovery retention state is unavailable",
                ):
                    issuer._recovery_outcome_retention_is_armed(
                        lease,
                        capability,
                        artifact_directory=artifact_directory,
                        ignored_root=ignored_root,
                    )
                assert registry[id(issuer)] is forged
                assert issuer._poisoned is False
            finally:
                registry[id(issuer)] = original_state

    issuer._run_exclusive_choreography_with_recovery_retention(inspect)
    assert issuer._poisoned is False
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def test_recovery_armed_query_rejects_foreign_thread_without_poison(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    artifact_directory = issuer._ignored_root / "trusted-time"
    ignored_root = issuer._ignored_root

    def inspect(lease: object, capability: object) -> None:
        failures: list[BaseException] = []

        def foreign_query() -> None:
            try:
                issuer._recovery_outcome_retention_is_armed(
                    lease,
                    capability,
                    artifact_directory=artifact_directory,
                    ignored_root=ignored_root,
                )
            except BaseException as error:
                failures.append(error)

        worker = threading.Thread(target=foreign_query)
        worker.start()
        worker.join()
        assert len(failures) == 1
        assert type(failures[0]) is reader.TrustedTimePostEnrollmentTopologyReaderError
        assert issuer._poisoned is False
        assert (
            issuer._recovery_outcome_retention_is_armed(
                lease,
                capability,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            is False
        )

    issuer._run_exclusive_choreography_with_recovery_retention(inspect)
    assert issuer._poisoned is False
    _close_and_assert_launch_lock_is_reacquirable(issuer)


