@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize("boundary", ["registry_commit_return", "caller_store"])
def test_recovery_begin_lost_return_selects_registered_checkpoint_and_unconfirms(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
    boundary: str,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    failure: BaseException = SystemExit(103) if failure_type is SystemExit else KeyboardInterrupt()
    observed_checkpoint_identities: list[tuple[object, ...]] = []

    def interrupt_begin(lease: object, capability: object) -> Never:
        _bind_registered_recovery_claim(
            issuer,
            lease,
            capability,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        if boundary == "registry_commit_return":
            authenticated_begin = _private_reader_function_test_seam(
                "_begin_authenticated_recovery_retention",
                type(issuer)._begin_recovery_outcome_retention,
            )
            target: Callable[..., object] | CodeType = _nested_code(
                authenticated_begin,
                "begin_recovery_retention_commit_locked",
            )
            offset = _call_return_offset(
                target,
                callable_name="compare_and_swap_choreography_state_locked",
            )
        else:
            target = type(issuer)._begin_recovery_outcome_retention
            offset = _call_return_offset(
                target,
                callable_name="_begin_authenticated_recovery_retention",
            )
        tool_id = _enable_instruction_interrupt(
            target,
            offset,
            tool_name=f"trusted-time-recovery-begin-{boundary}-{failure_type.__name__}-test",
            interruption=failure,
        )
        try:
            issuer._begin_recovery_outcome_retention(
                capability,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
        except failure_type as retained_interruption:
            assert retained_interruption is failure
            state = _active_choreography_state(issuer)
            checkpoint_identity = cast(
                tuple[object, ...],
                _choreography_state_raw_value(state, "retention_checkpoint"),
            )
            checkpoint = _choreography_state_value(state, "retention_checkpoint")
            observed_checkpoint_identities.append(checkpoint_identity)
            assert _choreography_state_value(state, "phase") == "recovery_unconfirmed"
            assert _choreography_state_value(state, "action_active") is False
            assert type(checkpoint_identity) is tuple
            assert len(checkpoint_identity) == 3
            assert tuple.__getitem__(checkpoint_identity, 0) == (
                "trusted-time-recovery-retention-checkpoint-identity-v1"
            )
            checkpoint_reference = cast(
                weakref.ReferenceType[object],
                tuple.__getitem__(checkpoint_identity, 1),
            )
            if boundary == "registry_commit_return":
                assert (
                    type(checkpoint) is reader._TrustedTimePostEnrollmentRecoveryRetentionCheckpoint
                )
                assert checkpoint_reference() is checkpoint
                assert tuple.__getitem__(checkpoint_identity, 2) == id(checkpoint)
                assert checkpoint.retained_claim is retained
                assert checkpoint.artifact_directory is artifact_directory
                assert checkpoint.ignored_root is ignored_root
            else:
                assert checkpoint is None
                assert checkpoint_reference() is None
            assert not reader._authenticated_recovery_retention_is_available(
                issuer,
                capability,
                expected_state="consuming",
                checkpoint=checkpoint,
            )
            raise
        finally:
            _disable_instruction_interrupt(tool_id, target)
        raise AssertionError("recovery begin interruption was not injected")

    with pytest.raises(failure_type) as retained_interruption:
        issuer._run_exclusive_choreography_with_recovery_retention(interrupt_begin)

    assert retained_interruption.value is failure
    assert len(observed_checkpoint_identities) == 1
    assert id(issuer) not in _active_choreography_registry()
    assert issuer._poisoned is True
    _close_and_assert_launch_lock_is_reacquirable(issuer)


