@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_async_interruption_during_binder_discovery_retires_and_preserves_identity(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    consume = reader._consume_authenticated_recovery_claim_binder
    consume_snapshot_code = next(
        constant
        for constant in consume.__code__.co_consts
        if type(constant) is CodeType
        and constant.co_name == "consume_recovery_claim_binder_snapshot_locked"
    )
    source, first_line = inspect.getsourcelines(consume_snapshot_code)
    discovery_line = first_line + next(
        offset
        for offset, line in enumerate(source)
        if "registration = active_choreographies.get(_id(owner))" in line
    )
    failure: BaseException = SystemExit(173) if failure_type is SystemExit else KeyboardInterrupt()
    interruption_injected = False
    observed_states: list[tuple[object, ...]] = []
    previous_trace = sys.gettrace()

    def interrupt_during_discovery(frame: object, event: str, _arg: object) -> Any:
        nonlocal interruption_injected
        if (
            not interruption_injected
            and event == "line"
            and getattr(frame, "f_code", None) is consume_snapshot_code
            and getattr(frame, "f_lineno", None) == discovery_line
        ):
            interruption_injected = True
            sys.settrace(None)
            raise failure
        return interrupt_during_discovery

    def propagate_interruption(lease: object, capability: object) -> Never:
        binder = _issue_registered_recovery_claim_binder(
            issuer,
            lease,
            capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        binder._checkpoint(
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        sys.settrace(interrupt_during_discovery)
        try:
            binder(retained)
        finally:
            sys.settrace(previous_trace)
            state = _active_choreography_state(issuer)
            observed_states.append(state)
            assert _choreography_state_value(state, "phase") == "revoked"
            assert _choreography_state_value(state, "recovery_claim_binder") is None
            assert all(value is not binder for value in state)
        raise AssertionError("binder discovery interruption was not injected")

    with pytest.raises(failure_type) as retained_interruption:
        issuer._run_exclusive_choreography_with_recovery_retention(propagate_interruption)

    assert retained_interruption.value is failure
    assert interruption_injected is True
    assert len(observed_states) == 1
    assert issuer._poisoned is True
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def test_opaque_claim_binder_is_exact_one_shot_and_fixed_to_retention(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    values = [20_000, 20_001, 20_002, 20_003, 20_004, 20_005]
    clock = _MonotonicClock(values)
    issuer, _ = _open_issuer(monkeypatch, tmp_path, monotonic_clock=clock)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    primary = RuntimeError("adopt the exact retained recovery receipt")
    completed_outcomes: list[recovery_outcome.RetainedTrustedTimePostEnrollmentStartOutcome] = []

    def bind_and_retain(lease: object, capability: object) -> None:
        binder = _issue_registered_recovery_claim_binder(
            issuer,
            lease,
            capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        assert type(binder) is reader._TrustedTimePostEnrollmentRecoveryClaimBinder
        assert reader._authenticated_recovery_claim_binder_is_available(
            binder,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
            copy(binder)
        with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
            pickle.dumps(binder)

        binder._checkpoint(
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        binder(retained)
        assert not reader._authenticated_recovery_claim_binder_is_available(
            binder,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
            binder(retained)

        checkpoint = issuer._begin_recovery_outcome_retention(
            capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        retained_outcome = _persist_recovery_outcome(
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        completed_outcomes.append(retained_outcome)
        issuer._complete_recovery_outcome_retention(
            capability,
            checkpoint,
            retained_outcome,
        )
        raise primary

    with pytest.raises(
        recovery_outcome.TrustedTimePostEnrollmentStartRecoveryOutcomeRetained
    ) as terminal:
        issuer._run_exclusive_choreography_with_recovery_retention(bind_and_retain)

    assert terminal.value.retained_outcome is completed_outcomes[0]
    assert terminal.value.__cause__ is primary
    assert clock.calls == values
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def _open_real_claimed_choreography(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    *,
    clock_start: int,
    sample_count: int,
) -> tuple[
    Any,
    reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
    _MonotonicClock,
]:
    def valid_test_seal(candidate: object, payload: object) -> bool:
        return type(candidate) is bytes and candidate == claimed_fixtures._authenticated_seal(
            cast(dict[str, object], payload)
        )

    monkeypatch.setattr(reader, "_valid_observation_seal", valid_test_seal)
    monkeypatch.setattr(
        reader,
        "_valid_cursor_seal",
        lambda candidate, payload, _result: valid_test_seal(candidate, payload),
    )
    context = claimed_fixtures._context(tmp_path)
    clock = _MonotonicClock([clock_start + offset for offset in range(sample_count)])
    issuer, _ = _open_issuer(monkeypatch, tmp_path, monotonic_clock=clock)
    context.topology_issuer = issuer
    cursors = iter(context.cursors)

    def issue_cursor(
        candidate: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
        *,
        _choreography_lease: object | None = None,
    ) -> reader.TrustedTimePostEnrollmentTopologyObservationCursor:
        candidate._require_active_choreography_lease(_choreography_lease)
        return next(cursors)

    def issue_staged(
        candidate: reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
        *,
        _choreography_lease: object | None = None,
        **_: object,
    ) -> reader.TrustedTimePostEnrollmentStagedTopologyObservation:
        candidate._require_active_choreography_lease(_choreography_lease)
        return context.staged_two

    monkeypatch.setattr(
        reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
        "issue_observation_cursor",
        issue_cursor,
    )
    monkeypatch.setattr(
        reader.TrustedTimePostEnrollmentTopologyObservationIssuer,
        "issue_staged_unreleased_snapshot",
        issue_staged,
    )
    monkeypatch.setattr(
        staging,
        "load_confirmed_first_enrollment_evidence",
        lambda **_: context.approval.confirmed_enrollment,
    )
    return context, issuer, clock


def test_real_claim_binder_survives_later_claimed_chronology_failure_to_outcome(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    context, issuer, clock = _open_real_claimed_choreography(
        monkeypatch,
        tmp_path,
        clock_start=30_000,
        sample_count=20,
    )
    monkeypatch.setattr(
        claimed_fence,
        "revalidate_retained_post_enrollment_start_claim",
        lambda *_args, **_kwargs: False,
    )

    def retain_after_later_failure(lease: object, capability: object) -> Never:
        try:
            claimed_fence.prepare_post_enrollment_start_leased_claimed_pre_release_fence(
                **context.kwargs(),  # type: ignore[arg-type]
                choreography_lease=lease,
                recovery_retention_capability=capability,
            )
        except claimed_fence.TrustedTimePostEnrollmentStartClaimedFenceRecoveryRequired:
            gc.collect()
            assert issuer._recovery_outcome_retention_is_armed(
                lease,
                capability,
                artifact_directory=context.artifact_directory,
                ignored_root=context.ignored_root,
            )
            recovery_outcome.retain_post_enrollment_start_recovery_required_outcome(
                topology_issuer=issuer,
                recovery_retention_capability=capability,
                artifact_directory=context.artifact_directory,
                ignored_root=context.ignored_root,
            )
        raise AssertionError("claimed chronology failure was not retained")

    with pytest.raises(
        recovery_outcome.TrustedTimePostEnrollmentStartRecoveryOutcomeRetained
    ) as terminal:
        issuer._run_exclusive_choreography_with_recovery_retention(retain_after_later_failure)

    retained = terminal.value.retained_outcome
    assert retained.operation_id == context.approval.operation_id
    assert recovery_outcome.revalidate_retained_post_enrollment_start_outcome(
        retained,
        artifact_directory=context.artifact_directory,
        ignored_root=context.ignored_root,
    )
    assert clock.call_count < 20
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_staging_issuer_close_async_is_preserved_after_confirmed_retry_and_burn(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
) -> None:
    context, issuer, _ = _open_real_claimed_choreography(
        monkeypatch,
        tmp_path,
        clock_start=31_000,
        sample_count=64,
    )
    arguments = context.kwargs()
    reauthentication_issuer = cast(claim_fixtures._Issuer, arguments["reauthentication_issuer"])
    native_close = reauthentication_issuer.close
    close_attempts = 0
    failure: BaseException = SystemExit(197) if failure_type is SystemExit else KeyboardInterrupt()

    def interrupt_first_close_then_confirm() -> None:
        nonlocal close_attempts
        close_attempts += 1
        if close_attempts == 1:
            raise failure
        native_close()

    monkeypatch.setattr(
        reauthentication_issuer,
        "close",
        interrupt_first_close_then_confirm,
    )
    registrations, claimed_actions, consumed_origins, run_under_lock, _ = (
        _claimed_fence_registration_test_seams()
    )
    registry_baseline = run_under_lock(
        lambda: (
            set(registrations),
            set(claimed_actions),
            set(consumed_origins),
        )
    )

    def interrupt_staging_close(lease: object, capability: object) -> Never:
        claimed_fence.prepare_post_enrollment_start_leased_claimed_pre_release_fence(
            **arguments,  # type: ignore[arg-type]
            choreography_lease=lease,
            recovery_retention_capability=capability,
        )
        raise AssertionError("staging issuer close interruption was not preserved")

    with pytest.raises(failure_type) as retained_interruption:
        issuer._run_exclusive_choreography_with_recovery_retention(interrupt_staging_close)

    assert retained_interruption.value is failure
    assert close_attempts == 2
    assert reauthentication_issuer.closed is True
    assert not (
        context.artifact_directory / claim_persistence.POST_ENROLLMENT_START_CLAIM_FILE_NAME
    ).exists()
    assert (
        run_under_lock(
            lambda: (
                set(registrations),
                set(claimed_actions),
                set(consumed_origins),
            )
        )
        == registry_baseline
    )
    authorization_registry, run_under_authorization_lock = (
        _claimed_fence_binder_authorization_test_seams()
    )
    assert run_under_authorization_lock(lambda: not authorization_registry) is True
    _assert_choreography_authority_is_burned(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
def test_claimed_builder_unregister_async_retries_and_retires_all_authority(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    failure_type: type[BaseException],
) -> None:
    context, issuer, _ = _open_real_claimed_choreography(
        monkeypatch,
        tmp_path,
        clock_start=32_000,
        sample_count=64,
    )
    arguments = context.kwargs()
    reauthentication_issuer = cast(claim_fixtures._Issuer, arguments["reauthentication_issuer"])
    registrations, claimed_actions, consumed_origins, run_under_lock, unregister_locked = (
        _claimed_fence_registration_test_seams()
    )
    registry_baseline = run_under_lock(
        lambda: (
            set(registrations),
            set(claimed_actions),
            set(consumed_origins),
        )
    )
    unregister_entry = next(
        instruction.offset
        for instruction in dis.get_instructions(unregister_locked)
        if instruction.opname not in {"COPY_FREE_VARS", "RESUME"}
    )
    failure: BaseException = SystemExit(199) if failure_type is SystemExit else KeyboardInterrupt()

    def reject_constructed_fence(
        _candidate: claimed_fence.TrustedTimePostEnrollmentStartClaimedPreReleaseTopologyFence,
    ) -> Never:
        raise RuntimeError("force the registered claimed fence cleanup corridor")

    monkeypatch.setattr(
        claimed_fence.TrustedTimePostEnrollmentStartClaimedPreReleaseTopologyFence,
        "__post_init__",
        reject_constructed_fence,
    )

    def interrupt_first_unregister(lease: object, capability: object) -> Never:
        tool_id = _enable_instruction_interrupt(
            unregister_locked,
            unregister_entry,
            tool_name=f"trusted-time-claimed-unregister-{failure_type.__name__}-test",
            interruption=failure,
        )
        try:
            claimed_fence.prepare_post_enrollment_start_leased_claimed_pre_release_fence(
                **arguments,  # type: ignore[arg-type]
                choreography_lease=lease,
                recovery_retention_capability=capability,
            )
        finally:
            _disable_instruction_interrupt(tool_id, unregister_locked)
        raise AssertionError("claimed fence unregister interruption was not preserved")

    with pytest.raises(failure_type) as retained_interruption:
        issuer._run_exclusive_choreography_with_recovery_retention(interrupt_first_unregister)

    assert retained_interruption.value is failure
    assert reauthentication_issuer.closed is True
    assert (
        context.artifact_directory / claim_persistence.POST_ENROLLMENT_START_CLAIM_FILE_NAME
    ).is_file()
    assert (
        run_under_lock(
            lambda: (
                set(registrations),
                set(claimed_actions),
                set(consumed_origins),
            )
        )
        == registry_baseline
    )
    authorization_registry, run_under_authorization_lock = (
        _claimed_fence_binder_authorization_test_seams()
    )
    assert run_under_authorization_lock(lambda: not authorization_registry) is True
    _assert_choreography_authority_is_burned(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def test_action_deadline_equality_revokes_action_but_preserves_bound_recovery(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    started = 2_000_000_000
    action_deadline = started + reader._POST_ENROLLMENT_START_CHOREOGRAPHY_DEADLINE_NANOSECONDS
    retention_deadline = (
        started + reader._POST_ENROLLMENT_START_RECOVERY_RETENTION_DEADLINE_NANOSECONDS
    )
    values = [
        started,
        started + 1,
        started + 2,
        started + 3,
        action_deadline,
        action_deadline + 1,
        retention_deadline - 1,
    ]
    clock = _MonotonicClock(values)
    issuer, queued = _open_issuer(
        monkeypatch,
        tmp_path,
        monotonic_clock=clock,
    )
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)

    def retain_after_expiry(lease: object, capability: object) -> None:
        _bind_registered_recovery_claim(
            issuer,
            lease,
            capability,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
            issuer._require_active_choreography_lease(lease)
        assert issuer._poisoned is True
        _assert_launch_lock_is_held(issuer)
        checkpoint = issuer._begin_recovery_outcome_retention(
            capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        retained_outcome = _persist_recovery_outcome(
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        issuer._complete_recovery_outcome_retention(
            capability,
            checkpoint,
            retained_outcome,
        )
        raise RuntimeError("trigger registered recovery outcome adoption")

    with pytest.raises(recovery_outcome.TrustedTimePostEnrollmentStartRecoveryOutcomeRetained):
        issuer._run_exclusive_choreography_with_recovery_retention(retain_after_expiry)

    assert clock.calls == values
    assert len(queued.calls) == 1
    _close_and_assert_launch_lock_is_reacquirable(issuer)


