def test_discarded_controller_receipt_capture_cannot_retain_lost_owner(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    def abandon_registered_owner() -> tuple[
        weakref.ReferenceType[object],
        int,
        _TrustedTimeLaunchLockLease,
        str,
    ]:
        issuer, _ = _open_issuer(monkeypatch, tmp_path)
        owner_reference = weakref.ref(issuer)
        owner_key = id(issuer)
        launch_lock_lease = issuer._launch_lock_lease
        ignored_root_value = os.fspath(issuer._ignored_root)
        assert type(launch_lock_lease) is _TrustedTimeLaunchLockLease
        retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)

        def abandon_candidate(lease: object, recovery_capability: object) -> None:
            post_effect_capability = _transition_registered_post_effect_retention(
                issuer,
                lease,
                recovery_capability,
                retained,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            checkpoint = issuer._begin_post_effect_controller_outcome_retention(
                post_effect_capability,
                lease,
                retained,
                outcome_kind="failure",
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )

            def capturing_candidate() -> object:
                return issuer

            issuer._abandon_post_effect_controller_outcome_retention(
                post_effect_capability,
                checkpoint,
                capturing_candidate,
            )
            state = _active_choreography_state(issuer)
            assert _choreography_state_value(state, "controller_outcome_receipt") is None
            assert all(value is not capturing_candidate for value in state)

        with suppress(reader.TrustedTimePostEnrollmentTopologyReaderError):
            issuer._run_exclusive_choreography_with_recovery_retention(abandon_candidate)
        state = _active_choreography_registry()[owner_key]
        assert _choreography_state_value(state, "phase") == "post_effect_unconfirmed"
        assert _choreography_state_value(state, "controller_outcome_receipt") is None
        return owner_reference, owner_key, launch_lock_lease, ignored_root_value

    with monkeypatch.context() as scoped:
        scope_defaults = _authenticated_choreography_scope_kwdefaults()
        assert scope_defaults is not None
        scoped.setitem(
            scope_defaults,
            "_revoke_scope",
            lambda _owner, _scope_nonce: None,
        )
        owner_reference, owner_key, launch_lock_lease, ignored_root_value = (
            abandon_registered_owner()
        )

    for _ in range(3):
        gc.collect()
        if owner_reference() is None:
            break

    assert owner_reference() is None
    assert owner_key not in _active_choreography_registry()
    launch_lock_lease.close()
    replacement = _acquire_trusted_time_launch_lock(ignored_root_value)
    _validate_trusted_time_launch_lock(replacement)
    replacement.close()


def test_confirmed_controller_receipt_backref_cannot_retain_lost_owner(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    def abandon_registered_owner() -> tuple[
        weakref.ReferenceType[object],
        weakref.ReferenceType[object],
        int,
        _TrustedTimeLaunchLockLease,
        str,
    ]:
        issuer, _ = _open_issuer(monkeypatch, tmp_path)
        owner_reference = weakref.ref(issuer)
        owner_key = id(issuer)
        launch_lock_lease = issuer._launch_lock_lease
        ignored_root_value = os.fspath(issuer._ignored_root)
        assert type(launch_lock_lease) is _TrustedTimeLaunchLockLease
        retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
        receipt = _real_prepared_controller_success_receipt(
            retained,
            artifact_directory=artifact_directory,
        )
        receipt_reference = weakref.ref(receipt)

        def retain_capturing_receipt(
            lease: object,
            recovery_capability: object,
        ) -> object:
            post_effect_capability = _transition_registered_post_effect_retention(
                issuer,
                lease,
                recovery_capability,
                retained,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            checkpoint = issuer._begin_post_effect_controller_outcome_retention(
                post_effect_capability,
                lease,
                retained,
                outcome_kind="success",
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            issuer._complete_post_effect_controller_outcome_retention(
                post_effect_capability,
                checkpoint,
                receipt,
            )
            controller_outcome._commit_prepared_controller_outcome(
                receipt,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
            object.__setattr__(receipt, "_evidence", issuer)
            state = _active_choreography_state(issuer)
            _assert_choreography_receipt_binding_slot(
                state,
                "controller_outcome_receipt",
                receipt,
                receipt_projection_length=15,
                checkpoint_identity=cast(
                    tuple[object, ...],
                    _choreography_state_raw_value(
                        state,
                        "controller_outcome_checkpoint",
                    ),
                ),
                checkpoint_projection_length=8,
                claim_identity=cast(
                    tuple[object, ...],
                    _choreography_state_raw_value(state, "retained_claim"),
                ),
            )
            assert not _tuple_tree_contains_identity(state, receipt)
            return receipt

        assert (
            issuer._run_exclusive_choreography_with_recovery_retention(retain_capturing_receipt)
            is receipt
        )
        assert owner_key in _active_choreography_registry()
        return (
            owner_reference,
            receipt_reference,
            owner_key,
            launch_lock_lease,
            ignored_root_value,
        )

    def retain_registry_for_gc(
        _owner: object,
        _lease: object,
        _scope_nonce: object,
        candidate_receipt: object,
        *,
        outcome_kind: object,
        _consume_scope: bool = False,
        _after_scope_consumed: Callable[[object], None] | None = None,
    ) -> object:
        assert outcome_kind == "success"
        assert _consume_scope is True
        assert _after_scope_consumed is not None
        _after_scope_consumed(candidate_receipt)
        return candidate_receipt

    with monkeypatch.context() as scoped:
        scope_defaults = _authenticated_choreography_scope_kwdefaults()
        assert scope_defaults is not None
        scoped.setitem(
            scope_defaults,
            "_select_controller_receipt",
            retain_registry_for_gc,
        )
        (
            owner_reference,
            receipt_reference,
            owner_key,
            launch_lock_lease,
            ignored_root_value,
        ) = abandon_registered_owner()

    for _ in range(3):
        gc.collect()
        if owner_reference() is None and receipt_reference() is None:
            break

    assert owner_reference() is None
    assert receipt_reference() is None
    assert owner_key not in _active_choreography_registry()
    launch_lock_lease.close()
    replacement = _acquire_trusted_time_launch_lock(ignored_root_value)
    _validate_trusted_time_launch_lock(replacement)
    replacement.close()


def test_post_effect_success_retention_is_exact_one_shot_and_scope_sealed(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, queued = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    escaped: list[tuple[object, object]] = []

    with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
        reader._TrustedTimePostEnrollmentPostEffectOutcomeCapability()

    def retain_success(lease: object, recovery_capability: object) -> None:
        post_effect_capability = _transition_registered_post_effect_retention(
            issuer,
            lease,
            recovery_capability,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        escaped.append((lease, post_effect_capability))
        for operation in (
            lambda: copy(post_effect_capability),
            lambda: deepcopy(post_effect_capability),
            lambda: pickle.dumps(post_effect_capability),
        ):
            with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
                operation()
        active = issuer._require_active_post_effect_outcome_retention(
            post_effect_capability,
            lease,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        checkpoint = issuer._begin_post_effect_controller_outcome_retention(
            post_effect_capability,
            lease,
            retained,
            outcome_kind="success",
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        assert checkpoint.retained_claim is retained
        assert checkpoint.outcome_kind == "success"
        assert checkpoint.started_monotonic_ns == active.started_monotonic_ns
        assert checkpoint.action_deadline_monotonic_ns == active.deadline_monotonic_ns
        assert checkpoint.deadline_monotonic_ns == active.deadline_monotonic_ns
        receipt = _real_prepared_controller_success_receipt(
            retained,
            artifact_directory=artifact_directory,
        )
        issuer._complete_post_effect_controller_outcome_retention(
            post_effect_capability,
            checkpoint,
            receipt,
        )
        state = _active_choreography_state(issuer)
        assert _choreography_state_value(state, "phase") == "post_effect_confirmed"
        assert _choreography_state_value(state, "controller_outcome_checkpoint") is checkpoint
        assert _choreography_state_value(state, "controller_outcome_receipt") is receipt
        with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
            issuer._complete_post_effect_controller_outcome_retention(
                post_effect_capability,
                checkpoint,
                receipt,
            )
        raise _PostEffectRetentionTerminal

    with pytest.raises(_PostEffectRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(retain_success)

    lease, post_effect_capability = escaped[0]
    with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
        issuer._begin_post_effect_controller_outcome_retention(
            post_effect_capability,
            lease,
            retained,
            outcome_kind="failure",
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
    assert len(queued.calls) == 1
    _close_and_assert_launch_lock_is_reacquirable(issuer)


