def test_outer_scope_retries_one_async_interruption_inside_exact_adopter(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    receipt = _real_prepared_controller_success_receipt(
        retained,
        artifact_directory=artifact_directory,
    )
    scope_defaults = _authenticated_choreography_scope_kwdefaults()
    assert scope_defaults is not None
    real_adopt = cast(Callable[..., object], scope_defaults["_registered_terminal"])
    adoption_attempts = 0
    interruption = KeyboardInterrupt()

    def interrupt_once(candidate: object, *args: object, **kwargs: object) -> object:
        nonlocal adoption_attempts
        assert candidate is issuer
        adoption_attempts += 1
        if adoption_attempts == 1:
            raise interruption
        return real_adopt(candidate, *args, **kwargs)

    monkeypatch.setitem(
        scope_defaults,
        "_registered_terminal",
        interrupt_once,
    )

    def complete_then_fail(lease: object, recovery_capability: object) -> Never:
        post_effect_capability = _transition_registered_post_effect_retention(
            issuer,
            lease,
            recovery_capability,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        checkpoint = issuer._begin_post_effect_controller_outcome_retention(
            post_effect_capability,
            lease,
            retained,
            outcome_kind="success",
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        issuer._complete_post_effect_controller_outcome_retention(
            post_effect_capability,
            checkpoint,
            receipt,
        )
        controller_outcome._commit_prepared_controller_outcome(
            receipt,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        raise RuntimeError("trigger exact terminal adoption")

    with pytest.raises(KeyboardInterrupt) as retained_interruption:
        issuer._run_exclusive_choreography_with_recovery_retention(complete_then_fail)

    assert retained_interruption.value is interruption
    assert adoption_attempts == 2
    _assert_choreography_authority_is_burned(issuer)
    _assert_launch_lock_is_held(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


