@pytest.mark.parametrize("failure_type", [KeyboardInterrupt, SystemExit])
@pytest.mark.parametrize(
    "boundary",
    [
        "cas_before",
        "cas_after",
        "claim_postproof_return",
        "checkpoint_postproof_return",
        "primitive_return",
        "wrapper_call_return",
        "handler_store",
        "handler_pop",
    ],
)
def test_begin_recovery_lost_return_and_handler_gaps_demote_consuming_identity(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    boundary: str,
    failure_type: type[BaseException],
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)
    begin = _choreography_authority_roots()["begin_recovery_retention"]
    commit_locked = _nested_code(begin, "begin_recovery_retention_commit_locked")
    confirm_locked = _nested_code(begin, "confirm_recovery_begin_locked")
    wrapper = type(issuer)._begin_recovery_outcome_retention
    primitive_call_return = _call_return_offset(
        wrapper,
        callable_name="_begin_authenticated_recovery_retention",
    )
    failure: BaseException = SystemExit(259) if failure_type is SystemExit else KeyboardInterrupt()
    if boundary in {"cas_before", "cas_after"}:
        target = commit_locked
        call_return = _call_return_offset(
            commit_locked,
            callable_name="compare_and_swap_choreography_state_locked",
        )
        instructions = list(dis.get_instructions(commit_locked))
        return_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.offset == call_return
        )
        assert instructions[return_index - 1].opname == "CALL"
        target_offset = (
            instructions[return_index - 1].offset if boundary == "cas_before" else call_return
        )
    elif boundary in {"claim_postproof_return", "checkpoint_postproof_return"}:
        target = confirm_locked
        target_offset = _call_return_offset(
            confirm_locked,
            callable_name=(
                "sealed_retained_claim_durable_projection"
                if boundary == "claim_postproof_return"
                else "sealed_recovery_checkpoint_projection"
            ),
            occurrence="last",
        )
    elif boundary == "primitive_return":
        target = begin
        target_offset = _instruction_offset(
            begin,
            opname="RETURN_VALUE",
            argval=None,
            occurrence="last",
        )
    else:
        target = wrapper
        target_offset = primitive_call_return

    def interrupt_begin(
        _lease: object,
        recovery_capability: object,
    ) -> Never:
        _bind_registered_recovery_claim(
            issuer,
            _lease,
            recovery_capability,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        armed = _active_choreography_state(issuer)
        retained_identity = _choreography_state_raw_value(armed, "retained_claim")
        if boundary in {"handler_store", "handler_pop"}:
            handler_offset = _reader_handler_gap_offset(
                wrapper.__code__,
                error_name="primary_error",
                boundary=(
                    "handler_error_store" if boundary == "handler_store" else "handler_pop_except"
                ),
            )
            tool_id, events = _enable_validation_then_handler_interrupt(
                wrapper.__code__,
                validation_return_offset=primitive_call_return,
                handler_offset=handler_offset,
                interruption=failure,
                tool_name=(f"trusted-time-begin-recovery-{boundary}-{failure_type.__name__}-test"),
            )
        else:
            events = []
            tool_id = _enable_instruction_interrupt(
                target,
                target_offset,
                tool_name=(f"trusted-time-begin-recovery-{boundary}-{failure_type.__name__}-test"),
                interruption=failure,
            )
        try:
            with pytest.raises(failure_type) as retained_interruption:
                issuer._begin_recovery_outcome_retention(
                    recovery_capability,
                    artifact_directory=artifact_directory,
                    ignored_root=ignored_root,
                )
        finally:
            _disable_instruction_interrupt(tool_id, target)
        assert retained_interruption.value is failure
        if events:
            assert events == ["validation", "handler"]
        state = _active_choreography_state(issuer)
        assert state is not armed
        assert _choreography_state_value(state, "phase") == "recovery_unconfirmed"
        assert _choreography_state_value(state, "action_active") is False
        assert _choreography_state_raw_value(state, "retained_claim") is retained_identity
        assert _choreography_state_value(state, "recovery_claim_binder") is None
        assert _choreography_state_value(state, "recovery_outcome_receipt") is None
        with pytest.raises(reader.TrustedTimePostEnrollmentTopologyReaderError):
            issuer._begin_recovery_outcome_retention(
                recovery_capability,
                artifact_directory=artifact_directory,
                ignored_root=ignored_root,
            )
        raise _RecoveryRetentionTerminal

    with pytest.raises(_RecoveryRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(interrupt_begin)
    _assert_choreography_authority_is_burned(issuer)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


def test_begin_recovery_success_keeps_exact_checkpoint_live_through_confirmation(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _require_coherent_projection_seal_reader()
    issuer, _ = _open_issuer(monkeypatch, tmp_path)
    retained, artifact_directory, ignored_root = _retain_claim_for_issuer(issuer)

    def begin_and_confirm(
        lease: object,
        recovery_capability: object,
    ) -> Never:
        _bind_registered_recovery_claim(
            issuer,
            lease,
            recovery_capability,
            retained,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        checkpoint = issuer._begin_recovery_outcome_retention(
            recovery_capability,
            artifact_directory=artifact_directory,
            ignored_root=ignored_root,
        )
        checkpoint_reference = weakref.ref(checkpoint)
        gc.collect()
        state = _active_choreography_state(issuer)
        assert _choreography_state_value(state, "phase") == "recovery_consuming"
        assert _choreography_state_value(state, "retention_checkpoint") is checkpoint
        assert checkpoint_reference() is checkpoint
        assert checkpoint.retained_claim is retained
        issuer._abandon_recovery_outcome_retention(
            recovery_capability,
            checkpoint,
        )
        assert _active_choreography_state_value(issuer, "phase") == "recovery_unconfirmed"
        raise _RecoveryRetentionTerminal

    with pytest.raises(_RecoveryRetentionTerminal):
        issuer._run_exclusive_choreography_with_recovery_retention(begin_and_confirm)
    _close_and_assert_launch_lock_is_reacquirable(issuer)


